		assertSame(SortMode.PERCENT_MOVE, SortMode.parse("% Move"));
		assertSame(SortMode.GP_MOVE, SortMode.parse("gp move"));
		assertSame(SortMode.GP_MOVE, SortMode.parse("  GP Move "));
