	private static void assertFits(String text, Font font, int width)
	{
		final int measured = width(text, font);
		assertTrue("\"" + text + "\" measures " + measured + " px, over " + width, measured <= width);
	}

	/** What {@code text} measures in {@code font}, with the same metrics a label paints with. */
	private static int width(String text, Font font)
	{
		return new JLabel().getFontMetrics(font).stringWidth(text);
	}

	/** The fitter brings a sentence inside its room, whether by fitting it whole or by cutting it. */
	private static void assertFitted(String text, Font font, int width)
	{
		final String shown = Widgets.fit(font, text, width);
		assertFits(shown, font, width);
		assertTrue("\"" + text + "\" came back longer than it went in", shown.length() <= text.length()
			+ Widgets.ELLIPSIS.length());
	}

	private static void assertGlyph(ImageIcon icon, int width, int height)
	{
		assertNotNull(icon);
		assertEquals(width, icon.getIconWidth());
		assertEquals(height, icon.getIconHeight());
		assertTrue("the glyph put no ink down", ink(image(icon)) > 0);
	}

	private static void assertHasColour(ImageIcon icon, Color colour)
	{
		final BufferedImage img = image(icon);
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				final int argb = img.getRGB(x, y);
				if (((argb >>> 24) & 0xff) == 0xff && (argb & 0xffffff) == (colour.getRGB() & 0xffffff))
				{
					return;
				}
			}
		}
		throw new AssertionError("no fully opaque pixel of " + colour + " in the glyph");
	}

	private static void assertSamePixels(ImageIcon left, ImageIcon right)
	{
		final BufferedImage a = image(left);
		final BufferedImage b = image(right);
		assertEquals(a.getWidth(), b.getWidth());
		assertEquals(a.getHeight(), b.getHeight());
		for (int x = 0; x < a.getWidth(); x++)
		{
			for (int y = 0; y < a.getHeight(); y++)
			{
				assertEquals("pixel " + x + "," + y, a.getRGB(x, y), b.getRGB(x, y));
			}
		}
	}

	private static BufferedImage image(ImageIcon icon)
	{
		assertTrue("the glyphs are drawn into a BufferedImage at build time",
			icon.getImage() instanceof BufferedImage);
		return (BufferedImage) icon.getImage();
	}

	/**
	 * How many separate runs of ink a circle of radius {@code r} about the glyph's centre crosses - the teeth of
	 * a gear, counted rather than assumed. Sampled every degree and read as a ring, so a run that straddles 0
	 * degrees counts once.
	 */
	private static int runsOfInk(BufferedImage img, double r)
	{
		final double centre = img.getWidth() / 2.0;
		final boolean[] inked = new boolean[360];
		for (int deg = 0; deg < 360; deg++)
		{
			final double a = Math.toRadians(deg);
			final int x = (int) Math.round(centre + Math.cos(a) * r);
			final int y = (int) Math.round(centre + Math.sin(a) * r);
			inked[deg] = x >= 0 && y >= 0 && x < img.getWidth() && y < img.getHeight() && alpha(img, x, y) > 0;
		}
		int runs = 0;
		for (int deg = 0; deg < 360; deg++)
		{
			if (inked[deg] && !inked[(deg + 359) % 360])
			{
				runs++;
			}
		}
		return runs;
	}

	/** The alpha of one pixel, 0 for fully transparent. */
	private static int alpha(BufferedImage img, int x, int y)
	{
		return (img.getRGB(x, y) >>> 24) & 0xff;
	}

	/** How many pixels of the glyph are not fully transparent. */
	private static int ink(BufferedImage img)
	{
		int count = 0;
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				if (((img.getRGB(x, y) >>> 24) & 0xff) > 0)
				{
					count++;
				}
			}
		}
		return count;
	}

	/** The LEFT button going down on {@code target} - what a click starts with. */
	private static void press(Component target)
	{
		deliver(target, new MouseEvent(target, MouseEvent.MOUSE_PRESSED, 0L, 0, 1, 1, 1, false, MouseEvent.BUTTON1));
	}

	/** The RIGHT button going down: the start of the hero card's menu gesture (N3 b), never a press. */
	private static void rightPress(Component target)
	{
		deliver(target, new MouseEvent(target, MouseEvent.MOUSE_PRESSED, 0L, 0, 1, 1, 1, false, MouseEvent.BUTTON3));
	}

	/** The platform's popup trigger on the left button (macOS ctrl-click): a menu gesture, never a press. */
	private static void popupPress(Component target)
	{
		deliver(target, new MouseEvent(target, MouseEvent.MOUSE_PRESSED, 0L, 0, 1, 1, 1, true, MouseEvent.BUTTON1));
	}

	private static void deliver(Component target, MouseEvent e)
	{
		for (MouseListener l : target.getMouseListeners())
		{
			l.mousePressed(e);
		}
	}

	private static void enter(Component target)
	{
		for (MouseListener l : target.getMouseListeners())
		{
			l.mouseEntered(new MouseEvent(target, MouseEvent.MOUSE_ENTERED, 0L, 0, 1, 1, 0, false));
		}
	}

	private static void exit(Component target)
	{
		for (MouseListener l : target.getMouseListeners())
		{
			l.mouseExited(new MouseEvent(target, MouseEvent.MOUSE_EXITED, 0L, 0, 1, 1, 0, false));
		}
	}

	/** Runs the body on the EDT (where every widget here lives) and re-throws whatever it failed with. */
	private static void onEdt(Runnable body) throws Exception
	{
		final AtomicReference<Throwable> failure = new AtomicReference<>();
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				body.run();
			}
			catch (Throwable t)
			{
				failure.set(t);
			}
		});

		final Throwable t = failure.get();
		if (t instanceof Error)
		{
			throw (Error) t;
		}
		if (t instanceof Exception)
		{
			throw (Exception) t;
		}
		if (t != null)
		{
			throw new RuntimeException(t);
		}
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/**
 * {@link BankSnapshot} and {@link BankItem} (contract C5): the persisted bank, its repair pass, and the
 * round trip through the stock Gson that {@code PriceStore} writes.
 *
 * <p>{@link BankSnapshot#normalize()} is what lets every reader downstream skip its null checks, so each of
 * its clauses is pinned here separately - including the one that doubles as a feature: a bank PLACEHOLDER is
 * a quantity of 0 and disappears in the same sweep that drops corrupt rows (design D6).
 */
public class BankSnapshotTest
{
	private static BankSnapshot snapshot(final BankItem... items)
	{
		return new BankSnapshot(new ArrayList<>(Arrays.asList(items)), 1_700_000_000_000L, 123L, "STANDARD");
	}

	@Test
	public void aSnapshotCarriesItsStacksAndItsIdentity()
	{
		final BankSnapshot bank = snapshot(new BankItem(4151, 2, "Abyssal whip", false));

		assertFalse(bank.isEmpty());
		assertEquals(1, bank.items.size());
		assertEquals(4151, bank.items.get(0).id);
		assertEquals(2, bank.items.get(0).quantity);
		assertEquals("Abyssal whip", bank.items.get(0).name);
		assertFalse(bank.items.get(0).stackable);
		assertEquals(1_700_000_000_000L, bank.capturedAtMillis);
		assertEquals("the account the bank belongs to", 123L, bank.accountHash);
		assertEquals("STANDARD", bank.profileType);
	}

	@Test
	public void emptyIsTheNoBankYetSnapshot()
	{
		assertTrue(BankSnapshot.EMPTY.isEmpty());
		assertEquals(0, BankSnapshot.EMPTY.items.size());
		assertEquals(0L, BankSnapshot.EMPTY.capturedAtMillis);
		assertEquals(0L, BankSnapshot.EMPTY.accountHash);
		assertEquals(BankSnapshot.DEFAULT_PROFILE_TYPE, BankSnapshot.EMPTY.profileType);
	}

	@Test
	public void aFreshSnapshotIsUsableBeforeAnythingIsSet()
	{
		final BankSnapshot bank = new BankSnapshot();
		assertNotNull("the no-arg ctor Gson uses leaves a list, not a null", bank.items);
		assertTrue(bank.isEmpty());
		assertEquals(BankSnapshot.DEFAULT_PROFILE_TYPE, bank.profileType);
	}

	// ---------------------------------------------------------------- normalize

	@Test
	public void normalizeDropsNullEntries()
	{
		final BankSnapshot bank = snapshot(new BankItem(4151, 1, "Abyssal whip", false), null,
			new BankItem(2, 5, "Cannonball", true));

		bank.normalize();

		assertEquals(2, bank.items.size());
		assertEquals(4151, bank.items.get(0).id);
		assertEquals(2, bank.items.get(1).id);
	}

	@Test
	public void normalizeDropsNonPositiveIdsAndQuantities()
	{
		final BankSnapshot bank = snapshot(
			new BankItem(0, 5, "no id", false),
			new BankItem(-3, 5, "negative id", false),
			new BankItem(4151, 0, "a placeholder", false),
			new BankItem(4152, -2, "negative quantity", false),
			new BankItem(2, 1, "kept", true));

		bank.normalize();

		assertEquals(1, bank.items.size());
		assertEquals("only the sound row survives", 2, bank.items.get(0).id);
	}

	@Test
	public void normalizeNeverLeavesANullName()
	{
		final BankItem nameless = new BankItem();
		nameless.id = 4151;
		nameless.quantity = 1;
		nameless.name = null;

		final BankSnapshot bank = snapshot(nameless);
		bank.normalize();

		assertEquals(1, bank.items.size());
		assertEquals("", bank.items.get(0).name);
	}

	@Test
	public void normalizeFillsInAMissingProfileAndList()
	{
		final BankSnapshot bank = new BankSnapshot(null, -5L, 9L, null);
		bank.normalize();

		assertNotNull(bank.items);
		assertTrue(bank.isEmpty());
		assertEquals(BankSnapshot.DEFAULT_PROFILE_TYPE, bank.profileType);
		assertEquals(0L, bank.capturedAtMillis);
		assertEquals("the account is left alone", 9L, bank.accountHash);

		final BankSnapshot blankProfile = new BankSnapshot(new ArrayList<>(), 1L, 9L, "");
		blankProfile.normalize();
		assertEquals(BankSnapshot.DEFAULT_PROFILE_TYPE, blankProfile.profileType);
	}

	@Test
	public void normalizeKeepsAGoodSnapshotAsItIs()
	{
		final BankSnapshot bank = snapshot(new BankItem(4151, 2, "Abyssal whip", false),
			new BankItem(2, 5000, "Cannonball", true));

		bank.normalize();

		assertEquals(2, bank.items.size());
		assertEquals("Abyssal whip", bank.items.get(0).name);
		assertEquals(5000, bank.items.get(1).quantity);
		assertEquals(1_700_000_000_000L, bank.capturedAtMillis);
	}

	// ---------------------------------------------------------------- disk

	@Test
	public void theSnapshotRoundTripsThroughStockGson()
	{
		final Gson gson = new Gson();
		final BankSnapshot bank = snapshot(new BankItem(4151, 2, "Abyssal whip", false),
			new BankItem(2, 5000, "Cannonball", true));

		final BankSnapshot back = gson.fromJson(gson.toJson(bank), BankSnapshot.class);
		back.normalize();

		assertEquals(bank, back);
		assertEquals(2, back.items.size());
		assertEquals("Cannonball", back.items.get(1).name);
		assertTrue(back.items.get(1).stackable);
	}

	/**
	 * Back compat: a file written before {@code stackable} existed still parses, and the missing flag reads as
	 * false rather than stopping the load (the workspace rule for every persisted class).
	 */
	@Test
	public void jsonWithoutStackableParses()
	{
		final String json = "{\"items\":[{\"id\":4151,\"quantity\":2,\"name\":\"Abyssal whip\"}],"
			+ "\"capturedAtMillis\":17,\"accountHash\":123,\"profileType\":\"STANDARD\"}";

		final BankSnapshot bank = new Gson().fromJson(json, BankSnapshot.class);
		bank.normalize();

		assertEquals(1, bank.items.size());
		assertEquals(4151, bank.items.get(0).id);
		assertFalse("a field no old file has reads as false", bank.items.get(0).stackable);
		assertEquals(17L, bank.capturedAtMillis);
	}

	/**
	 * Back compat again, and this one has a consequence worth stating: {@code currencyGp} arrived with B097, so
	 * every {@code bank-*.json} written before it reads back as 0. A REMEMBERED bank - the login-screen and Grand
	 * Exchange case of D7 - therefore shows no coins until the player next opens a bank, which is the honest
	 * answer, because the stored file does not know how many there were.
	 */
	@Test
	public void aFileWrittenBeforeCurrencyExistedReadsZeroCurrency()
	{
		final String json = "{\"items\":[{\"id\":4151,\"quantity\":2,\"name\":\"Abyssal whip\",\"stackable\":false}],"
			+ "\"capturedAtMillis\":17,\"accountHash\":123,\"profileType\":\"STANDARD\"}";

		final BankSnapshot bank = new Gson().fromJson(json, BankSnapshot.class);
		bank.normalize();

		assertEquals("a field no old file has reads as 0", 0L, bank.currencyGp);
		assertEquals(1, bank.items.size());
	}

	/**
	 * B097: the worth of the coins and platinum tokens is part of the bank and survives the file, so a total drawn
	 * from a remembered bank counts the same cash the live one did.
	 */
	@Test
	public void currencyWorthRoundTripsThroughStockGson()
	{
		final Gson gson = new Gson();
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(Arrays.asList(
			new BankItem(4151, 2, "Abyssal whip", false))), 1_700_000_000_000L, 123L, "STANDARD", 200_000_000L);

		final BankSnapshot back = gson.fromJson(gson.toJson(bank), BankSnapshot.class);
		back.normalize();

		assertEquals(200_000_000L, back.currencyGp);
		assertEquals(bank, back);
	}

	/** A hand-edited or truncated file cannot make the bank worth less than nothing. */
	@Test
	public void normalizeClampsANegativeCurrencyToZero()
	{
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(), 1L, 9L, "STANDARD", -5L);

		bank.normalize();

		assertEquals(0L, bank.currencyGp);
	}

	/**
	 * The oldest shape imaginable: an item list and nothing else. normalize() has to make it usable.
	 */
	@Test
	public void jsonWithNothingButItemsParses()
	{
		final BankSnapshot bank = new Gson().fromJson("{\"items\":[{\"id\":2,\"quantity\":1}]}",
			BankSnapshot.class);
		bank.normalize();

		assertEquals(1, bank.items.size());
		assertEquals("", bank.items.get(0).name);
		assertEquals(BankSnapshot.DEFAULT_PROFILE_TYPE, bank.profileType);
		assertEquals(0L, bank.capturedAtMillis);
	}

	@Test
	public void anEmptyJsonObjectParsesIntoAnEmptySnapshot()
	{
		final BankSnapshot bank = new Gson().fromJson("{}", BankSnapshot.class);
		bank.normalize();

		assertTrue(bank.isEmpty());
		assertEquals(BankSnapshot.DEFAULT_PROFILE_TYPE, bank.profileType);
	}

	// ---------------------------------------------------------------- values

	@Test
	public void theSnapshotAndItsItemsCompare()
	{
		final List<BankItem> items = new ArrayList<>();
		items.add(new BankItem(4151, 2, "Abyssal whip", false));

		assertEquals(new BankItem(4151, 2, "Abyssal whip", false), items.get(0));
		assertEquals(new BankItem(4151, 2, "Abyssal whip", false).hashCode(), items.get(0).hashCode());
		assertNotEquals(new BankItem(4151, 3, "Abyssal whip", false), items.get(0));
		assertNotEquals(new BankItem(4151, 2, "Abyssal whip", true), items.get(0));

		assertEquals(new BankSnapshot(items, 5L, 9L, "STANDARD"), new BankSnapshot(
			new ArrayList<>(items), 5L, 9L, "STANDARD"));
		assertNotEquals(new BankSnapshot(items, 5L, 9L, "STANDARD"),
			new BankSnapshot(items, 5L, 10L, "STANDARD"));
		assertNotEquals(new BankSnapshot(items, 5L, 9L, "STANDARD"),
			new BankSnapshot(items, 5L, 9L, "BETA"));
	}

	@Test
	public void anItemsNullNameNeverReachesTheAllArgsConstructor()
	{
		assertEquals("", new BankItem(4151, 1, null, false).name);
	}

	/**
	 * The content test the service skips a repeated disk write with (B008). {@code equals} cannot serve: it
	 * compares the capture clock, which {@code BankReader} stamps with {@code System.currentTimeMillis()} on every
	 * capture, so two readings of an unchanged bank are never equal - and the client posts one
	 * {@code ItemContainerChanged} per change to the container, many of them carrying identical stacks.
	 */
	@Test
	public void sameContentAsIgnoresTheCaptureClockAndNothingElse()
	{
		final List<BankItem> items = Arrays.asList(new BankItem(4151, 1, "Abyssal whip", false),
			new BankItem(385, 500, "Shark", true));
		final BankSnapshot first = new BankSnapshot(new ArrayList<>(items), 1_000L, 7L, "STANDARD");
		final BankSnapshot again = new BankSnapshot(new ArrayList<>(items), 9_999L, 7L, "STANDARD");

		assertTrue("the same stacks, captured later", first.sameContentAs(again));
		assertNotEquals("but not equal: a persisted snapshot must be told apart from a re-reading of it",
			first, again);

		final List<BankItem> more = new ArrayList<>(items);
		more.add(new BankItem(1042, 1, "Blue partyhat", false));
		assertFalse("a stack added", first.sameContentAs(new BankSnapshot(more, 1_000L, 7L, "STANDARD")));
		assertFalse("a quantity changed", first.sameContentAs(new BankSnapshot(
			Arrays.asList(new BankItem(4151, 1, "Abyssal whip", false), new BankItem(385, 499, "Shark", true)),
			1_000L, 7L, "STANDARD")));
		assertFalse("another account", first.sameContentAs(new BankSnapshot(new ArrayList<>(items), 1_000L, 8L, "STANDARD")));
		assertFalse("another profile", first.sameContentAs(new BankSnapshot(new ArrayList<>(items), 1_000L, 7L, "LEAGUE")));
		assertFalse("nothing at all", first.sameContentAs(null));
		assertTrue("and itself", first.sameContentAs(first));
	}

	// ---------------------------------------------------------------- addendum Y: the carried half

	private static final BankItem WHIP = new BankItem(4151, 1, "Abyssal whip", false);
	private static final BankItem SHARK = new BankItem(385, 3, "Shark", true);
	private static final BankItem HELM = new BankItem(1163, 1, "Rune full helm", false);

	private static BankReader.Carried carried()
	{
		return new BankReader.Carried(Arrays.asList(SHARK), Arrays.asList(HELM), 791_078L, 1_700_000_009_000L);
	}

	/** Y2: a fresh snapshot has an inventory and a worn list, not two nulls - the no-arg ctor is Gson's. */
	@Test
	public void aFreshSnapshotCarriesNothingRatherThanNull()
	{
		final BankSnapshot bank = new BankSnapshot();

		assertNotNull(bank.inventory);
		assertNotNull(bank.worn);
		assertTrue(bank.inventory.isEmpty());
		assertTrue(bank.worn.isEmpty());
		assertEquals(0L, bank.carriedGp);
		assertEquals(0L, bank.carriedAtMillis);
		assertTrue(BankSnapshot.EMPTY.inventory.isEmpty());
		assertTrue(BankSnapshot.EMPTY.worn.isEmpty());
	}

	/**
	 * Y2: {@code withCarried} replaces the carried part and touches nothing of the bank's - the stacks, the capture
	 * clock (the footnote's "bank HH:MM"), the cash and the account all stay exactly as they were, which is what
	 * lets Refresh republish the STORED bank beside a fresh inventory.
	 */
	@Test
	public void withCarriedReplacesTheCarriedPartAndLeavesTheBankAlone()
	{
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(Arrays.asList(WHIP)), 1_700_000_000_000L, 123L,
			"STANDARD", 500L);

		final BankSnapshot next = bank.withCarried(carried());

		assertEquals("the bank's own stacks are untouched", 1, next.items.size());
		assertEquals(1_700_000_000_000L, next.capturedAtMillis);
		assertEquals(123L, next.accountHash);
		assertEquals("STANDARD", next.profileType);
		assertEquals("the bank's own cash is untouched", 500L, next.currencyGp);
		assertEquals(Arrays.asList(SHARK), next.inventory);
		assertEquals(Arrays.asList(HELM), next.worn);
		assertEquals(791_078L, next.carriedGp);
		assertEquals("its own clock, not the bank's", 1_700_000_009_000L, next.carriedAtMillis);
		assertTrue("a copy, never a mutation: the snapshot the panel holds must not change under it",
			bank.inventory.isEmpty());
	}

	/** Y2: a read with no client logged in never happens, and a null still clears rather than throwing. */
	@Test
	public void withCarriedNullClearsTheCarriedPart()
	{
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(Arrays.asList(WHIP)), 1L, 123L, "STANDARD")
			.withCarried(carried());

		final BankSnapshot cleared = bank.withCarried(null);

		assertTrue(cleared.inventory.isEmpty());
		assertTrue(cleared.worn.isEmpty());
		assertEquals(0L, cleared.carriedGp);
		assertEquals(0L, cleared.carriedAtMillis);
		assertEquals("and the bank part is still there", 1, cleared.items.size());
	}

	/** Y2: the carried lists go through the same repair pass the bank's stacks do. */
	@Test
	public void normalizeCleansTheCarriedListsAndClampsTheirFigures()
	{
		final BankItem nameless = new BankItem();
		nameless.id = 4151;
		nameless.quantity = 1;
		nameless.name = null;
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(), 1L, 9L, "STANDARD", 0L,
			new ArrayList<>(Arrays.asList(nameless, null, new BankItem(2, 0, "a placeholder", true))),
			new ArrayList<>(Arrays.asList(new BankItem(-1, 5, "no id", false), HELM)), -5L, -9L);

		bank.normalize();

		assertEquals(1, bank.inventory.size());
		assertEquals("", bank.inventory.get(0).name);
		assertEquals(1, bank.worn.size());
		assertEquals(1163, bank.worn.get(0).id);
		assertEquals(0L, bank.carriedGp);
		assertEquals(0L, bank.carriedAtMillis);
	}

	/** Gson leaves an absent field null when it does not use the no-arg constructor; normalize answers for both. */
	@Test
	public void normalizeTurnsNullCarriedListsIntoEmptyOnes()
	{
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(), 1L, 9L, "STANDARD", 0L, null, null, 0L, 0L);

		bank.normalize();

		assertNotNull(bank.inventory);
		assertNotNull(bank.worn);
		assertTrue(bank.inventory.isEmpty());
		assertTrue(bank.worn.isEmpty());
	}

	/**
	 * Y2: the carried half is CONTENT. A Refresh that finds a different inventory has to be written, or the file
	 * would keep saying the old one and the next launch would draw a bank nobody has.
	 */
	@Test
	public void sameContentAsCoversTheCarriedHalf()
	{
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(Arrays.asList(WHIP)), 1_000L, 7L, "STANDARD");
		final BankSnapshot withCarried = bank.withCarried(carried());

		assertFalse("an inventory appeared", bank.sameContentAs(withCarried));
		assertFalse("and the other way round", withCarried.sameContentAs(bank));
		assertTrue("the same carried half, read again a moment later",
			withCarried.sameContentAs(bank.withCarried(new BankReader.Carried(Arrays.asList(SHARK),
				Arrays.asList(HELM), 791_078L, 1_700_000_099_000L))));
		assertFalse("one shark eaten", withCarried.sameContentAs(bank.withCarried(new BankReader.Carried(
			Arrays.asList(new BankItem(385, 2, "Shark", true)), Arrays.asList(HELM), 791_078L, 1L))));
		assertFalse("the helm taken off", withCarried.sameContentAs(bank.withCarried(new BankReader.Carried(
			Arrays.asList(SHARK), new ArrayList<>(), 791_078L, 1L))));
		assertFalse("coins spent", withCarried.sameContentAs(bank.withCarried(new BankReader.Carried(
			Arrays.asList(SHARK), Arrays.asList(HELM), 5L, 1L))));
	}

	/** Y2/Y5: the carried half survives the file, so the switch can be flipped without a bank visit. */
	@Test
	public void theCarriedHalfRoundTripsThroughStockGson()
	{
		final Gson gson = new Gson();
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(Arrays.asList(WHIP)), 1_700_000_000_000L, 123L,
			"STANDARD", 500L).withCarried(carried());

		final BankSnapshot back = gson.fromJson(gson.toJson(bank), BankSnapshot.class);
		back.normalize();

		assertEquals(Arrays.asList(SHARK), back.inventory);
		assertEquals(Arrays.asList(HELM), back.worn);
		assertEquals(791_078L, back.carriedGp);
		assertEquals(1_700_000_009_000L, back.carriedAtMillis);
		assertEquals(bank, back);
	}

	/**
	 * Back compat, the addendum-Y edition: a {@code bank-*.json} written before the four fields existed reads as
	 * "carrying nothing" and draws exactly the bank it always did.
	 */
	@Test
	public void aFileWrittenBeforeTheCarriedHalfExistedReadsAsCarryingNothing()
	{
		final String json = "{\"items\":[{\"id\":4151,\"quantity\":1,\"name\":\"Abyssal whip\",\"stackable\":false}],"
			+ "\"capturedAtMillis\":17,\"accountHash\":123,\"profileType\":\"STANDARD\",\"currencyGp\":500}";

		final BankSnapshot bank = new Gson().fromJson(json, BankSnapshot.class);
		bank.normalize();

		assertNotNull(bank.inventory);
		assertNotNull(bank.worn);
		assertTrue(bank.inventory.isEmpty());
		assertTrue(bank.worn.isEmpty());
		assertEquals(0L, bank.carriedGp);
		assertEquals(0L, bank.carriedAtMillis);
		assertEquals(500L, bank.currencyGp);
		assertEquals(1, bank.items.size());
	}

	/** A bank with no carried half prints exactly what it printed before addendum Y. */
	@Test
	public void toStringNamesTheCarriedHalfOnlyWhenThereIsOne()
	{
		final BankSnapshot bank = new BankSnapshot(new ArrayList<>(Arrays.asList(WHIP)), 17L, 123L, "STANDARD", 500L);

		assertEquals("BankSnapshot{items=1, capturedAtMillis=17, accountHash=123, profileType='STANDARD',"
			+ " currencyGp=500}", bank.toString());
		assertEquals("BankSnapshot{items=1, capturedAtMillis=17, accountHash=123, profileType='STANDARD',"
			+ " currencyGp=500, inventory=1, worn=1, carriedGp=791078}", bank.withCarried(carried()).toString());
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

/**
 * {@link MovementWindow} after addendum L (contract line L9): the five Grand Exchange windows, the CALENDAR
 * arithmetic that names the date a baseline is chosen for, and the legacy spellings a first-build profile still
 * holds.
 *
 * <p><b>Why the seconds are gone.</b> Addendum K's {@code targetFor(nowSeconds) = nowSeconds - seconds} was
 * measured against live data by six analysts and lands on the intended Jagex day only 50-56 % of clock hours,
 * because the wiki's price bot publishes day D's table at a random hour of day D (L-C). The GE site's own
 * arithmetic is over calendar days - {@code (daily[D] - daily[D-N]) / daily[D-N]} (L-B) - so a window is now a
 * count of DAYS taken off an anchor DATE that {@code PriceService} derives from the data (L3).
 *
 * <p>The legacy parse tests are the other load-bearing ones. A user who ran the first build has
 * {@code window=H24} written into their RuneLite config; {@code ConfigManager} reads an enum back with
 * {@code Enum.valueOf}, and an unknown constant there is how this workspace has already NPE'd a config panel
 * once (CLAUDE.md, "Config interfaces must be FLAT"). Every one of the four old spellings has to land on a
 * window that exists.
 */
public class MovementWindowTest
{
	/** 2026-09-07, the anchor day the calibration run's newest table belonged to. */
	private static final LocalDate ANCHOR = LocalDate.of(2026, 9, 7);

	@Test
	public void theFiveWindowsCarryTheirLabelAndSpan()
	{
		assertEquals("1d", MovementWindow.D1.label());
		assertEquals("7d", MovementWindow.D7.label());
		assertEquals("30d", MovementWindow.D30.label());
		assertEquals("90d", MovementWindow.D90.label());
		assertEquals("180d", MovementWindow.D180.label());

		assertEquals(1, MovementWindow.D1.days());
		assertEquals(7, MovementWindow.D7.days());
		assertEquals(30, MovementWindow.D30.days());
		assertEquals(90, MovementWindow.D90.days());
		assertEquals(180, MovementWindow.D180.days());

		assertEquals("the GE site's own spans: today, a week, 1 month, 3 months, 6 months",
			5, MovementWindow.values().length);
	}

	/**
	 * The label a chip draws and the number the arithmetic uses have to agree: "30d" that looked back 90 days
	 * would be a silently wrong figure on every row, not a failure anybody would see.
	 */
	@Test
	public void everyLabelIsItsOwnDayCountAndTheyIncrease()
	{
		int previous = 0;
		for (final MovementWindow window : MovementWindow.values())
		{
			assertEquals(window + " must look back exactly as far as its label says",
				window.label(), window.days() + "d");
			assertTrue(window + " must be longer than the window before it", window.days() > previous);
			previous = window.days();
		}
	}

	/**
	 * The hourly windows are gone with the trade API: the guide table is a step function stamped once a DAY, so
	 * an hour-wide window would put both ends on the same step and read 0.0 % for every item in the bank.
	 */
	@Test
	public void noWindowIsShorterThanADay()
	{
		for (final MovementWindow window : MovementWindow.values())
		{
			assertTrue(window + " is shorter than one guide-price step", window.days() >= 1);
		}
	}

	/**
	 * The config combo box and the sidebar chip both read {@code toString()}; the STORED value is the constant
	 * name, which {@code ConfigManager.java:1279-1281} writes and {@code :1205-1207} reads.
	 */
	@Test
	public void toStringIsTheLabelWhileTheNameIsUnchanged()
	{
		assertEquals("1d", MovementWindow.D1.toString());
		assertEquals("D1", MovementWindow.D1.name());
		assertSame(MovementWindow.D1, MovementWindow.valueOf("D1"));
		assertEquals("180d", MovementWindow.D180.toString());
		assertEquals("D180", MovementWindow.D180.name());
	}

	@Test
	public void theDefaultIsTheGeSitesTodayFigure()
	{
		assertSame(MovementWindow.D1, MovementWindow.DEFAULT);
	}

	// ---- targetDate (L9)

	@Test
	public void theTargetIsThatManyCalendarDaysBeforeTheAnchor()
	{
		assertEquals(LocalDate.of(2026, 9, 6), MovementWindow.D1.targetDate(ANCHOR));
		assertEquals(LocalDate.of(2026, 8, 31), MovementWindow.D7.targetDate(ANCHOR));
		assertEquals(LocalDate.of(2026, 8, 8), MovementWindow.D30.targetDate(ANCHOR));
		assertEquals(LocalDate.of(2026, 6, 9), MovementWindow.D90.targetDate(ANCHOR));
		assertEquals(LocalDate.of(2026, 3, 11), MovementWindow.D180.targetDate(ANCHOR));
	}

	/**
	 * Calendar arithmetic, not a multiple of 86,400 seconds: a window that spans a month end or a leap day has
	 * to land on the date a reader would count to, which is what the GE site's own figures are computed over.
	 */
	@Test
	public void theTargetCrossesMonthEndsAndLeapDaysTheWayACalendarDoes()
	{
		assertEquals(LocalDate.of(2026, 2, 28), MovementWindow.D1.targetDate(LocalDate.of(2026, 3, 1)));
		assertEquals("2024 was a leap year", LocalDate.of(2024, 2, 29),
			MovementWindow.D1.targetDate(LocalDate.of(2024, 3, 1)));
		assertEquals(LocalDate.of(2025, 12, 31), MovementWindow.D1.targetDate(LocalDate.of(2026, 1, 1)));
		assertEquals(LocalDate.of(2025, 9, 8), MovementWindow.D180.targetDate(LocalDate.of(2026, 3, 7)));
	}

	@Test
	public void everyWindowLooksBackwardsAndTheLongerOneLooksFurther()
	{
		LocalDate previous = ANCHOR;
		for (final MovementWindow window : MovementWindow.values())
		{
			final LocalDate target = window.targetDate(ANCHOR);
			assertTrue(window + " must look BACKWARDS", target.isBefore(ANCHOR));
			assertTrue(window + " must look further back than the window before it", target.isBefore(previous));
			previous = target;
		}
	}

	/**
	 * No anchor day yet means no target date, which means no baseline and a "-" in the change column. Guessing a
	 * date from the wall clock here is exactly the coin flip addendum L removed (L3).
	 */
	@Test
	public void noAnchorDayMeansNoTargetDate()
	{
		for (final MovementWindow window : MovementWindow.values())
		{
			assertNull(window + " must not invent an anchor", window.targetDate(null));
		}
	}

	// ---- parse (K4)

	@Test
	public void parseTakesLabelsNamesAndCasing()
	{
		assertSame(MovementWindow.D1, MovementWindow.parse("1d"));
		assertSame(MovementWindow.D7, MovementWindow.parse("7d"));
		assertSame(MovementWindow.D30, MovementWindow.parse("30d"));
		assertSame(MovementWindow.D90, MovementWindow.parse("90d"));
		assertSame(MovementWindow.D180, MovementWindow.parse("180d"));

		assertSame(MovementWindow.D1, MovementWindow.parse("D1"));
		assertSame(MovementWindow.D30, MovementWindow.parse("d30"));
		assertSame(MovementWindow.D180, MovementWindow.parse("  D180  "));
	}

	/**
	 * The reason this method exists at all: {@code window=H24} is sitting in the user's RuneLite profile from
	 * the first build, and H1 / H24 name nothing now. All four spellings collapse onto 1d - an hour is below the
	 * resolution of the guide series, and 24 h IS the new 1d.
	 */
	@Test
	public void theFourPreAddendumKSpellingsAllLandOnOneDay()
	{
		assertSame("the stored config value from the first build", MovementWindow.D1, MovementWindow.parse("H24"));
		assertSame(MovementWindow.D1, MovementWindow.parse("h24"));
		assertSame("the old chip text", MovementWindow.D1, MovementWindow.parse("24h"));
		assertSame(MovementWindow.D1, MovementWindow.parse("H1"));
		assertSame(MovementWindow.D1, MovementWindow.parse("h1"));
		assertSame(MovementWindow.D1, MovementWindow.parse("1h"));
		assertSame(MovementWindow.D1, MovementWindow.parse("  24H  "));
	}

	/** "7d" and "D7" meant the same window before addendum K and still do - the one value that carries over. */
	@Test
	public void theOldSevenDayWindowSurvivesUnchanged()
	{
		assertSame(MovementWindow.D7, MovementWindow.parse("7d"));
		assertSame(MovementWindow.D7, MovementWindow.parse("D7"));
		assertEquals(7, MovementWindow.D7.days());
	}

	@Test
	public void parseAnswersNullRatherThanGuessing()
	{
		assertNull(MovementWindow.parse(null));
		assertNull(MovementWindow.parse(""));
		assertNull(MovementWindow.parse("   "));
		assertNull(MovementWindow.parse("1"));
		assertNull(MovementWindow.parse("d"));
		assertNull(MovementWindow.parse("12h"));
		assertNull(MovementWindow.parse("2d"));
		assertNull(MovementWindow.parse("365d"));
		assertNull(MovementWindow.parse("week"));
	}

	@Test
	public void parseRoundTripsEveryLabelAndName()
	{
		for (final MovementWindow window : MovementWindow.values())
		{
			assertSame(window, MovementWindow.parse(window.label()));
			assertSame(window, MovementWindow.parse(window.name()));
			assertSame(window, MovementWindow.parse(window.toString()));
		}
	}

	/** Two windows sharing a label or a name would make the chips and the stored value ambiguous. */
	@Test
	public void everyLabelAndNameIsUnique()
	{
		final Set<String> seen = new HashSet<>();
		for (final MovementWindow window : MovementWindow.values())
		{
			assertTrue("duplicate label " + window.label(), seen.add(window.label()));
			assertTrue("duplicate name " + window.name(), seen.add(window.name()));
		}
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

/**
 * {@link NavIcon} (contract C34): the sidebar button's icon - the ONLY way a user reaches this plugin.
 *
 * <p><b>Why this file exists.</b> Its whole coverage was one {@code assertNotNull} on
 * {@code NavigationButton.getIcon()} in the wiring test, which a fully transparent 16 x 16 image satisfies. A
 * {@code setColor} moved after the fills, an alpha-0 colour or coordinates pushed off the raster while chasing
 * a crisper arrow would leave the user relaunching to a blank square in the sidebar with nothing to tell it
 * from a broken plugin, and every test would pass. So the ink is counted, and counted WHERE the bars and the
 * arrow are drawn - a global count alone would survive one bar going missing.
 *
 * <p>No golden bitmap: the arrow is stroked with antialiasing and {@code STROKE_PURE}, whose exact pixels
 * drift between JDK builds. This is the same idiom {@code WidgetsTest} uses for the panel's drawn glyphs, and
 * like that one it proves the drawing needs no display.
 */
public class NavIconTest
{
	@Test
	public void theIconIsSixteenSquareArgbAndHasOrangeInkInEveryBarAndTheArrow()
	{
		final BufferedImage img = NavIcon.create();
		assertEquals(NavIcon.SIZE, img.getWidth());
		assertEquals(NavIcon.SIZE, img.getHeight());
		assertEquals("16 x 16 ARGB, what NavigationButton.builder().icon(...) takes",
			BufferedImage.TYPE_INT_ARGB, img.getType());

		// The three fillRects alone are 3x6 + 3x9 + 3x12 = 81 opaque pixels, and fillRect is not antialiased, so
		// 81 is a hard floor before the arrow adds anything: 60 leaves real slack and still catches a blank icon.
		assertTrue("the icon put " + ink(img) + " px of ink down", ink(img) > 60);

		// One bar at a time: the three columns the bars stand in, on the bottom row they all reach.
		assertTrue("the short bar is missing", opaque(img, 1, 4, 15, 16));
		assertTrue("the middle bar is missing", opaque(img, 6, 9, 15, 16));
		assertTrue("the tall bar is missing", opaque(img, 11, 14, 15, 16));
		// ...and the arrow, which lives in the top-left quadrant above every bar.
		assertTrue("the arrow is missing", opaque(img, 0, 10, 0, 6));

		assertTrue("nothing is drawn in the brand colour", hasColour(img, ColorScheme.BRAND_ORANGE));
		assertEquals("the ground stays transparent", 0, img.getRGB(0, 0) >>> 24);
	}

	/**
	 * The javadoc's promise: a fresh image per call, so a plugin restart never shares a bitmap with a button
	 * already removed. Proved by writing into one and reading the other, not by {@code !=} - which any
	 * {@code new BufferedImage} satisfies and which therefore pins nothing.
	 */
	@Test
	public void everyCallDrawsItsOwnImage()
	{
		final BufferedImage first = NavIcon.create();
		final BufferedImage second = NavIcon.create();
		assertNotSame(first, second);
		final int was = second.getRGB(0, 0);
		first.setRGB(0, 0, Color.WHITE.getRGB());
		assertEquals("the two share no raster", was, second.getRGB(0, 0));
	}

	/** How many pixels are not fully transparent. */
	private static int ink(BufferedImage img)
	{
		int n = 0;
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					n++;
				}
			}
		}
		return n;
	}

	/** Whether any pixel in [x0, x1) x [y0, y1) has ink in it. */
	private static boolean opaque(BufferedImage img, int x0, int x1, int y0, int y1)
	{
		for (int x = x0; x < x1; x++)
		{
			for (int y = y0; y < y1; y++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static boolean hasColour(BufferedImage img, Color colour)
	{
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				final int argb = img.getRGB(x, y);
				if (((argb >>> 24) & 0xff) == 0xff && (argb & 0xffffff) == (colour.getRGB() & 0xffffff))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.bankpricemovement;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
