	/**
	 * AA1: the fifteenth key opens the fold on a fresh profile, which is the whole of the user's request - the
	 * three quick bands became editable one wave ago, and a control that starts folded away is a control nobody
	 * finds ("can you by default have 'All items' expanded too so the user can see the quick price presets on the
	 * main tab? ... currently it starts minimized").
	 *
	 * <p>It is not a {@link RowFilter} field and never could be: the fold is where a band is TYPED, so opening or
	 * closing it moves no row - {@code gpMin} and {@code gpMax} keep whatever was last applied, and a closed fold
	 * still filters. Nor is it a {@link ViewOptions} field: no figure is recomputed for it.
	 */
	@Test
	public void theFoldOpensByDefaultAndIsNeitherAFilterFieldNorAViewOption()
	{
		final BankPriceMovementConfig config = new BankPriceMovementConfig()
		{
		};
		assertTrue("the price fold is open on a fresh profile (AA1)", config.foldOpen());
		assertEquals(RowFilter.DEFAULT, new RowFilter(config.gpMin(), config.gpMax(), config.sortMode(),
			config.sortDescending(), config.window()));
		assertEquals(ViewOptions.DEFAULT, optionsOf(config));
	}

	/**
	 * AA1's exact words, in the nouns addendum AB line AB3 chose. The settings page is the ONLY place this switch
	 * is named - the sidebar's own way to it is the band button, which carries no label for the fold - so the name
	 * says what is shown ("Show preset price ranges") and the description says both halves: what stays open, and
	 * the gesture that closes it. It borrows the name of the item above it on purpose: AB3 renamed those three
	 * boxes and this row is the one that uncovers them, so the two rows a reader meets together name one thing.
	 * Position 3 puts it directly after "Preset price ranges", the item whose three bands it decides the
	 * visibility of.
	 */
	@Test
	public void theFoldItemIsNamedAndDescribedAsAddendumAaWroteIt()
	{
		final ConfigItem fold = item("foldOpen");
		assertEquals("Show preset price ranges", fold.name());
		assertEquals("Keep the preset price ranges and the Min / Max fields open under the sort button."
			+ " Clicking the band button folds them away or back.", fold.description());
		assertEquals("the row and the row it uncovers name one thing (AB3)",
			BankPriceMovementPanel.PRESETS_TEXT, item("bandPresets").name());
		assertTrue("...and this one says SHOW of those ranges",
			fold.name().startsWith("Show ") && fold.name().endsWith("price ranges"));
		assertEquals(3, fold.position());
		// Directly after the presets it uncovers, and directly before the sort column - the pair a reader meets
		// them as on the settings page.
		assertEquals(2, item("bandPresets").position());
		assertEquals(4, item("sortMode").position());
	}

	/**
	 * The five view switches read off a config, in the order and arity
	 * {@code BankPriceMovementPlugin.optionsFromConfig()} reads them - which is the point of doing it here rather
	 * than writing the constructor out in each test: five booleans in a row are five chances to pin the wrong
	 * round trip, and addendum AO line AO1 removed a field from the MIDDLE of that list, where a stale call
	 * would still have compiled.
	 */
	private static ViewOptions optionsOf(BankPriceMovementConfig config)
	{
		return new ViewOptions(config.countCash(), config.countUntradeables(), config.livePrices(),
			config.countInventory(), config.showHoverText());
	}

	/** The {@code @ConfigItem} of one stored key, by name; fails rather than returning null when it is gone. */
	private static ConfigItem item(String keyName)
	{
		for (Method m : itemMethods())
		{
			final ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (keyName.equals(item.keyName()))
			{
				return item;
			}
		}
		throw new AssertionError("no config item declares the key " + keyName);
	}

	/**
	 * W4: the config panel and the sidebar are the same switch, so they speak the same language - and since
	 * addendum W that language is four column names, which the settings dropdown prints for itself
	 * ({@link SortMode#toString()} is the label). So the description's job is only to name the set, and to teach
	 * the one gesture a settings page cannot show: pressing the lit column again flips the direction.
	 *
	 * <p>This replaces the test that demanded every one of addendum N's six invented sentences ("Biggest
	 * gainers", "Cheapest") appear here. They existed because the pair was undiscoverable in the sidebar; the
	 * arrow of W2 is what made it discoverable, and the sentences went with the {@code SortOrder} enum.
	 */
	@Test
	public void theSortColumnItemNamesTheFourColumnsAndTheFlip()
	{
		final ConfigItem sort = item("sortMode");
		assertEquals("Sort column", sort.name());
		assertEquals("Which column the list is ordered on: Percent change, gp change, Item price or Stack price -"
			+ " pressing the lit column again in the sidebar flips the direction.", sort.description());
		assertEquals(4, sort.position());
		// ...and the four are the four the enum has, so a column added later cannot go unnamed here.
		for (SortMode mode : SortMode.values())
		{
			assertTrue("the settings page never names the sidebar's \"" + mode.label() + "\":\n"
				+ sort.description(), sort.description().contains(mode.label()));
		}
	}

	/**
	 * W4, the direction half: "Biggest first" is the arrow the sort button draws (W2), and the arrow is the only
	 * place the direction is visible in the sidebar - so the description names BOTH ends of the switch and which
	 * way the arrow points at each, rather than leaving a user to tick it and go and look.
	 */
	@Test
	public void theSortDirectionItemNamesBiggestFirstAndTheArrow()
	{
		final ConfigItem descending = item("sortDescending");
		assertEquals("Biggest first", descending.name());
		assertEquals("On is biggest first and the sidebar's arrow points down; off is smallest first and it"
			+ " points up. Items with nothing to sort on always come last.", descending.description());
		assertEquals(5, descending.position());
	}

	/**
	 * O1: the {@code look} item is gone with the One Bar design, and so is its enum. A profile written by the
	 * addendum-N build may still hold the KEY - {@link BankPriceMovementPlugin#unstickLook()} sweeps it at
	 * startUp - but no item here may ever declare it again, or a stale design name would be read back into
	 * something new.
	 */
	@Test
	public void theLookItemIsGone()
	{
		for (Method m : itemMethods())
		{
			assertFalse("the look config item was deleted by addendum O (O1)",
				BankPriceMovementPlugin.LEGACY_LOOK_KEY.equals(m.getAnnotation(ConfigItem.class).keyName()));
		}
	}

	/**
	 * AO1, the same guard for the second key this plugin has deleted for good: {@code holdingOnRows} ("Show stack
	 * value on rows", addendum Q line Q3) chose whether a row printed the per-ITEM reading or the per-STACK one, and
	 * addendum AN's three-line row prints both - line 2 is the stack, line 3 is one item - so the switch reached
	 * nothing drawn and the user, asked whether to keep it, answered "if it doesnt do anything anymore then
	 * remove it".
	 *
	 * <p>A profile written before addendum AO may still hold the KEY -
	 * {@link BankPriceMovementPlugin#unstickHolding()} sweeps it at startUp, exactly as
	 * {@link BankPriceMovementPlugin#unstickLook()} sweeps addendum N's - but no item here may ever declare it
	 * again. This file is where a deleted key coming back by a merge is caught: the set assertion above would
	 * fail too, and would be read as "somebody forgot to update the list", which is the wrong reading and the
	 * reason this test says which addendum took it and why.
	 *
	 * <p>Nothing replaces it. The one behaviour it still had is now unconditional: {@link SortMode#GP_MOVE}
	 * compares {@code MovementRow.holdingDeltaGp()} - the whole STACK's move - under every setting, which is
	 * what the switch gave when it was ON rather than the per-item reading it defaulted to. That is a
	 * user-visible change to one column's ordering, and there is no key left to undo it with.
	 */
	@Test
	public void theHoldingSwitchIsGone()
	{
		for (Method m : itemMethods())
		{
			assertFalse("the holdingOnRows config item was deleted by addendum AO (AO1)",
				BankPriceMovementPlugin.LEGACY_HOLDING_KEY.equals(m.getAnnotation(ConfigItem.class).keyName()));
		}
		assertFalse("...and no item may declare it under the old name either",
			EXPECTED_KEYS.contains(BankPriceMovementPlugin.LEGACY_HOLDING_KEY));
	}
}

package com.bankpricemovement;

import java.awt.Component;
import java.awt.Dimension;
import javax.swing.JComponent;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.PluginPanel;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static com.bankpricemovement.SidebarViewPanelTest.NOW;
import static com.bankpricemovement.SidebarViewPanelTest.VALUE_NOW;
import static com.bankpricemovement.SidebarViewPanelTest.find;
import static com.bankpricemovement.SidebarViewPanelTest.onEdt;
import static com.bankpricemovement.SidebarViewPanelTest.rows;
import static com.bankpricemovement.SidebarViewPanelTest.status;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

/**
 * Amendment 9.8: the pinned header reserves the gutter of the SHOWING card's scroll bar - the History card has a
 * scroll pane of its own - so the header's cards end on the same pixel as whichever list is under them, and the
 * gutter follows the toggle both ways.
 *
 * <p>The History column is made tall by giving it a preferred height from here, so the proof does not depend on what
 * the History view itself draws.
 */
public class SidebarViewGutterTest
{
	private static final int OUTER = PluginPanel.PANEL_WIDTH + PluginPanel.SCROLLBAR_WIDTH;

	private PriceService service;
	private BankPriceMovementPanel panel;
	private PriceService.Listener listener;

	@Before
	public void setUp() throws Exception
	{
		service = mock(PriceService.class);
		final SidebarViewPanelTest.Prefs prefs = new SidebarViewPanelTest.Prefs();
		onEdt(() ->
		{
			panel = new BankPriceMovementPanel(mock(ItemManager.class), service, prefs);
			panel.setClock(() -> NOW);
		});
		final ArgumentCaptor<PriceService.Listener> captor = ArgumentCaptor.forClass(PriceService.Listener.class);
		verify(service).addListener(captor.capture());
		listener = captor.getValue();
	}

	@After
	public void tearDown() throws Exception
	{
		onEdt(() -> panel.stop());
	}

	@Test
	public void theHeaderReservesTheGutterOfTheListThatIsShowing() throws Exception
	{
		onEdt(() -> listener.onRows(rows(3), status(BankHistorySeries.EMPTY, VALUE_NOW, NOW - 60_000L)));
		onEdt(() ->
		{
			layout();
			assertFalse("three rows do not scroll", panel.scrollPane().getVerticalScrollBar().isVisible());
			assertEquals(0, panel.gutter());

			historyColumn().setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, 3_000));
			panel.pressView(SidebarView.HISTORY);
			layout();
			final JScrollBar bar = historyScroll().getVerticalScrollBar();
			assertTrue("the fixture has to actually scroll in History", bar.isVisible());
			assertTrue(bar.getWidth() > 0);
			assertEquals("the header reserves the History list's bar", bar.getWidth(), panel.gutter());

			panel.pressView(SidebarView.ITEMS);
			layout();
			assertEquals("...and hands it back over the short item list", 0, panel.gutter());
		});

		onEdt(() -> listener.onRows(rows(40), status(BankHistorySeries.EMPTY, VALUE_NOW, NOW - 30_000L)));
		onEdt(() ->
		{
			historyColumn().setPreferredSize(null);
			layout();
			final JScrollBar bar = panel.scrollPane().getVerticalScrollBar();
			assertTrue("forty rows scroll", bar.isVisible());
			assertEquals(bar.getWidth(), panel.gutter());

			panel.pressView(SidebarView.HISTORY);
			layout();
			assertFalse("the short History card does not scroll", historyScroll().getVerticalScrollBar().isVisible());
			assertEquals("the hidden item list's bar is not the header's business", 0, panel.gutter());
		});
	}

	private void layout()
	{
		panel.setSize(OUTER, 900);
		LookRenderer.layoutTree(panel);
		LookRenderer.layoutTree(panel);
	}

	/** The column the History view is mounted in (amendment 9.8). */
	private JComponent historyColumn()
	{
		final BankHistoryView view = find(panel, BankHistoryView.class);
		assertNotNull("the History view is mounted", view);
		return (JComponent) view.getParent();
	}

	private JScrollPane historyScroll()
	{
		final Component pane = SwingUtilities.getAncestorOfClass(JScrollPane.class, find(panel, BankHistoryView.class));
		assertNotNull(pane);
		return (JScrollPane) pane;
	}
}

package com.bankpricemovement;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * {@link BandPresets} (addendum Z line Z1): the immutable carrier of the fold's three quick bands, the pure half
 * of the gear menu's three boxes, of the {@code bandPresets} config line and of the {@code presets=} dev verb.
 *
 * <p>Four groups: what the DEFAULT is (the trio the fold has drawn since addendum N, so a profile that never
 * touches the new line sees today's chips byte for byte), what {@link BandPresets#parse(String)} reads, the three
 * refusals - not three values, not positive, not distinct - and what the value writes back out.
 */
public class BandPresetsTest
{
	/** The trio {@code PRESET_MINS} held before addendum Z made it a config line. */
	@Test
	public void theDefaultIsTheTrioTheFoldHasAlwaysDrawn()
	{
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L}, BandPresets.DEFAULT.mins());
		assertEquals("100k, 1m, 10m", BandPresets.DEFAULT.format());
		assertEquals("the config line's default parses back to the default", BandPresets.DEFAULT,
			BandPresets.parse("100k, 1m, 10m"));
	}

	/**
	 * Z1 pins these three strings: they are what the fold's chips have read since addendum N, and a default
	 * profile must draw the W pictures byte for byte.
	 */
	@Test
	public void theDefaultLabelsAreExactlyTheChipsTheFoldDraws()
	{
		assertArrayEquals(new String[]{"100k+", "1m+", "10m+"}, BandPresets.DEFAULT.labels());
	}

	/** Every shorthand {@code MovementMath.parseGp} takes - the Min / Max fields' own reader - works here too. */
	@Test
	public void parseReadsEveryGpShorthandTheBandFieldsRead()
	{
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L},
			BandPresets.parse("100k, 1m, 10m").mins());
		assertArrayEquals("upper case suffixes are the same suffixes",
			new long[]{100_000L, 1_000_000L, 10_000_000L}, BandPresets.parse("100K, 1M, 10M").mins());
		assertArrayEquals("a fraction and a billion", new long[]{1_500_000L, 100_000_000L, 2_000_000_000L},
			BandPresets.parse("1.5m, 100m, 2b").mins());
		assertArrayEquals("bare gp, under the shorthand threshold", new long[]{850L, 1_000L, 9_999L},
			BandPresets.parse("850, 1000, 9999").mins());
	}

	/** Z1's three separators, and any run of them - so ", " is one gap and not a gap with an empty band in it. */
	@Test
	public void parseSplitsOnCommasSlashesAndWhitespace()
	{
		final long[] expected = {100_000L, 1_000_000L, 10_000_000L};
		final String[] lines =
		{
			"100k, 1m, 10m",
			"100k,1m,10m",
			"100k/1m/10m",
			"100k / 1m / 10m",
			"100k 1m 10m",
			"100k\t1m\n10m",
			"  100k ,  1m ,  10m  ",
			", 100k, 1m, 10m",
		};

		for (final String line : lines)
		{
			final BandPresets parsed = BandPresets.parse(line);
			assertEquals("'" + line + "' should have parsed", BandPresets.DEFAULT, parsed);
			assertArrayEquals("'" + line + "'", expected, parsed.mins());
		}
	}

	/**
	 * The one comma that is NOT a separator: the thousands grouping comma of "1,000", which
	 * {@code MovementMath.parseGp} reads as part of the number. Without this rule a band under 10,000 could be
	 * typed but never read back, since {@link BandPresets#format()} writes those with grouping commas itself.
	 */
	@Test
	public void parseKeepsAThousandsGroupingCommaInsideOneBand()
	{
		final long[] small = {1_000L, 2_000L, 3_000L};
		assertArrayEquals(small, BandPresets.parse("1,000 2,000 3,000").mins());
		assertArrayEquals(small, BandPresets.parse("1,000, 2,000, 3,000").mins());
		assertArrayEquals(small, BandPresets.parse("1,000/2,000/3,000").mins());

		// A comma between digits that does NOT introduce a group of exactly three is still a separator.
		assertArrayEquals(new long[]{1_000L, 2_000L, 30_000L}, BandPresets.parse("1000,2000,30000").mins());
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 1_234_567L},
			BandPresets.parse("1,234,567 1m 100k").mins());
	}

	/** Z1: the trio is held ascending however it was typed, so the chips read smallest first. */
	@Test
	public void parseSortsWhateverOrderItIsGiven()
	{
		final long[] expected = {100_000L, 1_000_000L, 10_000_000L};
		assertArrayEquals(expected, BandPresets.parse("10m, 1m, 100k").mins());
		assertArrayEquals(expected, BandPresets.parse("1m, 10m, 100k").mins());
		assertArrayEquals(expected, BandPresets.parse("10m 100k 1m").mins());
		assertEquals("100k, 1m, 10m", BandPresets.parse("10m, 1m, 100k").format());
	}

	/** Refusal one: a line that does not name exactly three bands - including no line at all. */
	@Test
	public void parseRefusesAnythingButThreeValues()
	{
		final String[] wrong = {null, "", "   ", "100k", "100k, 1m", "100k, 1m, 10m, 100m", "1 2 3 4 5"};

		for (final String line : wrong)
		{
			assertNull("'" + line + "' should have been refused", BandPresets.parse(line));
		}
	}

	/** Refusal two: a band that is not a price. A zero would admit every row and is not a band at all. */
	@Test
	public void parseRefusesAValueThatIsNotPositive()
	{
		assertNull(BandPresets.parse("0, 1m, 10m"));
		assertNull(BandPresets.parse("100k, 0, 10m"));
		assertNull(BandPresets.parse("100k, 1m, 0"));
		// parseGp itself refuses a negative (a price cannot be negative), so this arrives as unreadable text.
		assertNull(BandPresets.parse("-1, 1m, 10m"));
		assertNull(BandPresets.parse("100k, -1m, 10m"));
	}

	/** Refusal three: two equal bands would draw two identical chips, only one of which could ever light. */
	@Test
	public void parseRefusesTwoBandsTheSame()
	{
		assertNull(BandPresets.parse("1m, 1m, 10m"));
		assertNull(BandPresets.parse("100k, 1m, 100k"));
		assertNull(BandPresets.parse("1m, 10m, 10m"));
		assertNull("the same amount written two ways is still the same amount",
			BandPresets.parse("1m, 1000000, 10m"));
	}

	/** A part that names no number refuses the whole line: half a trio is never half applied. */
	@Test
	public void parseRefusesTextThatNamesNoNumber()
	{
		final String[] rubbish = {"abc", "100k, abc, 10m", "100k, 1.5x, 10m", "k, m, b", "100k, 1e6, 10m"};

		for (final String line : rubbish)
		{
			assertNull("'" + line + "' should have been refused", BandPresets.parse(line));
		}
	}

	/**
	 * {@link BandPresets#of(long, long, long)} sorts, and enforces the same invariant {@link
	 * BandPresets#parse(String)} does - by throwing, because a caller holding three longs has already done the
	 * reading. A panel reading three boxes catches this beside the boxes' own {@code ParseException}.
	 */
	@Test
	public void ofSortsAndRefusesWhatParseRefuses()
	{
		assertEquals(BandPresets.DEFAULT, BandPresets.of(10_000_000L, 100_000L, 1_000_000L));
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L},
			BandPresets.of(1_000_000L, 10_000_000L, 100_000L).mins());

		final long[][] refused =
		{
			{0L, 1_000_000L, 10_000_000L},
			{100_000L, -1L, 10_000_000L},
			{1_000_000L, 1_000_000L, 10_000_000L},
			{100_000L, 10_000_000L, 100_000L},
		};

		for (final long[] trio : refused)
		{
			try
			{
				fail(Arrays.toString(trio) + " should not have built a trio, gave "
					+ BandPresets.of(trio[0], trio[1], trio[2]));
			}
			catch (IllegalArgumentException expected)
			{
				assertTrue("the refusal names the three values: " + expected.getMessage(),
					expected.getMessage().contains(String.valueOf(trio[0])));
			}
		}
	}

	/** Z1: a label is the band in gp shorthand plus the "+" that says "and everything dearer". */
	@Test
	public void aLabelIsTheBandInShorthandWithAPlus()
	{
		assertArrayEquals(new String[]{"1.5m+", "100m+", "2b+"},
			BandPresets.of(1_500_000L, 100_000_000L, 2_000_000_000L).labels());
		assertArrayEquals("under 10,000 the game writes every digit, so the label does too",
			new String[]{"1,000+", "2,000+", "30k+"}, BandPresets.of(1_000L, 2_000L, 30_000L).labels());
	}

	/** What the config line holds is what the value reads back: the round trip is the whole point of format(). */
	@Test
	public void formatRoundTripsThroughParse()
	{
		final BandPresets[] trios =
		{
			BandPresets.DEFAULT,
			BandPresets.of(1_000_000L, 10_000_000L, 100_000_000L),
			BandPresets.of(1_500_000L, 100_000_000L, 2_000_000_000L),
			BandPresets.of(500_000L, 5_000_000L, 50_000_000L),
			BandPresets.of(10_000L, 100_000L, 1_000_000L),
		};

		for (final BandPresets trio : trios)
		{
			assertEquals(trio.format(), trio, BandPresets.parse(trio.format()));
		}

		assertEquals("1.5m, 100m, 2b", BandPresets.of(2_000_000_000L, 1_500_000L, 100_000_000L).format());
	}

	/**
	 * The round trip has to survive the commas {@link BandPresets#format()} writes itself: a band under 10,000 is
	 * spelled "1,000" rather than "1k", so a blind split on commas would refuse the line the value had just
	 * written.
	 */
	@Test
	public void formatRoundTripsEvenWhenABandIsWrittenWithGroupingCommas()
	{
		final BandPresets small = BandPresets.of(1_000L, 2_000L, 3_000L);
		assertEquals("1,000, 2,000, 3,000", small.format());
		assertEquals(small, BandPresets.parse(small.format()));
	}

	/**
	 * Shorthand is lossy where the game's own stack text is lossy, and the boxes print shorthand: a band of
	 * 1,234,567 gp is written "1.23m" and comes back as 1,230,000. Pinned because it is the one case where the
	 * round trip does NOT return the same trio, and because the boxes re-print what was saved.
	 */
	@Test
	public void formatIsShorthandAndRoundsABandItCannotWriteExactly()
	{
		final BandPresets odd = BandPresets.of(1_234_567L, 1_000_000L, 10_000_000L);
		assertEquals("1m, 1.23m, 10m", odd.format());

		final BandPresets returned = BandPresets.parse(odd.format());
		assertNotEquals("the odd band does not survive the shorthand", odd, returned);
		assertArrayEquals(new long[]{1_000_000L, 1_230_000L, 10_000_000L}, returned.mins());
		// What a user typed IS read exactly; only what format() wrote is rounded.
		assertArrayEquals(new long[]{1_000_000L, 1_234_567L, 10_000_000L},
			BandPresets.parse("1,234,567, 1m, 10m").mins());
	}

	/** The value is immutable, so the two arrays it hands out are copies and not its insides. */
	@Test
	public void minsAndLabelsAreFreshArraysTheCallerCannotMutate()
	{
		final long[] mins = BandPresets.DEFAULT.mins();
		mins[0] = 42L;
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L}, BandPresets.DEFAULT.mins());

		final String[] labels = BandPresets.DEFAULT.labels();
		labels[2] = "wrong";
		assertArrayEquals(new String[]{"100k+", "1m+", "10m+"}, BandPresets.DEFAULT.labels());
	}

	/** Value semantics, so the panel can tell an incoming trio from the one it is already drawing. */
	@Test
	public void equalTriosAreEqualWhateverOrderTheyWereBuiltIn()
	{
		final BandPresets a = BandPresets.of(100_000L, 1_000_000L, 10_000_000L);
		final BandPresets b = BandPresets.of(10_000_000L, 100_000L, 1_000_000L);

		assertEquals(a, b);
		assertEquals(a.hashCode(), b.hashCode());
		assertEquals(a, BandPresets.DEFAULT);
		assertNotEquals(a, BandPresets.of(100_000L, 1_000_000L, 100_000_000L));
		assertNotEquals(a, null);
		assertNotEquals(a, "100k, 1m, 10m");
		assertEquals(a, a);

		final Set<BandPresets> seen = new HashSet<>();
		assertTrue(seen.add(a));
		assertFalse("an equal trio is the same key", seen.add(b));
		assertTrue(seen.add(BandPresets.of(1_000_000L, 10_000_000L, 100_000_000L)));
	}

	/** {@code toString} is a debugging line and prints gp, not the shorthand a log would have to un-round. */
	@Test
	public void toStringNamesTheThreeBandsInGp()
	{
		final String text = BandPresets.DEFAULT.toString();
		assertTrue(text, text.contains("BandPresets"));
		assertTrue(text, text.contains("100000"));
		assertTrue(text, text.contains("1000000"));
		assertTrue(text, text.contains("10000000"));
	}
}

