	// ---------------------------------------------------------------- C27 seams

	/**
	 * The direct-run {@link ScheduledExecutorService} stub of C27: {@code execute} runs inline (or queues while
	 * {@link #deferred} is set, so a test can interleave a fetch completion with a disk load), and every
	 * periodic schedule is recorded as a {@link Timer} the test fires by hand. Only what {@link PriceService}
	 * uses is implemented; {@code schedule(Callable)} is not.
	 */
	static final class DirectScheduler extends AbstractExecutorService implements ScheduledExecutorService
	{
		final List<Runnable> queued = new ArrayList<>();
		final List<Timer> timers = new ArrayList<>();
		boolean deferred;
		private boolean shutdown;

		@Override
		public void execute(final Runnable command)
		{
			if (deferred)
			{
				queued.add(command);
			}
			else
			{
				command.run();
			}
		}

		/** Runs every queued task in order, including the ones a task queues while running. */
		void runPending()
		{
			while (!queued.isEmpty())
			{
				queued.remove(0).run();
			}
		}

		/** Runs one queued task out of order. */
		void runQueued(final int index)
		{
			queued.remove(index).run();
		}

		Timer timerWithPeriod(final long periodMs)
		{
			for (final Timer timer : timers)
			{
				if (timer.periodMs == periodMs && !timer.future.isCancelled())
				{
					return timer;
				}
			}
			throw new AssertionError("no live timer with period " + periodMs + " ms");
		}

		@Override
		public ScheduledFuture<?> schedule(final Runnable command, final long delay, final TimeUnit unit)
		{
			return add(command, unit.toMillis(delay), 0L);
		}

		@Override
		public <V> ScheduledFuture<V> schedule(final Callable<V> callable, final long delay, final TimeUnit unit)
		{
			throw new UnsupportedOperationException("PriceService never schedules a Callable");
		}

		@Override
		public ScheduledFuture<?> scheduleAtFixedRate(final Runnable command, final long initialDelay, final long period, final TimeUnit unit)
		{
			return add(command, unit.toMillis(initialDelay), unit.toMillis(period));
		}

		@Override
		public ScheduledFuture<?> scheduleWithFixedDelay(final Runnable command, final long initialDelay, final long delay, final TimeUnit unit)
		{
			return add(command, unit.toMillis(initialDelay), unit.toMillis(delay));
		}

		private ScheduledFuture<?> add(final Runnable command, final long initialDelayMs, final long periodMs)
		{
			final Timer timer = new Timer(command, initialDelayMs, periodMs);
			timers.add(timer);
			return timer.future;
		}

		@Override
		public void shutdown()
		{
			shutdown = true;
		}

		@Override
		public List<Runnable> shutdownNow()
		{
			shutdown = true;
			final List<Runnable> rest = new ArrayList<>(queued);
			queued.clear();
			return rest;
		}

		@Override
		public boolean isShutdown()
		{
			return shutdown;
		}

		@Override
		public boolean isTerminated()
		{
			return shutdown;
		}

		@Override
		public boolean awaitTermination(final long timeout, final TimeUnit unit)
		{
			return true;
		}
	}

	/** One recorded periodic schedule. {@link #fire()} honours cancellation like the real executor would. */
	static final class Timer
	{
		final Runnable task;
		final long initialDelayMs;
		final long periodMs;
		final StubFuture future = new StubFuture();

		Timer(final Runnable task, final long initialDelayMs, final long periodMs)
		{
			this.task = task;
			this.initialDelayMs = initialDelayMs;
			this.periodMs = periodMs;
		}

		void fire()
		{
			if (!future.isCancelled())
			{
				task.run();
			}
		}
	}

	/** Just enough {@link ScheduledFuture} to be cancelled and inspected. */
	static final class StubFuture implements ScheduledFuture<Object>
	{
		private boolean cancelled;

		@Override
		public boolean cancel(final boolean mayInterruptIfRunning)
		{
			cancelled = true;
			return true;
		}

		@Override
		public boolean isCancelled()
		{
			return cancelled;
		}

		@Override
		public boolean isDone()
		{
			return cancelled;
		}

		@Override
		public Object get()
		{
			return null;
		}

		@Override
		public Object get(final long timeout, final TimeUnit unit)
		{
			return null;
		}

		@Override
		public long getDelay(final TimeUnit unit)
		{
			return 0L;
		}

		@Override
		public int compareTo(final Delayed other)
		{
			return 0;
		}
	}

	/**
	 * A {@link ClientThread} whose {@code invoke(Runnable)} runs inline, or queues while {@link #deferred} so a
	 * test can prove the guide-price read waits for the client thread and that a stale hop is dropped. The real
	 * class's {@code invoke} needs an injected {@code Client} to ask {@code isClientThread()}; overriding it
	 * sidesteps that without a mock.
	 */
	static final class FakeClientThread extends ClientThread
	{
		final Deque<Runnable> queued = new ArrayDeque<>();
		boolean deferred;
		int invocations;

		@Override
		public void invoke(final Runnable r)
		{
			invocations++;
			if (deferred)
			{
				queued.add(r);
			}
			else
			{
				r.run();
			}
		}

		void runAll()
		{
			Runnable next;
			while ((next = queued.poll()) != null)
			{
				next.run();
			}
		}
	}

	/** The {@code edt} consumer: inline by default, queued while {@link #deferred} to prove the hop. */
	static final class RecordingEdt implements Consumer<Runnable>
	{
		final Deque<Runnable> queue = new ArrayDeque<>();
		boolean deferred;

		@Override
		public void accept(final Runnable runnable)
		{
			if (deferred)
			{
				queue.add(runnable);
			}
			else
			{
				runnable.run();
			}
		}

		void drain()
		{
			Runnable next;
			while ((next = queue.poll()) != null)
			{
				next.run();
			}
		}
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.time.LocalDate;
import org.junit.Test;

/**
 * {@link BankHistoryPoint} (addendum AU, contract sections 2 and 9.4): the eight cells, the guide normalised away
 * when it equals the card, the arrays copied in, wrong lengths refused, value equality - and {@code valueFor}, the
 * ONE rule every History figure uses, checked cell by cell against the contract's table for all sixteen option
 * sets.
 *
 * <p>The cells are powers of ten, so every expected total below spells out which cells it holds: a digit 1 in
 * place {@code i} is cell {@code i} counted. The guide figures are twice the card's, so a total read from the wrong
 * array is twice as large.
 */
public class BankHistoryPointTest
{
	private static final LocalDate DAY = LocalDate.of(2026, 9, 28);
	private static final long[] CARD = {1L, 10L, 100L, 1_000L, 10_000L, 100_000L, 1_000_000L, 10_000_000L};
	private static final long[] GUIDE = {2L, 20L, 200L, 2_000L, 20_000L, 200_000L, 2_000_000L, 20_000_000L};

	private static BankHistoryPoint point(final long[] card, final long[] guide)
	{
		return new BankHistoryPoint(DAY, 1_000L, 900L, card, guide);
	}

	private static ViewOptions options(final boolean cash, final boolean untradeables, final boolean inventory,
		final boolean live)
	{
		return new ViewOptions(cash, untradeables, live, inventory, false);
	}

	@Test
	public void theCellsAreInTheFrozenOrder()
	{
		assertEquals(0, BankHistoryPoint.BANK_TRADEABLE);
		assertEquals(1, BankHistoryPoint.BANK_CASH);
		assertEquals(2, BankHistoryPoint.BANK_PARTS);
		assertEquals(3, BankHistoryPoint.BANK_ALCH);
		assertEquals(4, BankHistoryPoint.CARRIED_TRADEABLE);
		assertEquals(5, BankHistoryPoint.CARRIED_CASH);
		assertEquals(6, BankHistoryPoint.CARRIED_PARTS);
		assertEquals(7, BankHistoryPoint.CARRIED_ALCH);
		assertEquals(8, BankHistoryPoint.CELLS);
	}

	@Test
	public void theFieldsReadBack()
	{
		final BankHistoryPoint p = point(CARD, GUIDE);
		assertEquals(DAY, p.day());
		assertEquals(1_000L, p.readAtMillis());
		assertEquals(900L, p.bankAtMillis());
		assertTrue(p.hasGuide());
		for (int i = 0; i < BankHistoryPoint.CELLS; i++)
		{
			assertEquals(CARD[i], p.card(i));
			assertEquals(GUIDE[i], p.guide(i));
		}
	}

	@Test
	public void withNoGuideTheGuideReadsAsTheCard()
	{
		final BankHistoryPoint p = point(CARD, null);
		assertFalse(p.hasGuide());
		for (int i = 0; i < BankHistoryPoint.CELLS; i++)
		{
			assertEquals(CARD[i], p.guide(i));
		}
	}

	@Test
	public void aGuideEqualToTheCardIsNotStoredAndTheTwoSpellingsAreEqual()
	{
		final BankHistoryPoint spelledOut = point(CARD, CARD.clone());
		final BankHistoryPoint left = point(CARD, null);
		assertFalse("a guide equal to the card is normalised to none", spelledOut.hasGuide());
		assertEquals(left, spelledOut);
		assertEquals(left.hashCode(), spelledOut.hashCode());
	}

	@Test
	public void theArraysAreCopiedIn()
	{
		final long[] card = CARD.clone();
		final long[] guide = GUIDE.clone();
		final BankHistoryPoint p = point(card, guide);
		card[0] = 999L;
		guide[0] = 999L;
		assertEquals(1L, p.card(0));
		assertEquals(2L, p.guide(0));
	}

	@Test
	public void wrongLengthsAreRefused()
	{
		for (final int length : new int[]{0, 7, 9})
		{
			try
			{
				point(new long[length], null);
				fail("a card of " + length + " cells was accepted");
			}
			catch (IllegalArgumentException expected)
			{
				// the point of the test
			}
			try
			{
				point(CARD, new long[length]);
				fail("a guide of " + length + " cells was accepted");
			}
			catch (IllegalArgumentException expected)
			{
				// the point of the test
			}
		}
	}

	@Test(expected = NullPointerException.class)
	public void aNullCardIsRefused()
	{
		point(null, null);
	}

	@Test(expected = NullPointerException.class)
	public void aNullDayIsRefused()
	{
		new BankHistoryPoint(null, 1L, 1L, CARD, null);
	}

	@Test
	public void aNegativeCellReadsAsZero()
	{
		final long[] card = CARD.clone();
		card[BankHistoryPoint.BANK_ALCH] = -50L;
		final BankHistoryPoint p = point(card, null);
		assertEquals(0L, p.card(BankHistoryPoint.BANK_ALCH));
	}

	/**
	 * The contract's table, spelled out for the eight counting sets with live prices on (card figures) and off
	 * (guide figures, twice as large).
	 */
	@Test
	public void valueForCountsExactlyTheCellsTheContractsTableNames()
	{
		final BankHistoryPoint p = point(CARD, GUIDE);
		// cash, untradeables, inventory -> the cells counted, as digits (cell 0 is the units digit)
		final Object[][] table = {
			{false, false, false, 101L},
			{true, false, false, 111L},
			{false, true, false, 1_101L},
			{false, false, true, 1_010_101L},
			{true, true, false, 1_111L},
			{true, false, true, 1_110_111L},
			{false, true, true, 11_011_101L},
			{true, true, true, 11_111_111L},
		};
		for (final Object[] row : table)
		{
			final boolean cash = (Boolean) row[0];
			final boolean untradeables = (Boolean) row[1];
			final boolean inventory = (Boolean) row[2];
			final long expected = (Long) row[3];
			assertEquals("live on, cash=" + cash + " untradeables=" + untradeables + " inventory=" + inventory,
				expected, p.valueFor(options(cash, untradeables, inventory, true)));
			assertEquals("live off reads the guide figures", 2 * expected,
				p.valueFor(options(cash, untradeables, inventory, false)));
		}
	}

	@Test
	public void withLivePricesOffAndNoGuideTheCardFiguresAreUsed()
	{
		final BankHistoryPoint p = point(CARD, null);
		assertEquals(11_111_111L, p.valueFor(options(true, true, true, false)));
	}

	@Test
	public void theHoverSwitchChangesNothing()
	{
		final BankHistoryPoint p = point(CARD, GUIDE);
		assertEquals(p.valueFor(ViewOptions.DEFAULT), p.valueFor(ViewOptions.DEFAULT.withShowHoverText(true)));
	}

	@Test
	public void aNullOptionsReadsAsTheDefault()
	{
		final BankHistoryPoint p = point(CARD, GUIDE);
		// DEFAULT = cash on, alch-only untradeables off, live on, inventory on.
		assertEquals(1_110_111L, p.valueFor(null));
		assertEquals(p.valueFor(ViewOptions.DEFAULT), p.valueFor(null));
	}

	@Test
	public void theSumIsClampedLikeThePortfolios()
	{
		final long[] card = new long[BankHistoryPoint.CELLS];
		card[BankHistoryPoint.BANK_TRADEABLE] = Long.MAX_VALUE;
		card[BankHistoryPoint.BANK_PARTS] = 5L;
		card[BankHistoryPoint.CARRIED_TRADEABLE] = Long.MAX_VALUE;
		assertEquals(Long.MAX_VALUE, point(card, null).valueFor(ViewOptions.DEFAULT));
	}

	@Test
	public void equalityCoversEveryField()
	{
		final BankHistoryPoint base = point(CARD, GUIDE);
		assertEquals(base, point(CARD.clone(), GUIDE.clone()));
		assertEquals(base.hashCode(), point(CARD.clone(), GUIDE.clone()).hashCode());
		assertNotEquals(base, new BankHistoryPoint(DAY.plusDays(1), 1_000L, 900L, CARD, GUIDE));
		assertNotEquals(base, new BankHistoryPoint(DAY, 1_001L, 900L, CARD, GUIDE));
		assertNotEquals(base, new BankHistoryPoint(DAY, 1_000L, 901L, CARD, GUIDE));
		final long[] otherCard = CARD.clone();
		otherCard[7] = 1L;
		assertNotEquals(base, point(otherCard, GUIDE));
		final long[] otherGuide = GUIDE.clone();
		otherGuide[7] = 1L;
		assertNotEquals(base, point(CARD, otherGuide));
		assertNotEquals(base, point(CARD, null));
		assertTrue(base.toString().contains("2026-09-28"));
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * {@link PricePoint} (contract C3): the mid rule, branch by branch.
 *
 * <p>Every branch is a real case, not a defensive one: the live {@code /1h} bucket measured on 2026-09-08 had
 * about 20 % of entries with no {@code avgHighPrice} and about 16 % with no {@code avgLowPrice} (research C10),
 * so "one side only" is roughly a third of the market and the mid rule has to be symmetric. The both-null case
 * was never observed and is the defensive one.
 */
public class PricePointTest
{
	@Test
	public void bothSidesGiveTheMean()
	{
		assertEquals(Long.valueOf(150L), new PricePoint(200L, 100L).mid());
		assertEquals(Long.valueOf(1_550_000L), new PricePoint(1_600_000L, 1_500_000L).mid());
		assertEquals(Long.valueOf(99L), new PricePoint(100L, 98L).mid());
	}

	/**
	 * Half-up, so an odd sum does not silently round the price down every time.
	 */
	@Test
	public void anOddSumRoundsUp()
	{
		assertEquals(Long.valueOf(3L), new PricePoint(3L, 2L).mid());
		assertEquals(Long.valueOf(2L), new PricePoint(2L, 1L).mid());
		assertEquals(Long.valueOf(101L), new PricePoint(101L, 100L).mid());
	}

	@Test
	public void oneSideStandsAloneWhicheverSideItIs()
	{
		assertEquals("no low: the high is the price", Long.valueOf(100L), new PricePoint(100L, null).mid());
		assertEquals("no high: the low is the price", Long.valueOf(80L), new PricePoint(null, 80L).mid());
	}

	@Test
	public void neitherSideIsNoPriceRatherThanZero()
	{
		assertNull(new PricePoint(null, null).mid());
		assertTrue(new PricePoint(null, null).isEmpty());
		assertTrue(PricePoint.EMPTY.isEmpty());
		assertNull(PricePoint.EMPTY.mid());
	}

	@Test
	public void aPointWithEitherSideIsNotEmpty()
	{
		assertFalse(new PricePoint(1L, null).isEmpty());
		assertFalse(new PricePoint(null, 1L).isEmpty());
		assertFalse(new PricePoint(1L, 1L).isEmpty());
	}

	/**
	 * A price of zero is a price. Only null means "no price".
	 */
	@Test
	public void zeroIsAPrice()
	{
		final PricePoint zero = new PricePoint(0L, 0L);
		assertFalse(zero.isEmpty());
		assertEquals(Long.valueOf(0L), zero.mid());
	}

	/**
	 * Prices may exceed int (research), so the sides are longs - and the mid of two huge sides must not
	 * overflow the way {@code (high + low) / 2} would.
	 */
	@Test
	public void aHugePairDoesNotOverflow()
	{
		final Long mid = new PricePoint(Long.MAX_VALUE, Long.MAX_VALUE).mid();
		assertTrue("the mid of two maximums is still positive, not a wrapped negative", mid > 0L);
		assertEquals(Long.valueOf(Long.MAX_VALUE), mid);

		assertEquals(Long.valueOf(3_000_000_000L), new PricePoint(4_000_000_000L, 2_000_000_000L).mid());
	}

	@Test
	public void sidesAreReadableAndTheValueCompares()
	{
		final PricePoint point = new PricePoint(200L, 100L);
		assertEquals(Long.valueOf(200L), point.high());
		assertEquals(Long.valueOf(100L), point.low());

		assertEquals(new PricePoint(200L, 100L), point);
		assertEquals(new PricePoint(200L, 100L).hashCode(), point.hashCode());
		assertNotEquals(new PricePoint(100L, 200L), point);
		assertNotEquals(new PricePoint(200L, null), point);
		assertNotEquals(point, null);
		assertNotEquals(point, "PricePoint");
	}
}

package com.bankpricemovement;

import java.awt.image.BufferedImage;
import java.io.File;
import java.util.List;
import javax.imageio.ImageIO;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Addendum AU, builder C: the History view's own pictures ({@link HistoryViewRenderer}) are drawn into
 * {@code build/history-view/} on every run - the pinned copies under {@code docs/handoff/lab/} are written by the
 * harness's {@code main} - and each is the picture it claims to be.
 */
public class BankHistoryViewPicturesTest
{
	@Test
	public void theFivePicturesAreDrawnAtTheirWidths() throws Exception
	{
		final List<File> files = HistoryViewRenderer.write(new File("build/history-view"));
		assertEquals(5, files.size());
		final BufferedImage at213 = ImageIO.read(files.get(0));
		final BufferedImage at230 = ImageIO.read(files.get(1));
		final BufferedImage empty = ImageIO.read(files.get(2));
		final BufferedImage one = ImageIO.read(files.get(3));
		final BufferedImage hover = ImageIO.read(files.get(4));
		assertEquals(213, at213.getWidth());
		assertEquals(230, at230.getWidth());
		assertEquals("the same content at both widths, so the same height", at213.getHeight(), at230.getHeight());
		assertEquals("the hover changes nothing's size", at213.getHeight(), hover.getHeight());
		assertTrue("the whole list is drawn: 40 days of rows", at213.getHeight() > 1_200);
		assertTrue("the empty view is one short sentence", empty.getHeight() < 60);
		assertTrue("one reading: the block and one row", one.getHeight() < 250);
		assertTrue("the lit chip is orange", count(at213, ColorScheme.BRAND_ORANGE) > 20);
		assertTrue("the hover is a different picture", differ(at213, hover));
	}

	static int count(final BufferedImage image, final java.awt.Color colour)
	{
		int n = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) & 0xFFFFFF) == (colour.getRGB() & 0xFFFFFF))
				{
					n++;
				}
			}
		}
		return n;
	}

	static boolean differ(final BufferedImage a, final BufferedImage b)
	{
		for (int y = 0; y < Math.min(a.getHeight(), b.getHeight()); y++)
		{
			for (int x = 0; x < Math.min(a.getWidth(), b.getWidth()); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y))
				{
					return true;
				}
			}
		}
		return false;
	}
}

