	@Test
	public void theSeamReadsAndWritesTheOneKeyAndTheWriteDoesNotComeBack() throws Exception
	{
		final BankPriceMovementPlugin plugin = new BankPriceMovementPlugin();
		final BankPriceMovementPanel mocked = mock(BankPriceMovementPanel.class);
		final BankPriceMovementConfig config = mock(BankPriceMovementConfig.class);
		final ConfigManager cm = mock(ConfigManager.class);
		final PriceService service = mock(PriceService.class);
		set(plugin, "panel", mocked);
		set(plugin, "config", config);
		set(plugin, "configManager", cm);
		set(plugin, "service", service);
		when(config.startTab()).thenReturn(SidebarView.ITEMS);
		org.mockito.Mockito.doAnswer(invocation ->
		{
			when(config.startTab()).thenReturn((SidebarView) invocation.getArgument(2));
			plugin.onConfigChanged(changed((String) invocation.getArgument(1)));
			return null;
		}).when(cm).setConfiguration(anyString(), anyString(), any(Object.class));

		final BankPriceMovementPanel.Prefs prefs = plugin.configPrefs();
		assertEquals(SidebarView.ITEMS, prefs.loadStartTab());
		prefs.saveStartTab(SidebarView.HISTORY);
		verify(cm).setConfiguration(BankPriceMovementConfig.GROUP, "startTab", SidebarView.HISTORY);
		onEdt(() ->
		{
		});
		verify(mocked, never()).setStartTab(any());
		assertEquals(SidebarView.HISTORY, prefs.loadStartTab());
		verify(service, never()).setOptions(any());

		// No manager: a no-op, not an NPE.
		set(plugin, "configManager", null);
		plugin.configPrefs().saveStartTab(SidebarView.ITEMS);
	}

	// ---------------------------------------------------------------- the bridge

	@Test
	public void theVerbPressesTheDotsRoadRefusesOtherWordsAndEchoesTheState() throws Exception
	{
		final BankPriceMovementPanel mocked = mock(BankPriceMovementPanel.class);
		final BpmCommands dev = new BpmCommands(mocked, service(), gson);
		assertTrue(send(dev, "starttab=history").get("ok").getAsBoolean());
		verify(mocked).pressStartTab(SidebarView.HISTORY);
		assertTrue(send(dev, "starttab= Items ").get("ok").getAsBoolean());
		verify(mocked).pressStartTab(SidebarView.ITEMS);
		final JsonObject bad = send(dev, "starttab=Chart");
		assertFalse(bad.get("ok").getAsBoolean());
		assertEquals("starttab= wants items or history, not 'Chart'", bad.get("error").getAsString());
		assertEquals("starttab= wants items or history, not ''", send(dev, "starttab").get("error").getAsString());
		verify(mocked, never()).pressView(any());

		// The real panel: the echo follows the dot and not the showing tab.
		final Memory prefs = new Memory();
		final PriceService service = service();
		build(prefs, service);
		final BpmCommands real = new BpmCommands(panel, service, gson);
		JsonObject state = send(real, "state");
		assertEquals("ITEMS", state.get("startTab").getAsString());
		state = send(real, "starttab=history");
		assertEquals("HISTORY", state.get("startTab").getAsString());
		assertEquals("ITEMS", state.get("view").getAsString());
		assertEquals(Arrays.asList(SidebarView.HISTORY), prefs.saves);
		final String unknown = send(real, "nope").get("error").getAsString();
		assertTrue(unknown, unknown.contains("starttab="));
	}

	private JsonObject send(BpmCommands bridge, String cmd)
	{
		final String s = bridge.apply(cmd);
		assertNotNull(s);
		return gson.fromJson(s, JsonObject.class);
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Addendum AU, amendment 9.3: how {@link PriceService.Status} carries the drawn owner's bank-history series - the
 * three public constructors unchanged and EMPTY, {@code withBankHistory} copying every other field, the series in
 * {@code equals} / {@code hashCode}, and {@code toString} byte-identical while it is empty.
 */
public class StatusBankHistoryTest
{
	private static final BankHistorySeries TWO = BankHistorySeries.of(java.util.Arrays.asList(
		BankHistorySeriesTest.p(LocalDate.of(2026, 9, 7), 1L, 100L),
		BankHistorySeriesTest.p(LocalDate.of(2026, 9, 8), 2L, 200L)));

	private static PriceService.Status status()
	{
		return StatusFixtures.listed(3L, 7L, MovementWindow.D7, "No 7d history", LocalDate.of(2026, 9, 1),
			new PortfolioSummary(5L, 1, 1, null), 4, 2);
	}

	@Test
	public void everyPublicConstructorCarriesTheEmptySeries()
	{
		assertSame(BankHistorySeries.EMPTY, status().bankHistory());
		final PriceService.Status bare = new PriceService.Status(0L, 0L, false, false, null, null, null, 0, 0, null,
			false, 0L, 0L, 0L, 0L, null, -1.0d, 0, null, 0L, false, false, null, null);
		assertSame(BankHistorySeries.EMPTY, bare.bankHistory());
	}

	@Test
	public void withBankHistoryCopiesEveryOtherField()
	{
		final PriceService.Status base = status();
		final PriceService.Status with = base.withBankHistory(TWO);

		assertNotSame(base, with);
		assertSame(TWO, with.bankHistory());
		assertEquals("every other field copied: the same status once the series is taken back off", base,
			with.withBankHistory(BankHistorySeries.EMPTY));
		assertEquals(base.text(), with.text());
		assertEquals(base.portfolio(), with.portfolio());
		assertEquals(base.options(), with.options());
		assertEquals(base.live(), with.live());
		assertEquals(base.totalRows(), with.totalRows());
		assertEquals(base.bankItems(), with.bankItems());
		assertSame("null reads as EMPTY", BankHistorySeries.EMPTY, with.withBankHistory(null).bankHistory());
	}

	@Test
	public void theSeriesIsPartOfAStatussIdentity()
	{
		final PriceService.Status base = status();
		assertNotEquals(base, base.withBankHistory(TWO));
		assertEquals(base.withBankHistory(TWO), base.withBankHistory(BankHistorySeries.of(TWO.points())));
		assertEquals(base.withBankHistory(TWO).hashCode(),
			base.withBankHistory(BankHistorySeries.of(TWO.points())).hashCode());
	}

	@Test
	public void toStringIsUnchangedWhileTheSeriesIsEmpty()
	{
		final PriceService.Status base = status();
		assertEquals(base.toString(), base.withBankHistory(BankHistorySeries.EMPTY).toString());
		assertTrue(!base.toString().contains("bankHistory"));
		assertTrue(base.withBankHistory(TWO).toString().endsWith(", bankHistory=2}"));
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * {@link BankItem}'s two addendum-Q fields (Q5), the addendum-R {@code parts} beside them (R1), and what all three
 * mean off disk.
 *
 * <p>The first test is the load-bearing one. A snapshot is a Gson bag of public fields, and every
 * {@code bank-*.json} on a user's machine was written before addendum Q existed: it names neither field. Gson
 * leaves an absent {@code boolean} at {@code false}, so the field had to be spelled {@code untradeable} rather
 * than {@code tradeable} - the other way round, every stack of every stored bank would have read as untradeable,
 * been left out of the rows while the switch was off, and emptied the sidebar of anyone who had not opened their
 * bank since updating.
 */
public class BankItemTest
{
	private static final Gson GSON = new Gson();

	/** A stack as a pre-Q file spells it: four fields, neither of the new ones. */
	private static final String PRE_Q = "{\"id\":4151,\"quantity\":3,\"name\":\"Abyssal whip\",\"stackable\":false}";

	@Test
	public void aStackFromAFileWrittenBeforeAddendumQReadsAsTradeable()
	{
		final BankItem item = GSON.fromJson(PRE_Q, BankItem.class);

		assertEquals(4151, item.id);
		assertEquals(3, item.quantity);
		assertFalse("an absent boolean is false, and false here means tradeable", item.untradeable);
		assertEquals(0, item.haPrice);
		assertNull("so it is priced by the guide table, not alched", item.alchPrice());
	}

	@Test
	public void anUntradeableStackSurvivesTheRoundTrip()
	{
		final BankItem written = new BankItem(772, 2, "Dramen staff", false, true, 1500);

		final BankItem read = GSON.fromJson(GSON.toJson(written), BankItem.class);

		assertEquals(written, read);
		assertTrue(read.untradeable);
		assertEquals(1500, read.haPrice);
		assertEquals(Long.valueOf(1500L), read.alchPrice());
	}

	/** The four-argument constructor is the tradeable one, so every existing caller keeps its meaning. */
	@Test
	public void theShortConstructorMakesATradeableStack()
	{
		final BankItem item = new BankItem(385, 500, "Shark", true);

		assertFalse(item.untradeable);
		assertEquals(0, item.haPrice);
		assertNull(item.alchPrice());
	}

	/**
	 * The one rule for "this stack is valued at its alch price", spelled once so the reader's keep rule, the row
	 * and the bank value cannot drift apart: untradeable AND worth something. Either half alone is nothing.
	 */
	@Test
	public void anAlchPriceNeedsBothTheFlagAndAPositiveValue()
	{
		assertNull("marked but worthless", new BankItem(1, 1, "Junk", false, true, 0).alchPrice());
		assertNull("a negative is not a price", new BankItem(1, 1, "Junk", false, true, -5).alchPrice());
		assertNull("a value on a tradeable stack is not what it is priced at",
			new BankItem(4151, 1, "Abyssal whip", false, false, 72_000).alchPrice());
		assertEquals(Long.valueOf(1L), new BankItem(1, 1, "Junk", false, true, 1).alchPrice());
	}

	@Test
	public void theTwoNewFieldsArePartOfTheStacksIdentity()
	{
		final BankItem tradeable = new BankItem(772, 2, "Dramen staff", false);
		final BankItem untradeable = new BankItem(772, 2, "Dramen staff", false, true, 1500);
		final BankItem cheaper = new BankItem(772, 2, "Dramen staff", false, true, 1400);

		assertNotEquals("a bank that changed which stacks it holds must be written", tradeable, untradeable);
		assertNotEquals(untradeable, cheaper);
		assertEquals(untradeable, new BankItem(772, 2, "Dramen staff", false, true, 1500));
		assertEquals(untradeable.hashCode(), new BankItem(772, 2, "Dramen staff", false, true, 1500).hashCode());
	}

	/** An ordinary stack prints what it always printed; only a marked one says more. */
	@Test
	public void toStringNamesTheAlchValueOnlyWhenThereIsOne()
	{
		assertEquals("BankItem{id=385, quantity=500, name='Shark', stackable=true}",
			new BankItem(385, 500, "Shark", true).toString());
		assertEquals("BankItem{id=772, quantity=2, name='Dramen staff', stackable=false, untradeable, haPrice=1500}",
			new BankItem(772, 2, "Dramen staff", false, true, 1500).toString());
	}

	// ---------------------------------------------------------------- R1: the tradeable parts

	/** The addendum's own example: a Crystal body reverts to three Crystal armour seeds. */
	private static final int CRYSTAL_BODY = 23_975;
	private static final int ARMOUR_SEED = 23_956;
	private static final String SEED_NAME = "Crystal armour seed";

	private static BankItem crystalBody()
	{
		return new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000,
			Collections.singletonList(new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME)));
	}

	/**
	 * The same rule the class comment makes of {@code untradeable}, for the field addendum R adds: every
	 * {@code bank-*.json} on a user's machine was written before R and names no {@code parts}, Gson leaves an
	 * absent object null, and null has to read as "no parts" - which is what those files held. The next bank open
	 * fills it in.
	 */
	@Test
	public void aStackFromAFileWrittenBeforeAddendumRHasNoParts()
	{
		final BankItem item = GSON.fromJson(PRE_Q, BankItem.class);

		assertNull(item.parts);
		assertFalse("so it is valued as it was: by the guide table or, when marked, by the alch rule", item.hasParts());
	}

	@Test
	public void aPartSurvivesTheRoundTripAsAPlainGsonValue()
	{
		final BankItem read = GSON.fromJson(GSON.toJson(crystalBody()), BankItem.class);

		assertEquals(crystalBody(), read);
		assertTrue(read.hasParts());
		assertEquals(1, read.parts.size());
		final BankItem.Part part = read.parts.get(0);
		assertEquals(ARMOUR_SEED, part.id);
		assertEquals("a long, as ItemMapping.getQuantity() is", 3L, part.quantity);
		assertEquals(SEED_NAME, part.name);
	}

	/**
	 * "No mapping" and "a mapping that named nothing" are the same answer to every reader, so only one of them is
	 * ever stored - otherwise {@code PriceService} would have to test for both before valuing a stack.
	 */
	@Test
	public void anEmptyPartsListIsStoredAsNoPartsAtAll()
	{
		assertNull(new BankItem(772, 1, "Dramen staff", false, true, 1500, Collections.emptyList()).parts);
		assertNull(new BankItem(772, 1, "Dramen staff", false, true, 1500, null).parts);
	}

	/** A file could hold {@code "parts":[null]}; that is no more a valuation than an absent field is. */
	@Test
	public void hasPartsIgnoresAListOfNothingButNulls()
	{
		final BankItem item = new BankItem(772, 1, "Dramen staff", false, true, 1500);
		item.parts = Arrays.asList((BankItem.Part) null, null);

		assertFalse(item.hasParts());
	}

	/** The six-argument constructor is the pre-R one, so every existing caller keeps its meaning. */
	@Test
	public void theSixArgumentConstructorRecordsNoParts()
	{
		assertNull(new BankItem(772, 2, "Dramen staff", false, true, 1500).parts);
		assertFalse(new BankItem(385, 500, "Shark", true).hasParts());
	}

	/**
	 * A bank whose stacks changed what they revert to has changed, and the change-only write rule (B008) compares
	 * stacks - so the parts have to be part of a stack's identity or a re-mapped item would never be re-written.
	 */
	@Test
	public void thePartsArePartOfTheStacksIdentity()
	{
		final BankItem withParts = crystalBody();
		final BankItem withNone = new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000);
		final List<BankItem.Part> two = Collections.singletonList(new BankItem.Part(ARMOUR_SEED, 2L, SEED_NAME));
		final BankItem withTwo = new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000, two);

		assertNotEquals(withParts, withNone);
		assertNotEquals("three seeds is not two seeds", withParts, withTwo);
		assertEquals(withParts, crystalBody());
		assertEquals(withParts.hashCode(), crystalBody().hashCode());
	}

	@Test
	public void aPartIsAValueOfItsOwn()
	{
		final BankItem.Part part = new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME);

		assertEquals(part, new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME));
		assertEquals(part.hashCode(), new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME).hashCode());
		assertNotEquals(part, new BankItem.Part(ARMOUR_SEED, 1L, SEED_NAME));
		assertNotEquals(part, new BankItem.Part(ARMOUR_SEED + 1, 3L, SEED_NAME));
		assertNotEquals(part, new BankItem.Part(ARMOUR_SEED, 3L, "Crystal tool seed"));
		assertEquals("a null name is \"\", as a stack's is", "", new BankItem.Part(1, 1L, null).name);
		assertEquals("Part{id=23956, quantity=3, name='Crystal armour seed'}", part.toString());
	}

	/**
	 * Y3: the merge of a banked stack and a carried one is a COPY with the quantities added - the stacks it merges
	 * belong to the persisted snapshot, and a computation that wrote to one would put a number in
	 * {@code bank-*.json} that no bank ever held. Everything but the quantity rides along.
	 */
	@Test
	public void withQuantityCopiesTheStackAndChangesNothingElse()
	{
		final BankItem body = crystalBody();

		final BankItem merged = body.withQuantity(4);

		assertEquals(4, merged.quantity);
		assertEquals("the original is untouched", 1, body.quantity);
		assertEquals(body.id, merged.id);
		assertEquals(body.name, merged.name);
		assertEquals(body.stackable, merged.stackable);
		assertEquals(body.untradeable, merged.untradeable);
		assertEquals(body.haPrice, merged.haPrice);
		assertEquals(body.parts, merged.parts);
		assertEquals(body, merged.withQuantity(1));
	}

	/** An ordinary stack still prints what it always printed; only one with parts says more. */
	@Test
	public void toStringNamesThePartsOnlyWhenThereAreSome()
	{
		assertEquals("BankItem{id=385, quantity=500, name='Shark', stackable=true}",
			new BankItem(385, 500, "Shark", true).toString());
		assertEquals("BankItem{id=23975, quantity=1, name='Crystal body', stackable=false, untradeable, "
				+ "haPrice=900000, parts=[Part{id=23956, quantity=3, name='Crystal armour seed'}]}",
			crystalBody().toString());
	}
}

package com.bankpricemovement;

import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

/**
 * The History view's own render harness (addendum AU, contract section 10 "Pictures"): the view ALONE, chart block and
 * list, on the sidebar's dark ground, at a chosen width. The whole sidebar in History is {@link LookRenderer}'s
 * ({@link LookRenderer#renderHistory}), drawn over THIS class's fixture - there is one History fixture, and it is here.
 *
 * <p>The fixture is 40 days, 18 Aug to 26 Sep 2026, of a total around 736m that rises into mid-September and falls
 * after it, with three gaps: 30 Aug, 8 Sep, and the two days 21-22 Sep. Every figure is deterministic, so the
 * pictures are the same whenever they are drawn. "Today" is 26 Sep at local noon in {@link #ZONE}.
 *
 * <p>{@code main(dir)} writes the five pictures of the handoff: {@link #FILE_213}, {@link #FILE_230},
 * {@link #FILE_EMPTY}, {@link #FILE_ONE} and {@link #FILE_HOVER}.
 */
public final class HistoryViewRenderer
{
	static final ZoneId ZONE = ZoneId.of("America/Toronto");
	static final LocalDate TODAY = LocalDate.of(2026, 9, 26);
	static final int DAYS = 40;
	/** The days with no reading: 30 Aug, 8 Sep, and 21-22 Sep (the two-day gap). */
	static final Set<LocalDate> GAPS = new HashSet<>(Arrays.asList(LocalDate.of(2026, 8, 30),
		LocalDate.of(2026, 9, 8), LocalDate.of(2026, 9, 21), LocalDate.of(2026, 9, 22)));

	static final String FILE_213 = "history-view-213-2026-09-28.png";
	static final String FILE_230 = "history-view-230-2026-09-28.png";
	static final String FILE_EMPTY = "history-view-empty-2026-09-28.png";
	static final String FILE_ONE = "history-view-one-2026-09-28.png";
	static final String FILE_HOVER = "history-view-hover-2026-09-28.png";
	/** The fixture's last reading, today's: mock 5's own total, which the whole-sidebar pictures' card reads too. */
	static final long LAST_GP = 736_412_683L;
	/** The day the hover picture points at: mid-range, as in mock 5 (09 Sep). */
	static final LocalDate HOVER_DAY = LocalDate.of(2026, 9, 9);

	/** The shape of the total over the 40 days, in millions, at key days - mock 5's own path. */
	private static final double[][] KEYS = {{0, 701}, {4, 692}, {9, 713}, {14, 724}, {19, 741}, {24, 752},
		{28, 758.4}, {32, 748}, {35, 733}, {37, 729}, {39, 736.4}};

	private HistoryViewRenderer()
	{
	}

	/** Local noon of {@code day} in {@link #ZONE}: how every stamp here is built (amendment 9.1). */
	static long noon(final LocalDate day)
	{
		return day.atTime(12, 0).atZone(ZONE).toInstant().toEpochMilli();
	}

	/** A reading of {@code day} whose bank-tradeable cell is {@code gp}. */
	static BankHistoryPoint point(final LocalDate day, final long gp)
	{
		final long[] card = new long[BankHistoryPoint.CELLS];
		card[BankHistoryPoint.BANK_TRADEABLE] = gp;
		return new BankHistoryPoint(day, noon(day), noon(day), card, null);
	}

	/** The 40-day fixture described above. */
	static BankHistorySeries fixture()
	{
		final List<BankHistoryPoint> points = new ArrayList<>();
		for (int i = 0; i < DAYS; i++)
		{
			final LocalDate day = TODAY.minusDays(DAYS - 1 - i);
			if (GAPS.contains(day))
			{
				continue;
			}
			double base = KEYS[KEYS.length - 1][1];
			for (int k = 0; k + 1 < KEYS.length; k++)
			{
				if (i >= KEYS[k][0] && i <= KEYS[k + 1][0])
				{
					final double t = (i - KEYS[k][0]) / (KEYS[k + 1][0] - KEYS[k][0]);
					final double eased = (1 - Math.cos(t * Math.PI)) / 2;
					base = KEYS[k][1] + (KEYS[k + 1][1] - KEYS[k][1]) * eased;
					break;
				}
			}
			// A fixed wobble, so neighbouring days differ both ways, and odd digits all the way down.
			final double wobble = ((i * 37) % 11 - 5) * 0.45;
			final long gp = i == DAYS - 1 ? LAST_GP : Math.round((base + wobble) * 1_000_000d) + (i * 7_919L) % 999_983L;
			points.add(point(day, gp));
		}
		return BankHistorySeries.of(points);
	}

	/** Day one: the one reading of {@link #TODAY}, worth {@link #LAST_GP}. */
	static BankHistorySeries oneReading()
	{
		return BankHistorySeries.of(Arrays.asList(point(TODAY, LAST_GP)));
	}

	/** A view on the fixture's clock, shown {@code series} at {@code range}. EDT. */
	static BankHistoryView view(final BankHistorySeries series, final BankHistoryRange range)
	{
		final BankHistoryView view = new BankHistoryView(() -> noon(TODAY), ZONE);
		view.setRange(range);
		view.show(series, ViewOptions.DEFAULT);
		return view;
	}

	/** EDT. Sizes {@code view} to {@code width} and its own preferred height, and lays the tree out. */
	static void layOut(final JComponent view, final int width)
	{
		view.setSize(width, 10);
		layoutTree(view);
		view.setSize(width, view.getPreferredSize().height);
		layoutTree(view);
	}

	/** EDT. The view laid out at {@code width}, painted on the sidebar's ground. */
	static BufferedImage paint(final JComponent view, final int width)
	{
		layOut(view, width);
		final int height = view.getHeight();
		final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, width, height);
			view.printAll(g);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	/** {@link LookRenderer#layoutTree}'s recipe: doLayout top-down, with no peer. */
	static void layoutTree(final Component c)
	{
		c.doLayout();
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				layoutTree(child);
			}
		}
	}

	/** The view's chart, found in its tree. */
	static BankHistoryChart chart(final Container c)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof BankHistoryChart)
			{
				return (BankHistoryChart) child;
			}
			if (child instanceof Container)
			{
				final BankHistoryChart found = chart((Container) child);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	/** Moves a (synthetic) pointer onto the chart at {@code x}, in the chart's own coordinates. */
	static void hover(final BankHistoryChart chart, final int x)
	{
		chart.dispatchEvent(new MouseEvent(chart, MouseEvent.MOUSE_MOVED, System.currentTimeMillis(), 0, x,
			chart.getHeight() / 2, 0, false));
	}

	/** The pointer leaves the chart. */
	static void leave(final BankHistoryChart chart)
	{
		chart.dispatchEvent(new MouseEvent(chart, MouseEvent.MOUSE_EXITED, System.currentTimeMillis(), 0, -1, -1, 0,
			false));
	}

	/** Index of {@code day} among the chart's drawn days, or -1. */
	static int indexOf(final BankHistoryChart chart, final LocalDate day)
	{
		final List<BankHistoryMath.Day> days = chart.days();
		for (int i = 0; i < days.size(); i++)
		{
			if (days.get(i).day().equals(day))
			{
				return i;
			}
		}
		return -1;
	}

	/** The five pictures, drawn on the EDT. */
	static List<BufferedImage> renderAll() throws Exception
	{
		final AtomicReference<List<BufferedImage>> out = new AtomicReference<>();
		final AtomicReference<Throwable> failure = new AtomicReference<>();
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				final List<BufferedImage> images = new ArrayList<>();
				images.add(paint(view(fixture(), BankHistoryRange.D30), 213));
				images.add(paint(view(fixture(), BankHistoryRange.D30), 230));
				images.add(paint(view(BankHistorySeries.EMPTY, BankHistoryRange.D7), 213));
				images.add(paint(view(oneReading(),
					BankHistoryRange.D7), 213));
				final BankHistoryView hovered = view(fixture(), BankHistoryRange.D30);
				layOut(hovered, 213);
				final BankHistoryChart chart = chart(hovered);
				hover(chart, (int) Math.round(BankHistoryChart.xAt(indexOf(chart, HOVER_DAY), chart.days().size(),
					chart.getWidth())));
				images.add(paint(hovered, 213));
				out.set(images);
			}
			catch (Throwable t)
			{
				failure.set(t);
			}
		});
		if (failure.get() != null)
		{
			throw new IllegalStateException(failure.get());
		}
		return out.get();
	}

	/** Writes the five pictures into {@code dir}; answers the files in the order of {@link #names()}. */
	static List<File> write(final File dir) throws Exception
	{
		if (!dir.isDirectory() && !dir.mkdirs())
		{
			throw new IOException("could not create " + dir);
		}
		final List<BufferedImage> images = renderAll();
		final List<File> files = new ArrayList<>();
		final List<String> names = names();
		for (int i = 0; i < names.size(); i++)
		{
			final File f = new File(dir, names.get(i));
			if (!ImageIO.write(images.get(i), "png", f))
			{
				throw new IOException("no PNG writer for " + f);
			}
			files.add(f);
		}
		return files;
	}

	static List<String> names()
	{
		return Arrays.asList(FILE_213, FILE_230, FILE_EMPTY, FILE_ONE, FILE_HOVER);
	}

	/** Writes the five pictures into {@code args[0]}, or {@code build/history-view} when no directory is given. */
	public static void main(final String[] args) throws Exception
	{
		for (File f : write(new File(args.length > 0 ? args[0] : "build/history-view")))
		{
			System.out.println(f.getAbsolutePath());
		}
	}
}

package com.bankpricemovement;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.mockingDetails;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * The recording half's review and mutation fixes (addendum AU, review of 1bbd683): what {@link PriceService} got
 * wrong about WHEN a computation is a bank-history reading and whether its write reaches the disk.
 * <ul>
 * <li>H3 - a re-login of the account whose bank is held, on a day with no reading yet, records one.</li>
 * <li>H4 - "logged in" means the priced bank's OWNER is: another account's login is not its reading.</li>
 * <li>H5 - a write the store did not take is sent again with the next computation, never over a newer reading.</li>
 * <li>H10 - Refresh's carried re-stamp of the dev verb's made-up bank keeps it made-up.</li>
 * <li>N5 - an unchanged logout read still ends its capture's recording (amendment 9.18).</li>
 * <li>N9 - a guide price that moves under a LIVE row is a changed reading and is written.</li>
 * <li>N6 - the write's owner is the priced snapshot's, fixed under the lock (a source rule: the race cannot be
 * reached from a single-threaded test).</li>
 * </ul>
 * {@link PriceServiceTest}'s fixture by composition, with the mock store's two history methods answered by a REAL
 * {@link PriceStore} on a temporary folder, as {@link BankHistoryRecordingTest} does.
 */
public class BankHistoryRecordingReviewTest
{
	private static final long MINUTE = 60_000L;
	private static final long HOUR = 60L * MINUTE;
	private static final long DAY = 24L * HOUR;
	private static final long ACCOUNT = PriceServiceTest.ACCOUNT;
	private static final long OTHER = PriceServiceTest.OTHER_ACCOUNT;
	private static final String PROFILE = PriceServiceTest.PROFILE;
	private static final LocalDate SEP_8 = LocalDate.of(2026, 9, 8);
	private static final LocalDate SEP_9 = LocalDate.of(2026, 9, 9);

	@Rule
	public final TemporaryFolder tmp = new TemporaryFolder();

	private final PriceServiceTest f = new PriceServiceTest();
	private PriceStore disk;

	@Before
	public void setUp()
	{
		f.setUp();
		disk = new PriceStore(new Gson(), TestFilepaths.rooted(tmp.getRoot()));
		when(f.store.loadBankHistory(anyLong(), any())).thenAnswer(invocation ->
			disk.loadBankHistory(invocation.<Long>getArgument(0), invocation.<String>getArgument(1)));
		when(f.store.recordBankHistory(anyLong(), any(), any(), any())).thenAnswer(invocation ->
			disk.recordBankHistory(invocation.<Long>getArgument(0), invocation.<String>getArgument(1),
				invocation.<BankHistoryPoint>getArgument(2), invocation.<LocalDate>getArgument(3)));
		f.zonedService(ZoneOffset.UTC, false);
	}

	private void loginWith(final BankSnapshot bank)
	{
		f.service.start();
		f.service.setLoggedIn(true, ACCOUNT, PROFILE);
		f.service.setBank(bank);
	}

	private BankHistorySeries series()
	{
		return f.lastStatus().bankHistory();
	}

	private BankHistorySeries onDisk(final long account)
	{
		return disk.loadBankHistory(account, PROFILE).series();
	}

	private int writes()
	{
		int count = 0;
		for (final org.mockito.invocation.Invocation invocation : mockingDetails(f.store).getInvocations())
		{
			if ("recordBankHistory".equals(invocation.getMethod().getName()))
			{
				count++;
			}
		}
		return count;
	}

	private static BankSnapshot withMoreBoxes(final long capturedAt, final int boxes)
	{
		final BankSnapshot bank = PriceServiceTest.bank(capturedAt);
		for (int i = 0; i < bank.items.size(); i++)
		{
			if (bank.items.get(i).id == PriceServiceTest.BOX)
			{
				bank.items.set(i, bank.items.get(i).withQuantity(boxes));
			}
		}
		return bank;
	}

	// ---------------------------------------------------------------- H3

	/**
	 * Plan 7.5 item 1, "a day's reading = any day the player logs in": the client left open overnight, the game's idle
	 * logout, and the next day the same account logs in with the sidebar on another plugin. Nothing reloads (the bank
	 * is that account's) and addendum AS reads nothing from an unchanged bank, so without its own computation the
	 * day would be drawn "carried".
	 */
	@Test
	public void aReLoginOnADayWithNoReadingYetRecordsOne()
	{
		loginWith(PriceServiceTest.bank(PriceServiceTest.T0));
		f.service.setLoggedIn(false, ACCOUNT, PROFILE);
		f.clock.set(PriceServiceTest.T0 + DAY);

		f.service.setLoggedIn(true, ACCOUNT, PROFILE);

		assertNotNull("the day of the login has its reading", series().on(SEP_9));
		assertNotNull("and on disk", onDisk(ACCOUNT).on(SEP_9));
		assertEquals(f.lastStatus().portfolio().valueNow(), series().on(SEP_9).valueFor(ViewOptions.DEFAULT));
		assertTrue(f.lastStatus().loggedIn());

		// A second re-login the same day finds the reading and costs no computation.
		final int trips = f.clientThread.invocations;
		final int writes = writes();
		f.service.setLoggedIn(false, ACCOUNT, PROFILE);
		f.service.setLoggedIn(true, ACCOUNT, PROFILE);
		assertEquals(trips, f.clientThread.invocations);
		assertEquals(writes, writes());
	}

	// ---------------------------------------------------------------- H4

	/**
	 * Between another account's login and its own bank landing from disk, the service still holds the previous
	 * account's snapshot. A computation queued in that window (the 30-minute tick, a price landing) prices it while
	 * "logged in" - but not logged in as ITS owner, who never logged in that day.
	 */
	@Test
	public void theHeldBankOfAnotherAccountIsNotItsOwnersReadingAtALogin()
	{
		loginWith(PriceServiceTest.bank(PriceServiceTest.T0));
		assertNotNull(onDisk(ACCOUNT).on(SEP_8));
		f.service.setLoggedIn(false, ACCOUNT, PROFILE);
		f.clock.set(PriceServiceTest.T0 + DAY);
		when(f.store.loadBank(OTHER, PROFILE)).thenReturn(PriceServiceTest.bank(PriceServiceTest.T0 + DAY - HOUR, OTHER));

		f.scheduler.deferred = true;
		f.service.setLoggedIn(true, OTHER, PROFILE); // queues OTHER's bank load
		f.service.setOptions(ViewOptions.DEFAULT.withCountCash(false)); // queues a computation of the bank held
		// Everything but the bank load, which waits at the head of the queue.
		while (f.scheduler.queued.size() > 1)
		{
			f.scheduler.runQueued(1);
		}
		assertEquals("the computation ran over the previous account's bank", PriceServiceTest.T0,
			f.lastStatus().bankAtMillis());
		assertNull("no reading for the account that did not log in", series().on(SEP_9));
		assertNull(onDisk(ACCOUNT).on(SEP_9));

		f.scheduler.deferred = false;
		f.scheduler.runPending();

		assertNotNull("the account that did log in has its reading", onDisk(OTHER).on(SEP_9));
		assertEquals(1, onDisk(ACCOUNT).size());
	}

	// ---------------------------------------------------------------- H5

	/**
	 * A write the store did not take (a sharing violation on Windows, a clock behind the file) is sent again at the
	 * next computation, even when today's cells have not moved since - and only until one is taken.
	 */
	@Test
	public void aWriteThatFailedIsSentAgainWithTheNextComputation()
	{
		when(f.store.recordBankHistory(anyLong(), any(), any(), any())).thenReturn(false).thenAnswer(invocation ->
			disk.recordBankHistory(invocation.<Long>getArgument(0), invocation.<String>getArgument(1),
				invocation.<BankHistoryPoint>getArgument(2), invocation.<LocalDate>getArgument(3)));
		loginWith(PriceServiceTest.bank(PriceServiceTest.T0));
		assertEquals(1, writes());
		assertTrue("the first write was refused", onDisk(ACCOUNT).isEmpty());
		final BankHistoryPoint reading = series().on(SEP_8);

		f.service.setOptions(ViewOptions.DEFAULT.withCountCash(false));

		assertEquals("the same cells, sent again", 2, writes());
		assertEquals(reading, onDisk(ACCOUNT).on(SEP_8));

		f.service.setOptions(ViewOptions.DEFAULT);
		assertEquals("taken: nothing more to send", 2, writes());
	}

	/**
	 * The resend never sends an OLDER reading over a newer one: a write that fails after a later reading of the same
	 * day was taken leaves that later reading alone.
	 */
	@Test
	public void aFailedWriteOfAReadingSinceReplacedIsNotSentAgain()
	{
		final long first = PriceServiceTest.T0;
		final long second = first + MINUTE;
		final AtomicBoolean interleaved = new AtomicBoolean();
		when(f.store.recordBankHistory(anyLong(), any(), any(), any())).thenAnswer(invocation ->
		{
			final BankHistoryPoint point = invocation.getArgument(2);
			if (point.bankAtMillis() == first && interleaved.compareAndSet(false, true))
			{
				// While the first reading's write is out, a newer bank is read and its reading written; then the first
				// write fails. (The test scheduler runs every task at once, so this IS the executor's order.)
				f.service.setBank(withMoreBoxes(second, 40));
				return false;
			}
			return disk.recordBankHistory(invocation.<Long>getArgument(0), invocation.<String>getArgument(1), point,
				invocation.<LocalDate>getArgument(3));
		});
		loginWith(PriceServiceTest.bank(first));
		assertTrue(interleaved.get());
		assertEquals(2, writes());
		assertEquals(second, onDisk(ACCOUNT).on(SEP_8).bankAtMillis());
		assertEquals(second, series().on(SEP_8).bankAtMillis());

		f.service.setOptions(ViewOptions.DEFAULT.withCountCash(false));

		assertEquals("the failed older reading is not sent again", 2, writes());
		assertEquals(second, onDisk(ACCOUNT).on(SEP_8).bankAtMillis());
	}

	// ---------------------------------------------------------------- H10

	/**
	 * The plugin's Refresh re-stamps the bank it is drawing with a fresh carried half, persist true. When that bank is
	 * the dev verb's made-up one ({@code bpm bank=}), it must stay made-up: never saved, never a reading (plan 7.1
	 * item 6). A real capture afterwards is both.
	 */
	@Test
	public void aRefreshOfTheDevVerbsBankKeepsItMadeUp()
	{
		f.service.start();
		f.service.setLoggedIn(true, ACCOUNT, PROFILE);
		f.service.setBank(PriceServiceTest.bank(PriceServiceTest.T0), false);
		final BankSnapshot held = f.service.bank();
		assertNotNull(held);

		f.service.setBank(held.withCarried(new BankReader.Carried(Collections.singletonList(
			new BankItem(PriceServiceTest.item(3), 1, "Item 3", true)), Collections.<BankItem>emptyList(), 5_000L,
			PriceServiceTest.T0 + MINUTE)));

		assertTrue(f.lastStatus().portfolio().valueNow() > 0L);
		verify(f.store, never()).saveBank(any(BankSnapshot.class));
		verify(f.store, never()).recordBankHistory(anyLong(), any(), any(), any());
		assertTrue(series().isEmpty());

		f.service.setBank(PriceServiceTest.bank(PriceServiceTest.T0 + 2L * MINUTE));
		verify(f.store).saveBank(any(BankSnapshot.class));
		assertEquals(PriceServiceTest.T0 + 2L * MINUTE, onDisk(ACCOUNT).on(SEP_8).bankAtMillis());
	}

	// ---------------------------------------------------------------- N5

	/**
	 * Amendment 9.18: the logout read ends its capture's recording even when its cells equal today's reading (the
	 * bank did not change) - so a later re-pricing of that capture at the login screen never records.
	 */
	@Test
	public void anUnchangedLogoutReadStillEndsTheCapturesRecording()
	{
		loginWith(PriceServiceTest.bank(PriceServiceTest.T0));
		final BankHistoryPoint recorded = series().on(SEP_8);
		final int writes = writes();

		f.service.setLoggedIn(false, ACCOUNT, PROFILE);
		f.clock.addAndGet(10L * MINUTE);
		f.service.setBank(PriceServiceTest.bank(f.clock.get())); // the same contents, a NEW capture
		assertEquals("the same cells: nothing written", writes, writes());
		assertEquals(recorded, series().on(SEP_8));

		f.clock.addAndGet(HOUR);
		f.runelitePrice(PriceServiceTest.BOX, 5_000);
		f.service.setOptions(ViewOptions.DEFAULT.withCountCash(false));

		assertNotEquals("the prices did move", recorded.valueFor(ViewOptions.DEFAULT),
			f.lastStatus().portfolio().valueNow());
		assertEquals("its re-pricing at the login screen is not a reading", recorded, series().on(SEP_8));
		assertEquals(writes, writes());
	}

	// ---------------------------------------------------------------- N9

	/**
	 * Plan 7.7 item 7, "write when ANY cell changed": with live prices on, a live row's card figure is its live mid,
	 * while its guide figure is the guide price. Jagex's daily update moves the guide under an unchanged mid; the
	 * reading's guide cells then change and must be written, or "Use live prices" off would draw the day stale.
	 */
	@Test
	public void aGuideChangeUnderALiveRowIsWritten()
	{
		f.nameTheSeed();
		f.nameTheRing();
		f.warmUpLiveWith(BankHistoryInvariantTest.fixture(), Collections.<Integer, TradedPriceClient.Quote>emptyMap());
		f.answerDay(PriceServiceTest.SEP_7, PriceServiceTest.tradedSep7());
		final ViewOptions allOn = ViewOptions.DEFAULT.withLivePrices(true).withCountCash(true)
			.withCountUntradeables(true).withCountInventory(true);
		f.service.setOptions(allOn);
		assertTrue("the whip is live", PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.WHIP).isLive());
		final BankHistoryPoint before = series().last();
		final int writes = writes();

		f.runelitePrice(PriceServiceTest.WHIP, 800_400);
		f.service.setOptions(allOn.withCountCash(false));

		assertTrue("still live", PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.WHIP).isLive());
		final BankHistoryPoint after = series().last();
		assertEquals("the live mid did not move", before.card(BankHistoryPoint.BANK_TRADEABLE),
			after.card(BankHistoryPoint.BANK_TRADEABLE));
		assertNotEquals("the guide did", before.guide(BankHistoryPoint.BANK_TRADEABLE),
			after.guide(BankHistoryPoint.BANK_TRADEABLE));
		assertEquals("so the reading was written", writes + 1, writes());
		assertEquals(after, onDisk(ACCOUNT).last());

		final ViewOptions liveOff = allOn.withLivePrices(false);
		f.service.setOptions(liveOff);
		assertEquals("and live prices off draws the card's figure", f.lastStatus().portfolio().valueNow(),
			after.valueFor(liveOff));
	}

	// ---------------------------------------------------------------- N6

	/**
	 * The write's owner is the PRICED snapshot's, fixed under commit's lock - never the service's {@code bank} field
	 * read later, which a client-thread {@code setBank} can replace between the lock's release and the write (the
	 * old point would then land in the new owner's file). No single-threaded test reaches that window, and contract
	 * section 0 forbids a seam for it, so this pins the rule in the source: the store is called with the owner the
	 * write carries, and the write is built from {@code foldBankHistoryLocked}'s {@code PricedBank} parameter.
	 */
	@Test
	public void theWritesOwnerIsThePricedSnapshotsFixedUnderTheLock() throws IOException
	{
		final String source = priceServiceSource();

		final Matcher calls = Pattern.compile("store\\.recordBankHistory\\(").matcher(source);
		int count = 0;
		while (calls.find())
		{
			count++;
		}
		assertEquals("one call of the store's record", 1, count);
		assertTrue("the store is handed the write's own owner", Pattern.compile(
			"store\\.recordBankHistory\\(\\s*write\\.accountHash\\s*,\\s*write\\.profileType\\s*,").matcher(source).find());

		final int fold = source.indexOf("foldBankHistoryLocked(final PricedBank bank,");
		assertTrue("the fold takes the priced snapshot as `bank`", fold >= 0);
		final int foldEnd = source.indexOf("\n\t}\n", fold);
		final String foldBody = source.substring(fold, foldEnd);
		assertTrue("the write is built from that parameter", Pattern.compile(
			"new BankHistoryWrite\\(\\s*bank\\.accountHash\\s*,\\s*bank\\.profileType\\s*,").matcher(foldBody).find());
		assertFalse("and never from the field", foldBody.contains("this.bank"));
		assertEquals("built nowhere else", source.indexOf("new BankHistoryWrite("), source.lastIndexOf(
			"new BankHistoryWrite("));
	}

	private static String priceServiceSource() throws IOException
	{
		final String relative = "src/main/java/com/bankpricemovement/PriceService.java";
		Path here = Paths.get("").toAbsolutePath();
		for (int up = 0; up < 4 && here != null; up++, here = here.getParent())
		{
			final Path candidate = here.resolve(relative);
			if (Files.isRegularFile(candidate))
			{
				return new String(Files.readAllBytes(candidate), StandardCharsets.UTF_8).replace("\r\n", "\n");
			}
		}
		throw new AssertionError("PriceService.java not found from " + Paths.get("").toAbsolutePath());
	}
}

package com.bankpricemovement;

