	// ---------------------------------------------------------------- fixtures

	/**
	 * Where {@code shot} writes: the {@link TemporaryFolder}, as the sandboxed {@link Filepath} the bridge takes
	 * since addendum AD. It is a SUPPLIER rather than a value because that is the shape the bridge holds - in the
	 * client it is {@code getPluginDirectory().join(SHOT_DIR)}, asked for when a shot is taken rather than at
	 * construction, so a disk that says no becomes {@code shot}'s own error answer instead of a plugin that will
	 * not start. Handing each bridge its own supplier over the same folder keeps every test's shots together
	 * where {@link #shotFile(JsonObject)} can find them.
	 */
	private PriceStore.Directory shotDir()
	{
		return () -> TestFilepaths.rooted(shots.getRoot());
	}

	/**
	 * The file a {@code shot} answer names, as the {@link Filepath} it now is. The answer still carries the
	 * absolute path ({@code shot.file.toString()}), and this reads it back the one way that also PROVES the port:
	 * the path must start inside the directory the bridge was handed - {@code SHOT_DIR} is now just "shots" and it
	 * is the plugin that joins it onto its own data directory, so nothing here may expect a folder name of its own -
	 * and the file is then reached by joining onto that root rather than by building a bare {@code File}.
	 */
	private Filepath shotFile(JsonObject answer)
	{
		final Filepath dir = TestFilepaths.rooted(shots.getRoot());
		final String path = answer.get("path").getAsString();
		final String prefix = dir.toString() + File.separator;
		assertTrue("the shot must land in the directory the bridge was given (" + prefix + "): " + path,
			path.startsWith(prefix));
		return dir.join(path.substring(prefix.length()));
	}

	/**
	 * The picture inside a written shot, read through the {@link Filepath} instead of around it - the stream
	 * overload rather than {@code ImageIO.read(File)}, which is the same choice {@code writeShot} makes on the
	 * writing side. A stream ImageIO cannot decode answers null, so that is said out loud rather than arriving as
	 * an NPE two lines later.
	 */
	private static BufferedImage readPng(Filepath file) throws IOException
	{
		try (InputStream in = file.openInputStream())
		{
			final BufferedImage image = ImageIO.read(in);
			assertNotNull("the shot must be a readable PNG: " + file, image);
			return image;
		}
	}

	/** Sized (but never realised) panels standing in for the header and the scroll pane's view. */
	private static List<Component> parts(int... widthHeightPairs)
	{
		final List<Component> out = new ArrayList<>();
		for (int i = 0; i + 1 < widthHeightPairs.length; i += 2)
		{
			final JPanel p = new JPanel();
			p.setSize(widthHeightPairs[i], widthHeightPairs[i + 1]);
			out.add(p);
		}
		return out;
	}

	/**
	 * The days a live publish holds per window (U1, U2): {@link #LIVE_DAY} minus the window's own span, except
	 * 90d, which fell back one further day because the wiki had not closed 14 Jun when the bucket was wanted, and
	 * 180d, which has no traded bucket at all and is therefore absent - a missing key and a null value are the
	 * same answer to {@code LiveStatus}, and both must reach {@code jq} as {@code null}.
	 */
	private static Map<MovementWindow, LocalDate> liveWindowDays()
	{
		final Map<MovementWindow, LocalDate> days = new EnumMap<>(MovementWindow.class);
		days.put(MovementWindow.D1, LIVE_DAY.minusDays(1));
		days.put(MovementWindow.D7, LIVE_DAY.minusDays(7));
		days.put(MovementWindow.D30, LIVE_DAY.minusDays(30));
		days.put(MovementWindow.D90, LIVE_DAY.minusDays(91));
		return days;
	}

	/**
	 * One ISO day out of a JSON object, reading an ABSENT key and a JSON {@code null} as the same nothing - which
	 * they are to the operator, because the injected Gson drops a null field and {@code jq} answers {@code null}
	 * for both. Every live-acceptance step that reads a day is written in {@code jq}, so the tests read it the
	 * same way rather than pinning which of the two spellings this build happens to produce.
	 */
	@Nullable
	private static String isoOrNull(JsonObject o, String key)
	{
		final JsonElement e = o.get(key);
		return e == null || e.isJsonNull() ? null : e.getAsString();
	}

	/**
	 * {@code state.panel.bank} out of one answer - the path {@code jq .result.panel.bank} reads on the live run,
	 * less the lab's {@code result} wrapper - failing with what WAS there when it is missing or is not an object,
	 * because "panel is a quoted string" and "panel has no bank" are different faults in different files.
	 */
	private static JsonObject bankOf(JsonObject answer)
	{
		final JsonElement panelJson = answer.get("panel");
		assertNotNull("no panel in " + answer, panelJson);
		assertTrue("state.panel must be an object, not a quoted string: " + panelJson, panelJson.isJsonObject());
		final JsonElement bank = panelJson.getAsJsonObject().get("bank");
		assertNotNull("no bank in state.panel: " + panelJson, bank);
		assertTrue("state.panel.bank must be an object: " + bank, bank.isJsonObject());
		return bank.getAsJsonObject();
	}

	/**
	 * One {@code state.panel.bank} against what the plugin said and the panel should draw. The NAMES first, so a
	 * sixth key, a lost one or a misspelling fails on the names; then the TYPES, so a flag written as 1 / 0 or a
	 * counter written as a string cannot pass as its value; then the values, each with the moment it was taken.
	 */
	private static void assertBankHold(String when, JsonObject answer, boolean open, boolean pending, boolean glow,
		int heldEvents, int reads)
	{
		final JsonObject bank = bankOf(answer);
		assertEquals(when + ": the five keys of plan AS 7.3 and no others", BANK_KEYS, new TreeSet<>(bank.keySet()));
		assertFlag(when, bank, "open", open);
		assertFlag(when, bank, "pending", pending);
		assertFlag(when, bank, "glow", glow);
		assertCount(when, bank, "heldEvents", heldEvents);
		assertCount(when, bank, "reads", reads);
	}

	private static void assertFlag(String when, JsonObject bank, String key, boolean expected)
	{
		final JsonElement e = bank.get(key);
		assertTrue(when + ": " + key + " must be a JSON boolean: " + bank,
			e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean());
		assertEquals(when + ": " + key + " in " + bank, expected, e.getAsBoolean());
	}

	private static void assertCount(String when, JsonObject bank, String key, int expected)
	{
		final JsonElement e = bank.get(key);
		assertTrue(when + ": " + key + " must be a JSON number: " + bank,
			e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber());
		assertEquals(when + ": " + key + " in " + bank, expected, e.getAsInt());
	}

	/**
	 * A mocked {@code Status}: every addendum so far has added fields to its constructor and another agent owns
	 * that class, so stubbing the getters keeps this file off an argument list it has no business pinning.
	 * ({@code Status} is deliberately not final for exactly this.)
	 */
	private PriceService.Status status()
	{
		final PriceService.Status s = mock(PriceService.Status.class);
		when(s.text()).thenReturn(STATUS_TEXT);
		when(s.pricesAtMillis()).thenReturn(1_600_000_000_000L);
		when(s.bankAtMillis()).thenReturn(1_599_996_400_000L);
		when(s.bankLoaded()).thenReturn(true);
		when(s.loggedIn()).thenReturn(true);
		when(s.totalRows()).thenReturn(613);
		when(s.bankItems()).thenReturn(700);
		when(s.window()).thenReturn(MovementWindow.D1);
		when(s.baselineLoaded()).thenReturn(true);
		when(s.anchorDay()).thenReturn(ANCHOR_DAY);
		when(s.agree()).thenReturn(AGREE);
		when(s.r0Day()).thenReturn(R0_DAY);
		when(s.thenDay()).thenReturn(THEN_DAY);
		when(s.thenRevId()).thenReturn(REV_ID);
		when(s.mappingAtMillis()).thenReturn(MAPPING_AT);
		// The four the bridge echoes and nothing used to stub, so all four read as a never-wired field would
		// (see stateEchoesTheSourceTheIndexAgeAndTheProblemSeparatelyFromTheHeader). problem() is deliberately
		// NOT stubbed here: this fixture is the HEALTHY status - a baseline is loaded - and a healthy status
		// has no problem sentence (PriceService.problemLocked answers null once the window has a revision).
		when(s.source()).thenReturn(MovementRow.PriceSource.GUIDE);
		when(s.agreeSamples()).thenReturn(AGREE_SAMPLES);
		when(s.indexAtMillis()).thenReturn(INDEX_AT);
		return s;
	}

	/**
	 * A {@link BankPriceMovementPanel.Prefs} that starts on the default filter and forgets every save - for the
	 * real-panel tests whose subject is what a WIDGET shows rather than what was written to the config.
	 */
	private static BankPriceMovementPanel.Prefs prefs()
	{
		return new BankPriceMovementPanel.Prefs()
		{
			@Override
			public RowFilter load()
			{
				return RowFilter.DEFAULT;
			}

			@Override
			public void save(RowFilter filter)
			{
			}
		};
	}

	private static BpmCommands.Account account()
	{
		return account(4242L);
	}

	/** The seam with a chosen hash: 0 and -1 are the two ways the client says "nobody is logged in". */
	private static BpmCommands.Account account(long hash)
	{
		return new BpmCommands.Account()
		{
			@Override
			public long hash()
			{
				return hash;
			}

			@Override
			public String profileType()
			{
				return "STANDARD";
			}
		};
	}

	private static RowFilter last(List<RowFilter> saved)
	{
		assertFalse("nothing was written to the config", saved.isEmpty());
		return saved.get(saved.size() - 1);
	}

	private JsonObject reply(BpmCommands bridge, String cmd)
	{
		final String s = bridge.apply(cmd);
		assertNotNull("the bridge always answers", s);
		return gson.fromJson(s, JsonObject.class);
	}

	private JsonObject send(String cmd)
	{
		return reply(dev, cmd);
	}

	private JsonObject ok(String cmd)
	{
		return ok(dev, cmd);
	}

	/** The same, for a test that built its own bridge (a recording seam, a shorter timeout). */
	private JsonObject ok(BpmCommands bridge, String cmd)
	{
		final JsonObject r = reply(bridge, cmd);
		assertTrue(cmd + " -> " + r, r.get("ok").getAsBoolean());
		return r;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

/**
 * Addendum AU, amendment 9.12: the four semantics of {@link BankHistoryView#describe()} the panel relies on across the
 * seam - {@code range}, {@code readings}, {@code first}, {@code last} - which the view must keep whatever it draws; plus
 * the seven keys and their types (amendment 9.11). {@code SidebarHistorySeamTest} drives the same view through the real
 * panel.
 */
public class BankHistoryViewSeamTest
{
	private static final ZoneId TORONTO = ZoneId.of("America/Toronto");

	/** Local noon of a September day in Toronto, as amendment 9.1 tells the panel's tests to build stamps. */
	private static long noon(final int day)
	{
		return LocalDate.of(2026, 9, day).atTime(12, 0).atZone(TORONTO).toInstant().toEpochMilli();
	}

	private static BankHistorySeries series(final int... days)
	{
		final BankHistoryPoint[] points = new BankHistoryPoint[days.length];
		for (int i = 0; i < days.length; i++)
		{
			points[i] = BankHistorySeriesTest.p(BankHistorySeriesTest.sep(days[i]), noon(days[i]), 1_000L * days[i]);
		}
		return BankHistorySeries.of(Arrays.asList(points));
	}

	@Test
	public void theRangeStartsAtTheDefaultWindowsAndFollowsSetRange()
	{
		final BankHistoryView view = new BankHistoryView(() -> noon(20), TORONTO);
		assertEquals("7d", view.describe().get("range"));

		view.setRange(BankHistoryRange.D90);
		assertEquals("90d", view.describe().get("range"));
		view.setRange(BankHistoryRange.ALL);
		assertEquals("all", view.describe().get("range"));
		view.setRange(null);
		assertEquals("null is ignored", "all", view.describe().get("range"));
	}

	@Test
	public void readingsFirstAndLastComeFromTheLastShowCutToToday()
	{
		final AtomicLong clock = new AtomicLong(noon(20));
		final BankHistoryView view = new BankHistoryView(clock::get, TORONTO);
		assertEquals(0, view.describe().get("readings"));
		assertNull(view.describe().get("first"));
		assertNull(view.describe().get("last"));

		view.show(series(3, 9, 20, 22), ViewOptions.DEFAULT);

		assertEquals("the 22nd is after today and is not drawn", 3, view.describe().get("readings"));
		assertEquals("2026-09-03", view.describe().get("first"));
		assertEquals("2026-09-20", view.describe().get("last"));

		clock.set(noon(22));
		view.show(series(3, 9, 20, 22), null);
		assertEquals(4, view.describe().get("readings"));
		assertEquals("2026-09-22", view.describe().get("last"));

		view.show(null, null);
		assertEquals("null reads as EMPTY", 0, view.describe().get("readings"));
		assertNull(view.describe().get("first"));
	}

	@Test
	public void todayIsTheClocksLocalDate()
	{
		// 21 Sep 01:00 UTC is still 20 Sep in Toronto.
		final long lateEvening = LocalDate.of(2026, 9, 21).atTime(1, 0).toInstant(ZoneOffset.UTC).toEpochMilli();
		final BankHistoryView view = new BankHistoryView(() -> lateEvening, TORONTO);
		view.show(series(20, 21), ViewOptions.DEFAULT);
		assertEquals(1, view.describe().get("readings"));
		assertEquals("2026-09-20", view.describe().get("last"));
	}

	@Test
	public void describeHasExactlyTheSevenKeysInOrderWithStringIntegerAndNullValues()
	{
		final BankHistoryView view = new BankHistoryView(() -> noon(20), TORONTO);
		view.show(series(19, 20), ViewOptions.DEFAULT);
		final LinkedHashMap<String, Object> map = view.describe();

		assertEquals(Arrays.asList("readings", "first", "last", "range", "rows", "carriedRows", "hoverDay"),
			Arrays.asList(map.keySet().toArray()));
		assertEquals(Integer.valueOf(2), map.get("readings"));
		assertEquals("2026-09-19", map.get("first"));
		// The rows built: the 19th and the 20th, neither carried.
		assertEquals(Integer.valueOf(2), map.get("rows"));
		assertEquals(Integer.valueOf(0), map.get("carriedRows"));
		assertNull(map.get("hoverDay"));
		assertFalse("nothing more to page", view.showMore());
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import org.junit.Test;

/**
 * {@link GuideSnapshot} after addendum L: the DAY a table's prices belong to (L7) and the one name-folding rule
 * every lookup goes through (L8).
 *
 * <p>The two tests that carry the addendum are {@link #aHumanEditCarriesThePreviousDaysPricesUnderALaterStamp()}
 * and {@link #aCaseRenamedKeyIsStillFound()}. The first is revision 15329323 (Riblet15, saved
 * 2026-09-03T06:46Z, {@code %LAST_UPDATE_F%} "02 September 2026 07:21:23") - the measured proof that the
 * revision timestamp is not the data day (L-E). The second is the wiki's August 2026 case rename of 81 keys
 * ("3rd age amulet" to "3rd Age amulet"), which cost a byte-exact lookup three of the user's bank items on every
 * window of 30 days or more (L-F).
 *
 * <p>Fixture figures are the live ones from revision 15333448 (Green hat 1124, Barrel 835, Abyssal whip 807253,
 * 3rd Age axe 2,147,483,646) - {@code docs/research/bank-price-movement-calibration-2026-09-08.md}.
 */
public class GuideSnapshotTest
{
	/** 2026-09-07T19:55:12Z - when revision 15333448 was SAVED. */
	private static final long EDIT_SECONDS = 1_788_810_912L;
	/** 2026-09-07T19:45:22Z - the {@code %LAST_UPDATE%} inside that revision's body. */
	private static final long DATA_SECONDS = 1_788_810_322L;
	private static final long REV_ID = 15_333_448L;
	private static final long FETCHED_MILLIS = 1_788_909_600_123L;

	private static GuideSnapshot snapshot(final Map<String, Long> prices)
	{
		return new GuideSnapshot(REV_ID, EDIT_SECONDS, DATA_SECONDS, FETCHED_MILLIS, prices);
	}

	private static Map<String, Long> table()
	{
		final Map<String, Long> prices = new LinkedHashMap<>();
		prices.put("Green hat", 1124L);
		prices.put("Barrel", 835L);
		prices.put("Abyssal whip", 807_253L);
		return prices;
	}

	// ---------------------------------------------------------------- L7: the day marker

	@Test
	public void aSnapshotCarriesItsRevisionItsSaveTimeItsDayMarkerAndItsFetchStamp()
	{
		final GuideSnapshot table = snapshot(table());

		assertEquals(REV_ID, table.revId());
		assertEquals("the save time is cache identity only since addendum L", EDIT_SECONDS, table.revisionSeconds());
		assertEquals(DATA_SECONDS, table.dataSeconds());
		assertEquals(FETCHED_MILLIS, table.fetchedAtMillis());
		assertEquals(LocalDate.of(2026, 9, 7), table.dataDay());
		assertEquals(3, table.size());
		assertFalse(table.isEmpty());
	}

	/**
	 * The measurement addendum L is built on. Revision 15329323 was saved on 2026-09-03 and holds the table
	 * Jagex stamped on 2026-09-02: a status line reading the SAVE time would label those prices a day too late,
	 * and the L5 day check would have nothing to catch it with.
	 */
	@Test
	public void aHumanEditCarriesThePreviousDaysPricesUnderALaterStamp()
	{
		// 2026-09-03T06:46:00Z saved; %LAST_UPDATE% 2026-09-02T07:21:23Z.
		final GuideSnapshot stale = new GuideSnapshot(15_329_323L, 1_788_417_960L, 1_788_333_683L,
			FETCHED_MILLIS, table());

		assertEquals(LocalDate.of(2026, 9, 3), RevisionRef.dayOf(stale.revisionSeconds()));
		assertEquals("the day the prices are from, which is the one the row must be labelled with",
			LocalDate.of(2026, 9, 2), stale.dataDay());
	}

	@Test
	public void aTableWithNoDayMarkerHasNoDay()
	{
		assertNull(new GuideSnapshot(REV_ID, EDIT_SECONDS, 0L, FETCHED_MILLIS, table()).dataDay());
		assertNull(GuideSnapshot.EMPTY.dataDay());
	}

	/** Midnight UTC is the day boundary wherever the client runs (L9) - this box is four hours behind it. */
	@Test
	public void theDayIsUtcAndNotTheMachineZone()
	{
		assertEquals(LocalDate.of(2026, 9, 9),
			new GuideSnapshot(1L, 1L, 1_788_912_000L, 1L, table()).dataDay());
		assertEquals(LocalDate.of(2026, 9, 8),
			new GuideSnapshot(1L, 1L, 1_788_911_999L, 1L, table()).dataDay());
	}

	@Test
	public void emptyIsTheNoTableYetSnapshot()
	{
		assertTrue(GuideSnapshot.EMPTY.isEmpty());
		assertEquals(0, GuideSnapshot.EMPTY.size());
		assertEquals(0L, GuideSnapshot.EMPTY.revId());
		assertEquals(0L, GuideSnapshot.EMPTY.revisionSeconds());
		assertEquals(0L, GuideSnapshot.EMPTY.dataSeconds());
		assertEquals(0L, GuideSnapshot.EMPTY.fetchedAtMillis());
		assertNull(GuideSnapshot.EMPTY.get("Green hat"));
	}

	// ---------------------------------------------------------------- L8: one name-folding rule

	@Test
	public void aPriceIsFoundByTheNameTheWikiSpellsItWith()
	{
		final GuideSnapshot table = snapshot(table());

		assertEquals(Long.valueOf(1124L), table.get("Green hat"));
		assertEquals(Long.valueOf(835L), table.get("Barrel"));
		assertEquals(Long.valueOf(807_253L), table.get("Abyssal whip"));
		assertNull("a name the table does not list is null, not zero", table.get("Twisted bow"));
		assertNull(table.get(null));
	}

	/**
	 * The wiki case-renamed 81 keys on 2026-08-12..20 (L-F). A 30d or 180d baseline therefore spells three of
	 * the user's bank items the OLD way while the mapping spells them the new way; folding both sides is what
	 * recovers them.
	 */
	@Test
	public void aCaseRenamedKeyIsStillFound()
	{
		final Map<String, Long> old = new HashMap<>();
		old.put("3rd age amulet", 2_100_000L);

		final GuideSnapshot august = snapshot(old);

		assertEquals("the mapping's spelling today", Long.valueOf(2_100_000L), august.get("3rd Age amulet"));
		assertEquals("and the revision's own spelling", Long.valueOf(2_100_000L), august.get("3rd age amulet"));
		assertEquals(Long.valueOf(2_100_000L), august.get("3RD AGE AMULET"));
	}

	@Test
	public void theFoldNormalisesSpacingAndCaseAndNothingElse()
	{
		assertEquals("green hat", GuideSnapshot.key("Green hat"));
		assertEquals("leading, trailing and doubled spaces are invisible in a wiki edit box",
			"green hat", GuideSnapshot.key("  Green   hat "));
		assertEquals("a tab is whitespace as well", "green hat", GuideSnapshot.key("Green\that"));
		assertEquals("and so is the non-breaking space in this fixture, which \\s does NOT match",
			"green hat", GuideSnapshot.key("Green\u00A0hat"));
		assertNull(GuideSnapshot.key(null));
		assertEquals("", GuideSnapshot.key("   "));
	}

	/**
	 * Qualifiers and punctuation are NEVER stripped (L8 d). "Karambwan vessel (baited)" and "Karambwan vessel"
	 * are different items with prices a median 86 % apart, and collapsing them is precisely the defect the
	 * composition-name fallback had (L-F).
	 */
	@Test
	public void aQualifierIsPartOfTheNameAndIsNeverStripped()
	{
		final Map<String, Long> prices = new HashMap<>();
		prices.put("Karambwan vessel", 12L);
		prices.put("Karambwan vessel (baited)", 3388L);

		final GuideSnapshot table = snapshot(prices);

		assertEquals(Long.valueOf(3388L), table.get("Karambwan vessel (baited)"));
		assertEquals(Long.valueOf(12L), table.get("Karambwan vessel"));
		assertEquals("two names, two entries", 2, table.size());
	}

	/**
	 * The Turkish locale is the classic trap: {@code "I".toLowerCase()} there is a DOTLESS i, so a fold using
	 * the default locale would key "Ice gloves" onto a string no table holds and the item would silently lose
	 * its price - on that user's machine only. {@link Locale#ROOT} is what makes the fold the same everywhere.
	 */
	@Test
	public void theFoldIsLocaleIndependent()
	{
		final Locale original = Locale.getDefault();
		try
		{
			Locale.setDefault(new Locale("tr", "TR"));

			assertEquals("ice gloves", GuideSnapshot.key("Ice gloves"));
			assertEquals(Long.valueOf(180L),
				snapshot(one("Ice gloves", 180L)).get("ICE GLOVES"));
		}
		finally
		{
			Locale.setDefault(original);
		}
	}

	// ---------------------------------------------------------------- L8 (c): the unpriced sentinel

	/**
	 * Three table values were exactly 2,147,483,646 on the sampled revisions - "3rd Age axe", "3rd Age druidic
	 * robe top", "3rd Age pickaxe" - and they mean "no price", not "two billion gp". Left in, the 3rd Age axe in
	 * the user's bank would read as the single largest holding they own and dominate every sort.
	 */
	@Test
	public void theUnpricedSentinelIsNotAPrice()
	{
		final Map<String, Long> prices = table();
		prices.put("3rd Age axe", GuideSnapshot.NO_PRICE);
		prices.put("3rd Age pickaxe", GuideSnapshot.NO_PRICE + 1L);
		prices.put("Twisted bow", GuideSnapshot.NO_PRICE - 1L);

		final GuideSnapshot table = snapshot(prices);

		assertEquals(2_147_483_646L, GuideSnapshot.NO_PRICE);
		assertNull(table.get("3rd Age axe"));
		assertNull("anything at or above the sentinel is unpriced", table.get("3rd Age pickaxe"));
		assertEquals("one gp below it is a real, if absurd, price",
			Long.valueOf(2_147_483_645L), table.get("Twisted bow"));
		assertEquals("three real prices plus the Twisted bow", 4, table.size());
	}

	// ---------------------------------------------------------------- immutability and value semantics

	@Test
	public void theTableIsCopiedAtConstructionAndHandedOutUnmodifiable()
	{
		final Map<String, Long> source = table();
		final GuideSnapshot table = snapshot(source);

		source.put("Twisted bow", 1L);
		source.remove("Barrel");

		assertEquals("the snapshot does not follow the caller's map", 3, table.size());
		assertNull(table.get("Twisted bow"));
		assertEquals(Long.valueOf(835L), table.get("Barrel"));

		try
		{
			table.pricesByName().put("Twisted bow", 1L);
			fail("pricesByName() must be unmodifiable - it is read while rows are computed on another thread");
		}
		catch (final UnsupportedOperationException expected)
		{
			// the point of the test
		}
	}

	@Test
	public void theStoredKeysAreTheFoldedOnes()
	{
		assertEquals("green hat", snapshot(one("Green Hat", 1124L)).pricesByName().keySet().iterator().next());
	}

	@Test
	public void damagedEntriesAreDroppedRatherThanStored()
	{
		final Map<String, Long> source = new HashMap<>();
		source.put("Green hat", 1124L);
		source.put(null, 5L);
		source.put("Barrel", null);
		source.put("   ", 7L);

		final GuideSnapshot table = snapshot(source);

		assertEquals(1, table.size());
		assertEquals(Long.valueOf(1124L), table.get("Green hat"));
	}

	@Test
	public void aNullSourceMapIsAnEmptyTable()
	{
		final GuideSnapshot table = new GuideSnapshot(REV_ID, EDIT_SECONDS, DATA_SECONDS, FETCHED_MILLIS, null);

		assertTrue(table.isEmpty());
		assertEquals(DATA_SECONDS, table.dataSeconds());
	}

	@Test
	public void snapshotsCompareByValue()
	{
		assertEquals(snapshot(table()), snapshot(table()));
		assertEquals(snapshot(table()).hashCode(), snapshot(table()).hashCode());
		assertNotEquals("two revisions of the same numbers are different snapshots",
			snapshot(table()), new GuideSnapshot(REV_ID + 1L, EDIT_SECONDS, DATA_SECONDS, FETCHED_MILLIS, table()));
		assertNotEquals("and so are two DAYS of the same numbers",
			snapshot(table()), new GuideSnapshot(REV_ID, EDIT_SECONDS, DATA_SECONDS + 86_400L, FETCHED_MILLIS, table()));
		assertNotEquals(snapshot(table()), GuideSnapshot.EMPTY);
		assertNotEquals(snapshot(table()), null);
	}

	@Test
	public void toStringNamesTheRevisionAndTheDay()
	{
		final String text = snapshot(table()).toString();

		assertTrue(text, text.contains("15333448"));
		assertTrue(text, text.contains("2026-09-07"));
		assertTrue(text, text.contains("names=3"));
	}

	// ---------------------------------------------------------------- fixtures

	/** A one-entry table; a mutable map rather than {@code singletonMap} so the constructor really copies it. */
	private static Map<String, Long> one(final String name, final long price)
	{
		final Map<String, Long> prices = new HashMap<>();
		prices.put(name, price);
		return prices;
	}
}

package com.bankpricemovement;

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import net.runelite.client.util.Filepath;

/**
 * Turns a JUnit {@code TemporaryFolder} into the {@link Filepath} the plugin's classes now take, and reads and
 * writes one in a line (addendum AD).
 *
 * <p><b>Why {@code Filepath.Unchecked} is allowed HERE and nowhere else.</b> In the client a plugin gets its
 * directory from {@code Plugin.getPluginDirectory()}, which is {@code protected} on RuneLite's {@code Plugin}
 * and roots itself at {@code ~/.runelite/plugin-data/<internalName>/}. A unit test has no plugin instance and
 * must never touch the real {@code ~/.runelite}, so it makes its own root over a temporary folder - which is
 * exactly what {@code Unchecked.getRooted} is for. RuneLite's own javadoc warns that using {@code Unchecked}
 * stops a Plugin Hub plugin being reviewed automatically, and that warning is about SHIPPED code: the Hub
 * never sees {@code src/test} (it is not packaged and not scanned), and {@code FileIoRuleTest} proves no class
 * under {@code src/main} names it.
 *
 * <p>Test-only helper: it lives in the test source set and nothing in {@code src/main} may reference it.
 */
final class TestFilepaths
{
	private TestFilepaths()
	{
	}

	/** A {@link Filepath} rooted at {@code dir}, so nothing a test writes can land outside it. */
	static Filepath rooted(final File dir)
	{
		return Filepath.Unchecked.getRooted(dir.toPath());
	}

	/** {@code dir/name}, the way production builds every path: by joining onto the root. */
	static Filepath at(final File dir, final String name)
	{
		return rooted(dir).join(name);
	}

	/** Writes UTF-8 text, creating or replacing the file, and creating its directory if it is missing. */
	static void write(final Filepath file, final String text) throws IOException
	{
		final Filepath parent = file.getParent();
		if (!parent.isDirectory())
		{
			parent.createDirectories();
		}
		try (OutputStream out = file.openOutputStream(StandardOpenOption.CREATE, StandardOpenOption.WRITE,
			StandardOpenOption.TRUNCATE_EXISTING))
		{
			out.write(text.getBytes(StandardCharsets.UTF_8));
		}
	}

	/** The whole file as UTF-8 text. */
	static String read(final Filepath file) throws IOException
	{
		try (InputStream in = file.openInputStream())
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import java.util.Arrays;
import org.junit.Test;

/** {@link BankHistoryRange} (addendum AU, contract section 3 and plan 7.2 item 6). */
public class BankHistoryRangeTest
{
	@Test
	public void theFourRangesInOrderWithTheirDaysAndLabels()
	{
		assertEquals(Arrays.asList(BankHistoryRange.D7, BankHistoryRange.D30, BankHistoryRange.D90,
			BankHistoryRange.ALL), Arrays.asList(BankHistoryRange.values()));
		assertEquals(7, BankHistoryRange.D7.days());
		assertEquals(30, BankHistoryRange.D30.days());
		assertEquals(90, BankHistoryRange.D90.days());
		assertEquals(0, BankHistoryRange.ALL.days());
		assertEquals("7d", BankHistoryRange.D7.label());
		assertEquals("30d", BankHistoryRange.D30.label());
		assertEquals("90d", BankHistoryRange.D90.label());
		assertEquals("all", BankHistoryRange.ALL.label());
		for (final BankHistoryRange range : BankHistoryRange.values())
		{
			assertEquals(range.label(), range.toString());
		}
	}

	@Test
	public void theCardsWindowPicksTheRange()
	{
		assertEquals(BankHistoryRange.D7, BankHistoryRange.forWindow(MovementWindow.D1));
		assertEquals(BankHistoryRange.D7, BankHistoryRange.forWindow(MovementWindow.D7));
		assertEquals(BankHistoryRange.D30, BankHistoryRange.forWindow(MovementWindow.D30));
		assertEquals(BankHistoryRange.D90, BankHistoryRange.forWindow(MovementWindow.D90));
		assertEquals(BankHistoryRange.ALL, BankHistoryRange.forWindow(MovementWindow.D180));
		assertEquals("a null window is the default window's range", BankHistoryRange.D7,
			BankHistoryRange.forWindow(null));
		assertEquals(BankHistoryRange.forWindow(MovementWindow.DEFAULT), BankHistoryRange.forWindow(null));
	}
}

package com.bankpricemovement;

import static com.bankpricemovement.BankHistorySeriesTest.sep;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.withSettings;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.OpenOption;
import java.nio.file.StandardOpenOption;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The history file's review fixes (addendum AU, review of 65c7e4d / 1bbd683): the ways a store that obeyed every
 * rule of contract section 4 could still lose readings.
 * <ul>
 * <li>H1 - a clock set BACK must not prune every stored reading as "the future".</li>
 * <li>H2 - a file whose existence cannot be told is read, never taken for missing and written over.</li>
 * <li>H6 - the history's bytes reach the disk before the atomic move.</li>
 * <li>H7 - a file holding entries this build cannot keep is copied aside before its first rewrite.</li>
 * <li>H8 - an owner whose file failed is not read (and warned about) again this session.</li>
 * </ul>
 * Real disk through {@link TestFilepaths}; where a test must see what {@link Filepath} is ASKED (H2, H6), the store's
 * directory is a Mockito spy of the real one whose every joined path is a spy too.
 */
public class PriceStoreHistoryReviewTest
{
	private static final long ACCOUNT = 42L;
	private static final String PROFILE = "STANDARD";
	private static final LocalDate TODAY = sep(28);

	private final Gson gson = new Gson();

	@Rule
	public final TemporaryFolder tmp = new TemporaryFolder();

	private PriceStore store()
	{
		return new PriceStore(gson, TestFilepaths.rooted(tmp.getRoot()));
	}

	private static BankHistoryPoint point(final LocalDate day, final long readAt, final long base)
	{
		final long[] card = new long[BankHistoryPoint.CELLS];
		Arrays.fill(card, base);
		return new BankHistoryPoint(day, readAt, readAt, card, null);
	}

	private static String entry(final LocalDate day, final long readAt)
	{
		return "{\"day\":\"" + day + "\",\"readAtMillis\":" + readAt + ",\"bankAtMillis\":" + readAt
			+ ",\"card\":[1,1,1,1,1,1,1,1]}";
	}

	/** A document holding one reading for every day from {@code from} to {@code to}, both included. */
	private static String days(final LocalDate from, final LocalDate to)
	{
		final StringBuilder json = new StringBuilder("{\"schema\":1,\"points\":[");
		for (LocalDate day = from; !day.isAfter(to); day = day.plusDays(1))
		{
			if (!day.equals(from))
			{
				json.append(',');
			}
			json.append(entry(day, day.toEpochDay()));
		}
		return json.append("]}").toString();
	}

	private List<String> namesContaining(final String part)
	{
		final List<String> found = new ArrayList<>();
		final String[] names = tmp.getRoot().list();
		for (final String name : names == null ? new String[0] : names)
		{
			if (name.contains(part))
			{
				found.add(name);
			}
		}
		found.sort(null);
		return found;
	}

	// ---- H1: a clock behind the file

	/**
	 * A PC whose clock falls back to 01 Jan 2000 (a dead CMOS battery) files its first reading under 2000; the 28
	 * readings of September 2026 are then all "after today". Pruning them would replace the file with one point.
	 */
	@Test
	public void aClockSetBackBehindTheStoredReadingsWritesNothing() throws IOException
	{
		final PriceStore store = store();
		final Filepath file = store.historyFile(ACCOUNT, PROFILE);
		final String september = days(sep(1), sep(28));
		TestFilepaths.write(file, september);

		final LocalDate y2k = LocalDate.of(2000, 1, 1);
		assertFalse(store.recordBankHistory(ACCOUNT, PROFILE, point(y2k, 1L, 5L), y2k));
		assertEquals("not a byte changed", september, TestFilepaths.read(file));

		assertTrue("the clock put right, it records again",
			store.recordBankHistory(ACCOUNT, PROFILE, point(sep(29), 2L, 5L), sep(29)));
		assertEquals(29, store.loadBankHistory(ACCOUNT, PROFILE).series().size());
	}

	/**
	 * The one reading a traveller's clock put a day ahead is not a reason to stop: as long as the readings ahead are
	 * fewer than the ones on or before today (the new one counted), they are dropped as plan 7.1 item 7 says.
	 */
	@Test
	public void aFewReadingsAheadOfTheClockAreStillDropped() throws IOException
	{
		final PriceStore store = store();
		final Filepath file = store.historyFile(ACCOUNT, PROFILE);
		TestFilepaths.write(file, days(sep(20), sep(30)));
		// 20..27 and today: 9 on or before today; 29 and 30: 2 ahead.
		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 1L, 5L), TODAY));
		final BankHistorySeries s = store.loadBankHistory(ACCOUNT, PROFILE).series();
		assertEquals(9, s.size());
		assertEquals(TODAY, s.last().day());

		// As many ahead as on or before today (the new one counted: one and one) is a clock behind the file.
		final Filepath other = store.historyFile(ACCOUNT, "DEADMAN");
		final String even = days(sep(26), sep(26));
		TestFilepaths.write(other, even);
		assertFalse(store.recordBankHistory(ACCOUNT, "DEADMAN", point(sep(25), 1L, 5L), sep(25)));
		assertEquals(even, TestFilepaths.read(other));
	}

	// ---- H2: existence that cannot be told

	/**
	 * {@code Files.exists} answers false when it cannot tell - a transient error, a refused attribute read. A file
	 * read as missing on that word is a file the record writes a one-point document over. The store must open it.
	 */
	@Test
	public void aFileWhoseExistenceCannotBeToldIsReadNotReplaced() throws IOException
	{
		final Watched watched = new Watched();
		final PriceStore store = new PriceStore(gson, watchedRoot(watched));
		final Filepath file = store.historyFile(ACCOUNT, PROFILE);
		TestFilepaths.write(TestFilepaths.at(tmp.getRoot(), file.getFileName()), days(sep(1), sep(27)));
		watched.hideHistory = true;
		assertFalse("the premise: the store's own path says the file is not there", file.exists());

		assertEquals(PriceStore.BankHistoryLoad.State.LOADED, store.loadBankHistory(ACCOUNT, PROFILE).state());
		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 1L, 5L), TODAY));

		assertEquals("every September reading kept", 28, store().loadBankHistory(ACCOUNT, PROFILE).series().size());
	}

	/** And a file that really is not there is still MISSING - the open's own NoSuchFileException says so. */
	@Test
	public void aFileThatIsNotThereIsStillMissing()
	{
		final PriceStore inMissingFolder = new PriceStore(gson, TestFilepaths.at(tmp.getRoot(), "not-made-yet"));
		assertEquals(PriceStore.BankHistoryLoad.State.MISSING,
			inMissingFolder.loadBankHistory(ACCOUNT, PROFILE).state());
		assertEquals(PriceStore.BankHistoryLoad.State.MISSING, store().loadBankHistory(ACCOUNT, PROFILE).state());
		assertTrue(store().recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 1L, 5L), TODAY));
	}

	// ---- H6: durable

	/** The history's temp file is written through DSYNC; the caches' are not (they are fetched again). */
	@Test
	public void theHistoryIsWrittenThroughToTheDiskBeforeItsMove()
	{
		final Watched watched = new Watched();
		final PriceStore store = new PriceStore(gson, watchedRoot(watched));
		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 1L, 5L), TODAY));
		store.saveBank(new BankSnapshot(new ArrayList<BankItem>(), 5L, ACCOUNT, PROFILE));

		final List<String> historyTemps = new ArrayList<>();
		final List<String> bankTemps = new ArrayList<>();
		for (final Written written : watched.writes)
		{
			(written.name.startsWith(PriceStore.HISTORY_PREFIX) ? historyTemps : bankTemps).add(written.name);
			if (written.name.startsWith(PriceStore.HISTORY_PREFIX))
			{
				assertArrayEquals(written.name, new OpenOption[]{StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE,
					StandardOpenOption.DSYNC}, written.options);
			}
			else
			{
				assertFalse(written.name, Arrays.asList(written.options).contains(StandardOpenOption.DSYNC));
			}
		}
		assertEquals("one history temp file: " + historyTemps, 1, historyTemps.size());
		assertTrue(historyTemps.get(0).endsWith(".tmp"));
		assertEquals("one bank temp file: " + bankTemps, 1, bankTemps.size());
		assertEquals(1, store.loadBankHistory(ACCOUNT, PROFILE).series().size());
	}

	// ---- H7: what a rewrite would drop is copied aside first

	/**
	 * An entry that does not parse is skipped on the read (contract section 4) and would be gone after the rewrite;
	 * so would a key this build does not know. The first rewrite of the session copies the file as it was.
	 */
	@Test
	public void aFileWithEntriesThisBuildCannotKeepIsCopiedAsideBeforeItsFirstRewrite() throws IOException
	{
		final PriceStore store = store();
		final Filepath file = store.historyFile(ACCOUNT, PROFILE);
		final String damaged = "{\"schema\":1,\"points\":[" + entry(sep(1), 1L) + ",{\"day\":\"2026-09-02\"}]}";
		TestFilepaths.write(file, damaged);

		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 1L, 5L), TODAY));
		final List<String> copies = namesContaining(".corrupt-");
		assertEquals(1, copies.size());
		assertTrue(copies.get(0).startsWith("history-42-STANDARD.json.corrupt-"));
		assertEquals("the copy is the file as it was", damaged,
			TestFilepaths.read(TestFilepaths.at(tmp.getRoot(), copies.get(0))));
		assertEquals(Arrays.asList(sep(1), TODAY), BankHistorySeriesTest.days(store.loadBankHistory(ACCOUNT, PROFILE)
			.series()));

		// Once a session is enough: the copy already holds what this build could not keep.
		TestFilepaths.write(file, damaged);
		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 2L, 6L), TODAY));
		assertEquals(1, namesContaining(".corrupt-").size());
	}

	@Test
	public void unknownKeysAndDuplicateDaysAreKeptInTheCopyToo() throws IOException
	{
		final String[] kinds = {
			"{\"schema\":1,\"note\":\"a newer build's\",\"points\":[" + entry(sep(1), 1L) + "]}",
			"{\"schema\":1,\"points\":[{\"day\":\"2026-09-01\",\"readAtMillis\":1,\"bankAtMillis\":1,"
				+ "\"card\":[1,1,1,1,1,1,1,1],\"items\":12}]}",
			"{\"schema\":1,\"points\":[" + entry(sep(1), 1L) + "," + entry(sep(1), 2L) + "]}"};
		for (final String kind : kinds)
		{
			final PriceStore store = store();
			final Filepath file = store.historyFile(ACCOUNT, PROFILE);
			TestFilepaths.write(file, kind);
			assertTrue(kind, store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 1L, 5L), TODAY));
			final List<String> copies = namesContaining(".corrupt-");
			assertEquals(kind, 1, copies.size());
			final Filepath copy = TestFilepaths.at(tmp.getRoot(), copies.get(0));
			assertEquals(kind, kind, TestFilepaths.read(copy));
			copy.delete();
			file.delete();
		}
	}

	/** A file this build writes itself holds nothing it cannot keep: no copy is ever made of it. */
	@Test
	public void aCleanFileIsRewrittenWithNoCopy()
	{
		final PriceStore store = store();
		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(sep(27), 1L, 5L), TODAY));
		assertTrue(store.recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 2L, 5L), TODAY));
		assertTrue(store().recordBankHistory(ACCOUNT, PROFILE, point(TODAY, 3L, 6L), TODAY));
		assertTrue(namesContaining(".corrupt-").isEmpty());
	}

	// ---- H8: one WARN

	/** A failed owner answers FAILED for the rest of the session without its file being read (or warned about) again. */
	@Test
	public void anOwnerWhoseFileFailedIsNotReadAgainThisSession() throws IOException
	{
		final PriceStore store = store();
		final Filepath file = store.historyFile(ACCOUNT, PROFILE);
		file.createDirectories();
		assertEquals(PriceStore.BankHistoryLoad.State.FAILED, store.loadBankHistory(ACCOUNT, PROFILE).state());

		file.delete();
		TestFilepaths.write(file, days(sep(1), sep(2)));
		assertEquals(PriceStore.BankHistoryLoad.State.FAILED, store.loadBankHistory(ACCOUNT, PROFILE).state());
		assertEquals("a restart reads it", PriceStore.BankHistoryLoad.State.LOADED,
			store().loadBankHistory(ACCOUNT, PROFILE).state());
	}

	// ---- the spy

	/** What {@link #watchedRoot} saw, and the one lie it can tell. */
	private static final class Watched
	{
		final List<Written> writes = new ArrayList<>();
		/** When set, every {@code history-*} path answers {@code exists()} false - "cannot tell". */
		boolean hideHistory;
	}

	private static final class Written
	{
		final String name;
		final OpenOption[] options;

		Written(final String name, final OpenOption[] options)
		{
			this.name = name;
			this.options = options;
		}
	}

	/**
	 * The temporary folder as a store root that watches its children: every path joined onto it is a spy of the real
	 * one, reporting its {@code write} options and answering {@code getParent()} with this root, so a temp file the
	 * store names beside its target is watched too.
	 */
	private Filepath watchedRoot(final Watched watched)
	{
		final Filepath real = TestFilepaths.rooted(tmp.getRoot());
		final Filepath[] root = new Filepath[1];
		root[0] = mock(Filepath.class, withSettings().spiedInstance(real).defaultAnswer(invocation ->
			"joinSegment".equals(invocation.getMethod().getName())
				? watch((Filepath) invocation.callRealMethod(), root[0], watched)
				: invocation.callRealMethod()));
		return root[0];
	}

	private static Filepath watch(final Filepath real, final Filepath parent, final Watched watched)
	{
		final String name = real.getFileName();
		return mock(Filepath.class, withSettings().spiedInstance(real).defaultAnswer(invocation ->
		{
			switch (invocation.getMethod().getName())
			{
				case "getParent":
					return parent;
				case "exists":
					if (watched.hideHistory && name.startsWith(PriceStore.HISTORY_PREFIX))
					{
						return false;
					}
					return invocation.callRealMethod();
				case "write":
					watched.writes.add(new Written(name, (OpenOption[]) invocation.getRawArguments()[1]));
					return invocation.callRealMethod();
				default:
					return invocation.callRealMethod();
			}
		}));
	}
}

package com.bankpricemovement;

import static com.bankpricemovement.BankHistorySeriesTest.p;
import static com.bankpricemovement.BankHistorySeriesTest.sep;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * {@link BankHistoryMath} (addendum AU, contract sections 3, 9.5 and 9.6): the window change and the card's move,
 * the change against the previous reading, the calendar days with their carried gaps, the thinning, and the day a
 * greyed chip fills - with 0 and 1 readings, a window with no reading old enough (null, never 0), the span when the
 * reading used is older than the window's day, and the day boundary at local midnight.
 */
public class BankHistoryMathTest
{
	private static final ZoneId TORONTO = ZoneId.of("America/Toronto");

	/** Readings on 1, 2, 5 and 10 Sep worth 100, 110, 150, 200 (bank-tradeable only). */
	private static BankHistorySeries fourReadings()
	{
		return BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(2), 2, 110), p(sep(5), 5, 150),
			p(sep(10), 10, 200)));
	}

	private static long millis(final LocalDateTime local, final ZoneId zone)
	{
		return local.atZone(zone).toInstant().toEpochMilli();
	}

	// ---- dayOf

	@Test
	public void aReadingIsFiledUnderTheLocalDateAndTheDayTurnsAtLocalMidnight()
	{
		final long lastMilli = millis(LocalDateTime.of(2026, 9, 28, 23, 59, 59, 999_000_000), TORONTO);
		assertEquals(sep(28), BankHistoryMath.dayOf(lastMilli, TORONTO));
		assertEquals(sep(29), BankHistoryMath.dayOf(lastMilli + 1, TORONTO));

		// 9 pm in Toronto is 1 am UTC the next day: the player's day, not UTC's (plan 7.1 item 2).
		final long nineInTheEvening = millis(LocalDateTime.of(2026, 9, 28, 21, 0), TORONTO);
		assertEquals(sep(28), BankHistoryMath.dayOf(nineInTheEvening, TORONTO));
		assertEquals(sep(29), BankHistoryMath.dayOf(nineInTheEvening, ZoneOffset.UTC));
	}

	// ---- overDays

	@Test
	public void overDaysComparesTheLastReadingWithTheLastOneOnOrBeforeTheWindowsDay()
	{
		final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(10), 5, null);
		assertNotNull(c);
		assertEquals(sep(5), c.fromDay());
		assertEquals(sep(10), c.toDay());
		assertEquals("from 150 to 200", new BankHistoryMath.Change(sep(5), sep(10), 150L, 200L), c);
		assertEquals(50L, c.deltaGp());
		assertEquals(50 * 100.0d / 150, c.pct(), 0.0d);
		assertEquals(5, c.spanDays());
	}

	@Test
	public void theSpanSaysWhenTheReadingUsedIsOlderThanTheWindowsDay()
	{
		// 1d on the 10th wants the 9th; the 9th has none, so the 5th is used and the span is 5 days, not 1.
		final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(10), 1, null);
		assertEquals(sep(5), c.fromDay());
		assertEquals(5, c.spanDays());
	}

	@Test
	public void aWindowWithNoReadingOldEnoughIsNullNeverZero()
	{
		assertNull(BankHistoryMath.overDays(fourReadings(), sep(10), 10, null));
		assertNotNull("the 9th boundary: 9 days back is the 1st", BankHistoryMath.overDays(fourReadings(), sep(10),
			9, null));
		assertNull(BankHistoryMath.overDays(fourReadings(), sep(10), 30, null));
	}

	@Test
	public void overDaysWithNoOrOneReadingIsNull()
	{
		assertNull(BankHistoryMath.overDays(BankHistorySeries.EMPTY, sep(10), 7, null));
		assertNull(BankHistoryMath.overDays(null, sep(10), 7, null));
		final BankHistorySeries one = BankHistorySeries.EMPTY.with(p(sep(3), 3, 100));
		assertNull(BankHistoryMath.overDays(one, sep(10), 7, null));
		assertNull(BankHistoryMath.overDays(one, sep(10), 1, null));
		assertNull("all, over one reading: from is to", BankHistoryMath.overDays(one, sep(10), 0, null));
	}

	@Test
	public void overDaysIsNullWhenFromIsTheSameReadingAsTo()
	{
		// Readings on the 1st and 5th; on the 7th, 1d wants the 6th, whose last reading is the 5th - which is also
		// the latest. That is no measured change, so no figure.
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(5), 5, 150)));
		assertNull(BankHistoryMath.overDays(s, sep(7), 1, null));
		assertNotNull(BankHistoryMath.overDays(s, sep(7), 6, null));
	}

	@Test
	public void overDaysWithZeroOrFewerDaysMeansFromTheFirstReading()
	{
		for (final int days : new int[]{0, -1})
		{
			final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(10), days, null);
			assertEquals(sep(1), c.fromDay());
			assertEquals("from the first reading's 100", new BankHistoryMath.Change(sep(1), sep(10), 100L, 200L), c);
			assertEquals(9, c.spanDays());
		}
	}

	@Test
	public void overDaysIgnoresReadingsAfterToday()
	{
		// On the 7th the 10th has not happened: to is the 5th.
		final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(7), 5, null);
		assertEquals(sep(2), c.fromDay());
		assertEquals(sep(5), c.toDay());
		assertEquals(40L, c.deltaGp());
	}

	@Test
	public void theChangeFollowsTheSwitches()
	{
		final long[] a = new long[BankHistoryPoint.CELLS];
		a[BankHistoryPoint.BANK_TRADEABLE] = 100L;
		a[BankHistoryPoint.BANK_CASH] = 1_000L;
		final long[] b = a.clone();
		b[BankHistoryPoint.BANK_TRADEABLE] = 200L;
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(new BankHistoryPoint(sep(1), 1, 1, a, null),
			new BankHistoryPoint(sep(2), 2, 2, b, null)));
		final BankHistoryMath.Change withCash = BankHistoryMath.overDays(s, sep(2), 1, ViewOptions.DEFAULT);
		final BankHistoryMath.Change without = BankHistoryMath.overDays(s, sep(2), 1,
			ViewOptions.DEFAULT.withCountCash(false));
		assertEquals(new BankHistoryMath.Change(sep(1), sep(2), 1_100L, 1_200L), withCash);
		assertEquals(new BankHistoryMath.Change(sep(1), sep(2), 100L, 200L), without);
		assertEquals("the same gp move", withCash.deltaGp(), without.deltaGp());
		assertEquals(100 * 100.0d / 1_100, withCash.pct(), 0.0d);
