	@Test
	public void theTooltipGetsEveryDigit()
	{
		assertEquals("1,520,000", MovementMath.formatExact(1_520_000L));
		assertEquals("850", MovementMath.formatExact(850L));
		assertEquals("-4,100", MovementMath.formatExact(-4_100L));
