	// ---------------------------------------------------------------- the series crosses the seam

	/**
	 * A real Status carrying the record arrives while Items shows: the view is not fed (it is not showing). The toggle
	 * is pressed: the view draws that very series - every reading, every calendar day, the four carried - and its
	 * readout is the card's own total to the gp, because today's reading and the total come from one commit.
	 */
	@Test
	public void aSeriesThatArrivesWhileItemsShowsIsDrawnTheMomentTheToggleIsPressed() throws Exception
	{
		login();
		final PriceService.Status status = panel.status();
		assertNotNull(status);
		final BankHistorySeries series = status.bankHistory();
		assertEquals("the forty seeded days less the gaps, and today's", SEEDED_DAYS - GAPS.size() + 1, series.size());
		assertEquals(SidebarView.ITEMS, panel.view());
		assertEquals(BankPriceMovementPanel.CARD_LIST, panel.card());
		assertEquals("not fed while Items shows", 0, state("readings"));

		pressHistory();

		assertTrue("the toggle writes nothing", prefs.filterSaves.isEmpty() && prefs.optionSaves.isEmpty());
		assertEquals(BankPriceMovementPanel.CARD_HISTORY, panel.card());
		assertSame("the toggle asked the service for nothing", status, panel.status());
		assertEquals(series.size(), state("readings"));
		assertEquals(today.minusDays(SEEDED_DAYS).toString(), state("first"));
		assertEquals(today.toString(), state("last"));
		assertEquals("every calendar day from the first reading to today", SEEDED_DAYS + 1, state("rows"));
		assertEquals(GAPS.size(), state("carriedRows"));

		final long total = status.portfolio().valueNow();
		assertEquals("today's reading IS the card's total", total, series.on(today).valueFor(status.options()));
		onEdt(() ->
		{
			assertEquals(MovementMath.formatExact(total) + " gp", chartLabel(view(), READOUT_TOTAL));
			assertEquals(MovementMath.formatGp(total), panel.totalLabel().getText());
			assertEquals("1d vs your " + MovementMath.formatDay(today.minusDays(1)) + " total",
				panel.footnoteLabel().getText());
			assertEquals((SEEDED_DAYS - GAPS.size() + 1) + " days recorded since "
				+ MovementMath.formatDay(today.minusDays(SEEDED_DAYS)), panel.updateLabel().getText());
		});
		// And the record on disk now holds today beside the forty.
		assertEquals(series, disk.loadBankHistory(ACCOUNT, PROFILE).series());
	}

	// ---------------------------------------------------------------- the ranges

	/**
	 * A card chip moves the chart's range - and the card's move and the chart's change are then ONE figure; the view's
	 * own chip moves the chart alone: not the card's window, not the service's filter, nothing saved.
	 */
	@Test
	public void aCardChipMovesTheChartAndTheViewsOwnChipMovesNothingElse() throws Exception
	{
		login();
		pressHistory();
		assertEquals("1d draws 7d", "7d", state("range"));

		pressCardChip(MovementWindow.D30);
		assertEquals("30d", state("range"));
		assertEquals("the chip reached the service", MovementWindow.D30, service.filter().window());
		final String[] card = new String[2];
		onEdt(() ->
		{
			card[0] = panel.pctLabel().getText();
			card[1] = panel.footnoteLabel().getText();
			assertEquals("the card's move IS the chart's change", card[0], chartLabel(view(), CHANGE_PCT));
			assertEquals("30d vs your " + MovementMath.formatDay(today.minusDays(30)) + " total", card[1]);
		});
		pressCardChip(MovementWindow.D180);
		assertEquals("180d draws all", "all", state("range"));
		final int saves = prefs.filterSaves.size();
		onEdt(() ->
		{
			card[0] = panel.pctLabel().getText();
			card[1] = panel.footnoteLabel().getText();
		});

		// The view's own chips: the range bar's four cells under the chart, 7d 30d 90d all.
		onEdt(() -> press(BankHistoryViewTest.rangeCell(view(), BankHistoryRange.D90), MouseEvent.BUTTON1));
		settle();
		assertEquals("the view's chip moved the chart", "90d", state("range"));
		assertEquals("...and not the card", MovementWindow.D180, panel.filter().window());
		assertEquals("...nor the service", MovementWindow.D180, service.filter().window());
		assertEquals("...and saved nothing", saves, prefs.filterSaves.size());
		onEdt(() ->
		{
			assertEquals("the card is as it was", card[1], panel.footnoteLabel().getText());
			assertEquals(card[0], panel.pctLabel().getText());
		});

		pressCardChip(MovementWindow.D7);
		assertEquals("the card's next chip overrules the view's", "7d", state("range"));
		onEdt(() -> assertEquals(panel.pctLabel().getText(), chartLabel(view(), CHANGE_PCT)));
	}

	// ---------------------------------------------------------------- the counting switches

	/**
	 * A counting switch flipped in the settings menu goes the plugin's road to the service, which recomputes; the
	 * publish that answers redraws the card's History lines AND every figure of the view to the SAME totals - today's,
	 * the chart's change and every past day's row - and no stored reading changes (the cells ignore the switches).
	 */
	@Test
	public void aCountingSwitchFromTheSettingsMenuRedrawsTheCardAndTheViewToOneTotal() throws Exception
	{
		login();
		pressHistory();
		pressCardChip(MovementWindow.D7);
		final PriceService.Status before = panel.status();
		final LocalDate past = today.minusDays(9);
		final BankHistoryPoint pastPoint = before.bankHistory().on(past);
		assertNotNull(pastPoint);
		onEdt(() -> assertTrue(rowOf(past).model().toString(),
			rowOf(past).model().toString().contains(MovementMath.formatExact(pastPoint.valueFor(before.options())))));

		for (String which : new String[]{"cash", "inventory"})
		{
			onEdt(() -> ("cash".equals(which) ? panel.countCashItem() : panel.countInventoryItem()).doClick(0));
			settle();
			final PriceService.Status after = panel.status();
			assertNotSame(which + ": the service answered with a new status", before, after);
			final ViewOptions options = after.options();
			assertFalse(which, "cash".equals(which) ? options.countCash() : options.countInventory());
			assertEquals(which + ": the switch was saved, which told the service", options,
				prefs.optionSaves.get(prefs.optionSaves.size() - 1));
			assertEquals(which + ": no stored reading moved", before.bankHistory().upTo(today.minusDays(1)),
				after.bankHistory().upTo(today.minusDays(1)));
			final long total = after.portfolio().valueNow();
			assertEquals(which + ": today's reading is still the card's total", total,
				after.bankHistory().on(today).valueFor(options));
			onEdt(() ->
			{
				assertEquals(which, MovementMath.formatGp(total), panel.totalLabel().getText());
				assertEquals(which, MovementMath.formatExact(total) + " gp", chartLabel(view(), READOUT_TOTAL));
				assertEquals(which + ": the card's move and the chart's change", panel.pctLabel().getText(),
					chartLabel(view(), CHANGE_PCT));
				final String row = rowOf(past).model().toString();
				assertTrue(which + ": a past day redrawn under the switch: " + row,
					row.contains(MovementMath.formatExact(pastPoint.valueFor(options))));
				final String todayRow = rowOf(today).model().toString();
				assertTrue(which + ": today's row: " + todayRow, todayRow.contains(MovementMath.formatExact(total)));
			});
		}
		assertNotEquals("the totals did move", before.portfolio().valueNow(), panel.status().portfolio().valueNow());
		assertEquals("coins off, then the inventory off: what is left is the bank's tradeable stacks",
			pastPoint.card(BankHistoryPoint.BANK_TRADEABLE) + pastPoint.card(BankHistoryPoint.BANK_PARTS),
			pastPoint.valueFor(panel.status().options()));
	}

	// ---------------------------------------------------------------- the bank hold (addendum AS)

	/**
	 * With the bank open, a publish that restates the same bank at new prices - and so carries a new reading for today -
	 * is STORED while History shows: the view keeps the reading it drew. The bank closing replays it into the view and
	 * the card together.
	 */
	@Test
	public void theBankHoldStoresAPublishWhileHistoryShowsAndTheCloseReplaysItIntoTheView() throws Exception
	{
		login();
		pressHistory();
		final PriceService.Status drawn = panel.status();
		final String readout = readout();
		onEdt(() -> panel.setBankHold(true, true, 1, 0));

		// The 30-minute re-check while the sidebar is open, after RuneLite's price for one stack moved.
		f.runelitePrice(PriceServiceTest.BOX, 5_000);
		service.setVisible(true);
		f.fireTick();
		settle();
		final PriceService.Status restated = service.currentStatus();
		assertNotEquals("the re-check moved today's reading", drawn.bankHistory().on(today),
			restated.bankHistory().on(today));
		assertEquals("the same capture: a restatement, not a read", drawn.bankAtMillis(), restated.bankAtMillis());
		assertSame("held while the bank is open", drawn, panel.status());
		assertEquals("the view keeps what it drew", readout, readout());

		onEdt(() -> panel.setBankHold(false, false, 1, 0));
		settle();
		assertEquals("the close replays the stored publish", restated, panel.status());
		final long total = restated.portfolio().valueNow();
		assertEquals(MovementMath.formatExact(total) + " gp", readout());
		assertEquals(total, restated.bankHistory().on(today).valueFor(restated.options()));
		onEdt(() -> assertEquals(MovementMath.formatGp(total), panel.totalLabel().getText()));
	}

	private String readout() throws Exception
	{
		final String[] out = new String[1];
		onEdt(() -> out[0] = chartLabel(view(), READOUT_TOTAL));
		return out[0];
	}

	// ---------------------------------------------------------------- the dev bridge

	/** {@code bpm view=}, {@code range=} and {@code state.bankHistory} through BpmCommands, the real panel and view. */
	@Test
	public void theDevBridgeDrivesTheRealPanelAndReadsTheRealView() throws Exception
	{
		login();
		final Gson gson = new Gson();
		final BpmCommands dev = new BpmCommands(panel, service, gson);

		JsonObject state = gson.fromJson(dev.apply("state"), JsonObject.class);
		assertEquals("ITEMS", state.get("view").getAsString());
		assertEquals(0, state.getAsJsonObject("bankHistory").get("readings").getAsInt());

		state = gson.fromJson(dev.apply("view=history"), JsonObject.class);
		settle();
		assertTrue(state.get("ok").getAsBoolean());
		assertEquals("HISTORY", state.get("view").getAsString());
		assertTrue("the toggle writes nothing", prefs.filterSaves.isEmpty() && prefs.optionSaves.isEmpty());
		JsonObject history = state.getAsJsonObject("bankHistory");
		assertEquals(SEEDED_DAYS - GAPS.size() + 1, history.get("readings").getAsInt());
		assertEquals(today.minusDays(SEEDED_DAYS).toString(), history.get("first").getAsString());
		assertEquals(today.toString(), history.get("last").getAsString());
		assertEquals("7d", history.get("range").getAsString());
		assertEquals(SEEDED_DAYS + 1, history.get("rows").getAsInt());
		assertEquals(GAPS.size(), history.get("carriedRows").getAsInt());
		assertTrue("no hover", history.get("hoverDay") == null || history.get("hoverDay").isJsonNull());
		assertEquals(BankPriceMovementPanel.CARD_HISTORY, state.getAsJsonObject("panel").get("card").getAsString());

		state = gson.fromJson(dev.apply("range=all"), JsonObject.class);
		assertEquals("all", state.getAsJsonObject("bankHistory").get("range").getAsString());
		assertEquals("the card's window is untouched", "D1", state.getAsJsonObject("panel").get("window").getAsString());
		assertEquals(MovementWindow.D1, service.filter().window());

		dev.apply("window=90d");
		settle();
		state = gson.fromJson(dev.apply("state"), JsonObject.class);
		assertEquals("the card's window moves the chart", "90d",
			state.getAsJsonObject("bankHistory").get("range").getAsString());
		assertEquals(MovementWindow.D90, service.filter().window());

		final JsonObject refused = gson.fromJson(dev.apply("range=1d"), JsonObject.class);
		assertFalse(refused.get("ok").getAsBoolean());
		assertEquals("range= wants 7d, 30d, 90d or all, not '1d'", refused.get("error").getAsString());

		state = gson.fromJson(dev.apply("view=items"), JsonObject.class);
		settle();
		assertEquals("ITEMS", state.get("view").getAsString());
		assertEquals(BankPriceMovementPanel.CARD_LIST, state.getAsJsonObject("panel").get("card").getAsString());
		assertTrue("the toggle writes no option", prefs.optionSaves.isEmpty());
		// The view keeps what it drew while Items shows: the echo still reads the record.
		assertEquals(SEEDED_DAYS - GAPS.size() + 1,
			state.getAsJsonObject("bankHistory").get("readings").getAsInt());
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import javax.annotation.Nullable;
import org.junit.Test;

/**
 * {@link PortfolioMath} against addendum M line M1 ({@code docs/bank-price-movement-addendum-M-2026-09-09.md}):
 * the whole bank's worth, the both-days basis of every window's move, the overflow clamps, and the exact figures
 * of a three-item fixture - pure functions, no client (playbook 7.6, style PURE).
 *
 * <p>The fixture: an Abyssal whip (1 held, 1,520,000 now, 1,507,600 a day ago, 1,500,000 a week ago), 500 sharks
 * (1,000 now, flat over a day, 1,100 a week ago) and 100 bones (100 now, no 1d baseline, 90 a week ago). So
 * {@code valueNow} is 2,030,000 over 3 of 3 stacks; the 1d move covers the whip and the sharks only
 * (2,007,600 -> 2,020,000 = +12,400, +0.617 %); the 7d move covers all three (2,059,000 -> 2,030,000 = -29,000,
 * -1.408 %); and 30d has no baseline at all.
 *
 * <p>The last section adds addendum P line P1 ({@code docs/bank-price-movement-addendum-P-2026-09-10.md}): the same
 * fixture with {@value #CASH} gp of coins in the bank, where the total gains the cash, every window gains it on both
 * sides, the gp moves are unchanged and only the percentages fall.
 */
public class PortfolioMathTest
{
	private static final int WHIP = 4151;
	private static final int SHARK = 385;
	private static final int BONES = 526;
	private static final int BOX = 6199;
	/** Two items the Grand Exchange does not list, kept for their alch value since Q5. */
	private static final int DRAMEN = 772;
	private static final int GRACEFUL = 11_850;

	private static final LocalDate SEP_7 = LocalDate.of(2026, 9, 7);
	private static final LocalDate SEP_1 = LocalDate.of(2026, 9, 1);

	/** The cash of the P1 examples: 1,000,000 gp of coins and platinum tokens, half the fixture's stacks again. */
	private static final long CASH = 1_000_000L;

	// ---------------------------------------------------------------- the fixture

	private static List<BankItem> bank()
	{
		return Arrays.asList(
			new BankItem(WHIP, 1, "Abyssal whip", false),
			new BankItem(SHARK, 500, "Shark", true),
			new BankItem(BONES, 100, "Bones", true));
	}

	private static Map<Integer, Long> now()
	{
		final Map<Integer, Long> m = new HashMap<>();
		m.put(WHIP, 1_520_000L);
		m.put(SHARK, 1_000L);
		m.put(BONES, 100L);
		return m;
	}

	private static Map<Integer, Long> oneDayAgo()
	{
		final Map<Integer, Long> m = new HashMap<>();
		m.put(WHIP, 1_507_600L);
		m.put(SHARK, 1_000L);
		return m;
	}

	private static Map<Integer, Long> sevenDaysAgo()
	{
		final Map<Integer, Long> m = new HashMap<>();
		m.put(WHIP, 1_500_000L);
		m.put(SHARK, 1_100L);
		m.put(BONES, 90L);
		return m;
	}

	private static Map<MovementWindow, Function<Integer, Long>> thens()
	{
		final Map<MovementWindow, Function<Integer, Long>> m = new EnumMap<>(MovementWindow.class);
		m.put(MovementWindow.D1, oneDayAgo()::get);
		m.put(MovementWindow.D7, sevenDaysAgo()::get);
		return m;
	}

	private static Map<MovementWindow, LocalDate> days()
	{
		final Map<MovementWindow, LocalDate> m = new EnumMap<>(MovementWindow.class);
		m.put(MovementWindow.D1, SEP_7);
		m.put(MovementWindow.D7, SEP_1);
		return m;
	}

	private static PortfolioSummary fixture()
	{
		return PortfolioMath.summariseResolved(bank(), now()::get, thens(), days(), 0L);
	}

	private static PriceMap map(final Map<Integer, Long> prices, final long revId)
	{
		final Map<Integer, PricePoint> points = new HashMap<>();
		for (final Map.Entry<Integer, Long> entry : prices.entrySet())
		{
			points.put(entry.getKey(), new PricePoint(entry.getValue(), entry.getValue()));
		}
		return new PriceMap(points, 1L, 2L, revId);
	}

	// ---------------------------------------------------------------- M1: the exact figures

	@Test
	public void theWholeBankIsValuedAtTodaysPricesOverEveryPricedStack()
	{
		final PortfolioSummary s = fixture();

		assertEquals("1,520,000 + 500 x 1,000 + 100 x 100", 2_030_000L, s.valueNow());
		assertEquals(3, s.itemsPriced());
		assertEquals(3, s.itemsTotal());
		assertEquals("1d and 7d have baselines; 30d, 90d and 180d do not", 2, s.moves().size());
		assertEquals(Arrays.asList(MovementWindow.D1, MovementWindow.D7), new ArrayList<>(s.moves().keySet()));
	}

	@Test
	public void theOneDayMoveCountsOnlyTheStacksPricedOnBothDays()
	{
		final WindowMove d1 = fixture().move(MovementWindow.D1);

		assertEquals(MovementWindow.D1, d1.window());
		assertEquals(SEP_7, d1.thenDay());
		assertEquals("the bones have no 1d baseline: the whip and the sharks", 2, d1.itemsCovered());
		assertEquals("1,507,600 + 500,000", 2_007_600L, d1.valueThen());
		assertEquals("the SAME two stacks now: 1,520,000 + 500,000 - not the whole bank's 2,030,000", 2_020_000L, d1.valueNowCovered());
		assertEquals(12_400L, d1.deltaGp());
		assertEquals(12_400L * 100.0d / 2_007_600L, d1.deltaPct(), 1e-12);
		assertEquals("+0.6%", MovementMath.formatPct(d1.deltaPct(), d1.deltaGp()));
	}

	@Test
	public void theSevenDayMoveCoversAllThreeAndFalls()
	{
		final WindowMove d7 = fixture().move(MovementWindow.D7);

		assertEquals(SEP_1, d7.thenDay());
		assertEquals(3, d7.itemsCovered());
		assertEquals("1,500,000 + 500 x 1,100 + 100 x 90", 2_059_000L, d7.valueThen());
		assertEquals(2_030_000L, d7.valueNowCovered());
		assertEquals(-29_000L, d7.deltaGp());
		assertEquals(-29_000L * 100.0d / 2_059_000L, d7.deltaPct(), 1e-12);
		assertEquals("-1.4%", MovementMath.formatPct(d7.deltaPct(), d7.deltaGp()));
	}

	@Test
	public void aWindowWithoutABaselineHasNoMove()
	{
		final PortfolioSummary s = fixture();

		assertNull(s.move(MovementWindow.D30));
		assertNull(s.move(MovementWindow.D90));
		assertNull(s.move(MovementWindow.D180));
		assertNull(s.move(null));
		assertFalse(s.moves().containsKey(MovementWindow.D30));
	}

	// ---------------------------------------------------------------- M1: the basis rules

	@Test
	public void unpricedStacksAreLeftOutOfEverySum()
	{
		final List<BankItem> items = new ArrayList<>(bank());
		items.add(new BankItem(BOX, 3, "Mystery box", true)); // RuneLite has no price: null
		final Map<Integer, Long> now = now();
		now.put(SHARK, 0L); // 0 is "no price" (L1), not a price of zero
		final Map<Integer, Long> then = sevenDaysAgo();
		then.put(BOX, 1_000_000L); // a "then" with no "now" is not a covered stack either
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D7, then::get);

		final PortfolioSummary s = PortfolioMath.summariseResolved(items, now::get, thens, days(), 0L);

		assertEquals("the whip and the bones only", 1_520_000L + 10_000L, s.valueNow());
		assertEquals(2, s.itemsPriced());
		assertEquals("every stack counts in the total, priced or not", 4, s.itemsTotal());
		final WindowMove d7 = s.move(MovementWindow.D7);
		assertEquals("the sharks have no now, the box has no now: two covered", 2, d7.itemsCovered());
		assertEquals(1_500_000L + 9_000L, d7.valueThen());
		assertEquals(1_520_000L + 10_000L, d7.valueNowCovered());
		assertEquals(21_000L, d7.deltaGp());
	}

	@Test
	public void aStackWhoseBaselineIsMissingOrZeroIsNotCoveredButStillCountsNow()
	{
		final Map<Integer, Long> then = oneDayAgo();
		then.put(SHARK, 0L); // a then of 0 would make the percentage infinite: not priced (MovementMath.row's rule)
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D1, then::get);

		final PortfolioSummary s = PortfolioMath.summariseResolved(bank(), now()::get, thens, days(), 0L);

		assertEquals(2_030_000L, s.valueNow());
		final WindowMove d1 = s.move(MovementWindow.D1);
		assertEquals("only the whip has a positive then", 1, d1.itemsCovered());
		assertEquals(1_507_600L, d1.valueThen());
		assertEquals(1_520_000L, d1.valueNowCovered());
		assertEquals(12_400L, d1.deltaGp());
	}

	@Test
	public void aWindowWhoseCoveredStacksWereWorthNothingHasAGpMoveAndNoPercent()
	{
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D1, id -> null); // a baseline that names none of the bank

		final WindowMove d1 = PortfolioMath.summariseResolved(bank(), now()::get, thens, days(), 0L).move(MovementWindow.D1);

		assertEquals(0, d1.itemsCovered());
		assertEquals(0L, d1.valueThen());
		assertEquals(0L, d1.valueNowCovered());
		assertEquals(0L, d1.deltaGp());
		assertNull("deltaPct is null when valueThen is 0 (M1) - never a division by zero", d1.deltaPct());
		assertEquals(MovementMath.DASH, MovementMath.formatPct(d1.deltaPct(), d1.deltaGp()));
	}

	@Test
	public void aFlatWindowIsAZeroMoveWithAZeroPercent()
	{
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D1, now()::get);

		final WindowMove d1 = PortfolioMath.summariseResolved(bank(), now()::get, thens, days(), 0L).move(MovementWindow.D1);

		assertEquals(3, d1.itemsCovered());
		assertEquals(2_030_000L, d1.valueThen());
		assertEquals(0L, d1.deltaGp());
		assertEquals(0.0d, d1.deltaPct(), 0.0d);
		assertEquals("0.0%", MovementMath.formatPct(d1.deltaPct(), d1.deltaGp()));
	}

	// ---------------------------------------------------------------- M1: the clamps

	@Test
	public void sumsClampAtLongMaxInsteadOfWrapping()
	{
		final List<BankItem> items = Arrays.asList(
			new BankItem(1, 3, "A fortune", true),
			new BankItem(2, Integer.MAX_VALUE, "Another", true),
			new BankItem(3, 1, "Small change", false));
		final Map<Integer, Long> now = new HashMap<>();
		now.put(1, Long.MAX_VALUE / 2L + 1L); // x3 overflows the multiply: clamped
		now.put(2, 5_000_000_000L);           // x (2^31 - 1) is 1.07e19, past Long.MAX_VALUE: clamped too
		now.put(3, 1L);
		final Map<Integer, Long> then = new HashMap<>();
		then.put(1, 1L);
		then.put(2, 1L);
		then.put(3, 1L);
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D1, then::get);

		final PortfolioSummary s = PortfolioMath.summariseResolved(items, now::get, thens, days(), 0L);

		assertEquals("a clamped holding plus anything is still the clamp, never negative", Long.MAX_VALUE, s.valueNow());
		assertEquals(3, s.itemsPriced());
		final WindowMove d1 = s.move(MovementWindow.D1);
		assertEquals(3, d1.itemsCovered());
		assertEquals(3L + Integer.MAX_VALUE + 1L, d1.valueThen());
		assertEquals(Long.MAX_VALUE, d1.valueNowCovered());
		assertEquals("the difference of two clamped sums cannot overflow", Long.MAX_VALUE - d1.valueThen(), d1.deltaGp());
		assertTrue(d1.deltaPct() > 0.0d);
	}

	@Test
	public void clampedAddSaturatesAtTheTop()
	{
		assertEquals(3L, PortfolioMath.clampedAdd(1L, 2L));
		assertEquals(Long.MAX_VALUE, PortfolioMath.clampedAdd(Long.MAX_VALUE, 1L));
		assertEquals(Long.MAX_VALUE, PortfolioMath.clampedAdd(Long.MAX_VALUE - 1L, 2L));
		assertEquals(Long.MAX_VALUE, PortfolioMath.clampedAdd(Long.MAX_VALUE, Long.MAX_VALUE));
		assertEquals(Long.MAX_VALUE, PortfolioMath.clampedAdd(Long.MAX_VALUE, 0L));
	}

	// ---------------------------------------------------------------- M2: the two signatures agree

	@Test
	public void theContractSignatureOverProjectedMapsGivesTheSameSummary()
	{
		final Map<MovementWindow, PriceMap> baselines = new EnumMap<>(MovementWindow.class);
		baselines.put(MovementWindow.D1, map(oneDayAgo(), 15_333_448L));
		baselines.put(MovementWindow.D7, map(sevenDaysAgo(), 15_328_200L));

		final PortfolioSummary viaMaps = PortfolioMath.summarise(bank(), now()::get, baselines, days(), 0L);

		assertEquals(fixture(), viaMaps);
		assertEquals(fixture().hashCode(), viaMaps.hashCode());
		assertEquals(2_020_000L, viaMaps.move(MovementWindow.D1).valueNowCovered());
	}

	@Test
	public void aResolverOverAMapReadsThePointsMid()
	{
		final Function<Integer, Long> resolver = PortfolioMath.resolver(map(oneDayAgo(), 1L));

		assertEquals(Long.valueOf(1_507_600L), resolver.apply(WHIP));
		assertNull(resolver.apply(BONES));
		assertNull(resolver.apply(null));
		assertNull(PortfolioMath.resolver(null).apply(WHIP));
		assertNull(PortfolioMath.resolver(PriceMap.EMPTY).apply(WHIP));
	}

	// ---------------------------------------------------------------- M2: the model

	@Test
	public void emptyAndNullInputsAreTheEmptySummary()
	{
		assertEquals(PortfolioSummary.EMPTY, PortfolioMath.summariseResolved(null, null, null, null, 0L));
		assertEquals(PortfolioSummary.EMPTY, PortfolioMath.summarise(null, null, null, null, 0L));
		assertEquals("null entries are skipped, not counted", PortfolioSummary.EMPTY,
			PortfolioMath.summariseResolved(Collections.singletonList(null), now()::get, Collections.emptyMap(), null, 0L));
		// An empty bank against real baselines: nothing is worth anything, and a window with a baseline is still
		// a window (zero covered, no percent) - it is the SERVICE that publishes EMPTY for an empty snapshot (M3).
		final PortfolioSummary noStacks = PortfolioMath.summariseResolved(Collections.emptyList(), now()::get, thens(), days(), 0L);
		assertEquals(0L, noStacks.valueNow());
		assertEquals(0, noStacks.itemsTotal());
		assertEquals(2, noStacks.moves().size());
		assertEquals(0, noStacks.move(MovementWindow.D1).itemsCovered());
		assertNull(noStacks.move(MovementWindow.D1).deltaPct());
		assertEquals(0L, PortfolioSummary.EMPTY.valueNow());
		assertEquals(0, PortfolioSummary.EMPTY.itemsPriced());
		assertEquals(0, PortfolioSummary.EMPTY.itemsTotal());
		assertTrue(PortfolioSummary.EMPTY.moves().isEmpty());
		assertNull(PortfolioSummary.EMPTY.move(MovementWindow.D1));
