		assertEquals(BandPresets.DEFAULT, plugin.presetsFromConfig());

		when(config.bandPresets()).thenReturn("1m, 10m, 100m");
		assertEquals(BandPresets.of(1_000_000L, 10_000_000L, 100_000_000L), plugin.presetsFromConfig());

