/**
 * The mountain chart's pins added after the review and mutation pass of 2026-09-29: the first of two equal readings
 * takes the high (and the low), new data at the same size lays the chart out again, the hover ring takes the line's
 * colour, the fill's alpha is 70 on a rise and 80 on a fall, and the last point stands where the target puts it.
 */
public class BankHistoryChartPinsTest
{
	/** Two readings share the range's highest total: the FIRST of them carries the high's mark. */
	@Test
	public void theFirstOfTwoEqualHighsTakesTheMark() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView view = view(dated(6, 700, 4, 500, 2, 700, 0, 600), BankHistoryRange.D7);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			final List<BankHistoryChart.Figure> figures = chart.figures();
			assertEquals(2, figures.size());
			assertEquals("700m", figures.get(0).text);
			assertEquals("the high is the first 700m", TODAY.minusDays(6), chart.days().get(figures.get(0).index).day());
		});
	}

	/** Two readings share the range's lowest total: the FIRST of them carries the low's mark. */
	@Test
	public void theFirstOfTwoEqualLowsTakesTheMark() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView view = view(dated(6, 500, 4, 800, 2, 500, 0, 700), BankHistoryRange.D7);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			final List<BankHistoryChart.Figure> figures = chart.figures();
			assertEquals(2, figures.size());
			assertEquals("500m", figures.get(1).text);
			assertEquals("the low is the first 500m", TODAY.minusDays(6), chart.days().get(figures.get(1).index).day());
		});
	}

	/**
	 * A press on the range bar hands the chart new days at the SAME size: it lays them out again rather than painting
	 * them on the old range's coordinates - 7d to 30d (more days than the old layout had) and back (fewer).
	 */
	@Test
	public void newDataAtTheSameSizeIsLaidOutAgain() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryRange[][] moves = {{BankHistoryRange.D7, BankHistoryRange.D30},
				{BankHistoryRange.D30, BankHistoryRange.D7}};
			for (BankHistoryRange[] move : moves)
			{
				final BankHistoryView view = view(fixture(), move[0]);
				layOut(view, 213);
				final BankHistoryChart chart = chart(view);
				paint(chart);
				final int size = chart.getWidth() * 1000 + chart.getHeight();
				press(rangeCell(view, move[1]));
				assertEquals("the premise: the chart keeps its size", size, chart.getWidth() * 1000 + chart.getHeight());
				final BankHistoryView fresh = view(fixture(), move[1]);
				layOut(fresh, 213);
				assertEquals(chart(fresh).days().size(), chart.days().size());
				assertSameImage(move[0] + " then " + move[1], paint(chart(fresh)), paint(chart));
				assertEquals(chart(fresh).figures().get(0).left, chart.figures().get(0).left);
				assertEquals(chart(fresh).figures().get(1).index, chart.figures().get(1).index);
			}
		});
	}

	/** The hover ring is stroked in the line's colour round a disc of the card grey - green on a rise, red on a fall. */
	@Test
	public void theHoverRingTakesTheLinesColour() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView rise = view(fixture(), BankHistoryRange.D30);
			layOut(rise, 213);
			final BankHistoryChart up = chart(rise);
			assertRing(up, indexOf(up, HOVER_DAY), ColorScheme.PROGRESS_COMPLETE_COLOR);

			final BankHistoryView fall = view(dated(6, 900, 4, 880, 2, 700, 0, 690), BankHistoryRange.D7);
			layOut(fall, 213);
			final BankHistoryChart down = chart(fall);
			assertEquals("the premise: a fall", Widgets.MOVE_DOWN_TEXT, down.lineColour());
			assertRing(down, 2, Widgets.MOVE_DOWN_TEXT);
		});
	}

	/** The fill's tint under the line's highest point: alpha 70 on a rise, 80 on a fall, fading to 0 at the bottom. */
	@Test
	public void theFillIsAlpha70OnARiseAnd80OnAFall() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView rise = view(fixture(), BankHistoryRange.D30);
			layOut(rise, 213);
			assertFillAlpha(chart(rise), ColorScheme.PROGRESS_COMPLETE_COLOR, BankHistoryChart.FILL_ALPHA);
			assertEquals(70, BankHistoryChart.FILL_ALPHA);

			final BankHistoryView fall = view(dated(6, 900, 4, 880, 2, 700, 0, 690), BankHistoryRange.D7);
			layOut(fall, 213);
			assertFillAlpha(chart(fall), Widgets.MOVE_DOWN_TEXT, BankHistoryChart.FILL_ALPHA_FALL);
			assertEquals(80, BankHistoryChart.FILL_ALPHA_FALL);
		});
	}

	/**
	 * The last point stands 9 px in from the chart's right edge: at 213 at x 204, so its 3 px dot ends on the range
	 * bar's right edge (207) and its 6 px halo 3 px inside the block; at 230 at x 221.
	 */
	@Test
	public void theLastPointStandsWhereTheTargetPutsIt()
	{
		assertEquals(204.0, BankHistoryChart.xAt(30, 31, 213), 1e-9);
		assertEquals(221.0, BankHistoryChart.xAt(7, 8, 230), 1e-9);
		assertEquals(6.0, BankHistoryChart.xAt(0, 31, 213), 1e-9);
		assertEquals("the dot ends on the bar's right edge", 207.0,
			BankHistoryChart.xAt(30, 31, 213) + BankHistoryChart.DOT_RADIUS, 1e-9);
		assertEquals("the halo ends 3 px inside the block", 213 - 3.0,
			BankHistoryChart.xAt(30, 31, 213) + BankHistoryChart.HALO_RADIUS, 1e-9);
	}

	// ---------------------------------------------------------------------------------------- helpers

	private static void assertRing(final BankHistoryChart chart, final int index, final Color expected)
	{
		assertTrue("the premise: a point to hover", index >= 0 && index != chart.readoutIndex());
		hover(chart, BankHistoryChartTest.x(chart, index));
		assertEquals("the premise: the hover is on it", index, chart.readoutIndex());
		final BufferedImage image = paint(chart);
		final double cx = BankHistoryChart.xAt(index, chart.days().size(), chart.getWidth());
		final double cy = ys(chart)[index];
		int ring = 0;
		int coloured = 0;
		for (int y = (int) cy - 7; y <= (int) cy + 7; y++)
		{
			for (int x = (int) cx - 7; x <= (int) cx + 7; x++)
			{
				final double r = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
				if (r >= 4.1 && r <= 4.9)
				{
					ring++;
					coloured += near(new Color(image.getRGB(x, y)), expected, 40) ? 1 : 0;
				}
			}
		}
		assertTrue("the ring is the line's colour: " + coloured + " of " + ring + " px", ring >= 20
			&& coloured * 4 >= ring * 3);
		assertEquals("inside the ring, the card grey", ColorScheme.DARKER_GRAY_COLOR.getRGB() & 0xFFFFFF,
			image.getRGB((int) Math.floor(cx), (int) Math.floor(cy)) & 0xFFFFFF);
	}

	private static void assertFillAlpha(final BankHistoryChart chart, final Color line, final int alpha)
	{
		final BufferedImage image = paint(chart);
		final double[] ys = ys(chart);
		int hi = 0;
		for (int i = 1; i < ys.length; i++)
		{
			hi = ys[i] < ys[hi] ? i : hi;
		}
		final double top = ys[hi];
		final int h = chart.getHeight();
		final int x = (int) Math.max(8, Math.min(chart.getWidth() - 12,
			Math.round(BankHistoryChart.xAt(hi, ys.length, chart.getWidth()))));
		final int y = (int) Math.ceil(lineY(chart, ys, x + 0.5) + 5);
		final double a = alpha * (1 - (y + 0.5 - top) / (h - top)) / 255.0;
		final Color card = ColorScheme.DARKER_GRAY_COLOR;
		final Color want = new Color((int) Math.round(card.getRed() + (line.getRed() - card.getRed()) * a),
			(int) Math.round(card.getGreen() + (line.getGreen() - card.getGreen()) * a),
			(int) Math.round(card.getBlue() + (line.getBlue() - card.getBlue()) * a));
		final Color got = new Color(image.getRGB(x, y));
		assertTrue("the fill at (" + x + ", " + y + ") is the line's colour at alpha " + alpha + " there: " + got
			+ " want " + want, near(got, want, 3));
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * {@link BankPriceMovementPanel.Prefs} - the seam between the sidebar and where its choices are kept (contract
 * C28; the hero pair is addendum O line O2, the options pair addendum Q line Q3, the presets pair addendum Z
 * line Z1, the fold pair addendum AA line AA1,
 * {@code docs/bank-price-movement-addendum-AA-2026-09-13.md}, and the view pair addendum AU, the phase-0 contract's
 * amendment 9.15).
 *
 * <p>Only the FILTER pair is abstract. Every pair added since has a default, so a caller with nothing to
 * remember - the headless renderer, a throwaway test seam - need not care, and the panel draws exactly what it
 * drew before that pair existed. This file pins that: what a bare implementation answers, and that the writes it
 * does not want are no-ops rather than errors.
 *
 * <p>The plugin's own implementation over {@code ConfigManager} is a different thing and is pinned in
 * {@code BankPriceMovementWiringTest}; what a null from any of the three READS as is the panel's business and is
 * pinned in {@code BankPriceMovementPanelTest}.
 */
public class PrefsTest
{
	/** The least a {@code Prefs} can be: the filter pair, and not one line more. */
	private static final class Bare implements BankPriceMovementPanel.Prefs
	{
		final List<RowFilter> saved = new ArrayList<>();

		@Override
		public RowFilter load()
		{
			return null;
		}

		@Override
		public void save(RowFilter filter)
		{
			saved.add(filter);
		}
	}

	@Test
	public void aPrefsThatRemembersOnlyTheFilterAnswersNullToEverythingElse()
	{
		final Bare prefs = new Bare();
		assertNull("a fresh install has no filter", prefs.load());
		assertNull("O2: no stored hero switches", prefs.loadHero());
		assertNull("Q3/T1/Y1: no stored view switches", prefs.loadOptions());
		assertNull("Z1: no stored price presets", prefs.loadPresets());
		assertNull("AA1: no stored fold state", prefs.loadFoldOpen());
		assertNull("AU: no stored start tab", prefs.loadStartTab());
	}

	/**
	 * AA1: the fold pair answers a {@code Boolean} and not a {@code boolean}, because "nothing stored" and
	 * "stored closed" are different answers and only the first may be read as the shipped default (open). A
	 * primitive here would make every bare implementation - the renderer, a throwaway seam - claim the reader had
	 * chosen to shut the fold.
	 */
	@Test
	public void theFoldPairAnswersNullRatherThanFalseWhenNothingIsStored()
	{
		final Bare prefs = new Bare();
		assertNull(prefs.loadFoldOpen());
		assertNotEquals("a stored FALSE would be a choice, and this is not one", Boolean.FALSE, prefs.loadFoldOpen());
	}

	@Test
	public void theWritesItDoesNotWantAreNoOps()
	{
		final Bare prefs = new Bare();
		prefs.saveHero(HeroVisibility.NONE);
		prefs.saveOptions(ViewOptions.DEFAULT);
		prefs.savePresets(BandPresets.DEFAULT);
		prefs.saveFoldOpen(false);
		prefs.saveFoldOpen(true);
		prefs.saveStartTab(SidebarView.HISTORY);
		assertTrue("the defaults write nothing anywhere", prefs.saved.isEmpty());

		prefs.save(RowFilter.DEFAULT);
		assertEquals("...and the one pair that is abstract is the implementation's own", 1, prefs.saved.size());
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileAlreadyExistsException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * {@link PriceStore} on a real temp directory (contract C17-C19, rewritten by K11 and extended by addendum L
 * line L4): round trips of the four kinds of file - bank, mapping, revision index, baseline - the EMPTY answers
 * for a missing one, the quarantine of a corrupt one, the refusal to quarantine a merely unreadable one, the
 * atomic replace and its temp-file hygiene, the file naming that keeps two accounts, two profiles and the five
 * windows apart - and the addendum-K sweep.
 *
 * <p>The sweep is the test that matters most here. The plugin shipped once with movement measured off the
 * wiki's real-time TRADE buckets, and the first live look read "Green hat +1,413 gp (+12845.5 %)" against a GE
 * site figure of -38 gp. Those buckets are on the user's disk as {@code baseline-*.json}. If one survived the
 * switch, the panel would show that number again for the minutes between start-up and the first refetch - which
 * is the whole reason {@link PriceStore#deleteStaleFiles()} exists.
 *
 * <p>Real disk, no mocks and no sleeps: the store is synchronous by contract (the caller owns the executor), so
 * every assertion here is on what is on the file system when the call returns.
 *
 * <p>Since addendum AD the store speaks {@link Filepath} rather than {@link java.io.File}, so the temporary
 * folder is handed over as a ROOT ({@link TestFilepaths#rooted}) and every path below is a join onto it -
 * exactly how the plugin builds its own from {@code Plugin.getPluginDirectory()}. Nothing here can name a file
 * outside {@code tmp}, which is a property of the wrapper and not of this test's manners.
 */
public class PriceStoreTest
{
	/** 2026-09-07T19:55:12Z and its revision - the baseline the calibration run actually fetched. */
	private static final long REVISION_SECONDS = 1_788_810_912L;
	private static final long REV_ID = 15_333_448L;

	/** A stock Gson stands in for RuneLite's injected one; the documents are public-field only. */
	private final Gson gson = new Gson();

	@Rule
	public final TemporaryFolder tmp = new TemporaryFolder();

	private PriceStore store()
	{
		return new PriceStore(gson, TestFilepaths.rooted(tmp.getRoot()));
	}

	// ---- file names and the directory (C17, K11, AD)

	/**
	 * What {@code PriceStore.defaultDir()} used to guard, re-pinned (addendum AD). That method is GONE: the
	 * directory now comes from {@code Plugin.getPluginDirectory()}, which no unit test may call, because calling
	 * it would create - and perform the one-time legacy move into - the developer's own
	 * {@code ~/.runelite/plugin-data}. What the old test really protected was never the folder's name but that
	 * the store reaches nowhere else, and {@link Filepath} turns that from a habit into a rule: a path built from
	 * this root cannot name anything above it, so a whole session of saves and a sweep leave the temporary folder
	 * holding exactly what they wrote and the rest of the disk untouched.
	 */
	@Test
	public void everyPathTheStoreNamesIsInsideTheDirectoryItWasBuiltOver()
	{
		assertEquals("the directory name is still the hub slug (C17/D10) - the descriptor's internalName since AD",
			"bank-portfolio-tracker", PriceStore.DIR_NAME);

		final Filepath root = TestFilepaths.rooted(tmp.getRoot());
		final PriceStore store = new PriceStore(gson, root);
		assertEquals("the store reads and writes the directory it was given", root, store.dir());

		for (final Filepath file : Arrays.asList(store.bankFile(1234L, "STANDARD"), store.bankFile(7L, "../../etc"),
			store.mappingFile(), store.revisionIndexFile(), store.tradedLatestFile(),
			store.bucketFile(MovementWindow.D1), store.tradedFile(MovementWindow.D180)))
		{
			assertTrue(file + " is outside the store's directory", file.startsWith(root));
			assertEquals("and it is a child of it, not a grandchild", root, file.getParent());
		}

		try
		{
			root.join("..");
			fail("a Filepath cannot name its own parent - that is the whole point of the wrapper");
		}
		catch (IllegalArgumentException expected)
		{
			// the point of the test
		}

		store.saveBank(snapshot(42L, "STANDARD", 1L, item(4151, 1, "Whip", false)));
		store.saveBucket(MovementWindow.D1, guideMap(658, 1124L));
		assertEquals("a sweep of a directory this build wrote takes nothing", 0, store.deleteStaleFiles());
		assertEquals("and what was written is all that is there", Arrays.asList("bank-42-STANDARD.json",
			"baseline-D1.json"), names());
	}

	@Test
	public void theDirectoryIsCreatedLazilyOnTheFirstWriteAndNotBeforeIt()
	{
		final Filepath missing = TestFilepaths.at(tmp.getRoot(), "never-used");
		final PriceStore store = new PriceStore(gson, missing);

		assertSame("a load must not create anything", PriceMap.EMPTY, store.loadBucket(MovementWindow.D1));
		assertSame(BankSnapshot.EMPTY, store.loadBank(1, "STANDARD"));
		assertTrue(store.loadMapping().value().isEmpty());
		assertEquals(0L, store.loadMapping().fetchedAtMillis());
		assertEquals("and neither must the sweep", 0, store.deleteStaleFiles());
		assertFalse("an installed but unused plugin leaves no directory behind", missing.exists());

		store.saveBucket(MovementWindow.D1, guideMap(658, 1124L));
		assertTrue("the first write creates the directory", missing.isDirectory());
		assertTrue(missing.join("baseline-D1.json").isFile());
	}

	@Test
	public void theFourKindsOfFileAreNamedByTheContract()
	{
		final PriceStore store = store();
		assertEquals("bank-1234-STANDARD.json", store.bankFile(1234L, "STANDARD").getFileName());
		assertEquals("mapping.json", store.mappingFile().getFileName());
		assertEquals("revindex.json", store.revisionIndexFile().getFileName());
		assertEquals("baseline-D1.json", store.bucketFile(MovementWindow.D1).getFileName());
		assertEquals("baseline-D7.json", store.bucketFile(MovementWindow.D7).getFileName());
		assertEquals("baseline-D30.json", store.bucketFile(MovementWindow.D30).getFileName());
		assertEquals("baseline-D90.json", store.bucketFile(MovementWindow.D90).getFileName());
		assertEquals("baseline-D180.json", store.bucketFile(MovementWindow.D180).getFileName());
		assertEquals("the store reads and writes the directory it was given",
			TestFilepaths.rooted(tmp.getRoot()), store.dir());
	}

	/** A separator in the profile type would write outside the store's directory. */
	@Test
	public void aProfileTypeIsSanitisedIntoTheFileNameAndBlankBecomesUnknown()
	{
		final PriceStore store = store();
		assertEquals("bank-7-a_b_c.json", store.bankFile(7L, "a/b\\c").getFileName());

		final Filepath traversal = store.bankFile(7L, "../../etc");
		assertEquals("a traversal cannot walk out of the store's directory", store.dir(), traversal.getParent());
		assertTrue("and since addendum AD it could not even if the sanitiser let it through: the path is a join "
			+ "onto the store's own root, which throws rather than escaping", traversal.startsWith(store.dir()));
		assertFalse(traversal.getFileName().contains(".."));
		assertFalse(traversal.getFileName().contains("/"));
		assertFalse(traversal.getFileName().contains("\\"));

		assertEquals("bank-7-UNKNOWN.json", store.bankFile(7L, "").getFileName());
		assertEquals("bank-7-UNKNOWN.json", store.bankFile(7L, "   ").getFileName());
		assertEquals("bank-7-UNKNOWN.json", store.bankFile(7L, null).getFileName());
		assertEquals("a logged-out account hash is -1", "bank--1-STANDARD.json",
			store.bankFile(-1L, "STANDARD").getFileName());
	}

	// ---- banks (C18)

	@Test
	public void aBankRoundTripsThroughItsOwnFile()
	{
		final PriceStore store = store();
		final BankSnapshot saved = snapshot(42L, "STANDARD", 1_700_000_000_000L,
			item(4151, 1, "Abyssal whip", false),
			item(565, 25_000, "Blood rune", true));
		store.saveBank(saved);

		assertTrue(store.bankFile(42L, "STANDARD").isFile());
		final BankSnapshot loaded = store.loadBank(42L, "STANDARD");
		assertEquals(42L, loaded.accountHash);
		assertEquals("STANDARD", loaded.profileType);
		assertEquals(1_700_000_000_000L, loaded.capturedAtMillis);
		assertEquals(2, loaded.items.size());
		assertEquals(4151, loaded.items.get(0).id);
		assertEquals(1, loaded.items.get(0).quantity);
		assertEquals("Abyssal whip", loaded.items.get(0).name);
