	// ---------------------------------------------------------------- AD: the Directory seam

	/**
	 * The seam PRODUCTION uses, which every other test in this class walks past: the store is built over a
	 * {@link PriceStore.Directory} - {@code BankPriceMovementPlugin::getPluginDirectory} in the client - and the
	 * {@link Filepath} convenience constructor the tests above take is only a lambda over that same seam.
	 *
	 * <p>{@code getPluginDirectory()} creates {@code ~/.runelite/plugin-data/}, performs the one-time move of the
	 * legacy {@code ~/.runelite/bank-portfolio-tracker/} folder and throws {@link IOException} when the disk says
	 * no, so "it refused" is a state a real client reaches - a full disk, a locked folder, a roaming profile that
	 * has not come back yet. The store's standing failure policy (C18) says what must happen then, and this is the
	 * test of it: every load reads its EMPTY value, every path is null, every save is dropped, the sweep counts
	 * nothing, and NOTHING is thrown, because the caller is a task on {@code PriceService}'s
	 * {@code ScheduledExecutorService} - an exception there is swallowed into a {@code Future} nobody reads, and a
	 * scheduled task that throws is never run again.
	 *
	 * <p>Breaks if: the {@code catch (IOException | RuntimeException)} in {@link PriceStore#dir()} is deleted and
	 * {@code directory.get()} is allowed to propagate - the first load below throws instead of reading EMPTY.
	 */
	@Test
	public void aDirectoryThatThrowsLeavesEveryLoadEmptyEveryPathNullAndEverySaveDropped()
	{
		assertItBehavesAsIfItHadNoDirectory(new PriceStore(gson, CountingDirectory.refusing(Refusal.IO)));
	}

	/**
	 * A seam that answers null rather than throwing - a plugin with no {@code internalName}, or a future
	 * {@code getPluginDirectory()} that reports "none" instead of failing. {@link PriceStore#dir()} treats it as a
	 * failure, because a null directory joined onto would be a {@link NullPointerException} in
	 * {@code PriceStore.file} on the very next line rather than at the seam.
	 *
	 * <p>Breaks if: the {@code found == null} branch in {@code dir()} becomes an assertion
	 * ({@code Objects.requireNonNull(directory.get())}) - the first load below then throws an NPE into the
	 * executor instead of reading EMPTY.
	 */
	@Test
	public void aDirectoryThatAnswersNullIsNoDirectoryAtAll()
	{
		assertItBehavesAsIfItHadNoDirectory(new PriceStore(gson, CountingDirectory.refusing(Refusal.NONE_AT_ALL)));
	}

	/**
	 * And an UNCHECKED failure out of the same call - a {@code SecurityException} from the file system, an
	 * {@code IllegalStateException} from a descriptor that has no {@code internalName}, anything RuneLite's own
	 * code can raise inside it. The catch covers both kinds deliberately: the store's promise is "no load and no
	 * save ever throws", and a promise that holds only for the checked half is not one.
	 *
	 * <p>Breaks if: the catch in {@code dir()} is narrowed to {@code IOException} alone.
	 */
	@Test
	public void anUncheckedFailureOutOfTheDirectoryIsSurvivedExactlyLikeAnIoException()
	{
		assertItBehavesAsIfItHadNoDirectory(new PriceStore(gson, CountingDirectory.refusing(Refusal.RUNTIME)));
	}

	/**
	 * The seam is not touched until the store is USED. Constructing one happens in {@code startUp}, on the client
	 * thread, and {@code getPluginDirectory()} is disk work - it creates {@code plugin-data} and may move a whole
	 * legacy folder - so asking it there would put a file-system stall in the middle of enabling the plugin, which
	 * is the 3-5 s freeze the playbook (7.2) already records once.
	 *
	 * <p>A store per verb, because the answer is memoised: one asks on a load, one on a save, one on the sweep, and
	 * each is asked exactly once and not before.
	 *
	 * <p>Breaks if: the constructor resolves ({@code this.resolved = directory.get()}), or {@code dir()} is called
	 * anywhere in it.
	 */
	@Test
	public void theDirectoryIsNotAskedForUntilTheFirstLoadSaveOrSweep()
	{
		final Filepath root = TestFilepaths.rooted(tmp.getRoot());
		final CountingDirectory forALoad = CountingDirectory.answering(root);
		final CountingDirectory forASave = CountingDirectory.answering(root);
		final CountingDirectory forASweep = CountingDirectory.answering(root);

		final PriceStore reader = new PriceStore(gson, forALoad);
		final PriceStore writer = new PriceStore(gson, forASave);
		final PriceStore sweeper = new PriceStore(gson, forASweep);

		assertEquals("building the store must cost no disk at all", 0, forALoad.calls);
		assertEquals(0, forASave.calls);
		assertEquals(0, forASweep.calls);
		assertEquals("and nothing on the file system either", 0, names().size());

		reader.loadBank(42L, "STANDARD");
		writer.saveMapping(Collections.singletonMap(4151, "Abyssal whip"), 5L);
		sweeper.deleteStaleFiles();

		assertEquals("the first load asks", 1, forALoad.calls);
		assertEquals("so does the first save", 1, forASave.calls);
		assertEquals("and so does the sweep", 1, forASweep.calls);
		assertEquals("the one that saved is the only one that made a file",
			Arrays.asList(PriceStore.MAPPING_FILE), names());
	}

	/**
	 * The memo, both halves of it. A directory that ANSWERS is asked once and never again, however many paths are
	 * built afterwards - the store builds one per file per refresh, and asking the seam each time would mean a
	 * {@code plugin-data} round trip per path. A directory that REFUSES is not remembered at all, so a transient
	 * blip costs the one save it happened during rather than the rest of the session.
	 *
	 * <p>Exact counts on both sides: "at most one" would pass with no memo and "at least one" with a permanent one.
	 *
	 * <p>Breaks if: {@code resolved = found} is dropped from {@code dir()} (the first count climbs), or the failure
	 * path starts remembering itself - a {@code resolved = SOMETHING} or a "tried already" flag guarding the
	 * lookup rather than only the warning (the second count stops at 1, and the recovery test below fails with it).
	 */
	@Test
	public void aWorkingDirectoryIsAskedForOnceAndARefusingOneEveryTime()
	{
		final CountingDirectory working = CountingDirectory.answering(TestFilepaths.rooted(tmp.getRoot()));
		final PriceStore store = new PriceStore(gson, working);

		store.saveBucket(MovementWindow.D1, guideMap(658, 1124L));
		assertEquals("the first save resolves it", 1, working.calls);

		store.bankFile(1L, "STANDARD");
		store.bucketFile(MovementWindow.D7);
		store.mappingFile();
		store.revisionIndexFile();
		store.tradedLatestFile();
		store.tradedFile(MovementWindow.D180);
		store.loadBucket(MovementWindow.D1);
		store.loadMapping();
		store.saveBank(snapshot(7L, "STANDARD", 1L, item(4151, 1, "Whip", false)));
		store.deleteStaleFiles();
		assertEquals("and nothing asks again - every path after it is a join onto the remembered root",
			1, working.calls);

		final CountingDirectory refusing = CountingDirectory.refusing(Refusal.IO);
		final PriceStore homeless = new PriceStore(gson, refusing);

		homeless.saveBucket(MovementWindow.D1, guideMap(658, 1124L));
		assertEquals(1, refusing.calls);
		homeless.loadBucket(MovementWindow.D1);
		assertEquals(2, refusing.calls);
		homeless.deleteStaleFiles();
		assertEquals("a refusal is never memoised: the next call asks the disk again", 3, refusing.calls);
	}

	/**
	 * What that retry is FOR. The seam refuses once - the disk was busy, the folder was locked for a moment - and
	 * the store carries on: the save made during the blip is dropped, exactly as a save with no directory is, and
	 * the very next one resolves and lands in the real folder. Without the retry a single unlucky moment at
	 * start-up would leave the plugin saving nothing for the whole session, with only one warning to say so.
	 *
	 * <p>Breaks if: the failure path in {@code dir()} memoises anything, or the recovered directory is not
	 * memoised (the last count would climb past 2).
	 */
	@Test
	public void aDirectoryThatRefusesOnceRecoversAndTheNextSaveLandsInIt()
	{
		final Filepath root = TestFilepaths.rooted(tmp.getRoot());
		final CountingDirectory blip = CountingDirectory.refusingOnce(root);
		final PriceStore store = new PriceStore(gson, blip);

		store.saveBucket(MovementWindow.D1, guideMap(658, 1124L));
		assertEquals("the save made during the blip went nowhere, and threw nothing", 0, names().size());
		assertEquals(1, blip.calls);

		store.saveBucket(MovementWindow.D1, guideMap(658, 1086L));
		assertEquals("the next one asks again", 2, blip.calls);
		assertEquals("and lands in the folder the seam finally named",
			Arrays.asList("baseline-D1.json"), names());
		assertEquals(Long.valueOf(1086L), store.loadBucket(MovementWindow.D1).get(658).mid());
		assertEquals("a recovered directory is memoised like any other", 2, blip.calls);
		assertEquals(root, store.dir());
	}

	/**
	 * The two constructors are one store. Everything above this section is built through
	 * {@code PriceStore(Gson, Filepath)}, which exists for the tests and for a caller that already holds a path;
	 * production takes {@code PriceStore(Gson, Directory)}. This is the test that says the convenience overload is
	 * a lambda over the seam and not a second code path - a folder handed over by a {@link PriceStore.Directory}
	 * is written, read, named and swept identically, and the two stores see each other's files.
	 *
	 * <p>Breaks if: the {@code Filepath} constructor stops delegating to the {@code Directory} one, or the
	 * {@code Directory} one resolves anywhere other than {@code dir()}.
	 */
	@Test
	public void aStoreOverTheSeamAndOneOverTheSameFolderAreTheSameStore()
	{
		final Filepath root = TestFilepaths.rooted(tmp.getRoot());
		final PriceStore.Directory seamDirectory = () -> root;
		final PriceStore seam = new PriceStore(gson, seamDirectory);
		final PriceStore direct = new PriceStore(gson, root);

		seam.saveBank(snapshot(42L, "STANDARD", 1_700_000_000_000L, item(4151, 1, "Abyssal whip", false)));
		direct.saveBucket(MovementWindow.D1, guideMap(658, 1124L));

		assertEquals("what the seam wrote, a store over the same folder reads", 1_700_000_000_000L,
			direct.loadBank(42L, "STANDARD").capturedAtMillis);
		assertEquals("and the other way round", Long.valueOf(1124L),
			seam.loadBucket(MovementWindow.D1).get(658).mid());
		assertEquals(root, seam.dir());
		assertEquals(seam.dir(), direct.dir());
		assertEquals(seam.bankFile(42L, "STANDARD"), direct.bankFile(42L, "STANDARD"));
		assertEquals(seam.tradedFile(MovementWindow.D90), direct.tradedFile(MovementWindow.D90));
		assertEquals(Arrays.asList("bank-42-STANDARD.json", "baseline-D1.json"), names());
		assertEquals("and one sweep of the shared folder takes nothing either way", 0, seam.deleteStaleFiles());
	}

	/**
	 * Every promise a store with no directory makes, asserted the same way for each of the three shapes a refusal
	 * takes. Kept in one place because the three tests differ only in HOW the seam says no, and a guarantee spelled
	 * out three times drifts into three different guarantees.
	 */
	private void assertItBehavesAsIfItHadNoDirectory(final PriceStore store)
	{
		assertNull("dir() answers null rather than throwing", store.dir());

		assertSame(BankSnapshot.EMPTY, store.loadBank(42L, "STANDARD"));
		assertSame(PriceMap.EMPTY, store.loadBucket(MovementWindow.D1));
		assertTrue(store.loadMapping().value().isEmpty());
		assertEquals("an unstamped nothing, which is what makes a fetch due", 0L,
			store.loadMapping().fetchedAtMillis());
		assertTrue(store.loadRevisionIndex().value().isEmpty());
		assertEquals(0L, store.loadRevisionIndex().fetchedAtMillis());
		assertTrue(store.loadTradedLatest().value().isEmpty());
		assertEquals(0L, store.loadTradedLatest().fetchedAtMillis());
		assertSame(PriceStore.TradedDay.EMPTY, store.loadTradedDay(MovementWindow.D1));

		assertNull(store.bankFile(42L, "STANDARD"));
		assertNull(store.bucketFile(MovementWindow.D1));
		assertNull(store.mappingFile());
		assertNull(store.revisionIndexFile());
		assertNull(store.tradedLatestFile());
		assertNull(store.tradedFile(MovementWindow.D180));

		store.saveBank(snapshot(42L, "STANDARD", 1_700_000_000_000L, item(4151, 1, "Abyssal whip", false)));
		store.saveBucket(MovementWindow.D1, guideMap(658, 1124L));
		store.saveMapping(Collections.singletonMap(4151, "Abyssal whip"), 5L);
		store.saveRevisionIndex(history(), 7L);
		store.saveTradedLatest(quotes(), 9L);
		store.saveTradedDay(MovementWindow.D1, SEP_11, buckets(), 11L);

		assertEquals("a sweep with nowhere to sweep counts nothing", 0, store.deleteStaleFiles());
		assertTrue("and not one byte was written anywhere", names().isEmpty());
	}

	/** How a refusing {@link PriceStore.Directory} says no - the three shapes {@code dir()} has to survive. */
	private enum Refusal
	{
		/** {@code Plugin.getPluginDirectory()}'s own checked failure: the disk, or the legacy move, said no. */
		IO,
		/** Anything unchecked out of the same call - a {@code SecurityException}, a broken descriptor. */
		RUNTIME,
		/** No exception and no directory either: the seam simply has none to give. */
		NONE_AT_ALL
	}

	/**
	 * A {@link PriceStore.Directory} that counts how often the store asks it, and that can refuse the first
	 * {@code refusalsLeft} of those calls. It is the whole point of this section: production's seam is neither
	 * free nor infallible, and the count is how "asked once on success, asked again after a refusal, never asked
	 * by the constructor" is stated as a number rather than a hope.
	 */
	private static final class CountingDirectory implements PriceStore.Directory
	{
		private final Filepath root;
		private final Refusal refusal;
		private int refusalsLeft;
		/** How often {@link #get()} has been called - read directly by the tests above. */
		private int calls;

		private CountingDirectory(final Filepath root, final Refusal refusal, final int refusalsLeft)
		{
			this.root = root;
			this.refusal = refusal;
			this.refusalsLeft = refusalsLeft;
		}

		/** Always answers {@code root}; the counter is the point. */
		private static CountingDirectory answering(final Filepath root)
		{
			return new CountingDirectory(root, Refusal.IO, 0);
		}

		/** Never answers at all, in one of the three ways the seam can fail. */
		private static CountingDirectory refusing(final Refusal refusal)
		{
			return new CountingDirectory(null, refusal, Integer.MAX_VALUE);
		}

		/** Refuses once and answers afterwards - the transient blip the retry in {@code dir()} exists for. */
		private static CountingDirectory refusingOnce(final Filepath root)
		{
			return new CountingDirectory(root, Refusal.IO, 1);
		}

		@Override
		public Filepath get() throws IOException
		{
			calls++;
			if (refusalsLeft <= 0)
			{
				return root;
			}
			refusalsLeft--;
			if (refusal == Refusal.IO)
			{
				throw new IOException("the disk said no");
			}
			if (refusal == Refusal.RUNTIME)
			{
				throw new IllegalStateException("no internalName on this plugin");
			}
			return null;
		}
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class ViewOptionsTest
{
	@Test
	public void theDefaultCountsCashAndNothingElse()
	{
		assertTrue(ViewOptions.DEFAULT.countCash());
		assertFalse(ViewOptions.DEFAULT.countUntradeables());
		assertTrue(ViewOptions.DEFAULT.livePrices());
		assertTrue("Y1: the inventory and worn gear count unless the user says otherwise",
			ViewOptions.DEFAULT.countInventory());
		assertFalse("AH: and the hover text is OFF until the user asks for it",
			ViewOptions.DEFAULT.showHoverText());
	}

	/**
	 * Addendum AH, and the one thing about this switch that is easy to lose in a renumbering: <b>its default is the
	 * QUIETER sidebar</b>, where every other switch here defaults to the fuller one. {@code countCash},
	 * {@code livePrices} and {@code countInventory} default ON because leaving them off would withhold figures a
	 * reader expects; {@code countUntradeables} defaults off, but off is the plugin's own long-standing shape - the
	 * tradeable list - rather than a thing taken away.
	 *
	 * <p>{@code showHoverText} is the only one of the five that, at its default, shows LESS than the build before it
	 * did: the hero card's hover and every control's were drawn unconditionally through addendum AG, and on a fresh
	 * profile they are now drawn not at all. That is the user's own request ("i would like it to be default 'off'
	 * and only display hover text if turned on", 2026-09-20), so it is pinned in a test whose name says it - a
	 * later hand that "tidied" the default to true would otherwise pass every other test in this file.
	 *
	 * <p>The field itself was deleted by addendum AI and restored by AJ, when the user asked where the switch had
	 * gone. That round trip is the reason the default is pinned by name here as well as beside the other four:
	 * a value re-added by hand is exactly where a shipped default gets written down the wrong way round.
	 */
	@Test
	public void theHoverSwitchIsTheOneSwitchWhoseDefaultShowsLessThanTheBuildBeforeIt()
	{
		assertFalse("AH: a fresh profile draws no hover text at all", ViewOptions.DEFAULT.showHoverText());
		assertTrue("...while the three switches that ADD figures all default on",
			ViewOptions.DEFAULT.countCash() && ViewOptions.DEFAULT.livePrices()
				&& ViewOptions.DEFAULT.countInventory());
		// Turning it on is what restores the addendum-AG sidebar, and it is the only difference between the two.
		final ViewOptions hovers = ViewOptions.DEFAULT.withShowHoverText(true);
		assertTrue(hovers.showHoverText());
		assertNotEquals(ViewOptions.DEFAULT, hovers);
		assertEquals("and nothing else moved with it", ViewOptions.DEFAULT, hovers.withShowHoverText(false));
	}

	@Test
	public void eachWithFlipsOneSwitchAndLeavesTheOthers()
	{
		final ViewOptions cashOff = ViewOptions.DEFAULT.withCountCash(false);
		assertFalse(cashOff.countCash());
		assertFalse(cashOff.countUntradeables());
		assertTrue(cashOff.livePrices());
		assertTrue(cashOff.countInventory());
		assertFalse(cashOff.showHoverText());

		final ViewOptions untradeables = ViewOptions.DEFAULT.withCountUntradeables(true);
		assertTrue(untradeables.countCash());
		assertTrue(untradeables.countUntradeables());
		assertTrue(untradeables.livePrices());

		final ViewOptions guideOnly = ViewOptions.DEFAULT.withLivePrices(false);
		assertFalse(guideOnly.livePrices());
		assertTrue(guideOnly.countCash());
		assertTrue("and the inventory is untouched by it", guideOnly.countInventory());

		// The value is shared - DEFAULT is a static every road in the plugin reads - so a with() that wrote through
		// to the receiver would hand the whole client one user's answer. Pin the receiver, not just the copy.
		assertEquals("and none of them touched the value they were called on", ViewOptions.DEFAULT,
			new ViewOptions(true, false, true, true, false));
	}

	/** Y1: the inventory switch is one more {@code with} of the same shape, and it moves nothing else. */
	@Test
	public void withCountInventoryFlipsTheFourthSwitchAlone()
	{
		final ViewOptions bankOnly = ViewOptions.DEFAULT.withCountInventory(false);

		assertFalse(bankOnly.countInventory());
		assertTrue(bankOnly.countCash());
		assertFalse(bankOnly.countUntradeables());
		assertTrue(bankOnly.livePrices());
		assertFalse(bankOnly.showHoverText());
		assertTrue("and back again", bankOnly.withCountInventory(true).countInventory());
		assertEquals(ViewOptions.DEFAULT, bankOnly.withCountInventory(true));
	}

	/** AH: the hover switch is one more {@code with} of the same shape, and it moves nothing else. */
	@Test
	public void withShowHoverTextFlipsTheFifthSwitchAlone()
	{
		final ViewOptions hovers = ViewOptions.DEFAULT.withShowHoverText(true);

		assertTrue(hovers.showHoverText());
		assertTrue(hovers.countCash());
		assertFalse(hovers.countUntradeables());
		assertTrue(hovers.livePrices());
		assertTrue(hovers.countInventory());
		assertFalse("and back again", hovers.withShowHoverText(false).showHoverText());
		assertEquals(ViewOptions.DEFAULT, hovers.withShowHoverText(false));
		// ...and it survives every other switch being flipped over it, which is what makes it a field and not a mode.
		assertTrue("the hover text stays on through the other four",
			hovers.withCountCash(false).withCountUntradeables(true)
				.withLivePrices(false).withCountInventory(false).showHoverText());
	}

	/**
	 * Addendum AO line AO1 deleted the ladder of shorter constructors along with {@code holdingOnRows}, so there is
	 * exactly ONE way to build this value and its five arguments are the whole contract. The test that stood here
	 * pinned what each rung of that ladder defaulted (the inventory ON, the hovers OFF); its subject is gone, and
	 * what replaces it is the reason the ladder went.
	 *
	 * <p>The removed field sat in the MIDDLE of the list, so a five-argument call meaning
	 * {@code (cash, untradeables, holding, live, inventory)} would still COMPILE against
	 * {@code (cash, untradeables, live, inventory, hover)} and quietly mean three different things. Nothing but a
	 * test can catch that, because the compiler never will: each position is pinned here on its own, by a call that
	 * sets that one argument true and every other false.
	 */
	@Test
	public void theOneConstructorTakesTheFiveSwitchesInThisOrder()
	{
		assertTrue("first: cash", new ViewOptions(true, false, false, false, false).countCash());
		assertTrue("second: untradeables", new ViewOptions(false, true, false, false, false).countUntradeables());
		assertTrue("third: live", new ViewOptions(false, false, true, false, false).livePrices());
		assertTrue("fourth: inventory", new ViewOptions(false, false, false, true, false).countInventory());
		assertTrue("fifth: hover", new ViewOptions(false, false, false, false, true).showHoverText());

		assertFalse("and nothing else came on with it", new ViewOptions(true, false, false, false, false)
			.countUntradeables());
		assertFalse(new ViewOptions(false, false, false, false, true).countCash());

		assertEquals("so the default spelled out IS DEFAULT", ViewOptions.DEFAULT,
			new ViewOptions(true, false, true, true, false));
	}

	@Test
	public void asMapPrintsTheFiveSwitchesInTheOrderTheBridgeUses()
	{
		final ViewOptions o = new ViewOptions(false, true, false, false, true);
		assertEquals("[cash, untradeables, live, inventory, hover]",
			new ArrayList<>(o.asMap().keySet()).toString());
		assertEquals("[false, true, false, false, true]", new ArrayList<>(o.asMap().values()).toString());
		assertEquals("AO1: live moves up to THIRD, where holding used to sit", "live",
			new ArrayList<>(ViewOptions.DEFAULT.asMap().keySet()).get(2));
		assertEquals("Y1: inventory is the FOURTH key", "inventory",
			new ArrayList<>(ViewOptions.DEFAULT.asMap().keySet()).get(3));
		assertEquals("AH: hover is the FIFTH and last", "hover",
			new ArrayList<>(ViewOptions.DEFAULT.asMap().keySet()).get(4));
		assertEquals("and a fresh profile prints it off", Boolean.FALSE, ViewOptions.DEFAULT.asMap().get("hover"));
		assertFalse("AO1: and nothing prints the deleted switch any more",
			ViewOptions.DEFAULT.asMap().containsKey("holding"));
	}

	@Test
	public void equalityIsByValue()
	{
		assertEquals(new ViewOptions(true, false, true, true, false), ViewOptions.DEFAULT);
		assertEquals(ViewOptions.DEFAULT.hashCode(),
			new ViewOptions(true, false, true, true, false).hashCode());
		// Every remaining field on its own: the panel decides what to rebuild by comparing two of these values, so
		// a field equals() skipped would be a switch the user pressed and the sidebar never followed.
		assertNotEquals(ViewOptions.DEFAULT, ViewOptions.DEFAULT.withCountCash(false));
		assertNotEquals(ViewOptions.DEFAULT, ViewOptions.DEFAULT.withCountUntradeables(true));
		assertNotEquals(ViewOptions.DEFAULT, ViewOptions.DEFAULT.withLivePrices(false));
		assertNotEquals(ViewOptions.DEFAULT, ViewOptions.DEFAULT.withCountInventory(false));
		// AH: two options that differ in the hover switch ALONE are two different options - the panel decides
		// whether to build the card's tooltip and whether the controls carry theirs by comparing them, so an
		// equals() that ignored this field would leave the sidebar's hover text whatever it was when the menu
		// item was last pressed.
		assertNotEquals(ViewOptions.DEFAULT, ViewOptions.DEFAULT.withShowHoverText(true));
		assertNotEquals(ViewOptions.DEFAULT.hashCode(), ViewOptions.DEFAULT.withShowHoverText(true).hashCode());
		assertEquals("ViewOptions{cash=true, untradeables=false, live=true, inventory=true, hover=false}",
			ViewOptions.DEFAULT.toString());
		assertEquals("ViewOptions{cash=true, untradeables=false, live=true, inventory=true, hover=true}",
			ViewOptions.DEFAULT.withShowHoverText(true).toString());
	}

	/**
	 * The field count is pinned by a number as well as by the assertions above, because this value has changed shape
	 * three times in three days: addendum AI deleted the hover switch, AJ restored it, and addendum AO line AO1
	 * deleted {@code holdingOnRows} when the user answered "if it doesnt do anything anymore then remove it". Every
	 * field here is read on the {@code ConfigChanged} option road and compared by {@link ViewOptions#equals}, so a
	 * sixth arriving unnoticed would be a switch the sidebar never followed - and a fifth going missing again would
	 * be a stored answer nothing reads.
	 */
	@Test
	public void theValueCarriesFiveSwitchesAndNoMore()
	{
		assertEquals("AO1: holding is gone, so the bridge prints five", 5, ViewOptions.DEFAULT.asMap().size());
		assertEquals("ViewOptions{cash=true, untradeables=false, live=true, inventory=true, hover=false}",
			ViewOptions.DEFAULT.toString());
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * The last bank the plugin saw, for one account on one profile (contract C5). Persisted so the panel is
 * useful at the Grand Exchange and on the login screen: the file is read at start-up and the rows are drawn
 * with "Bank as of HH:MM" long before - or entirely without - a bank visit (design D7).
 *
 * <p>Public fields, no-arg constructor, plain types: the injected Gson writes and reads it directly
 * (playbook step 13). {@link #normalize()} is the single place a loaded file is made safe, so every reader
 * downstream may assume a non-null item list, non-null names and positive ids and quantities.
 *
 * <p>Since addendum Y line Y2 the same file carries what the player was CARRYING and WEARING at the last read
 * ({@link #inventory}, {@link #worn}, {@link #carriedGp}, {@link #carriedAtMillis}, put there by
 * {@link #withCarried(BankReader.Carried)}), so "Include inventory and worn gear" can be flipped on and off without
 * a bank visit - the same reasoning that keeps {@link #currencyGp} and every untradeable stack in every capture.
 * Older files have none of it and read as "carrying nothing".
 *
 * <p>The account hash and profile type are stored INSIDE the file as well as in its name
 * ({@code bank-<accountHash>-<profileType>.json}, contract C17) so a file that has been renamed or copied can
 * still be told apart from the current account - the service checks them before showing a snapshot as this
 * account's bank (C23).
 */
public class BankSnapshot
{
	/**
	 * The profile type used when a file names none - RuneLite's ordinary main-game profile
	 * ({@code RuneScapeProfileType.STANDARD}).
	 */
	public static final String DEFAULT_PROFILE_TYPE = "STANDARD";

	/**
	 * The "no bank captured" snapshot, which the panel renders as "Open your bank once to load your items".
	 *
	 * <p>Shared and to be treated as READ-ONLY: this class is a persisted bag of public fields, so nothing but
	 * discipline stops a caller mutating it. Its item list is {@link Collections#emptyList()} for that reason.
	 */
	public static final BankSnapshot EMPTY = new BankSnapshot(Collections.emptyList(), 0L, 0L, DEFAULT_PROFILE_TYPE);

	/**
	 * The stacks, one per canonical item id. Never null after {@link #normalize()}.
	 */
	public List<BankItem> items;

	/**
	 * When the bank was captured, epoch millis; 0 means "never" ({@link #EMPTY}).
	 */
	public long capturedAtMillis;

	/**
	 * {@code Client.getAccountHash()} at capture time - the account this bank belongs to.
	 */
	public long accountHash;

	/**
	 * {@code RuneScapeProfileType.getCurrent(client).name()} at capture time: a main-game bank and a
	 * Leagues/DMM bank are different banks and never share a file.
	 */
	public String profileType;

	/**
	 * What the bank's COINS and PLATINUM TOKENS are worth, in gp: {@code coins x 1 + platinum x 1000}, exactly
	 * the valuation RuneLite's own item manager hard-codes for the two (clone
	 * {@code runelite-client/src/main/java/net/runelite/client/game/ItemManager.java:328-337}). Clamped at
	 * {@link Long#MAX_VALUE} rather than wrapped.
	 *
	 * <p>Currency is NOT one of {@link #items}, and this field is why both can be true at once (B097). Design
	 * D6 keeps it out of the ROWS because it has no market - a movement row for coins would read 0 % for ever -
	 * but it is half of what a player means by "bank value", and a total that leaves it out disagrees with the
	 * figure RuneLite's own bundled Bank plugin puts in the bank title bar by exactly the player's cash.
	 * {@link BankReader#currencyWorth} is the one place the sum is defined.
	 *
	 * <p><b>Persistence caveat.</b> This is a Gson bag of public fields, so a {@code bank-*.json} written before
	 * the field existed reads back as 0: a REMEMBERED bank (the login-screen and Grand Exchange case of D7) shows
	 * no currency at all until the player next opens a bank. Nothing repairs that, and nothing should - the old
	 * file genuinely does not know.
	 */
	public long currencyGp;

	/**
	 * The stacks in the player's INVENTORY at the last carried read (addendum Y, line Y2), one per canonical id and
	 * by exactly the rules {@link #items} follows. Never null after {@link #normalize()}; EMPTY in every
	 * {@code bank-*.json} written before addendum Y. It is read at every bank read and every Refresh WHATEVER
	 * "Include inventory and worn gear" says - the switch acts only when the service adds up (addendum AV), which is
	 * what lets addendum AU's History keep the carried half of every reading - and "we have read nothing" and "you
	 * were carrying nothing" are the same thing to every reader, because both mean there is nothing to add.
	 */
	public List<BankItem> inventory;

	/** The stacks on the player's WORN gear at that same read (Y2), by the same rules. Never null after normalize. */
	public List<BankItem> worn;

	/**
	 * What the coins and platinum tokens the player was CARRYING are worth, in gp - the carried twin of
	 * {@link #currencyGp}, kept apart from it so that turning "Include inventory and worn gear" off takes exactly
	 * the carried cash back out of the bank value and leaves the bank's own alone. 0 in a file written before
	 * addendum Y.
	 */
	public long carriedGp;

	/**
	 * When the two carried containers were read, epoch millis; 0 means "never" - which is what a pre-Y file and a
	 * snapshot captured with no client logged in both say.
	 *
	 * <p>Its own stamp rather than {@link #capturedAtMillis}, because the two really are read at different moments:
	 * Refresh re-reads what the player carries and republishes the STORED bank beside it (Y2), so the footnote's
	 * "bank HH:MM" clock has to keep naming the bank's own read.
	 */
	public long carriedAtMillis;

	public BankSnapshot()
	{
		items = new ArrayList<>();
		profileType = DEFAULT_PROFILE_TYPE;
		inventory = new ArrayList<>();
		worn = new ArrayList<>();
	}

	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType)
	{
		this(items, capturedAtMillis, accountHash, profileType, 0L);
	}

	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType, final long currencyGp)
	{
		this(items, capturedAtMillis, accountHash, profileType, currencyGp, Collections.emptyList(),
			Collections.emptyList(), 0L, 0L);
	}

	/**
	 * The full shape since addendum Y: a bank part and a carried part, each with its own cash and its own clock.
	 *
	 * @param inventory       the inventory's stacks; null becomes an empty list
	 * @param worn            the worn gear's stacks; null becomes an empty list
	 * @param carriedGp       the coins and platinum tokens in hand, in gp
	 * @param carriedAtMillis when the two carried containers were read; 0 = never
	 */
	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType, final long currencyGp, final List<BankItem> inventory, final List<BankItem> worn,
		final long carriedGp, final long carriedAtMillis)
	{
		this.items = items;
		this.capturedAtMillis = capturedAtMillis;
		this.accountHash = accountHash;
		this.profileType = profileType;
		this.currencyGp = currencyGp;
		this.inventory = inventory == null ? Collections.<BankItem>emptyList() : inventory;
		this.worn = worn == null ? Collections.<BankItem>emptyList() : worn;
		this.carriedGp = carriedGp;
		this.carriedAtMillis = carriedAtMillis;
	}

	/**
	 * This same BANK with a fresh carried part (addendum Y, line Y2) - what Refresh publishes: the stored stacks,
	 * their capture time, their cash and their account untouched, and the inventory, the worn gear, the carried cash
	 * and the carried clock replaced by what the client has just been asked for.
	 *
	 * <p>A copy rather than a mutation, because the snapshot the service holds is handed to the executor and the
	 * EDT and must never change under them; the item list is shared by reference, which is safe for the same reason
	 * {@code setBank}'s is - nothing mutates a captured list.
	 *
	 * @param carried what the player carries and wears; null clears the carried part, which is what a read with no
	 *                client logged in would have found
	 */
	public BankSnapshot withCarried(final BankReader.Carried carried)
	{
		final BankReader.Carried next = carried == null ? BankReader.Carried.EMPTY : carried;
		return new BankSnapshot(items, capturedAtMillis, accountHash, profileType, currencyGp, next.inventory,
			next.worn, next.carriedGp, next.readAtMillis);
	}

	/**
	 * True when there are no priceable ROWS to show. {@link #currencyGp} is deliberately not consulted: a bank of
	 * nothing but coins has no movement rows to draw, which is the question every caller asks this. What the card
	 * at the top of a row-less bank should say about the coins in it is the panel's call, made on the row count.
	 */
	public boolean isEmpty()
	{
		return items == null || items.isEmpty();
	}

	/**
	 * The same bank, of the same account and profile, whatever MOMENT the two were captured at - which
	 * {@link #equals(Object)} deliberately does not answer, because a persisted snapshot has to be told apart
	 * from a re-read of it.
	 *
	 * <p>Why it exists: OSRS posts one {@code ItemContainerChanged} per change to the bank container, and a great
	 * many of those carry an identical stack list - the plugin's own start-up replay of the cached container, a
	 * bank re-opened without a change, a placeholder shuffled. Each one used to cost a full serialisation of
	 * every stack plus a temp file and an atomic replace on the client's single shared executor. The service
	 * compares with this and skips the write when nothing about the CONTENT moved; the price of that is a
	 * persisted {@code capturedAtMillis} that keeps the first capture time of an unchanged bank, which is the
	 * honest stamp for it anyway.
	 *
	 * <p>{@link #currencyGp} counts as content (B097): a player who deposits their coins and nothing else has
	 * changed their bank, and a comparison that ignored the currency would leave the new total unwritten until
	 * some unrelated stack happened to move.
	 *
	 * @param other anything, including null (which is never the same content)
	 */
	public boolean sameContentAs(final BankSnapshot other)
	{
		if (other == null)
		{
			return false;
		}

		if (this == other)
		{
			return true;
		}

		return accountHash == other.accountHash
			&& currencyGp == other.currencyGp
			&& carriedGp == other.carriedGp
			&& Objects.equals(profileType, other.profileType)
			&& Objects.equals(items, other.items)
			// Y2: what the player carries is content too, or a Refresh that found a different inventory would leave
			// the file saying the old one - and the next launch would draw a bank nobody has.
			&& Objects.equals(inventory, other.inventory)
			&& Objects.equals(worn, other.worn);
	}

	/**
	 * Makes a snapshot that came off disk safe to read (contract C5): drops null entries and anything with a
	 * non-positive id or quantity - which is also how a bank PLACEHOLDER (quantity 0) disappears, exactly as
	 * design D6 asks - replaces a null name with "" so no renderer has to null-check, and fills in a missing
	 * profile type with {@link #DEFAULT_PROFILE_TYPE}.
	 *
	 * <p>Void, like {@code BeamLayer.normalize()}: it repairs this object in place and is called once, right
	 * after the file is parsed.
	 */
	public void normalize()
	{
		items = cleaned(items);
		// Y2: a file written before addendum Y has neither list, and Gson leaves an absent field at whatever the
		// no-arg constructor set - or at null when it instantiates without one. Both read as "carrying nothing",
		// which is the truth about a capture made before the plugin ever looked.
		inventory = cleaned(inventory);
		worn = cleaned(worn);

		if (profileType == null || profileType.isEmpty())
		{
			profileType = DEFAULT_PROFILE_TYPE;
		}

		if (capturedAtMillis < 0)
		{
			capturedAtMillis = 0;
		}

		// A hand-edited or truncated file could carry a negative worth, and a negative would be SUBTRACTED from
		// the bank's total. Absent reads as 0 through Gson already; this is the other half of that.
		if (currencyGp < 0)
		{
			currencyGp = 0;
		}

		if (carriedGp < 0)
		{
			carriedGp = 0;
		}

		if (carriedAtMillis < 0)
		{
			carriedAtMillis = 0;
		}
	}

	/**
	 * One stack list made safe: null entries and anything with a non-positive id or quantity dropped - which is also
	 * how a bank PLACEHOLDER (quantity 0) disappears, exactly as design D6 asks - and a null name replaced with ""
	 * so no renderer has to null-check. A null list is an empty one.
	 *
	 * <p>The one rule, so the bank's stacks and the carried stacks of Y2 cannot be cleaned two different ways.
	 */
	private static List<BankItem> cleaned(final List<BankItem> stacks)
	{
		final List<BankItem> clean = new ArrayList<>();
		if (stacks != null)
		{
			for (final BankItem item : stacks)
			{
				if (item == null || item.id <= 0 || item.quantity <= 0)
				{
					continue;
				}

				if (item.name == null)
				{
					item.name = "";
				}

				clean.add(item);
			}
		}
		return clean;
	}

	/**
	 * The same content captured at the same MOMENT: {@link #sameContentAs} plus {@link #capturedAtMillis}, which
	 * is the one field the content comparison leaves out (a persisted snapshot has to be told apart from a re-read
	 * of it). Spelling it this way keeps the field list in one place, so a field added to the content can never be
	 * forgotten here.
	 */
	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof BankSnapshot))
		{
			return false;
		}

		final BankSnapshot other = (BankSnapshot) o;
		return capturedAtMillis == other.capturedAtMillis && sameContentAs(other);
	}

	@Override
	public int hashCode()
	{
		int result = items == null ? 0 : items.hashCode();
		result = 31 * result + (int) (capturedAtMillis ^ (capturedAtMillis >>> 32));
		result = 31 * result + (int) (accountHash ^ (accountHash >>> 32));
		result = 31 * result + (profileType == null ? 0 : profileType.hashCode());
		result = 31 * result + (int) (currencyGp ^ (currencyGp >>> 32));
		result = 31 * result + (inventory == null ? 0 : inventory.hashCode());
		result = 31 * result + (worn == null ? 0 : worn.hashCode());
		result = 31 * result + (int) (carriedGp ^ (carriedGp >>> 32));
		return result;
	}

	/**
	 * The carried part is printed only when there IS one, so a bank captured before addendum Y - and every bank of a
	 * player with the switch off - reads exactly as it did.
	 */
	@Override
	public String toString()
	{
		final int held = inventory == null ? 0 : inventory.size();
		final int equipped = worn == null ? 0 : worn.size();
		return "BankSnapshot{items=" + (items == null ? 0 : items.size())
			+ ", capturedAtMillis=" + capturedAtMillis
			+ ", accountHash=" + accountHash
			+ ", profileType='" + profileType + "'"
			+ ", currencyGp=" + currencyGp
			+ (held == 0 && equipped == 0 && carriedGp == 0L
				? ""
				: ", inventory=" + held + ", worn=" + equipped + ", carriedGp=" + carriedGp) + '}';
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * One day's reading of the player's net worth (addendum AU; plan 7.5 item 2 and 7.7 items 3-5; phase 0 contract
 * sections 2 and 9.4): the total the Bank value card showed that day, saved IN PARTS so the History line can be
 * drawn under whatever counting switches are on NOW.
 *
 * <p><b>The eight cells.</b> WHERE (in the bank | carried = inventory + worn) times WHAT (tradeable stacks | coins
 * and platinum tokens | untradeables valued as their tradeable PARTS that day | untradeables at their High Alchemy
 * value that day). An untradeable is filed by its ACTUAL source that day, not by whether it has a mapping: a parts
 * stack with one unpriced part ended at its alch value, and so is an alch cell. Every cell is recorded whatever the
 * switches say, so a switch flipped later redraws the whole line instead of showing as a one-day jump.
 *
 * <p><b>Two sets of figures.</b> {@code card} is the day as the card priced it (live mids where "Use live prices"
 * priced them live); {@code guide} is the same stacks at guide prices alone. When the two are equal - every day
 * recorded with live prices off, and any day no stack went live - {@code guide} is not stored and
 * {@link #hasGuide()} is false.
 *
 * <p><b>The day is a LOCAL date</b> (plan 7.1 item 2), unlike every other day in this plugin, which are the wiki's
 * UTC days. The caller derives it with {@link BankHistoryMath#dayOf(long, java.time.ZoneId)}; nothing here reads a
 * clock or a zone.
 *
 * <p>Immutable, with value equality. The arrays are copied in and never handed out.
 */
public final class BankHistoryPoint
{
	/** Tradeable stacks in the bank. Counted always. */
	public static final int BANK_TRADEABLE = 0;
	/** Coins and platinum tokens in the bank. Counted with "Include coins and platinum tokens". */
	public static final int BANK_CASH = 1;
	/** Untradeables in the bank valued as their tradeable parts that day. Counted always (addendum AV). */
	public static final int BANK_PARTS = 2;
	/** Untradeables in the bank at their alch value that day. Counted with "Include alch-only untradeables". */
	public static final int BANK_ALCH = 3;
	/** Tradeable stacks carried (inventory + worn). Counted with "Include inventory and worn gear". */
	public static final int CARRIED_TRADEABLE = 4;
	/** Carried coins and platinum tokens. Counted with the inventory switch AND the coins switch. */
	public static final int CARRIED_CASH = 5;
	/** Carried untradeables valued as their parts. Counted with the inventory switch. */
	public static final int CARRIED_PARTS = 6;
	/** Carried untradeables at their alch value. Counted with the inventory switch AND the untradeables switch. */
	public static final int CARRIED_ALCH = 7;
	/** How many cells a reading holds, in {@code card} and in {@code guide}. */
	public static final int CELLS = 8;

	private final LocalDate day;
	private final long readAtMillis;
	private final long bankAtMillis;
	private final long[] card;
	/** Null when the guide figures equal {@link #card} - never an array equal to it (amendment 9.4). */
	@Nullable
	private final long[] guide;

	/**
	 * @param day          the LOCAL date of the reading
	 * @param readAtMillis when the reading was taken, epoch millis - the tie-breaker when two readings name a day
	 * @param bankAtMillis when the bank it priced was captured, epoch millis
	 * @param card         the {@value #CELLS} cells as the card priced them; copied, a negative cell reads as 0
	 * @param guide        the same cells at guide prices alone, or null when they equal {@code card}; copied, and an
	 *                     array equal to {@code card} is stored as null so the two spellings of one reading are equal
	 * @throws NullPointerException     if {@code day} or {@code card} is null
	 * @throws IllegalArgumentException if {@code card} or {@code guide} does not hold exactly {@value #CELLS} cells
	 */
	public BankHistoryPoint(final LocalDate day, final long readAtMillis, final long bankAtMillis, final long[] card,
		@Nullable final long[] guide)
	{
		this.day = Objects.requireNonNull(day, "day");
		this.readAtMillis = readAtMillis;
		this.bankAtMillis = bankAtMillis;
		this.card = cells(Objects.requireNonNull(card, "card"), "card");
		final long[] g = guide == null ? null : cells(guide, "guide");
		this.guide = g == null || Arrays.equals(g, this.card) ? null : g;
	}

	/** A copy of exactly {@value #CELLS} cells, each at least 0 - there is no such thing as a negative holding. */
	private static long[] cells(final long[] values, final String name)
	{
		if (values.length != CELLS)
		{
			throw new IllegalArgumentException(name + " must hold " + CELLS + " cells, not " + values.length);
		}
		final long[] copy = new long[CELLS];
		for (int i = 0; i < CELLS; i++)
		{
			copy[i] = Math.max(0L, values[i]);
		}
		return copy;
	}

	/** The LOCAL date this reading is of. */
	public LocalDate day()
	{
		return day;
	}

	/** When the reading was taken, epoch millis. */
	public long readAtMillis()
	{
		return readAtMillis;
	}

	/** When the bank it priced was captured, epoch millis. */
	public long bankAtMillis()
	{
		return bankAtMillis;
	}

	/**
	 * One cell as the card priced it that day.
	 *
	 * @throws ArrayIndexOutOfBoundsException if {@code cell} is not one of the eight
	 */
	public long card(final int cell)
	{
		return card[cell];
	}

	/**
	 * One cell at guide prices alone; equal to {@link #card(int)} when no separate figure was stored.
	 *
	 * @throws ArrayIndexOutOfBoundsException if {@code cell} is not one of the eight
	 */
	public long guide(final int cell)
	{
		return guide == null ? card[cell] : guide[cell];
	}

	/** False when the guide figures equal the card's and are not stored. */
	public boolean hasGuide()
	{
		return guide != null;
	}

	/**
	 * The reading's total under these switches - the ONE rule every History figure uses (contract section 2), so
	 * the History figure always equals the Bank value card. The cells counted:
	 * <ul>
	 * <li>bank tradeable and bank parts - always;</li>
	 * <li>bank cash - {@code countCash}; bank alch - {@code countUntradeables};</li>
	 * <li>carried tradeable and carried parts - {@code countInventory};</li>
	 * <li>carried cash - {@code countInventory && countCash}; carried alch -
	 * {@code countInventory && countUntradeables}.</li>
	 * </ul>
	 * Summed from {@code card} with {@code livePrices} on and from {@code guide} with it off, with the clamped
	 * addition {@link PortfolioSummary} uses ({@link PortfolioMath#clampedAdd}).
	 *
	 * @param options the switches; null reads as {@link ViewOptions#DEFAULT} (amendment 9.2)
	 */
	public long valueFor(@Nullable final ViewOptions options)
	{
		final ViewOptions o = options == null ? ViewOptions.DEFAULT : options;
		final long[] figures = o.livePrices() || guide == null ? card : guide;
		final boolean cash = o.countCash();
		final boolean alch = o.countUntradeables();
		final boolean carried = o.countInventory();

		long sum = figures[BANK_TRADEABLE];
		sum = PortfolioMath.clampedAdd(sum, figures[BANK_PARTS]);
		if (cash)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[BANK_CASH]);
		}
		if (alch)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[BANK_ALCH]);
		}
		if (carried)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_TRADEABLE]);
			sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_PARTS]);
			if (cash)
			{
				sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_CASH]);
			}
			if (alch)
			{
				sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_ALCH]);
			}
		}
		return sum;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BankHistoryPoint))
		{
			return false;
		}
		final BankHistoryPoint other = (BankHistoryPoint) o;
		return day.equals(other.day)
			&& readAtMillis == other.readAtMillis
			&& bankAtMillis == other.bankAtMillis
			&& Arrays.equals(card, other.card)
			&& Arrays.equals(guide, other.guide);
	}

	@Override
	public int hashCode()
	{
		int h = Objects.hash(day, readAtMillis, bankAtMillis);
		h = 31 * h + Arrays.hashCode(card);
		return 31 * h + Arrays.hashCode(guide);
	}

	@Override
	public String toString()
	{
		return "BankHistoryPoint{day=" + day + ", readAtMillis=" + readAtMillis + ", bankAtMillis=" + bankAtMillis
			+ ", card=" + Arrays.toString(card) + (guide == null ? "" : ", guide=" + Arrays.toString(guide)) + '}';
	}
}

package com.bankpricemovement;

import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * One stack in the user's bank, folded onto its CANONICAL item id (contract C5). Public fields, a no-arg
 * constructor and nothing but plain types, because a snapshot is persisted with the injected Gson and read
 * back on the next launch (playbook step 13: "public fields, no-arg ctor, stock Gson").
 *
 * <p>The name and the stackable flag are carried rather than looked up again at render time on purpose: the
 * panel must draw the saved bank BEFORE the user logs in (design D7 - "Bank as of HH:MM" with no client
 * session), and {@code ItemComposition} is a client-thread read that is simply not available then.
 * {@code stackable} is what {@code ItemManager.getImage(id, quantity, stackable)} needs to draw the stack
 * number on the icon.
 *
 * <p>Noted items do not appear here as themselves: {@code BankReader} canonicalises first, so a note and its
 * unnoted twin are ONE entry with the quantities summed (design D6).
 *
 * <p><b>Untradeable stacks</b> (addendum Q, line Q5). Since Q the reader also keeps a stack the Grand Exchange
 * does not list when it has a High Alchemy value, so the service can list it without a bank visit - one RuneLite
 * maps onto tradeable parts always, an alch-only one while "Include alch-only untradeables" is on (addendum AV)
 * ({@link #untradeable} and {@link #haPrice} are the two fields that carry it). The negative spelling is
 * deliberate and load-bearing: a {@code bank-*.json} written before Q has neither field, and Gson leaves an absent
 * boolean at {@code false} - so {@code untradeable} reads as "tradeable" for every stack of an old file,
 * which is exactly what those files held. A {@code tradeable} field would have read every old stack as
 * untradeable and emptied the sidebar.
 *
 * <p><b>Tradeable parts</b> (addendum R, line R1). RuneLite knows what many an untradeable item reverts to:
 * {@code net.runelite.client.game.ItemMapping} maps a Crystal body onto three Crystal armour seeds, a degraded
 * barrows piece onto the base piece, a graceful piece onto marks of grace, and so on. {@link #parts} records that
 * answer at capture time, so such a stack can be valued at what its parts are worth on the exchange - with a
 * movement - instead of at the High Alchemy value Q5 had to settle for. It is null for a tradeable stack, null for
 * an untradeable one RuneLite has no mapping for, and null in every {@code bank-*.json} written before addendum R
 * (Gson leaves an absent field null); the next bank open fills it in. {@link #haPrice} is recorded either way, so a
 * stack whose parts turn out to have no price still has the alch rule to fall back on.
 */
public class BankItem
{
	/**
	 * One TRADEABLE item an untradeable stack reverts to, as RuneLite's {@code ItemMapping} names it (addendum R,
	 * line R1): {@code ITEM_CRYSTAL_BODY(PRIF_ARMOUR_SEED, true, 3L, CRYSTAL_CHESTPLATE)} becomes one of these,
	 * with {@code id} the seed and {@code quantity} 3.
	 *
	 * <p>Public fields, a no-arg constructor and plain types, for the same reason {@link BankItem} has them: a
	 * snapshot is persisted with the injected Gson and read back on the next launch.
	 */
	public static class Part
	{
		/** The tradeable item's id ({@code ItemMapping.getTradeableItem()}); positive in a recorded part. */
		public int id;

		/**
		 * How many of {@link #id} ONE of the untradeable item is worth ({@code ItemMapping.getQuantity()}, a long
		 * in RuneLite's own enum); positive in a recorded part.
		 */
		public long quantity;

		/**
		 * That part's name at capture time - {@code ItemComposition.getMembersName()}, the same naming rule the
		 * rows use (addendum L line L8 b) - so a guide table can be asked for it by name when the wiki's
		 * id-to-name mapping does not cover the id. "" when the composition had none.
		 */
		public String name;

		public Part()
		{
			name = "";
		}

		/**
		 * @param id       the tradeable item's id
		 * @param quantity how many of it ONE untradeable item is worth
		 * @param name     the part's members name; null becomes ""
		 */
		public Part(final int id, final long quantity, final String name)
		{
			this.id = id;
			this.quantity = quantity;
			this.name = name == null ? "" : name;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}

			if (!(o instanceof Part))
			{
				return false;
			}

			final Part other = (Part) o;
			return id == other.id && quantity == other.quantity && Objects.equals(name, other.name);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(id, quantity, name);
		}

		@Override
		public String toString()
		{
			return "Part{id=" + id + ", quantity=" + quantity + ", name='" + name + "'}";
		}
	}

	/**
	 * The canonical item id ({@code ItemManager.canonicalize}), always positive in a normalised snapshot.
	 */
	public int id;

	/**
	 * How many the bank holds; always positive in a normalised snapshot - a placeholder (quantity 0) is
	 * dropped rather than shown (design D6).
	 */
	public int quantity;

	/**
	 * The item's name at capture time. Never null after {@link BankSnapshot#normalize()}; "" when the
	 * composition had none.
	 */
	public String name;

	/**
	 * Whether the item stacks - what the icon needs to decide whether to draw a stack number.
	 */
	public boolean stackable;

	/**
	 * True when the Grand Exchange does not list this item ({@code ItemComposition.isGeTradeable()} is false), so
	 * it has no market price and no movement - it is valued at its {@link #parts} when they can all be priced
	 * (addendum R, always counted since addendum AV), else at {@link #haPrice}, and then only while the "Include
	 * alch-only untradeables" switch is on (Q5, AV). False for every ordinary stack, and false for every stack of a
	 * file written before addendum Q (see the class comment).
	 */
	public boolean untradeable;

	/**
	 * The High Alchemy value of ONE ({@code ItemComposition.getHaPrice()}, clone
	 * {@code runelite-api/src/main/java/net/runelite/api/ItemComposition.java:120}), recorded only for an
	 * {@link #untradeable} stack, which is valued at it. 0 for a tradeable stack - its price is the guide price,
	 * looked up live - and 0 for every stack of a pre-Q file.
	 */
	public int haPrice;

	/**
	 * The TRADEABLE items ONE of this stack reverts to, as {@code ItemMapping} named them at capture time
	 * (addendum R, line R1) - three Crystal armour seeds for a Crystal body, a black mask for a slayer helmet, the
	 * base piece for a degraded barrows item. Null for a tradeable stack, for an untradeable one RuneLite has no
	 * mapping for, and for every stack of a file written before addendum R; never empty when it is present.
	 *
	 * <p>Recorded whatever the "Include alch-only untradeables" switch says, exactly as {@link #haPrice} is: a snapshot
	 * that held only what the switch of the day wanted would need a bank visit every time it was flipped.
	 */
	public List<Part> parts;

	public BankItem()
	{
		name = "";
	}

	public BankItem(final int id, final int quantity, final String name, final boolean stackable)
	{
		this(id, quantity, name, stackable, false, 0);
	}

	/**
	 * The pre-R arity, kept so every caller that knows nothing of parts keeps compiling AND keeps its meaning: it
	 * records no parts, which is what an untradeable stack with no mapping holds.
	 *
	 * @param untradeable the Grand Exchange does not list this item (Q5)
	 * @param haPrice     what one alchs for, the value an untradeable stack is counted at when it has no parts
	 */
	public BankItem(final int id, final int quantity, final String name, final boolean stackable,
		final boolean untradeable, final int haPrice)
	{
		this(id, quantity, name, stackable, untradeable, haPrice, null);
	}

	/**
	 * @param parts the tradeable items one of this stack reverts to (R1), or null when RuneLite maps it to none; an
	 *              empty list is stored as null, because "no mapping" and "a mapping naming nothing" are the same
	 *              answer to every reader
	 */
	public BankItem(final int id, final int quantity, final String name, final boolean stackable,
		final boolean untradeable, final int haPrice, final List<Part> parts)
	{
		this.id = id;
		this.quantity = quantity;
		this.name = name == null ? "" : name;
		this.stackable = stackable;
		this.untradeable = untradeable;
		this.haPrice = haPrice;
		this.parts = parts == null || parts.isEmpty() ? null : Collections.unmodifiableList(parts);
	}

	/**
	 * This same stack with another quantity (addendum Y, line Y3): what {@code PriceService} folds a banked stack
	 * and a carried one into while "Include inventory and worn gear" is on - three in the bank and one in the
	 * inventory become one stack of four.
	 *
	 * <p>A COPY, and that is the whole point: the stacks it merges belong to the persisted snapshot, which the
	 * panel draws and the store writes, and a computation that changed a quantity under them would put a number in
	 * {@code bank-*.json} that no bank ever held. Everything else - the name, the stackable flag, the untradeable
	 * mark, the alch value and the parts - rides along unchanged.
	 *
	 * @param quantity the merged quantity
	 */
	public BankItem withQuantity(final int quantity)
	{
		return new BankItem(id, quantity, name, stackable, untradeable, haPrice, parts);
	}

	/**
	 * Whether this stack can be valued at its tradeable parts (R1) - the ONE place that rule is spelled, so the
	 * reader, the row, the bank value and the tooltip cannot drift apart. A list read off disk could be empty or
	 * hold nothing but nulls; both read as "no parts" here.
	 */
	public boolean hasParts()
	{
		if (parts == null)
		{
			return false;
		}

		for (final Part part : parts)
		{
			if (part != null)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * What this stack is worth per item when it is listed at its High Alchemy value, or null when it has no such
	 * value: an untradeable stack with a positive {@link #haPrice}, and nothing else. The ONE place that rule is
	 * spelled, so the row, the bank value and the reader's keep rule cannot drift apart.
	 *
	 * <p>Since addendum R this is the SECOND choice for an untradeable stack: one whose {@link #parts} can all be
	 * priced is worth their sum instead (R2), and the alch value is what a stack with no parts - or one whose parts
	 * the guide tables cannot price - falls back to. The rule itself is unchanged, and so is every stack it answers
	 * for; the decision between the two belongs to {@code PriceService}, which is the only thing that knows what a
	 * part costs today.
	 */
	public Long alchPrice()
	{
		return untradeable && haPrice > 0 ? Long.valueOf(haPrice) : null;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof BankItem))
		{
			return false;
		}

		final BankItem other = (BankItem) o;
		return id == other.id
			&& quantity == other.quantity
			&& stackable == other.stackable
			&& untradeable == other.untradeable
			&& haPrice == other.haPrice
			&& (name == null ? other.name == null : name.equals(other.name))
			&& Objects.equals(parts, other.parts);
	}

	@Override
	public int hashCode()
	{
		int result = id;
		result = 31 * result + quantity;
		result = 31 * result + (stackable ? 1 : 0);
		result = 31 * result + (untradeable ? 1 : 0);
		result = 31 * result + haPrice;
		result = 31 * result + (name == null ? 0 : name.hashCode());
		result = 31 * result + (parts == null ? 0 : parts.hashCode());
		return result;
	}

	@Override
	public String toString()
	{
		return "BankItem{id=" + id + ", quantity=" + quantity + ", name='" + name + "', stackable=" + stackable
			+ (untradeable ? ", untradeable, haPrice=" + haPrice : "")
			+ (hasParts() ? ", parts=" + parts : "") + '}';
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.TreeMap;
import javax.annotation.Nullable;

/**
 * The readings of one account on one profile (addendum AU; phase 0 contract sections 1, 3 and 9.4): immutable,
 * sorted by day, at most ONE reading per day. Days with no reading are not here - they are derived when drawing,
 * by {@link BankHistoryMath#days} and nowhere else.
 *
 * <p><b>One reading per day.</b> Two readings that name one day are resolved by their {@code readAtMillis}: the
 * later one wins, because "the last one of the day stays" (plan 7.5 item 1). On a tie the one given later wins -
 * the element later in {@link #of}'s collection. {@link #with} replaces its day's reading unconditionally.
 *
 * <p>Value equality over {@link #points()}, so a series re-read from disk equals the one in memory when they hold
 * the same readings - which is how the store decides that a write would change nothing, and how the History view
 * decides that there is nothing to redraw.
 */
public final class BankHistorySeries
{
	/** No readings at all. */
	public static final BankHistorySeries EMPTY = new BankHistorySeries(Collections.<BankHistoryPoint>emptyList());

	/** Ascending by day, one per day, unmodifiable. */
	private final List<BankHistoryPoint> points;

	private BankHistorySeries(final List<BankHistoryPoint> sorted)
	{
		this.points = sorted;
	}

	/**
	 * The series of these readings: sorted by day, one per day - the higher {@code readAtMillis} wins, and on a tie
	 * the one later in the collection. Null elements are skipped; a null or empty collection is {@link #EMPTY}.
	 */
	public static BankHistorySeries of(@Nullable final Collection<BankHistoryPoint> points)
	{
		if (points == null || points.isEmpty())
		{
			return EMPTY;
		}
		final TreeMap<LocalDate, BankHistoryPoint> byDay = new TreeMap<>();
		for (final BankHistoryPoint point : points)
		{
			if (point != null)
			{
				byDay.merge(point.day(), point, BankHistorySeries::later);
			}
		}
		return fromMap(byDay);
	}

	/** Of two readings of one day, the one taken later; {@code b} on a tie. */
	private static BankHistoryPoint later(final BankHistoryPoint a, final BankHistoryPoint b)
	{
		return a.readAtMillis() > b.readAtMillis() ? a : b;
	}

	private static BankHistorySeries fromMap(final TreeMap<LocalDate, BankHistoryPoint> byDay)
	{
		if (byDay.isEmpty())
		{
			return EMPTY;
		}
		return new BankHistorySeries(Collections.unmodifiableList(new ArrayList<>(byDay.values())));
	}

	private TreeMap<LocalDate, BankHistoryPoint> toMap()
	{
		final TreeMap<LocalDate, BankHistoryPoint> byDay = new TreeMap<>();
		for (final BankHistoryPoint point : points)
		{
			byDay.put(point.day(), point);
		}
		return byDay;
	}

	/**
	 * This series with {@code point} as its day's reading, replacing whatever was there whatever its time - the
	 * reading just taken is the last one of its day (plan 7.5 item 1). A null point answers this series.
	 */
	public BankHistorySeries with(@Nullable final BankHistoryPoint point)
	{
		if (point == null)
		{
			return this;
		}
		final TreeMap<LocalDate, BankHistoryPoint> byDay = toMap();
		byDay.put(point.day(), point);
		return fromMap(byDay);
	}

	/**
	 * This series without the readings dated after {@code today} - a clock that was wrong when they were taken
	 * (plan 7.1 item 7). They are not drawn, and the store drops them at its next write.
	 */
	public BankHistorySeries upTo(final LocalDate today)
	{
		Objects.requireNonNull(today, "today");
		final BankHistoryPoint last = last();
		if (last == null || !last.day().isAfter(today))
		{
			return this;
		}
		final List<BankHistoryPoint> kept = new ArrayList<>(points.size());
		for (final BankHistoryPoint point : points)
		{
			if (!point.day().isAfter(today))
			{
				kept.add(point);
			}
		}
		return kept.isEmpty() ? EMPTY : new BankHistorySeries(Collections.unmodifiableList(kept));
	}

	/** Every reading, ascending by day; unmodifiable. */
	public List<BankHistoryPoint> points()
	{
		return points;
	}

	public boolean isEmpty()
	{
		return points.isEmpty();
	}

	/** How many readings - days WITH a reading; carried days are not counted. */
	public int size()
	{
		return points.size();
	}

	/** The earliest reading, or null when there is none. */
	@Nullable
	public BankHistoryPoint first()
	{
		return points.isEmpty() ? null : points.get(0);
	}

	/** The latest reading, or null when there is none. */
	@Nullable
	public BankHistoryPoint last()
	{
		return points.isEmpty() ? null : points.get(points.size() - 1);
	}

	/** The reading OF that day, or null when that day has none (or {@code day} is null). */
	@Nullable
	public BankHistoryPoint on(@Nullable final LocalDate day)
	{
		final int i = indexAtOrBefore(day);
		return i >= 0 && points.get(i).day().equals(day) ? points.get(i) : null;
	}

	/** The last reading on or before that day, or null when there is none (or {@code day} is null). */
	@Nullable
	public BankHistoryPoint atOrBefore(@Nullable final LocalDate day)
	{
		final int i = indexAtOrBefore(day);
		return i >= 0 ? points.get(i) : null;
	}

	/** The index of the last reading on or before {@code day}, or -1: a binary search over the sorted days. */
	private int indexAtOrBefore(@Nullable final LocalDate day)
	{
		if (day == null)
		{
			return -1;
		}
		int lo = 0;
		int hi = points.size() - 1;
		int found = -1;
		while (lo <= hi)
		{
			final int mid = (lo + hi) >>> 1;
			if (points.get(mid).day().isAfter(day))
			{
				hi = mid - 1;
			}
			else
			{
				found = mid;
				lo = mid + 1;
			}
		}
		return found;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		return o instanceof BankHistorySeries && points.equals(((BankHistorySeries) o).points);
	}

	@Override
	public int hashCode()
	{
		return points.hashCode();
	}

	@Override
	public String toString()
	{
		final BankHistoryPoint first = first();
		final BankHistoryPoint last = last();
		return "BankHistorySeries{readings=" + points.size()
			+ (first == null ? "" : ", first=" + first.day() + ", last=" + last.day()) + '}';
	}
}

package com.bankpricemovement;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The TRADED price feeds of addendum T line T2 - the OSRS Wiki's real-time prices, which is a different series
 * from the Jagex guide table {@link GuidePriceClient} reads and is only ever used for a stack that passes the
 * liquidity checks of T3 (three at addendum T, five since addendum V).
 *
 * <p>Two endpoints, and nothing else:
 * <ul>
 * <li>{@value #LATEST_URL} - the newest instant-buy and instant-sell per item, each with the second it was
 * traded at: {@code {"data":{"4151":{"high":1700000,"highTime":1788859512,"low":1690000,"lowTime":1788859480}}}}.
 * Any of the four members may be null (an item nobody has bought, or nobody has sold, since the API's own
 * horizon). Fetched on every accepted Refresh, on the thirty-minute tick and at start-up, and only while the
 * {@code livePrices} switch is on;</li>
 * <li>{@value #DAILY_URL}{@code ?timestamp=<UTC midnight of day D in seconds>} - the BULK daily bucket, one
 * entry per item traded that day: {@code {"data":{"4151":{"avgHighPrice":1699000,"avgLowPrice":1688000,
 * "highPriceVolume":213,"lowPriceVolume":304}},"timestamp":1788825600}}. A price may be null; a volume is 0 when
 * the side saw no trade. Fetched once per UTC day per window, for the day that window counts back to from the
 * live snapshot's own date ({@code liveDay - N}, addendum U line U1), and never for TODAY - the running day
 * answers an empty bucket, and every window is at least one day back. An EMPTY answer for a past day means the
 * wiki has not closed that day yet, and {@code PriceService} then asks once for the day before it (U2).</li>
 * </ul>
 *
 * <p><b>Why this is a second client and not three more methods on {@link GuidePriceClient}.</b> That class is
 * the GUIDE series - one host, one page, one set of failure shapes, and a class comment that promises every
 * printed figure comes from Jagex's daily table. The traded series answers a different question (what someone
 * actually paid, minutes ago), has its own hosts and its own fail gate, and is switched off entirely by one
 * config item. Keeping them apart is what makes "the switch off is byte-identical to today" a property of the
 * wiring rather than a promise about branches.
 *
 * <p><b>What leaves the client, exactly.</b> As with {@link GuidePriceClient}, neither URL carries anything
 * derived from the player: {@link #latestUrl()} is a bare GET, and {@link #dayUrl(LocalDate)} carries one UTC
 * midnight the plugin computed from a date it derived itself. No item id, no quantity, no account. Every user
 * of this plugin issues byte-identical requests, and the hosts learn only an IP and that the plugin is
 * installed. {@code theRequestUrlsCarryNothingDerivedFromThePlayer} in the tests keeps that true.
 *
 * <p><b>Why the client and the Gson are injected, and why enqueue.</b> Both for the reasons spelled out on
 * {@link GuidePriceClient}: RuneLite's {@code @Provides OkHttpClient} is the only one whose requests carry a
 * usable User-Agent and transparent gzip, constructing an OkHttpClient or a Gson in plugin code is a Plugin Hub
 * packaging blocker, and {@code RuneLiteModule} throws for a blocking call made on the client thread or the EDT.
 * The User-Agent string is {@link GuidePriceClient#USER_AGENT} itself rather than a second spelling of it, so an
 * operator reading either wiki host's logs sees one plugin.
 *
 * <p><b>One failure type</b> ({@link WikiPriceException}), exactly as the guide client has: a non-2xx, a body
 * that is not the expected shape, an empty feed and a transport {@code IOException} all complete the future
 * exceptionally, and the future never completes with null. {@code PriceService} keeps whatever it last stored
 * and carries on with the guide prices (T7).
 *
 * <p>This class holds no cache and no schedule: staleness, the six-hour rule and one-in-flight-per-feed are
 * {@code PriceService}'s. Its only state is {@link #setEnabled(boolean)}, the calls still on the wire for
 * {@link #cancelInFlight()}, and the "a failure has already been logged loudly" flag.
 */
public class TradedPriceClient
{
	private static final Logger log = LoggerFactory.getLogger(TradedPriceClient.class);

	/** The newest instant-buy / instant-sell per item (T2 a). */
	public static final String LATEST_URL = "https://prices.runescape.wiki/api/v1/osrs/latest";

	/** The bulk daily bucket (T2 b); one {@code timestamp} parameter names the UTC day. */
	public static final String DAILY_URL = "https://prices.runescape.wiki/api/v1/osrs/24h";

	/** The same descriptive User-Agent the guide client sends - one plugin, one string. */
	public static final String USER_AGENT = GuidePriceClient.USER_AGENT;

	/** Header name, spelled once so the request builder and the tests cannot drift apart. */
	public static final String USER_AGENT_HEADER = GuidePriceClient.USER_AGENT_HEADER;

	/** Seconds in a UTC calendar day - what {@link #midnightSeconds(LocalDate)} multiplies by. */
	public static final long SECONDS_PER_DAY = 86_400L;

	/** Error and diagnostic text is cut to this many characters before it reaches a message or the log. */
	private static final int MAX_DETAIL_CHARS = 200;

	private final OkHttpClient client;
	private final Gson gson;

	/**
	 * Developer-mode switch, the twin of {@link GuidePriceClient#setEnabled(boolean)}: when false every fetch
	 * fails immediately without touching the network, so T7's "live prices unavailable" state can be exercised in
	 * a live client. Volatile because it is written from the bridge/EDT and read on whichever thread starts a
	 * fetch. Never flipped by user-facing code.
	 */
	private volatile boolean enabled = true;

	/** Every call enqueued and not yet answered, so {@link #cancelInFlight()} can drop them when the plugin stops. */
	private final List<Call> inFlight = new CopyOnWriteArrayList<>();

	/** Whether {@link #report} has already logged a failure loudly this session. */
	private volatile boolean reported;

	/**
	 * @param client RuneLite's injected OkHttpClient; constructing one here is a Plugin Hub blocker
	 * @param gson   RuneLite's injected Gson, for the same reason
	 */
	public TradedPriceClient(final OkHttpClient client, final Gson gson)
	{
		if (client == null)
		{
			throw new IllegalArgumentException("client is required (inject RuneLite's OkHttpClient)");
		}
		if (gson == null)
		{
			throw new IllegalArgumentException("gson is required (inject RuneLite's Gson)");
		}
		this.client = client;
		this.gson = gson;
	}

	// ---------------------------------------------------------------- the two fetches (T2)

	/**
	 * The newest traded quote per item (T2 a).
	 *
	 * @param nowMillis the caller's clock; not part of the request, but taken so the SERVICE's settable clock -
	 *                  never {@code System.currentTimeMillis()} in here - decides what "six hours old" means (T7)
	 * @return a future completing with item id to {@link Quote}, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<Map<Integer, Quote>> fetchLatest(final long nowMillis)
	{
		log.debug("bank-portfolio-tracker: fetching the traded /latest snapshot at {}", nowMillis);
		return request(latestUrl(), this::parseLatest);
	}

	/**
	 * One whole UTC calendar day's traded bucket (T2 b).
	 *
	 * @param day       the day; must be in the past - the running day answers an empty bucket, and
	 *                  {@code PriceService} never asks for it. Null is refused rather than turned into "today"
	 * @param nowMillis stamped by the caller onto whatever it stores; not part of the request
	 * @return a future completing with item id to {@link Bucket}, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<Map<Integer, Bucket>> fetchDay(final LocalDate day, final long nowMillis)
	{
		if (day == null)
		{
			// Deliberately a failure and not an empty success: a caller with no day has a bug, and an empty map
			// would look like "that day traded nothing" to the code that stores buckets.
			return failed(new WikiPriceException("no day to fetch a traded bucket for"));
		}
		log.debug("bank-portfolio-tracker: fetching the traded bucket of {} at {}", day, nowMillis);
		return request(dayUrl(day), this::parseDay);
	}

	/**
	 * Developer-mode kill switch, the twin of {@link GuidePriceClient#setEnabled(boolean)}; true is the shipped
	 * state. User-facing behaviour must never depend on this (workspace rule: no user feature may need a dev hook).
	 */
	public void setEnabled(final boolean enabled)
	{
		this.enabled = enabled;
	}

	/** @see #setEnabled(boolean) */
	public boolean isEnabled()
	{
		return enabled;
	}

	/**
	 * Cancels every call still on the wire, from {@code PriceService.stop()}. {@code Call.cancel()} is safe from
	 * any thread; a cancelled call's {@code onFailure} completes its future as an ordinary failure.
	 */
	public void cancelInFlight()
	{
		for (final Call call : new ArrayList<>(inFlight))
		{
			inFlight.remove(call);
			try
			{
				call.cancel();
			}
			catch (final RuntimeException e)
			{
				log.debug("bank-portfolio-tracker: a traded-price call refused to cancel", e);
			}
		}
	}

	// ---------------------------------------------------------------- the exact URLs

	/** {@value #LATEST_URL}, with no parameters at all. */
	static String latestUrl()
	{
		return LATEST_URL;
	}

	/**
	 * {@value #DAILY_URL}{@code ?timestamp=<UTC midnight of the day, in seconds>} - the only parameter this
	 * plugin ever sends to either wiki host, and it is a date the plugin derived from the guide tables rather
	 * than anything about the player.
	 */
	static String dayUrl(final LocalDate day)
	{
		return DAILY_URL + "?timestamp=" + midnightSeconds(day);
	}

	/**
	 * The UTC midnight that opens a calendar day, in unix seconds - the {@code timestamp} the bulk endpoint
	 * indexes a day by.
	 *
	 * <p>{@link LocalDate#toEpochDay()} times {@value #SECONDS_PER_DAY} rather than a zoned conversion: every
	 * date in this plugin is already a UTC date (addendum L line L9), and a day here has exactly 86,400 seconds -
	 * there are no leap seconds in unix time and no zone to shift it.
	 */
	static long midnightSeconds(final LocalDate day)
	{
		Objects.requireNonNull(day, "day");
		return day.toEpochDay() * SECONDS_PER_DAY;
	}

	// ---------------------------------------------------------------- parsers (package-private, pure)

	/**
	 * The {@code /latest} body as item id to {@link Quote}. Shape:
	 * {@code {"data":{"2":{"high":193,"highTime":1616682200,"low":186,"lowTime":1616682209}, ...}}}.
	 *
	 * <p>Any of the four members may be null or absent, and an entry with NEITHER price is dropped: it names no
	 * traded price, so nothing downstream could do anything with it but skip it. An id that is not an integer is
	 * skipped rather than thrown, for the same reason the guide parsers skip an odd entry - one bad row must not
	 * cost the other four thousand.
	 *
	 * @throws WikiPriceException on a non-object body, a missing {@code data} object, or a feed with no usable
	 *                            entry in it (a route change, as opposed to one odd item)
	 */
	Map<Integer, Quote> parseLatest(final String json) throws WikiPriceException
	{
		final JsonObject data = dataOf(readObject(json), "latest");
		final Map<Integer, Quote> quotes = new LinkedHashMap<>();
		for (final Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			final Integer id = parseId(entry.getKey());
			final JsonObject value = objectOf(entry.getValue());
			if (id == null || value == null)
			{
				continue;
			}
			final Long high = optLong(value, "high");
			final Long low = optLong(value, "low");
			if (high == null && low == null)
			{
				continue;
			}
			quotes.put(id, new Quote(high, seconds(value, "highTime"), low, seconds(value, "lowTime")));
		}
		if (quotes.isEmpty())
		{
			throw new WikiPriceException("the wiki traded /latest feed carried no prices");
		}
		return quotes;
	}

	/**
	 * A {@code /24h?timestamp=} body as item id to {@link Bucket}. Shape:
	 * {@code {"data":{"2":{"avgHighPrice":190,"avgLowPrice":186,"highPriceVolume":100,"lowPriceVolume":200},
	 * ...},"timestamp":1615766400}}.
	 *
	 * <p>Either price may be null while the volumes stand - an item bought but never sold that day - and that
	 * entry is KEPT, because T3's volume check reads the volumes and T4's own rule reads the price separately.
	 * An entry with no price and no volume names nothing and is dropped.
	 *
	 * @throws WikiPriceException on a non-object body, a missing {@code data} object, or an empty bucket - which
	 *                            is what the RUNNING day answers, and which is why a caller must only ever ask
	 *                            for a day that has closed
	 */
	Map<Integer, Bucket> parseDay(final String json) throws WikiPriceException
	{
		final JsonObject data = dataOf(readObject(json), "24h");
		final Map<Integer, Bucket> buckets = new LinkedHashMap<>();
		for (final Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			final Integer id = parseId(entry.getKey());
			final JsonObject value = objectOf(entry.getValue());
			if (id == null || value == null)
			{
				continue;
			}
			final Long avgHigh = optLong(value, "avgHighPrice");
			final Long avgLow = optLong(value, "avgLowPrice");
			final long highVolume = Math.max(0L, orZero(optLong(value, "highPriceVolume")));
			final long lowVolume = Math.max(0L, orZero(optLong(value, "lowPriceVolume")));
			if (avgHigh == null && avgLow == null && highVolume == 0L && lowVolume == 0L)
			{
				continue;
			}
			buckets.put(id, new Bucket(avgHigh, highVolume, avgLow, lowVolume));
		}
		if (buckets.isEmpty())
		{
			throw new WikiPriceException("the wiki traded daily bucket carried no entries");
		}
		return buckets;
	}

	// ---------------------------------------------------------------- the two value types

	/**
	 * One item's newest traded pair from {@code /latest}: the instant-BUY price someone paid ({@code high}), the
	 * instant-SELL price someone accepted ({@code low}), and the second each was traded at. Either price may be
	 * absent; a quote with neither never reaches here ({@link #parseLatest}).
	 *
	 * <p>Immutable and shared: built on OkHttp's dispatcher thread, stored on the service's executor, read while
	 * the rows are computed.
	 */
	public static final class Quote
	{
		private final Long buy;
		private final Long sell;
		private final long buySeconds;
		private final long sellSeconds;

		/**
		 * @param buy         the newest instant-buy price ({@code high}), or null
		 * @param buySeconds  when it was traded, unix seconds; 0 when unknown
		 * @param sell        the newest instant-sell price ({@code low}), or null
		 * @param sellSeconds when it was traded, unix seconds; 0 when unknown
		 */
		public Quote(final Long buy, final long buySeconds, final Long sell, final long sellSeconds)
		{
			this.buy = buy;
			this.sell = sell;
			this.buySeconds = buySeconds;
			this.sellSeconds = sellSeconds;
		}

		/** The newest instant-buy price ({@code high}), or null when nobody has bought since the API's horizon. */
		public Long buy()
		{
			return buy;
		}

		/** The newest instant-sell price ({@code low}), or null when nobody has sold. */
		public Long sell()
		{
			return sell;
		}

		/** When {@link #buy()} was traded, unix seconds; 0 when there is no buy side. */
		public long buySeconds()
		{
			return buySeconds;
		}

		/** When {@link #sell()} was traded, unix seconds; 0 when there is no sell side. */
		public long sellSeconds()
		{
			return sellSeconds;
		}

		/** Both sides present - the first half of T3's spread check. */
		public boolean hasBothSides()
		{
			return buy != null && sell != null;
		}

		/**
		 * The live price of one item: the mean of the two sides, rounded HALF UP, in integer arithmetic (T3).
		 * Null when a side is missing - a one-sided quote is never a live price, because T3 refuses it anyway and
		 * inventing a mid from it would make the refusal look like a number.
		 *
		 * <p>The halves are added separately so a pair near {@link Long#MAX_VALUE} cannot overflow the way
		 * {@code (buy + sell) / 2} would; every real price is far below that.
		 */
		public Long mid()
		{
			if (!hasBothSides())
			{
				return null;
			}
			final long half = buy / 2L + sell / 2L;
			final long remainder = (buy % 2L) + (sell % 2L);
			return half + (remainder + 1L) / 2L;
		}

		/**
		 * The gap between the two sides, as an absolute figure - T3's spread numerator. Null when a side is
		 * missing. Absolute rather than {@code buy - sell}: the two sides are the newest trade on each side of
		 * the book and nothing guarantees which is larger, and a negative gap would sail through the check.
		 */
		public Long spread()
		{
			return hasBothSides() ? Long.valueOf(Math.abs(buy - sell)) : null;
		}

		/**
		 * Whether BOTH sides were traded inside the last {@code maxAgeSeconds} - T3's "each with a time inside the
		 * last 24 h". A time in the FUTURE passes: that is clock skew between the viewer's machine and the wiki,
		 * not a stale quote, and refusing it would make the feature depend on an unsynchronised clock.
		 *
		 * @param nowSeconds     the caller's clock in unix seconds
		 * @param maxAgeSeconds  how old a side may be
		 */
		public boolean tradedWithin(final long nowSeconds, final long maxAgeSeconds)
		{
			if (!hasBothSides() || buySeconds <= 0L || sellSeconds <= 0L)
			{
				return false;
			}
			return nowSeconds - buySeconds <= maxAgeSeconds && nowSeconds - sellSeconds <= maxAgeSeconds;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Quote))
			{
				return false;
			}
			final Quote other = (Quote) o;
			return Objects.equals(buy, other.buy) && Objects.equals(sell, other.sell)
				&& buySeconds == other.buySeconds && sellSeconds == other.sellSeconds;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(buy, sell, buySeconds, sellSeconds);
		}

		@Override
		public String toString()
		{
			return "Quote{buy=" + buy + "@" + buySeconds + ", sell=" + sell + "@" + sellSeconds + '}';
		}
	}

	/**
	 * One item's whole-day traded bucket from {@code /24h}: the day's average on each side and how many units
	 * changed hands on each. Either price may be absent while its volume stands.
	 *
	 * <p>Immutable and shared, like {@link Quote}.
	 */
	public static final class Bucket
	{
		private final Long avgHigh;
		private final Long avgLow;
		private final long highVolume;
		private final long lowVolume;

		/**
		 * @param avgHigh    the day's average instant-buy price, or null when nobody bought
		 * @param highVolume how many units were bought; never negative
		 * @param avgLow     the day's average instant-sell price, or null when nobody sold
		 * @param lowVolume  how many units were sold; never negative
		 */
		public Bucket(final Long avgHigh, final long highVolume, final Long avgLow, final long lowVolume)
		{
			this.avgHigh = avgHigh;
			this.avgLow = avgLow;
			this.highVolume = Math.max(0L, highVolume);
			this.lowVolume = Math.max(0L, lowVolume);
		}

		/** The day's average instant-buy price, or null. */
		public Long avgHigh()
		{
			return avgHigh;
		}

		/** The day's average instant-sell price, or null. */
		public Long avgLow()
		{
			return avgLow;
		}

		/** How many units were bought that day. */
		public long highVolume()
		{
			return highVolume;
		}

		/** How many units were sold that day. */
		public long lowVolume()
		{
			return lowVolume;
		}

		/** Units traded that day, both sides - T3's volume check and the tooltip's "517 traded yesterday". */
		public long volume()
		{
			return PortfolioMath.clampedAdd(highVolume, lowVolume);
		}

		/**
		 * The day's one price: {@code (avgHigh x hv + avgLow x lv) / (hv + lv)}, rounded half up (T4). Null when
		 * the bucket carries no price at all.
		 *
		 * <p>Three shapes, exactly as T4 words them:
		 * <ul>
		 * <li>one side absent: the side that IS present, whatever the volumes say - an average of one number is
		 * that number;</li>
		 * <li>both sides present with volume: the volume-weighted mean;</li>
		 * <li>both sides present with NO volume on either (a bucket the feed carried prices for and zero counts):
		 * the plain mean, because a weighted mean of zero weights is not a number.</li>
		 * </ul>
		 * The weighted arithmetic is exact in {@code long} and falls back to {@code double} only if a product
		 * overflows, which needs a price and a volume no exchange has ever seen.
		 */
		public Long weightedAverage()
		{
			if (avgHigh == null)
			{
				return avgLow;
			}
			if (avgLow == null)
			{
				return avgHigh;
			}
			final long weight = highVolume + lowVolume;
			if (weight <= 0L)
			{
				return new Quote(avgHigh, 0L, avgLow, 0L).mid();
			}
			try
			{
				final long total = Math.addExact(Math.multiplyExact(avgHigh, highVolume),
					Math.multiplyExact(avgLow, lowVolume));
				// Half up, the same rounding the mid uses; both operands are non-negative here.
				return (total + weight / 2L) / weight;
			}
			catch (final ArithmeticException overflow)
			{
				return Math.round((avgHigh * (double) highVolume + avgLow * (double) lowVolume) / (double) weight);
			}
		}

		/**
		 * The middle of the day's two averages, {@code (avgHigh + avgLow + 1) / 2} - addendum V line V3's gap
		 * denominator. Integer arithmetic rounded HALF UP, the same shape {@link Quote#mid()} gives the live pair,
		 * so the bucket's gap is judged by exactly the rule and the rounding check 2 judges the quote's by.
		 *
		 * <p>Null when either side is absent: a bucket with one side has no middle, only that side - and V3 reads
		 * that null as "no gap to measure", never as a failure.
		 *
		 * <p>The halves are added separately for {@link Quote#mid()}'s reason: a pair near {@link Long#MAX_VALUE}
		 * must not overflow on its way to being refused.
		 */
		public Long bucketMid()
		{
			if (avgHigh == null || avgLow == null)
			{
				return null;
			}
			final long half = avgHigh / 2L + avgLow / 2L;
			final long remainder = (avgHigh % 2L) + (avgLow % 2L);
			return half + (remainder + 1L) / 2L;
		}

		/**
		 * How far the day's two averages sit apart, absolute - addendum V line V3's gap numerator, and the figure
		 * the refusal "buy/sell gap 100 % yesterday" names as a percentage of {@link #bucketMid()}.
		 *
		 * <p>Null when either side is absent, and ABSOLUTE for {@link Quote#spread()}'s reason: nothing guarantees
		 * which side of a day's book averaged higher, and a negative gap would sail through the check.
		 */
		public Long gap()
		{
			return avgHigh == null || avgLow == null ? null : Long.valueOf(Math.abs(avgHigh - avgLow));
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Bucket))
			{
				return false;
			}
			final Bucket other = (Bucket) o;
			return Objects.equals(avgHigh, other.avgHigh) && Objects.equals(avgLow, other.avgLow)
				&& highVolume == other.highVolume && lowVolume == other.lowVolume;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(avgHigh, avgLow, highVolume, lowVolume);
		}

		@Override
		public String toString()
		{
			return "Bucket{avgHigh=" + avgHigh + "x" + highVolume + ", avgLow=" + avgLow + "x" + lowVolume + '}';
		}
	}

	// ---------------------------------------------------------------- internals (the guide client's shapes)

	/**
	 * Builds the request, enqueues it and adapts OkHttp's callback pair onto one future - the same shape as
	 * {@code GuidePriceClient.request}, including the reason the future is completed on every path and BEFORE an
	 * {@link Error} is rethrown: OkHttp 3.14.9 rethrows a Throwable from inside {@code onResponse} on its own
	 * dispatcher thread rather than routing it to {@code onFailure}, so a rethrow first would leave the caller's
	 * in-flight flag claimed for the rest of the session.
	 */
	private <T> CompletableFuture<T> request(final String url, final BodyParser<T> parser)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();

		if (!enabled)
		{
			future.completeExceptionally(new WikiPriceException("traded price fetches are switched off (developer mode)"));
			return future;
		}

		final Request request;
		try
		{
			request = new Request.Builder()
				.url(url)
				.header(USER_AGENT_HEADER, USER_AGENT)
				.get()
				.build();
		}
		catch (final RuntimeException e)
		{
			future.completeExceptionally(new WikiPriceException("could not build the traded-price request for " + url, e));
			return future;
		}

		try
		{
			final Call call = client.newCall(request);
			inFlight.add(call);
			future.whenComplete((value, error) -> inFlight.remove(call));
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(final Call call, final IOException e)
				{
					fail(future, url, new WikiPriceException("traded-price request failed: " + messageOf(e), e));
				}

				@Override
				public void onResponse(final Call call, final Response response)
				{
					final T value;
					try (Response closing = response)
					{
						final String body = bodyText(closing);
						if (!closing.isSuccessful())
						{
							fail(future, url, httpFailure(closing.code()));
							return;
						}
						value = parser.parse(body);
					}
					catch (final IOException e)
					{
						fail(future, url, e instanceof WikiPriceException
							? (WikiPriceException) e
							: new WikiPriceException("could not read the traded-price response: " + messageOf(e), e));
						return;
					}
					catch (final Throwable t)
					{
						failAndRethrow(future, url, new WikiPriceException(
							"could not parse the traded-price response: " + messageOf(t), t), t);
						return;
					}
					future.complete(value);
				}
			});
		}
		catch (final Throwable t)
		{
			failAndRethrow(future, url, new WikiPriceException("could not queue the traded-price request: " + messageOf(t), t), t);
		}

		return future;
	}

	/** The one way a request fails: {@link #report} it, THEN complete the future with it. */
	private <T> void fail(final CompletableFuture<T> future, final String url, final WikiPriceException failure)
	{
		report(url, failure);
		future.completeExceptionally(failure);
	}

	/** {@link #fail} for a {@code catch} on {@link Throwable}: complete first, rethrow an {@link Error} after. */
	private <T> void failAndRethrow(final CompletableFuture<T> future, final String url,
		final WikiPriceException failure, final Throwable cause)
	{
		fail(future, url, failure);
		if (cause instanceof Error)
		{
			throw (Error) cause;
		}
	}

	/**
	 * Logs one failure: the FIRST of the session loudly, with the url and any HTTP status, every one after it at
	 * debug - the same rule {@code GuidePriceClient.report} follows, and for the same reason (an outage lasts
	 * hours, the tick is thirty minutes, and a repeated line is noise in someone else's log).
	 */
	private void report(final String url, final WikiPriceException failure)
	{
		final String status = failure.hasHttpCode() ? " (HTTP " + failure.getHttpCode() + ")" : "";
		if (reported)
		{
			log.debug("bank-portfolio-tracker: traded-price request to {} failed{}", url, status, failure);
			return;
		}
		reported = true;
		log.warn("bank-portfolio-tracker: traded-price request to {} failed{} - live prices will fall back to the"
			+ " guide prices until it recovers", url, status, failure);
	}

	/** A future that has already failed - the shape {@link #fetchDay} refuses a bad argument with. */
	private static <T> CompletableFuture<T> failed(final WikiPriceException failure)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();
		future.completeExceptionally(failure);
		return future;
	}

	/** The {@code data} member of either feed, or a failure naming which feed it was. */
	private static JsonObject dataOf(final JsonObject root, final String feed) throws WikiPriceException
	{
		final JsonElement data = root.get("data");
		if (data == null || !data.isJsonObject())
		{
			throw new WikiPriceException("the wiki traded " + feed + " response has no data object");
		}
		return data.getAsJsonObject();
	}

	/** Reads the whole body as text, tolerating a null body (a HEAD-shaped or synthetic response). */
	private static String bodyText(final Response response) throws IOException
	{
		final ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	/**
	 * A body as a {@link JsonObject}, or a failure. Parsed as {@link JsonElement} first so a non-object body
	 * becomes a clean failure rather than a ClassCastException, and with the INJECTED Gson - constructing one in
	 * plugin code is a Plugin Hub blocker.
	 */
	private JsonObject readObject(final String json) throws WikiPriceException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new WikiPriceException("empty response from the wiki traded prices");
		}

		final JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (final RuntimeException e)
		{
			throw new WikiPriceException("malformed JSON from the wiki traded prices: " + messageOf(e), e);
		}

		if (root == null || root.isJsonNull() || !root.isJsonObject())
		{
			throw new WikiPriceException("the wiki traded-price response was not a JSON object");
		}
		return root.getAsJsonObject();
	}

	/** One JSON value as an object, or null when it is anything else. Never throws. */
	private static JsonObject objectOf(final JsonElement value)
	{
		return value != null && value.isJsonObject() ? value.getAsJsonObject() : null;
	}

	/** A nullable numeric member as a {@code Long}; absent, JSON null or non-numeric all read as null. */
	private static Long optLong(final JsonObject object, final String key)
	{
		final JsonElement value = object.get(key);
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return Long.valueOf(value.getAsLong());
		}
		catch (final RuntimeException e)
		{
			// A boolean primitive, or a string that is not a number: skip the member, never fail the fetch.
			return null;
		}
	}

	/** A trade time member in unix seconds; absent or negative reads as 0, which {@link Quote} treats as unknown. */
	private static long seconds(final JsonObject object, final String key)
	{
		return Math.max(0L, orZero(optLong(object, key)));
	}

	private static long orZero(final Long value)
	{
		return value == null ? 0L : value;
	}

	/** An item id key, or null when the text is not an integer (skip the entry, never fail the fetch). */
	private static Integer parseId(final String key)
	{
		if (key == null)
		{
			return null;
		}
		try
		{
			final int id = Integer.parseInt(key.trim());
			return id > 0 ? Integer.valueOf(id) : null;
		}
		catch (final NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * A non-2xx answer. The status is carried on the exception because 403 is diagnosable on its own (the prices
	 * host pre-emptively blocks default user agents) while the body for it is unhelpful.
	 */
	private static WikiPriceException httpFailure(final int code)
	{
		return new WikiPriceException("traded-price request failed with HTTP " + code, code);
	}

	/** {@code Throwable.getMessage()} is null for plenty of IO failures; fall back to the type name. */
	private static String messageOf(final Throwable t)
	{
		final String message = t.getMessage();
		return truncate(message == null || message.isEmpty() ? t.getClass().getSimpleName() : message);
	}

	private static String truncate(final String text)
	{
		if (text == null)
		{
			return null;
		}
		return text.length() <= MAX_DETAIL_CHARS ? text : text.substring(0, MAX_DETAIL_CHARS) + "...";
	}

	/** The one thing that differs between the two requests once the bytes are in hand. */
	@FunctionalInterface
	private interface BodyParser<T>
	{
		T parse(String body) throws WikiPriceException;
	}
}

package com.bankpricemovement;

