/**
 * The Net Worth History's chart (addendum AU, plan 7.2 item 10), drawn as the user chose it on 2026-09-29 - "plain
 * line, design 2": the "Mountain". The bank's total over the chart's range, one point per drawn day, in a
 * {@link #PLOT_HEIGHT} px plot that is the whole component.
 *
 * <p><b>The mountain.</b> A 1.5 px line in the colour of the range's direction (a rise green, a fall the lifted red, no
 * change grey) over a fill that fades from a tint of that colour at the line's highest point down to nothing at the
 * plot's bottom. The range's HIGH and LOW - chosen among the days WITH a reading, the first of equals - each carry a
 * small grey dot and their compact total ("759m") in small grey figures, the high's above its point and the low's
 * below; they are drawn only when the range has two readings or more and the two differ, since a single reading or a
 * flat range has no high or low to tell (the readout already gives the total). The latest READING carries a filled dot
 * inside a soft halo. No gridline, axis or baseline.
 *
 * <p><b>A plain line</b> (the user: "plain line"). A day with no reading is carried forward flat from the last reading
 * ({@link BankHistoryMath#days}) and takes its place on the time axis, and NOTHING marks it: the same stroke, colour
 * and fill as any other day, the step into the next reading an ordinary segment. A series of ONE reading draws that
 * one dot and halo and no line.
 *
 * <p><b>Hover</b>: one {@link MouseAdapter}, registered as the mouse and the mouse-motion listener, picks the drawn
 * point nearest the pointer by x - a carried day as readily as a reading - draws a thin dashed guide and a ring on it,
 * and tells the view (which prints the readout); leaving the chart hands the readout back to the latest reading. The
 * chart repaints only when the hovered index changes, and the points' coordinates and the figures' places are computed
 * when the data or the size changes - never per mouse move. It paints and hit-tests from its own {@link #getWidth()}
 * (amendment 9.8). No tooltip, ever (amendment 9.13).
 */
final class BankHistoryChart extends JComponent
{
	/** The plot's height, the whole component: 110 px (design 2; 84 before it, 42 as first built). */
	static final int PLOT_HEIGHT = 110;
	/** The first point's x: on the range bar's left edge. */
	static final int INSET_LEFT = 6;
	/**
	 * Room right of the last point: the latest point's {@link #DOT_RADIUS} px dot ends on the range bar's right edge and
	 * its {@link #HALO_RADIUS} px halo 3 px inside the chart block.
	 */
	static final int INSET_RIGHT = 9;
	/** Room above the highest point and below the lowest one, for the high's and the low's figures. */
	static final int INSET_Y = 14;
	/** The high's and the low's figures stay this far inside either side of the chart. */
	static final int FIGURE_MARGIN = 6;
	/** A figure's baseline (the high) or its ink's top (the low) stands at least this far from its point. */
	static final int FIGURE_CLEAR = 3;
	/** The air a figure keeps round the latest point's halo. */
	static final int HALO_AIR = 2;
	/**
	 * How far every pixel of a figure's ink keeps from the line's centre: the 1.5 px stroke's half and a little over a
	 * pixel of air.
	 */
	private static final double LINE_AIR = 0.75 + 1.2;
	/** No clear row inside the plot at a figure's left edge. */
	private static final int NOWHERE = Integer.MIN_VALUE;
	static final double HALO_RADIUS = 6;
	static final double DOT_RADIUS = 3;
	/** The fill's alpha at the line's highest point: 70 for a rise or no change, 80 for a fall (a red at 70 reads muddy). */
	static final int FILL_ALPHA = 70;
	static final int FILL_ALPHA_FALL = 80;
	static final int HALO_ALPHA = 50;
	/** The high's and the low's figures. */
	static final Font FIGURE_FONT = Widgets.sans(10);

	private static final BasicStroke LINE = new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final BasicStroke GUIDE = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f,
		new float[]{2f, 2f}, 0f);
	private static final BasicStroke RING = new BasicStroke(1.6f);
	private static final double MARK_RADIUS = 1.5;
	private static final double RING_RADIUS = 4.5;

	/** Told whenever the hovered point changes: its index, or -1 when the pointer left. */
	interface HoverListener
	{
		void hoverChanged(int index);
	}

	/** The high's or the low's figure as placed: the day it names, its text, its left edge and its baseline. */
	static final class Figure
	{
		/** The day's index among the drawn days. */
		final int index;
		final String text;
		final int left;
		final int baseline;

		Figure(final int index, final String text, final int left, final int baseline)
		{
			this.index = index;
			this.text = text;
			this.left = left;
			this.baseline = baseline;
		}
	}

	private final HoverListener listener;

	private List<BankHistoryMath.Day> days = Collections.emptyList();
	private boolean drawLine;
	private int sign;
	private Color line = ColorScheme.LIGHT_GRAY_COLOR;
	/** The latest reading among {@link #days}, or -1. */
	private int latest = -1;
	private int hover = -1;

	/** The points' coordinates and the figures' places, for the size they were computed at. */
	private double[] xs = new double[0];
	private double[] ys = new double[0];
	private List<Figure> figures = Collections.emptyList();
	private int laidWidth = -1;
	private int laidHeight = -1;

	BankHistoryChart(final HoverListener listener)
	{
		this.listener = Objects.requireNonNull(listener, "listener");
		setOpaque(false);
		setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, PLOT_HEIGHT));
		final MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(final MouseEvent e)
			{
				setHover(indexAt(e.getX()));
			}

			@Override
			public void mouseDragged(final MouseEvent e)
			{
				setHover(indexAt(e.getX()));
			}

			@Override
			public void mouseEntered(final MouseEvent e)
			{
				setHover(indexAt(e.getX()));
			}

			@Override
			public void mouseExited(final MouseEvent e)
			{
				setHover(-1);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	/**
	 * New points to draw. Clears the hover without telling the listener - the view that calls this prints its
	 * readout from the new data straight after.
	 *
	 * @param days     the drawn days, ascending, already thinned
	 * @param drawLine false for a series of one reading: the dot alone
	 * @param sign     the range's direction, which colours the line, its fill and the latest point: +1 a rise, -1 a
	 *                 fall, 0 no change
	 */
	void setData(final List<BankHistoryMath.Day> days, final boolean drawLine, final int sign)
	{
		this.days = days == null ? Collections.emptyList() : days;
		this.drawLine = drawLine;
		this.sign = Integer.signum(sign);
		line = Widgets.move(this.sign, Widgets.Kind.FIGURE);
		latest = -1;
		for (int i = this.days.size() - 1; i >= 0; i--)
		{
			if (!this.days.get(i).carried())
			{
				latest = i;
				break;
			}
		}
		hover = -1;
		laidWidth = -1;
		repaint();
	}

	List<BankHistoryMath.Day> days()
	{
		return days;
	}

	/** The point the readout names: the hovered one, else the latest reading, else the last day drawn; -1 if none. */
	int readoutIndex()
	{
		if (hover >= 0)
		{
			return hover;
		}
		return latest >= 0 ? latest : days.size() - 1;
	}

	/** The line's colour, which is every point's: a day with no reading is drawn like any other. */
	Color lineColour()
	{
		return line;
	}

	/** The x of point {@code i} of {@code n} across a chart {@code width} px wide: evenly spaced, one point centred. */
	static double xAt(final int i, final int n, final int width)
	{
		if (n <= 1)
		{
			return (INSET_LEFT + width - INSET_RIGHT) / 2.0;
		}
		return INSET_LEFT + i * (width - (double) INSET_LEFT - INSET_RIGHT) / (n - 1);
	}

	/** The drawn point nearest {@code x}, or -1 when nothing is drawn. */
	int indexAt(final int x)
	{
		final int n = days.size();
		if (n == 0)
		{
			return -1;
		}
		if (n == 1)
		{
			return 0;
		}
		final double step = (getWidth() - (double) INSET_LEFT - INSET_RIGHT) / (n - 1);
		if (step <= 0)
		{
			return n - 1;
		}
		final long i = Math.round((x - INSET_LEFT) / step);
		return (int) Math.max(0, Math.min(n - 1, i));
	}

	private void setHover(final int index)
	{
		if (index == hover)
		{
			return;
		}
		hover = index;
		repaint();
		listener.hoverChanged(index);
	}

	/**
	 * The high's and the low's figures as they are painted at the chart's present size: none with fewer than two
	 * readings among the drawn days, or when the high and the low are equal.
	 */
	List<Figure> figures()
	{
		layOut();
		return figures;
	}

	/** The coordinates and the figures for the current size, computed once per data or size change. */
	private void layOut()
	{
		final int w = getWidth();
		final int h = getHeight();
		if (w == laidWidth && h == laidHeight)
		{
			return;
		}
		laidWidth = w;
		laidHeight = h;
		final int n = days.size();
		xs = new double[n];
		ys = new double[n];
		long min = Long.MAX_VALUE;
		long max = Long.MIN_VALUE;
		for (BankHistoryMath.Day d : days)
		{
			min = Math.min(min, d.valueGp());
			max = Math.max(max, d.valueGp());
		}
		final double top = INSET_Y;
		final double plot = Math.max(1, h - 2 * INSET_Y);
		for (int i = 0; i < n; i++)
		{
			xs[i] = xAt(i, n, w);
			ys[i] = max == min ? top + plot / 2.0
				: top + (max - (double) days.get(i).valueGp()) * plot / ((double) max - (double) min);
		}
		figures = placeFigures(w, h);
	}

	/**
	 * The high and the low, chosen among the days with a reading (a carried day repeats a total, it never makes one),
	 * each placed by one rule: centred on its point's x and kept {@link #FIGURE_MARGIN} px inside either side; the
	 * high's baseline {@link #FIGURE_CLEAR} px above its point, the low's ink top as far below it; and a figure that
	 * would come within {@link #HALO_AIR} px of the latest point's halo, or within {@link #LINE_AIR} px of the line's
	 * centre, steps one pixel further from its point (the high up, the low down) until it is clear of both. When that
	 * would take it out of the plot - a high or a low that IS the latest point, at the plot's edge, or one the line
	 * comes down (or up) into from days carried from an older reading beyond every reading in the range - it slides
	 * sideways instead, to the nearest place (the left side first at equal distance) where the same steps find it a
	 * clear row inside the plot.
	 */
	private List<Figure> placeFigures(final int w, final int h)
	{
		int hi = -1;
		int lo = -1;
		int readings = 0;
		for (int i = 0; i < days.size(); i++)
		{
			final BankHistoryMath.Day d = days.get(i);
			if (d.carried())
			{
				continue;
			}
			readings++;
			if (hi < 0 || d.valueGp() > days.get(hi).valueGp())
			{
				hi = i;
			}
			if (lo < 0 || d.valueGp() < days.get(lo).valueGp())
			{
				lo = i;
			}
		}
		if (readings < 2 || days.get(hi).valueGp() == days.get(lo).valueGp())
		{
			return Collections.emptyList();
		}
		final FontMetrics fm = getFontMetrics(FIGURE_FONT);
		final List<Figure> out = new ArrayList<>(2);
		out.add(place(hi, true, fm, w, h));
		out.add(place(lo, false, fm, w, h));
		return out;
	}

	private Figure place(final int i, final boolean high, final FontMetrics fm, final int w, final int h)
	{
		final String text = MovementMath.formatGp(days.get(i).valueGp());
		final int width = fm.stringWidth(text);
		// The ink's height above the baseline, as the face draws this text (the figures have no descenders).
		final int cap = -FIGURE_FONT.createGlyphVector(fm.getFontRenderContext(), text).getPixelBounds(null, 0, 0).y;
		final int maxLeft = Math.max(FIGURE_MARGIN, w - FIGURE_MARGIN - width);
		final int centred = (int) Math.max(FIGURE_MARGIN, Math.min(maxLeft, Math.round(xs[i] - width / 2.0)));
		int baseline = settle(i, high, centred, width, cap, h);
		if (baseline != NOWHERE)
		{
			return new Figure(i, text, centred, baseline);
		}
		for (int d = 1; centred - d >= FIGURE_MARGIN || centred + d <= maxLeft; d++)
		{
			for (int side = -1; side <= 1; side += 2)
			{
				final int left = centred + side * d;
				if (left < FIGURE_MARGIN || left > maxLeft)
				{
					continue;
				}
				baseline = settle(i, high, left, width, cap, h);
				if (baseline != NOWHERE)
				{
					return new Figure(i, text, left, baseline);
				}
			}
		}
		// Nowhere clear in the whole plot (it cannot happen at the sidebar's sizes): the first row, centred.
		return new Figure(i, text, centred, high ? (int) Math.round(ys[i] - FIGURE_CLEAR)
			: (int) Math.round(ys[i] + FIGURE_CLEAR) + cap);
	}

	/**
	 * The baseline of the first row, stepping away from point {@code i} (the high up, the low down) from
	 * {@link #FIGURE_CLEAR} px, at which the figure's ink {@code [left, left + width) x [baseline - cap, baseline)} stays
	 * inside the plot and clear of the latest point's halo and of the line; {@link #NOWHERE} when it leaves the plot first.
	 */
	private int settle(final int i, final boolean high, final int left, final int width, final int cap, final int h)
	{
		for (int clear = FIGURE_CLEAR; ; clear++)
		{
			final int b = high ? (int) Math.round(ys[i] - clear) : (int) Math.round(ys[i] + clear) + cap;
			if (b - cap < 0 || b > h)
			{
				return NOWHERE;
			}
			if ((latest < 0 || clearOfHalo(left, width, b - cap, b)) && clearOfLine(left, width, b - cap, b))
			{
				return b;
			}
		}
	}

	/** Whether the box {@code [left, left + width) x [top, bottom)} keeps {@link #HALO_AIR} px from the halo's box. */
	private boolean clearOfHalo(final int left, final int width, final int top, final int bottom)
	{
		final double reach = HALO_RADIUS + HALO_AIR;
		return left + width <= xs[latest] - reach || left >= xs[latest] + reach
			|| bottom <= ys[latest] - reach || top >= ys[latest] + reach;
	}

	/**
	 * Whether every pixel of the box {@code [left, left + width) x [top, bottom)} - the rectangle through its pixels'
	 * centres - keeps {@link #LINE_AIR} px from every segment of the line.
	 */
	private boolean clearOfLine(final int left, final int width, final int top, final int bottom)
	{
		final double x0 = left + 0.5;
		final double x1 = left + width - 0.5;
		final double y0 = top + 0.5;
		final double y1 = bottom - 0.5;
		for (int s = 0; s + 1 < xs.length; s++)
		{
			if (xs[s + 1] < x0 - LINE_AIR || xs[s] > x1 + LINE_AIR)
			{
				continue;
			}
			if (segmentToBox(xs[s], ys[s], xs[s + 1], ys[s + 1], x0, y0, x1, y1) < LINE_AIR)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * The distance from segment {@code (ax, ay) - (bx, by)} to the rectangle {@code [x0, x1] x [y0, y1]}: 0 when they
	 * meet, else the nearest of the segment's ends to the rectangle and of the rectangle's corners to the segment (two
	 * convex shapes apart are nearest at a corner of one of them).
	 */
	private static double segmentToBox(final double ax, final double ay, final double bx, final double by,
		final double x0, final double y0, final double x1, final double y1)
	{
		if (inside(ax, ay, x0, y0, x1, y1) || inside(bx, by, x0, y0, x1, y1)
			|| Line2D.linesIntersect(ax, ay, bx, by, x0, y0, x1, y0) || Line2D.linesIntersect(ax, ay, bx, by, x1, y0, x1, y1)
			|| Line2D.linesIntersect(ax, ay, bx, by, x1, y1, x0, y1) || Line2D.linesIntersect(ax, ay, bx, by, x0, y1, x0, y0))
		{
			return 0;
		}
		double d = Math.min(pointToBox(ax, ay, x0, y0, x1, y1), pointToBox(bx, by, x0, y0, x1, y1));
		d = Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x0, y0));
		d = Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x1, y0));
		d = Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x0, y1));
		return Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x1, y1));
	}

	private static boolean inside(final double x, final double y, final double x0, final double y0, final double x1,
		final double y1)
	{
		return x >= x0 && x <= x1 && y >= y0 && y <= y1;
	}

	private static double pointToBox(final double x, final double y, final double x0, final double y0, final double x1,
		final double y1)
	{
		final double dx = Math.max(0, Math.max(x0 - x, x - x1));
		final double dy = Math.max(0, Math.max(y0 - y, y - y1));
		return Math.hypot(dx, dy);
	}

	@Override
	protected void paintComponent(final Graphics g)
	{
		final int n = days.size();
		if (n == 0)
		{
			return;
		}
		final List<Figure> marks = figures();
		final Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			final int h = getHeight();
			final boolean line = drawLine && n > 1;
			if (line)
			{
				paintFill(g2, h);
			}
			if (hover >= 0 && hover < n)
			{
				g2.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				g2.setStroke(GUIDE);
				g2.draw(new Line2D.Double(xs[hover], 0, xs[hover], h));
			}
			if (line)
			{
				final Path2D.Double path = new Path2D.Double();
				path.moveTo(xs[0], ys[0]);
				for (int i = 1; i < n; i++)
				{
					path.lineTo(xs[i], ys[i]);
				}
				g2.setColor(this.line);
				g2.setStroke(LINE);
				g2.draw(path);
			}
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			for (Figure f : marks)
			{
				if (f.index != latest)
				{
					g2.fill(circle(xs[f.index], ys[f.index], MARK_RADIUS));
				}
			}
			if (latest >= 0)
			{
				g2.setColor(withAlpha(this.line, HALO_ALPHA));
				g2.fill(circle(xs[latest], ys[latest], HALO_RADIUS));
				g2.setColor(this.line);
				g2.fill(circle(xs[latest], ys[latest], DOT_RADIUS));
			}
			if (!marks.isEmpty())
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setFont(FIGURE_FONT);
				g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				for (Figure f : marks)
				{
					g2.drawString(f.text, f.left, f.baseline);
				}
			}
			if (hover >= 0 && hover < n)
			{
				final Ellipse2D ring = circle(xs[hover], ys[hover], RING_RADIUS);
				g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
				g2.fill(ring);
				g2.setColor(this.line);
				g2.setStroke(RING);
				g2.draw(ring);
			}
		}
		finally
		{
			g2.dispose();
		}
	}

	/** The area under the line down to the plot's bottom, its tint fading from the line's highest point to nothing. */
	private void paintFill(final Graphics2D g2, final int h)
	{
		final int n = days.size();
		final Path2D.Double area = new Path2D.Double();
		area.moveTo(xs[0], ys[0]);
		double top = ys[0];
		for (int i = 1; i < n; i++)
		{
			area.lineTo(xs[i], ys[i]);
			top = Math.min(top, ys[i]);
		}
		area.lineTo(xs[n - 1], h);
		area.lineTo(xs[0], h);
		area.closePath();
		final int alpha = sign < 0 ? FILL_ALPHA_FALL : FILL_ALPHA;
		g2.setPaint(new GradientPaint(0f, (float) top, withAlpha(line, alpha), 0f, (float) h, withAlpha(line, 0)));
		g2.fill(area);
	}

	private static Color withAlpha(final Color c, final int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	private static Ellipse2D circle(final double x, final double y, final double r)
	{
		return new Ellipse2D.Double(x - r, y - r, 2 * r, 2 * r);
	}

	/** The day of the hovered point, or null. */
	@Nullable
	BankHistoryMath.Day hoverDay()
	{
		return hover >= 0 && hover < days.size() ? days.get(hover) : null;
	}
}

package com.bankpricemovement;

import java.util.LinkedHashMap;
import java.util.Objects;

/**
 * The five view switches, carried as one immutable value the way {@link HeroVisibility} carries the card's three
 * figures: the two addendum Q still has - whether coins and platinum tokens count in the bank value
 * ({@code countCash}, config item {@code countCash}, default on) and whether untradeable stacks are listed and
 * counted at their High Alchemy value when they have no tradeable parts ({@code countUntradeables}, default off;
 * narrowed by addendum AV) - addendum T's, whether an actively
 * traded item is priced from the wiki's live traded series ({@code livePrices}, default ON) - addendum Y's,
 * whether the stacks the player is CARRYING and WEARING are counted and listed beside the bank's
 * ({@code countInventory}, default ON) - and addendum AH's, whether the sidebar's DATA hovers are shown at all
 * ({@code showHoverText}, default OFF). The gear menu on the hero card, RuneLite's settings page and the dev verb
 * {@code opt=} all read and write the same five switches through the plugin's config.
 *
 * <p><b>Addendum AO line AO1 took the sixth away</b>: {@code holdingOnRows}, addendum Q's third, which chose
 * whether a row printed the per-ITEM reading or the per-STACK one. Addendum AN's three-line row prints BOTH - line
 * 2 is the stack, line 3 is one item - so the switch no longer reached anything drawn, and the user, asked whether
 * to keep it, answered "if it doesnt do anything anymore then remove it". The one thing it still did was pick
 * {@link SortMode#GP_MOVE}'s comparison key, which is the STACK's gp move permanently now.
 */
public final class ViewOptions
{
	/**
	 * Every switch at its default: cash counted, untradeables left out, live prices on, the inventory and worn
	 * gear counted, and the data hovers OFF (addendum AH - the one switch here whose default is the quieter
	 * sidebar rather than the fuller one).
	 */
	public static final ViewOptions DEFAULT = new ViewOptions(true, false, true, true, false);

	private final boolean countCash;
	private final boolean countUntradeables;
	private final boolean livePrices;
	private final boolean countInventory;
	private final boolean showHoverText;

	/**
	 * The one constructor, and since addendum AO the ONLY one: this class carried a ladder of shorter overloads
	 * that defaulted the switches added after them, and every rung of it became a trap the moment a field was
	 * removed from the MIDDLE of the list. Five booleans that used to mean
	 * {@code (cash, untradeables, holding, live, inventory)} would still compile against a five-argument
	 * {@code (cash, untradeables, live, inventory, hover)} and mean three different things, with no error anywhere
	 * to say so. Deleting the ladder makes the compiler name every call site instead.
	 */
	public ViewOptions(final boolean countCash, final boolean countUntradeables, final boolean livePrices,
		final boolean countInventory, final boolean showHoverText)
	{
		this.countCash = countCash;
		this.countUntradeables = countUntradeables;
		this.livePrices = livePrices;
		this.countInventory = countInventory;
		this.showHoverText = showHoverText;
	}

	/** Coins and platinum tokens (1,000 gp each) count in the bank value and in the percentage's basis. */
	public boolean countCash()
	{
		return countCash;
	}

	/** Untradeable stacks are listed and counted at their High Alchemy value, with no movement figures. */
	public boolean countUntradeables()
	{
		return countUntradeables;
	}

	/**
	 * Actively traded items use the wiki's live traded prices for every figure (addendum T); thin items keep the daily
	 * guide price. Off means exactly the guide-only behaviour of addenda K to S.
	 */
	public boolean livePrices()
	{
		return livePrices;
	}

	/**
	 * The stacks in the player's INVENTORY and on their WORN gear count in the bank value and are listed beside the
	 * bank's, one row per item with the quantities added (addendum Y, lines Y1 to Y3). Off means exactly the
	 * bank-only behaviour of addenda K to W, figure for figure.
	 *
	 * <p>Both containers are read at the two moments the bank itself is read - a bank container event and Refresh -
	 * so what the sidebar shows is what the player was carrying then (Y2).
	 */
	public boolean countInventory()
	{
		return countInventory;
	}

	/**
	 * Whether the sidebar shows hover text at all (addendum AH, reach narrowed by AI and AJ). Default OFF, and
	 * the only switch here whose default is the quieter sidebar: every figure is already drawn, so a hover that
	 * opens whenever the pointer crosses one is something a reader asks for rather than something they dismiss.
	 *
	 * <p><b>What it reaches.</b> The bank value's hover on the hero card, and every CONTROL's - the sort button
	 * and its menu, the chips, the band button, Refresh, the update line, the gear's own items, the buttons,
	 * and the four labels {@code Widgets.setFitted} gives a full-text hover to when it has to cut them. AH1
	 * spared the controls and AH3 overruled that on the user's word: "make sure there is no hover text at all
	 * unless it is on".
	 *
	 * <p><b>What it does not reach: the item ROWS.</b> Since addendum AI a row carries no tooltip at any
	 * setting - its description is the block the cell opens when it is clicked - so there is nothing there for
	 * this switch to silence, and wiring it into a row would be a regression rather than a feature.
	 */
	public boolean showHoverText()
	{
		return showHoverText;
	}

	public ViewOptions withCountCash(final boolean value)
	{
		return new ViewOptions(value, countUntradeables, livePrices, countInventory, showHoverText);
	}

	public ViewOptions withCountUntradeables(final boolean value)
	{
		return new ViewOptions(countCash, value, livePrices, countInventory, showHoverText);
	}

	public ViewOptions withLivePrices(final boolean value)
	{
		return new ViewOptions(countCash, countUntradeables, value, countInventory, showHoverText);
	}

	public ViewOptions withCountInventory(final boolean value)
	{
		return new ViewOptions(countCash, countUntradeables, livePrices, value, showHoverText);
	}

	public ViewOptions withShowHoverText(final boolean value)
	{
		return new ViewOptions(countCash, countUntradeables, livePrices, countInventory, value);
	}

	/**
	 * The switches in the order the dev bridge prints them: {@code cash}, {@code untradeables}, {@code live},
	 * {@code inventory}, {@code hover}. Addendum AO line AO1 removed {@code holding} from between the second and
	 * the third with the switch it echoed.
	 */
	public LinkedHashMap<String, Boolean> asMap()
	{
		final LinkedHashMap<String, Boolean> map = new LinkedHashMap<>();
		map.put("cash", countCash);
		map.put("untradeables", countUntradeables);
		map.put("live", livePrices);
		map.put("inventory", countInventory);
		map.put("hover", showHoverText);
		return map;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof ViewOptions))
		{
			return false;
		}
		final ViewOptions other = (ViewOptions) o;
		return countCash == other.countCash
			&& countUntradeables == other.countUntradeables
			&& livePrices == other.livePrices
			&& countInventory == other.countInventory
			&& showHoverText == other.showHoverText;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(countCash, countUntradeables, livePrices, countInventory, showHoverText);
	}

	@Override
	public String toString()
	{
		return "ViewOptions{cash=" + countCash + ", untradeables=" + countUntradeables + ", live=" + livePrices
			+ ", inventory=" + countInventory + ", hover=" + showHoverText + '}';
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Locale;

/**
 * How far back a bank row's movement is measured, in the five spans the Grand Exchange item pages themselves
 * show - "today", 1 month, 3 months, 6 months - rewritten to 1d / 7d / 30d / 90d / 180d (contract K4, restated
 * in CALENDAR DAYS by addendum L, line L9; {@code docs/bank-price-movement-addendum-L-2026-09-08.md}).
 *
 * <p><b>Why these five and not the old 1h / 24h / 7d.</b> Movement is not the wiki's real-time TRADE series; it
 * is the Jagex GUIDE price, the number the in-game GE, the GE web site and RuneLite itself all show. That is a
 * step function that moves ONCE A DAY, at a variable UTC hour (L-A: the rollover was observed between 00:47 and
 * 02:06 UTC), so an hourly window would measure nothing at all: both ends would land on the same step and every
 * row would read 0 %. A day is the shortest window the series can express, and the longer four are the ones the
 * GE site itself offers.
 *
 * <p><b>Why a window is DAYS and not seconds now</b> (L9, evidence L-C). Addendum K asked for "the revision at
 * or before now minus 86,400 seconds". Six analysts measured that against live data: the wiki's price bot writes
 * day D's table at a random hour of day D (02:11-22:20 UTC, median about 12:00), so subtracting a fixed span
 * from the wall clock lands on the intended Jagex day only 50-56 % of clock hours, changing the printed percent
 * on 40-60 % of the user's rows and flipping its sign on 3-5 %. The GE site's own arithmetic is
 * {@code (daily[D] - daily[D-N]) / daily[D-N]} over CALENDAR days (L-B), so a window is now a count of days
 * subtracted from an anchor DATE that is derived from the data (L3), and {@code seconds()} and
 * {@code targetFor(long)} are gone with the clock arithmetic that produced the coin flip.
 *
 * <p>{@link #toString()} is the LABEL, not the enum name, because RuneLite's config panel renders an enum combo
 * box with {@code toString()} while {@code ConfigManager} stores and reads the constant by {@code name()}
 * ({@code ConfigManager.java:1279-1281} writes {@code ((Enum) object).name()}, {@code :1205-1207} reads it back
 * with {@code Enum.valueOf}). Overriding the display text therefore cannot corrupt a saved setting.
 */
public enum MovementWindow
{
	D1("1d", 1),
	D7("7d", 7),
	D30("30d", 30),
	D90("90d", 90),
	D180("180d", 180);

	/**
	 * The window a fresh profile gets, and the one every legacy stored value collapses onto: it is the GE site's
	 * headline "today" figure and the only span the daily guide table can resolve sharply (K4).
	 */
	public static final MovementWindow DEFAULT = D1;

	private final String label;
	private final int days;

	MovementWindow(final String label, final int days)
	{
		this.label = label;
		this.days = days;
	}

	/**
	 * The chip text the sidebar draws ("1d", "7d", "30d", "90d", "180d").
	 */
	public String label()
	{
		return label;
	}

	/**
	 * How many calendar days back the baseline sits (L9). The GE site's 30d / 90d / 180d figures are exactly
	 * {@code daily[D] - daily[D-N]} for these N, so a "30d" here is 30 dates back, never 2,592,000 seconds back.
	 */
	public int days()
	{
		return days;
	}

	/**
	 * The UTC calendar date whose guide table is this window's "then" side: {@code anchorDay.minusDays(days)}
	 * (L5, L9).
	 *
	 * <p>The anchor is DERIVED from the data, never read off the wall clock (L3): RuneLite's price table can
	 * already hold the next Jagex day while the wiki's newest revision still holds the previous one, for roughly
	 * half of every day (L-D). {@code PriceService} settles which day D is by comparing RuneLite's prices against
	 * the newest table and hands the answer here.
	 *
	 * <p>{@link LocalDate#minusDays} is calendar arithmetic, so a window that spans a leap day or the end of a
	 * month lands on the date a reader would count to - which subtracting {@code days * 86400} seconds does not
	 * guarantee once a caller starts from an instant rather than a date.
	 *
	 * @param anchorDay the derived anchor day D; null (no anchor settled yet) answers null, so a caller with no
	 *                  anchor gets no target, picks no baseline and shows "-" rather than guessing a date
	 * @return the target date, or null when {@code anchorDay} is null
	 */
	public LocalDate targetDate(final LocalDate anchorDay)
	{
		return anchorDay == null ? null : anchorDay.minusDays(days);
	}

	/**
	 * Reads a window out of user text, a dev-bridge verb or a stored config value: the label ("1d", "30d"), the
	 * constant name ("D1", "D30"), or one of the pre-addendum-K spellings, trimmed and case-insensitive.
	 *
	 * <p>The legacy spellings matter because a user who ran the first build has {@code window=H24} written into
	 * their RuneLite profile ({@code ConfigManager} stores an enum by {@code name()}), and {@code H1} / {@code H24}
	 * / {@code 1h} / {@code 24h} no longer name anything. They all collapse onto {@link #D1}: an hour is below
	 * the resolution of the guide series, and 24 h IS the new 1d. Without this, the stored value would fail
	 * {@code Enum.valueOf} and the config panel would NPE on the way in (the flat-config trap this workspace
	 * already hit - CLAUDE.md "Config interfaces must be FLAT"); K9 also unsets an unparseable value at startUp,
	 * so the two guards overlap on purpose.
	 *
	 * @param text anything, including null
	 * @return the window, or null when the text names none (the caller keeps its current window)
	 */
	public static MovementWindow parse(final String text)
	{
		if (text == null)
		{
			return null;
		}

		final String key = text.trim().toLowerCase(Locale.ENGLISH);
		if (key.isEmpty())
		{
			return null;
		}

		for (final MovementWindow window : values())
		{
			if (key.equals(window.label) || key.equals(window.name().toLowerCase(Locale.ENGLISH)))
			{
				return window;
			}
		}

		// Pre-addendum-K windows, in both the spelling the chips used and the spelling ConfigManager stored.
		if (key.equals("1h") || key.equals("h1") || key.equals("24h") || key.equals("h24"))
		{
			return D1;
		}

		return null;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

