	/**
	 * Draws the series under these switches. EDT only. A null series reads as {@link BankHistorySeries#EMPTY} and
	 * null options as {@link ViewOptions#DEFAULT} (amendment 9.2); the series is cut to {@code upTo(today)} first,
	 * today being the clock's LOCAL date, read now. A no-op when the cut series, the four switches that change a
	 * total ({@code countCash}, {@code countUntradeables}, {@code countInventory}, {@code livePrices} - not
	 * {@code showHoverText}) and today all equal what is drawn (amendment 9.10).
	 */
	public void show(@Nullable final BankHistorySeries series, @Nullable final ViewOptions options)
	{
		final BankHistorySeries all = series == null ? BankHistorySeries.EMPTY : series;
		final ViewOptions o = options == null ? ViewOptions.DEFAULT : options;
		final LocalDate today = BankHistoryMath.dayOf(clockMillis.getAsLong(), zone);
		final BankHistorySeries cut = all.upTo(today);
		if (today.equals(drawnToday) && cut.equals(shown) && sameTotals(o, drawnOptions))
		{
			return;
		}
		final BankHistoryPoint wasFirst = shown.first();
		final BankHistoryPoint nowFirst = cut.first();
		if (drawnToday == null || wasFirst == null || nowFirst == null || !wasFirst.day().equals(nowFirst.day()))
		{
			// Another bank's history, or the first one: back to one page.
			pageLimit = BankPriceMovementPanel.ROWS_PER_PAGE;
		}
		drawnToday = today;
		shown = cut;
		drawnOptions = o;
		arrange();
		renderChart();
		renderList();
		revalidate();
		repaint();
	}

	/** Whether two option sets give every total the same figure: the four switches {@code valueFor} reads. */
	private static boolean sameTotals(final ViewOptions a, final ViewOptions b)
	{
		return a.countCash() == b.countCash() && a.countUntradeables() == b.countUntradeables()
			&& a.countInventory() == b.countInventory() && a.livePrices() == b.livePrices();
	}

	/**
	 * The chart's range, as the card's chip sets it ({@code BankHistoryRange.forWindow(window)}). Redraws the chart
	 * only; a no-op for the range already drawn, and safe before any {@link #show}. Null is ignored.
	 */
	public void setRange(@Nullable final BankHistoryRange next)
	{
		if (next == null || next == range)
		{
			return;
		}
		range = next;
		renderChips();
		if (drawnToday != null)
		{
			renderChart();
			block.revalidate();
			block.repaint();
		}
	}

	/** One of the view's own chips: moves the chart, and nothing else - unsaved, never sent anywhere. */
	private void pickRange(final BankHistoryRange r)
	{
		setRange(r);
	}

	/**
	 * The day list's pager: builds the next {@link BankPriceMovementPanel#ROWS_PER_PAGE} rows. False when there was
	 * nothing more to show.
	 */
	public boolean showMore()
	{
		if (drawnToday == null || rows.size() >= listDays.size())
		{
			return false;
		}
		pageLimit = rows.size() + BankPriceMovementPanel.ROWS_PER_PAGE;
		renderList();
		revalidate();
		repaint();
		return true;
	}

	/**
	 * The dev bridge's view of the History card (amendment 9.11), exactly these seven keys and only String,
	 * Integer and null values: {@code readings} (the last show's {@code upTo(today).size()}), {@code first} and
	 * {@code last} (ISO {@code yyyy-MM-dd}, or null), {@code range} ({@link BankHistoryRange#label()}),
	 * {@code rows} and {@code carriedRows} (day rows built so far, carried ones among them) and {@code hoverDay}
	 * (the hovered point's day, ISO, or null).
	 */
	public LinkedHashMap<String, Object> describe()
	{
		final LinkedHashMap<String, Object> map = new LinkedHashMap<>();
		final BankHistoryPoint first = shown.first();
		final BankHistoryPoint last = shown.last();
		int carried = 0;
		for (BankHistoryDayRow row : rows)
		{
			if (row.model().carried())
			{
				carried++;
			}
		}
		final BankHistoryMath.Day hovered = chart.hoverDay();
		map.put("readings", shown.size());
		map.put("first", first == null ? null : first.day().toString());
		map.put("last", last == null ? null : last.day().toString());
		map.put("range", range.label());
		map.put("rows", rows.size());
		map.put("carriedRows", carried);
		map.put("hoverDay", hovered == null ? null : hovered.day().toString());
		return map;
	}

	// ------------------------------------------------------------------------------------------ drawing

	/** The chart block and the list - or, with no reading at all, the one sentence and nothing else. */
	private void arrange()
	{
		final List<Component> want = new ArrayList<>(2);
		if (shown.isEmpty())
		{
			want.add(empty);
		}
		else
		{
			want.add(block);
			want.add(list);
		}
		boolean same = getComponentCount() == want.size();
		for (int i = 0; same && i < want.size(); i++)
		{
			same = getComponent(i) == want.get(i);
		}
		if (!same)
		{
			removeAll();
			for (Component c : want)
			{
				add(c);
			}
		}
	}

	/** The range bar: the lit cell orange, a range with nothing older than its start dimmed. */
	private void renderChips()
	{
		final Set<BankHistoryRange> dim = EnumSet.noneOf(BankHistoryRange.class);
		for (BankHistoryRange r : BankHistoryRange.values())
		{
			if (r != range && reachesPastFirstReading(r))
			{
				dim.add(r);
			}
		}
		bar.light(range, dim);
	}

	/** Whether a range starts before the first reading: nothing on or before its start to compare with. */
	private boolean reachesPastFirstReading(final BankHistoryRange r)
	{
		return drawnToday != null && r.days() > 0 && shown.atOrBefore(drawnToday.minusDays(r.days())) == null;
	}

	/** Re-feeds the range bar, the change line, the chart and the readout from what is drawn. */
	private void renderChart()
	{
		renderChips();
		if (drawnToday == null || shown.isEmpty())
		{
			chart.setData(Collections.emptyList(), false, 0);
			renderReadout();
			return;
		}
		final LocalDate today = drawnToday;
		final LocalDate from = range.days() <= 0 ? null : today.minusDays(range.days());
		final List<BankHistoryMath.Day> days = BankHistoryMath.thin(
			BankHistoryMath.days(shown, from, today, drawnOptions), MAX_POINTS);

		// A range reaching back past the first reading has no reading at its start: the change is then the one the
		// chart can show, since the first reading - its left date says so. ONLY then: a range that has a reading at
		// its start but none inside it (its last reading is the one at its start) moved nothing that was measured,
		// and prints the dash like a series of one reading, over a chart that is flat and carried.
		BankHistoryMath.Change change = BankHistoryMath.overDays(shown, today, range.days(), drawnOptions);
		if (change == null && reachesPastFirstReading(range))
		{
			change = BankHistoryMath.overDays(shown, today, 0, drawnOptions);
		}
		final int sign = change == null ? 0 : Long.signum(change.deltaGp());
		if (change == null)
		{
			final BankHistoryPoint last = shown.last();
			changeDays.setText(last == null ? "" : MovementMath.formatDay(last.day()));
			changeGp.setText("");
			changePct.setText(MovementMath.DASH);
		}
		else
		{
			changeDays.setText(MovementMath.formatDay(change.fromDay()) + " - " + MovementMath.formatDay(change.toDay()));
			changeGp.setText(change.deltaGp() == 0L ? "" : MovementRowPanel.signedGp(change.deltaGp()));
			changePct.setText(MovementMath.formatPctCompact(change.pct(), change.deltaGp()));
		}
		changeGp.setForeground(Widgets.move(sign, Widgets.Kind.QUIET));
		changePct.setForeground(Widgets.move(sign, Widgets.Kind.FIGURE));

		chart.setData(days, shown.size() > 1, sign);
		renderReadout();
	}

	/** The readout line: the hovered point, or with no hover the latest reading - its ring, its day, its total. */
	private void renderReadout()
	{
		final List<BankHistoryMath.Day> days = chart.days();
		final int i = chart.readoutIndex();
		if (i < 0 || i >= days.size())
		{
			readoutDay.setText("");
			readoutTotal.setText("");
			ring.colour = null;
			readoutDay.repaint();
			return;
		}
		final BankHistoryMath.Day day = days.get(i);
		ring.colour = chart.lineColour();
		readoutDay.setText(BankHistoryDayRow.dayText(day.day(), drawnToday));
		readoutTotal.setText(MovementMath.formatExact(day.valueGp()) + " gp");
		readoutDay.repaint();
		block.doLayout();
	}

	/**
	 * The list of days, keeping every row whose strings did not change: a new total for today rebuilds today's row
	 * alone, and a flipped switch every row it changes.
	 */
	private void renderList()
	{
		if (drawnToday == null || shown.isEmpty())
		{
			listDays = Collections.emptyList();
		}
		else
		{
			final List<BankHistoryMath.Day> ascending = BankHistoryMath.days(shown, null, drawnToday, drawnOptions);
			final List<BankHistoryMath.Day> newest = new ArrayList<>(ascending);
			Collections.reverse(newest);
			listDays = newest;
		}
		final int want = Math.min(listDays.size(), Math.max(pageLimit, BankPriceMovementPanel.ROWS_PER_PAGE));
		final Map<LocalDate, BankHistoryDayRow> old = new HashMap<>();
		for (BankHistoryDayRow row : rows)
		{
			old.put(row.model().day(), row);
		}
		final List<BankHistoryDayRow> next = new ArrayList<>(want);
		for (int i = 0; i < want; i++)
		{
			final BankHistoryDayRow.Model model = BankHistoryDayRow.model(shown, listDays.get(i), drawnToday, drawnOptions);
			final BankHistoryDayRow kept = old.get(model.day());
			next.add(kept != null && kept.model().equals(model) ? kept : new BankHistoryDayRow(model));
		}

		// The list's children: the header, the rows, and the pager row when more are left.
		final boolean more = want < listDays.size();
		if (more)
		{
			showMoreLabel.setText(BankPriceMovementPanel.showMoreText(listDays.size() - want));
		}
		final int expected = 1 + next.size() + (more ? 1 : 0);
		boolean inPlace = list.getComponentCount() == expected && rows.size() == next.size()
			&& list.getComponent(0) == listHeader && (list.getComponent(expected - 1) == showMoreRow) == more;
		if (inPlace)
		{
			// A swap in place is right only while no KEPT row changes its place: a kept row moved (a new day at a
			// full page shifts every row by one, a clock set back shifts them the other way) is re-added in order.
			final Set<BankHistoryDayRow> before = Collections.newSetFromMap(new IdentityHashMap<>());
			before.addAll(rows);
			for (int i = 0; inPlace && i < next.size(); i++)
			{
				inPlace = rows.get(i) == next.get(i) || !before.contains(next.get(i));
			}
		}
		if (inPlace)
		{
			// Same shape, every kept row where it was: swap only the rows that changed.
			for (int i = 0; i < next.size(); i++)
			{
				if (rows.get(i) != next.get(i))
				{
					list.remove(1 + i);
					list.add(next.get(i), 1 + i);
				}
			}
		}
		else
		{
			list.removeAll();
			list.add(listHeader);
			for (BankHistoryDayRow row : next)
			{
				list.add(row);
			}
			if (more)
			{
				list.add(showMoreRow);
			}
		}
		rows.clear();
		rows.addAll(next);
		list.revalidate();
	}

	// ------------------------------------------------------------------------------------------ parts

	/**
	 * The chart block's card, top to bottom: change line, rule, readout line, chart, range bar - laid out from its own
	 * width, so it is right at 213 px and at 230. Block-local: the change line's baseline at y 17, the rule at 23, the
	 * readout's baseline at 39, the chart over 45..154 and the block's whole width, the bar over 159..176 with 6 px of
	 * card either side, and 6 px of card under it - 183 px in all.
	 */
	private final class ChartBlock extends JPanel
	{
		static final int PAD_X = 12;
		/** Baselines of the change line and the readout line, from the block's top. */
		static final int CHANGE_BASELINE = 17;
		static final int RULE_Y = 23;
		static final int READOUT_BASELINE = 39;
		/** The chart's top, 6 px under the readout's baseline. */
		static final int CHART_TOP = 45;
		/** The range bar's top, 4 px under the chart. */
		static final int BAR_TOP = CHART_TOP + BankHistoryChart.PLOT_HEIGHT + 4;
		static final int HEIGHT = BAR_TOP + RangeBar.HEIGHT + RangeBar.SIDE;
		/** Between the change line's gp figure and its percentage. */
		static final int FIGURE_GAP = 8;
		static final int GAP = 4;
		static final int RING_GAP = 5;

		ChartBlock()
		{
			super(null);
			setOpaque(true);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			add(changeDays);
			add(changeGp);
			add(changePct);
			add(readoutDay);
			add(readoutTotal);
			add(chart);
			add(bar);
			setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, HEIGHT));
		}

		@Override
		public void doLayout()
		{
			final int left = PAD_X;
			final int right = getWidth() - PAD_X;

			final int pctW = pref(changePct);
			final int pctX = right - pctW;
			put(changePct, pctX, pctW, CHANGE_BASELINE);
			final int gpW = pref(changeGp);
			final int gpX = pctX - (gpW == 0 ? 0 : FIGURE_GAP) - gpW;
			put(changeGp, gpX, gpW, CHANGE_BASELINE);
			put(changeDays, left, Math.min(pref(changeDays), gpX - GAP - left), CHANGE_BASELINE);

			final int totalW = pref(readoutTotal);
			final int totalX = right - totalW;
			put(readoutTotal, totalX, totalW, READOUT_BASELINE);
			put(readoutDay, left, Math.min(pref(readoutDay), totalX - GAP - left), READOUT_BASELINE);

			chart.setBounds(0, CHART_TOP, getWidth(), BankHistoryChart.PLOT_HEIGHT);
			bar.setBounds(RangeBar.SIDE, BAR_TOP, getWidth() - 2 * RangeBar.SIDE, RangeBar.HEIGHT);
		}

		private int pref(final JLabel label)
		{
			return label.getPreferredSize().width;
		}

		/** A label at {@code x}, {@code width} wide, its text standing on {@code baseline}. */
		private void put(final JLabel label, final int x, final int width, final int baseline)
		{
			final FontMetrics fm = label.getFontMetrics(label.getFont());
			final int h = label.getPreferredSize().height;
			// With an icon the label centres its text in its height: the baseline is where the text's box puts it.
			final int top = baseline - fm.getAscent() - (h - fm.getHeight()) / 2;
			label.setBounds(x, top, Math.max(0, width), h);
		}

		@Override
		protected void paintComponent(final Graphics g)
		{
			super.paintComponent(g);
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(PAD_X - 4, RULE_Y, getWidth() - 2 * (PAD_X - 4), 1);
		}
	}

	/**
	 * The chart's range chips "7d 30d 90d all" as ONE segmented bar under the chart (the user, 2026-09-29: "i want the
	 * chips below like design 8"), in the Items | Net Worth History toggle's family - its look copied, not its code:
	 * four EQUAL cells (the last ones take any odd pixel) in a 1 px {@link ColorScheme#MEDIUM_GRAY_COLOR} frame with
	 * 1 px dividers of the same grey - the bar's own ground, round and between the cells' grounds, which the bar paints
	 * in each cell's background colour (the cells' labels are see-through, so that each word can stand on
	 * {@link #TEXT_BASELINE} whatever the face's ascent). The lit cell is filled {@link ColorScheme#BRAND_ORANGE} with
	 * its word in dark bold; the others are the card's grey with their word in light grey, or in
	 * {@link ColorScheme#MEDIUM_GRAY_COLOR} for a DIMMED range - one with no reading on or before its start - which is
	 * still a cell and still answers a press.
	 *
	 * <p>A LEFT press ({@link Widgets#isPress}) on an unlit cell hands its range to {@code onPick}; a press on the lit
	 * one does nothing, it is already the answer. The mouse over an unlit cell lights its word orange, as on the
	 * toggle. Nothing here decides which cell is lit: the view says so through {@link #light}. No hover text
	 * (amendment 9.13).
	 */
	static final class RangeBar extends JPanel
	{
		/** The bar's height, its frame included. */
		static final int HEIGHT = 18;
		/** The card left on either side of the bar, and under it. */
		static final int SIDE = 6;
		static final Font LIT_FONT = Widgets.sansBold(12);
		static final Font UNLIT_FONT = Widgets.sans(12);
		/** A word's baseline, 13 px under the bar's top: 3 px of cell over its 9 px of ink and 4 px under it. */
		static final int TEXT_BASELINE = 13;

		private final Map<BankHistoryRange, JLabel> cells = new EnumMap<>(BankHistoryRange.class);
		@Nullable
		private BankHistoryRange lit;
		private Set<BankHistoryRange> dim = EnumSet.noneOf(BankHistoryRange.class);
		/** Each cell's ground, inside the frame: its left edge and width, from the last layout. */
		private final int[] groundX = new int[BankHistoryRange.values().length];
		private final int[] groundWidth = new int[BankHistoryRange.values().length];

		RangeBar(final Consumer<BankHistoryRange> onPick)
		{
			super(null);
			Objects.requireNonNull(onPick, "onPick");
			setOpaque(true);
			// The frame and the dividers: the bar's own ground, round and between the cells' grounds.
			setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
			for (final BankHistoryRange r : BankHistoryRange.values())
			{
				final JLabel cell = new JLabel(r.label());
				cell.setHorizontalAlignment(SwingConstants.CENTER);
				cell.setVerticalAlignment(SwingConstants.TOP);
				cell.setOpaque(false);
				cell.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mousePressed(final MouseEvent e)
					{
						if (Widgets.isPress(e) && r != lit)
						{
							onPick.accept(r);
						}
					}

					@Override
					public void mouseEntered(final MouseEvent e)
					{
						if (r != lit)
						{
							cell.setForeground(ColorScheme.BRAND_ORANGE);
						}
					}

					@Override
					public void mouseExited(final MouseEvent e)
					{
						paintCell(r);
					}
				});
				cells.put(r, cell);
				add(cell);
				paintCell(r);
			}
			setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH - 2 * SIDE, HEIGHT));
		}

		/** Lights {@code range}'s cell and dims those in {@code dimmed} (the view never dims the lit one). */
		void light(final BankHistoryRange range, final Set<BankHistoryRange> dimmed)
		{
			lit = range;
			dim = dimmed.isEmpty() ? EnumSet.noneOf(BankHistoryRange.class) : EnumSet.copyOf(dimmed);
			for (BankHistoryRange r : BankHistoryRange.values())
			{
				paintCell(r);
			}
		}

		private void paintCell(final BankHistoryRange r)
		{
			final JLabel cell = cells.get(r);
			final boolean on = r == lit;
			cell.setBackground(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
			cell.setForeground(on ? ColorScheme.DARKER_GRAY_COLOR
				: dim.contains(r) ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
			final Font font = on ? LIT_FONT : UNLIT_FONT;
			cell.setFont(font);
			// The word stands on TEXT_BASELINE: a top inset in a cell as tall as the bar, not the label's own centring,
			// which would set it a pixel low in a face whose ascent is the logical font's (its fallbacks' included).
			final int inset = Math.max(0, TEXT_BASELINE - cell.getFontMetrics(font).getAscent());
			if (!(cell.getBorder() instanceof EmptyBorder) || cell.getBorder().getBorderInsets(cell).top != inset)
			{
				cell.setBorder(new EmptyBorder(inset, 0, 0, 0));
			}
			// A hand only where a press does something.
			cell.setCursor(on ? Cursor.getDefaultCursor() : Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}

		/**
		 * Four equal cells inside the 1 px frame, 1 px apart; the last ones take any odd pixel. Each word's label spans
		 * its cell's width and the bar's whole height; its ground is painted by {@link #paintComponent}.
		 */
		@Override
		public void doLayout()
		{
			final BankHistoryRange[] ranges = BankHistoryRange.values();
			final int n = ranges.length;
			final int room = getWidth() - 2 - (n - 1);
			final int base = room / n;
			final int odd = room % n;
			int x = 1;
			for (int k = 0; k < n; k++)
			{
				final int w = Math.max(0, base + (k >= n - odd ? 1 : 0));
				groundX[k] = x;
				groundWidth[k] = w;
				cells.get(ranges[k]).setBounds(x, 0, w, getHeight());
				x += w + 1;
			}
		}

		/** The frame and dividers (the bar's ground), then each cell's ground inside them in its cell's colour. */
		@Override
		protected void paintComponent(final Graphics g)
		{
			super.paintComponent(g);
			final BankHistoryRange[] ranges = BankHistoryRange.values();
			for (int k = 0; k < ranges.length; k++)
			{
				g.setColor(cells.get(ranges[k]).getBackground());
				g.fillRect(groundX[k], 1, groundWidth[k], Math.max(0, getHeight() - 2));
			}
		}
	}

	/**
	 * A top-to-bottom stack: every child as wide as the parent and exactly as tall as it asks, {@code gap} px apart.
	 * Not {@code DynamicGridLayout}, which scales a child's preferred width by a ratio and truncates it - a 213 px
	 * row in a 215 px column came out 214 - and scales heights too.
	 */
	static final class Stack implements LayoutManager
	{
		private final int gap;

		Stack(final int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(final String name, final Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(final Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(final Container parent)
		{
			final Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			for (int i = 0; i < parent.getComponentCount(); i++)
			{
				final Dimension d = parent.getComponent(i).getPreferredSize();
				width = Math.max(width, d.width);
				height += (i == 0 ? 0 : gap) + d.height;
			}
			return new Dimension(in.left + width + in.right, in.top + height + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(final Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(final Container parent)
		{
			final Insets in = parent.getInsets();
			final int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (int i = 0; i < parent.getComponentCount(); i++)
			{
				final Component c = parent.getComponent(i);
				final int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}

	/** The readout's small ring, in the line's colour; nothing when there is no point to name. */
	private static final class Ring implements Icon
	{
		static final int SIZE = 9;
		@Nullable
		Color colour;

		@Override
		public void paintIcon(final Component c, final Graphics g, final int x, final int y)
		{
			if (colour == null)
			{
				return;
			}
			final Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(colour);
				g2.setStroke(new BasicStroke(1.2f));
				g2.draw(new Ellipse2D.Double(x + 0.6, y + 0.6, SIZE - 1.2, SIZE - 1.2));
				g2.fill(new Ellipse2D.Double(x + SIZE / 2.0 - 1.2, y + SIZE / 2.0 - 1.2, 2.4, 2.4));
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}

	/**
	 * One grey sentence wrapped to the component's width - a plain painted component rather than an HTML label
	 * (plan 7.2 item 9). Before it has a width it wraps at {@link Widgets#CONTENT_WIDTH}.
	 */
	static final class Sentence extends JComponent
	{
		static final int PAD_X = 12;
		static final int PAD_Y = 8;
		static final Font FONT = Widgets.sans(11);

		private final String text;

		Sentence(final String text)
		{
			this.text = Objects.requireNonNull(text, "text");
			setOpaque(true);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			setFont(FONT);
		}

		/** The lines {@link #text} breaks into at {@code width} px, words kept whole. */
		List<String> lines(final int width)
		{
			final FontMetrics fm = getFontMetrics(FONT);
			final int room = Math.max(1, width - 2 * PAD_X);
			final List<String> out = new ArrayList<>();
			String current = "";
			for (String word : text.split(" "))
			{
				final String tried = current.isEmpty() ? word : current + " " + word;
				if (current.isEmpty() || fm.stringWidth(tried) <= room)
				{
					current = tried;
				}
				else
				{
					out.add(current);
					current = word;
				}
			}
			if (!current.isEmpty())
			{
				out.add(current);
			}
			return out;
		}

		private int layoutWidth()
		{
			return getWidth() > 0 ? getWidth() : Widgets.CONTENT_WIDTH;
		}

		@Override
		public Dimension getPreferredSize()
		{
			final FontMetrics fm = getFontMetrics(FONT);
			return new Dimension(Widgets.CONTENT_WIDTH, 2 * PAD_Y + lines(layoutWidth()).size() * fm.getHeight());
		}

		@Override
		public void setBounds(final int x, final int y, final int width, final int height)
		{
			final boolean resized = width != getWidth();
			super.setBounds(x, y, width, height);
			if (resized && getPreferredSize().height != height)
			{
				revalidate();
			}
		}

		@Override
		protected void paintComponent(final Graphics g)
		{
			g.setColor(getBackground());
			g.fillRect(0, 0, getWidth(), getHeight());
			final Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setFont(FONT);
				g2.setColor(getForeground());
				final FontMetrics fm = g2.getFontMetrics();
				int y = PAD_Y + fm.getAscent();
				for (String line : lines(getWidth()))
				{
					g2.drawString(line, PAD_X, y);
					y += fm.getHeight();
				}
			}
			finally
			{
				g2.dispose();
			}
		}
	}
}

package com.bankpricemovement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.ParseException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.client.util.QuantityFormatter;

/**
 * Every number the sidebar shows, in one pure place (contract C8-C10): how a bank stack plus two price points
 * become a row, how a row list is filtered and ordered, and how a long becomes the short text a 213 px column
 * has room for.
 *
 * <p>Pure on purpose. The service computes rows on its executor and the panel formats them on the EDT, so
 * nothing here touches the client, Swing, the network or the clock beyond the millis it is handed - which is
 * also what makes the whole of the plugin's arithmetic testable without a client (playbook 7.6, style PURE).
 *
 * <p>The formatting delegates to RuneLite's own {@code QuantityFormatter} rather than inventing a second
 * house style for gp
 * ({@code runelite-client/src/main/java/net/runelite/client/util/QuantityFormatter.java}:
 * {@code quantityToStackSize} :80-115, {@code parseQuantity} :165-170, {@code formatNumber} :177-180),
 * so "12.3k" here means exactly what it means on an item stack in the game.
 */
public final class MovementMath
{
	/**
	 * What every "there is no number here" cell reads. One dash, everywhere, so a missing baseline is never
	 * mistaken for a zero move.
	 */
	public static final String DASH = "-";

	/**
	 * {@code HH:mm} in the viewer's own zone. Immutable and therefore safe to share
	 * ({@link DateTimeFormatter} is thread-safe); {@link Locale#ENGLISH} only pins the digits, as the pattern
	 * carries no locale-sensitive text.
	 */
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);

	/**
	 * {@code dd MMM} for a CALENDAR DATE - "07 Sep" - the day marker addendum L put in the status line and every
	 * row tooltip (L7). No clock and no zone: what it prints is a {@link LocalDate} that was already derived in
	 * UTC from the guide table's own {@code %LAST_UPDATE%} (L9), and turning a date into an instant to show it in
	 * the viewer's zone would shift it a day for half the world.
	 */
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("dd MMM", Locale.ENGLISH);

	/**
	 * How many decimals a percentage keeps (L2). The Grand Exchange site prints whole percents; ours keeps one,
	 * because a bank full of guide prices moves by fractions of a percent on most days (calibration: median
	 * |move| 0.36 % over 504 items) and whole percents would print a wall of zeroes.
	 */
	private static final int PCT_DECIMALS = 1;

	private MovementMath()
	{
	}

	// ---------------------------------------------------------------- rows (C8)

	/**
	 * Builds one row from a bank stack and the two price points that bracket the window (contract C8, sources
	 * per addendum K line K6/K13).
	 *
	 * <p>The source ladder is: the "now" point's mid if there is a POSITIVE one - since addendum K the service
	 * builds it as {@code new PricePoint(guide, guide)} from RuneLite's guide price (K1), so the mid IS that price
	 * and the source is GUIDE; otherwise the fallback price if the caller offered a positive one (source RUNELITE -
	 * the pre-K path, which the service no longer takes: it always passes 0); otherwise no price. A point that
	 * exists but has NEITHER side counts as no price, not as zero.
	 *
	 * <p><b>Why a "now" of 0 or less is no price at all.</b> L1 spells 0 as "RuneLite has no price for this item",
	 * and both the other two places that decide what counts as a price already say so - {@code PriceService.finish}
	 * ({@code price > 0 ? Long.valueOf(price) : null}) and {@code PortfolioMath}'s own {@code priced} test. The
	 * degraded mode of L3 takes "now" from the newest guide TABLE instead, where a 0 or a negative would survive
	 * the fold, and a row priced at 0 would pass the gp band, count as priced, and read "-100.0%" at the top of
	 * the losers - while the bank-value card, which applies the rule, would leave the same stack out. One rule,
	 * three places.
	 *
	 * <p>A move is computed ONLY for a GUIDE row with both ends present and a positive "then": the baseline is
	 * the same Jagex series at an earlier revision, so the difference is a real move, while a fallback price is
	 * a different measurement and subtracting a baseline from it would invent one; a "then" of 0 would make the
	 * percentage infinite.
	 *
	 * @param item                  the bank stack; never null
	 * @param now                   the guide price now as a point, or null when RuneLite has none
	 * @param then                  the baseline revision's point for this item, or null when no table names it
	 * @param runeliteFallbackPrice a fallback price with no history behind it, or 0 for "do not fall back"
	 * @return the row, never null
	 */
	public static MovementRow row(final BankItem item, final PricePoint now, final PricePoint then,
		final int runeliteFallbackPrice)
	{
		Objects.requireNonNull(item, "item");

		final Long guideNow = now == null ? null : now.mid();

		final Long unitPrice;
		final MovementRow.PriceSource source;
		if (guideNow != null && guideNow > 0L)
		{
			unitPrice = guideNow;
			source = MovementRow.PriceSource.GUIDE;
		}
		else if (runeliteFallbackPrice > 0)
		{
			unitPrice = (long) runeliteFallbackPrice;
			source = MovementRow.PriceSource.RUNELITE;
		}
		else
		{
			unitPrice = null;
			source = MovementRow.PriceSource.NONE;
		}

		final Long thenPrice = then == null ? null : then.mid();

		Long deltaGp = null;
		Double deltaPct = null;
		if (source == MovementRow.PriceSource.GUIDE && thenPrice != null && thenPrice > 0L)
		{
			deltaGp = unitPrice - thenPrice;
			deltaPct = deltaGp * 100.0d / thenPrice;
		}

		return new MovementRow(item.id, item.name, item.quantity, item.stackable, unitPrice, thenPrice,
			deltaGp, deltaPct, holdingValue(unitPrice, item.quantity), source);
	}

	/**
	 * The row an UNTRADEABLE stack that could not be parts-priced becomes while "Include alch-only untradeables" is
	 * on (addendum Q, line Q5; addendum AV): its unit price is the item's High Alchemy value
	 * ({@link BankItem#alchPrice()}), its source is {@link MovementRow.PriceSource#ALCH}, and it has no baseline and
	 * therefore no move - an alch value is a constant of the item rather than a series, so subtracting one from
	 * another would invent a movement that never happened.
	 *
	 * <p>The holding is the alch value times the quantity, as for any other row, which is what puts the stack in
	 * the bank value and what the row's headline line prints (addendum AN).
	 *
	 * @param item the bank stack; never null. A stack that is not untradeable, or whose alch value is 0, has no
	 *             price here at all and renders as the dash - the caller decides whether such a row is worth
	 *             drawing ({@code MovementMath.apply} drops it)
	 */
	public static MovementRow alchRow(final BankItem item)
	{
		Objects.requireNonNull(item, "item");

		final Long alch = item.alchPrice();
		return new MovementRow(item.id, item.name, item.quantity, item.stackable, alch, null, null, null,
			holdingValue(alch, item.quantity),
			alch == null ? MovementRow.PriceSource.NONE : MovementRow.PriceSource.ALCH);
	}

	/**
	 * What a stack is worth: unit price times quantity (contract C8). A bank can hold 2.1 billion of a
	 * 2 billion gp item on paper, so the multiplication is checked and CLAMPED to {@link Long#MAX_VALUE}
	 * rather than allowed to wrap into a negative fortune.
	 *
	 * @return 0 when there is no price or nothing to hold
	 */
	public static long holdingValue(final Long unitPrice, final int quantity)
	{
		if (unitPrice == null || quantity <= 0)
		{
			return 0L;
		}

		try
		{
			return Math.multiplyExact(unitPrice, (long) quantity);
		}
		catch (ArithmeticException overflow)
		{
			return Long.MAX_VALUE;
		}
	}

	/**
	 * What a stack's price CHANGED by: the unit change times the quantity - the gp figure the row's headline
	 * line prints (addendum AN) and the key the {@link SortMode#GP_MOVE} column sorts on, since addendum AO
	 * line AO1 under every switch rather than only while {@code holdingOnRows} was on (Q6).
	 *
	 * <p>Not {@link #holdingValue}: a change is signed, so the overflow clamp has to pick an END rather than
	 * always {@link Long#MAX_VALUE}. A fall clamped upwards would sort a collapse to the top of the gainers.
	 *
	 * @param deltaGp  the change in the price of one, or null when there is no move
	 * @param quantity how many the bank holds
	 * @return 0 when there is no move or nothing to hold; otherwise the product, clamped to
	 *         {@link Long#MAX_VALUE} or {@link Long#MIN_VALUE} by the change's own sign
	 */
	public static long holdingDelta(@Nullable final Long deltaGp, final int quantity)
	{
		if (deltaGp == null || quantity <= 0)
		{
			return 0L;
		}

		try
		{
			return Math.multiplyExact(deltaGp, (long) quantity);
		}
		catch (ArithmeticException overflow)
		{
			return deltaGp > 0L ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	// ---------------------------------------------------------------- filter and sort (C9)

	/**
	 * The user's view of the rows: keep what the gp band admits, order it by the chosen sort (contract C9).
	 *
	 * <p>A row with no unit price is dropped rather than shown at the bottom - a band on the price of one
	 * cannot say anything about an item that has no price, and the count line would otherwise claim items the
	 * filter never considered.
	 *
	 * <p>The band judges the price of ONE item whatever a row prints - it is "gp min / max" on the unit price
	 * (design D4), and a band that silently meant something else would be a different feature. Nothing but the
	 * {@link RowFilter} reaches this any more: the overload the view switches used to arrive by existed for the
	 * single key {@code holdingOnRows}, and went with it (addendum AO, line AO1).
	 *
	 * @param rows   every bank row; null reads as empty
	 * @param filter the band, sort, direction and window; null reads as {@link RowFilter#DEFAULT}
	 * @return a new unmodifiable list
	 */
	public static List<MovementRow> apply(final List<MovementRow> rows, final RowFilter filter)
	{
		final RowFilter used = filter == null ? RowFilter.DEFAULT : filter;
		final List<MovementRow> kept = new ArrayList<>();

		if (rows != null)
		{
			for (final MovementRow row : rows)
			{
				if (row == null || row.unitPrice() == null)
				{
					continue;
				}

				if (inBand(row.unitPrice(), used.gpMin(), used.gpMax()))
				{
					kept.add(row);
				}
			}
		}

		kept.sort(comparator(used.sort(), used.descending()));
		return Collections.unmodifiableList(kept);
	}

	/**
	 * The order one sort puts rows in (contract C9).
	 *
	 * <p>Two rules beyond "compare the key": a row WITHOUT the key - no move to speak of, or no price - is
	 * always last whichever way the arrow points (flipping the direction must not fill the top of the list
	 * with dashes), and equal keys fall back to name then id so the list never shuffles between two
	 * recomputes of the same data.
	 *
	 * <p><b>Every key is a property of the row alone.</b> {@code holdingOnRows} used to make
	 * {@link SortMode#GP_MOVE} compare the whole STACK's change (Q6) and, for one addendum, {@link
	 * SortMode#UNIT_PRICE} the whole stack's WORTH (V1) - the question V was answering, that a hundred Robin
	 * hood hats are a large holding though one hat is not a dear item, having since been given a column of its
	 * own in {@link SortMode#STACK_VALUE} (W1, which reverted V1). Addendum AO then deleted the key outright:
	 * the gp column compares the stack's change always (AO1), the price column one item's price always, and the
	 * percentage column is the same number however many are held. So no view switch reaches the ordering, and
	 * this takes no {@link ViewOptions}.
	 *
	 * @param sort       which key to compare; null reads as {@link SortMode#PERCENT_MOVE}
	 * @param descending true for biggest first
	 */
	public static Comparator<MovementRow> comparator(final SortMode sort, final boolean descending)
	{
		final SortMode used = sort == null ? SortMode.PERCENT_MOVE : sort;

		return (a, b) ->
		{
			final Double keyA = key(a, used);
			final Double keyB = key(b, used);

			if (keyA == null || keyB == null)
			{
				if (keyA != null)
				{
					return -1;
				}

				if (keyB != null)
				{
					return 1;
				}

				return byNameThenId(a, b);
			}

			final int byKey = Double.compare(keyA, keyB);
			if (byKey != 0)
			{
				return descending ? -byKey : byKey;
			}

			return byNameThenId(a, b);
		};
	}

	/**
	 * Whether a unit price sits inside the band, where a maximum of 0 means "no upper bound" (contract C10) -
	 * the reading an empty Max field writes.
	 */
	public static boolean inBand(final long unit, final long min, final long max)
	{
		return unit >= min && (max == 0L || unit <= max);
	}

	/**
	 * The sort key as a double. Every gp figure a bank can hold is far below 2^53, where a double still counts
	 * exactly, so this loses nothing and keeps one comparator for the four columns (addendum W, line W1).
	 *
	 * <p>{@link SortMode#STACK_VALUE} is gated on {@link MovementRow#unitPrice()} rather than on the holding
	 * value itself, because {@link MovementRow#holdingValue()} answers a plain 0 for a row with no price, and a
	 * 0 sorts as the cheapest thing in the bank rather than as a dash. The same gate the price column has always
	 * used therefore serves both, and a priceless row is last under either whichever way the arrow points.
	 *
	 * <p>{@link SortMode#GP_MOVE} is gated the same way, on {@link MovementRow#deltaGp()}, though what it
	 * compares is {@link MovementRow#holdingDeltaGp()} (AO1): a row with no move has no gp key under either
	 * reading, and the stack's change answers a plain 0 for it, which would sort it among the unmoved instead
	 * of behind them.
	 *
	 * @return null when this row has no such key - the "always last" case
	 */
	private static Double key(final MovementRow row, final SortMode sort)
	{
		switch (sort)
		{
			case PERCENT_MOVE:
				return row.deltaPct();
			case GP_MOVE:
				return row.deltaGp() == null ? null : (double) row.holdingDeltaGp();
			case UNIT_PRICE:
				return row.unitPrice() == null ? null : (double) row.unitPrice();
			case STACK_VALUE:
				return row.unitPrice() == null ? null : (double) row.holdingValue();
			default:
				return null;
		}
	}

	/**
	 * The tiebreak, always ascending whichever way the sort points: alphabetical (case-insensitive, so
	 * "Abyssal whip" and "abyssal whip" land together), then by id so two items sharing a name still have a
	 * fixed order.
	 */
	private static int byNameThenId(final MovementRow a, final MovementRow b)
	{
		final int byName = String.CASE_INSENSITIVE_ORDER.compare(a.name(), b.name());
		return byName != 0 ? byName : Integer.compare(a.id(), b.id());
	}

	// ---------------------------------------------------------------- text (C10)

	/**
	 * Reads a gp amount the user typed: "100k", "1.5m", "2b", "1,000", "850" (contract C10). Delegates to
	 * {@code QuantityFormatter.parseQuantity} ({@code QuantityFormatter.java:165-170}) so the field accepts
	 * exactly what the rest of the client accepts, then adds the two rules a PRICE band needs and the
	 * formatter does not have: blank is not a number, and a negative is not a price (the formatter's suffix
	 * pattern :49 admits a leading "-" and would return it happily).
	 *
	 * @param text what the field holds; null and blank both throw
	 * @return the amount in gp, never negative
	 * @throws ParseException when the text names no non-negative amount - the panel turns the field's border
	 *                        red and leaves the filter alone (design C29 (5))
	 */
	public static long parseGp(final String text) throws ParseException
	{
		final String trimmed = text == null ? "" : text.trim();
		if (trimmed.isEmpty())
		{
			throw new ParseException("Enter a gp amount", 0);
		}

		final long value = QuantityFormatter.parseQuantity(trimmed);
		if (value < 0L)
		{
			throw new ParseException("A price cannot be negative: " + trimmed, 0);
		}

		return value;
	}

	/**
	 * A gp amount as the game writes a stack size: "850", "12.3k", "1.52m"
	 * ({@code QuantityFormatter.quantityToStackSize}, {@code QuantityFormatter.java:80-115}), lower-cased so
	 * the suffix sits quietly beside the number in a small row.
	 *
	 * <p>Note the client's own threshold rides along: anything under 10,000 is written out in full with
	 * commas ("4,100", not "4.1k").
	 */
	public static String formatGp(final long gp)
	{
		return lowerSuffix(QuantityFormatter.quantityToStackSize(gp));
	}

	/**
	 * The same amount in full, comma grouped ({@code QuantityFormatter.formatNumber},
	 * {@code QuantityFormatter.java:177-180}) - what the tooltip shows, where there is room for every digit.
	 */
	public static String formatExact(final long gp)
	{
		return QuantityFormatter.formatNumber(gp);
	}

	/**
	 * A price change with its sign: "+12.3k", "-4,100", "0", or {@link #DASH} when there is no move to show
	 * (contract C10).
	 *
	 * <p>A negative is formatted through the formatter's own minus rather than by negating the value, so
	 * {@link Long#MIN_VALUE} cannot overflow on its way to the screen.
	 */
	public static String formatDelta(final Long gp)
	{
		if (gp == null)
		{
			return DASH;
		}

		if (gp > 0L)
		{
			return "+" + formatGp(gp);
		}

		return formatGp(gp);
	}

	/**
	 * A percentage move as the Grand Exchange site writes one, to one decimal: "+0.8%", "-12.4%", "0.0%", or
	 * {@link #DASH} when there is none (contract C10, redefined by addendum L line L2).
	 *
	 * <p>The sign comes from the percentage itself here; the {@link #formatPct(Double, Long)} overload takes it
	 * from the gp change instead, which is what a row shows (L2).
	 */
	public static String formatPct(@Nullable final Double pct)
	{
		return formatPct(pct, null);
	}

	/**
	 * The same percentage, signed by the gp change beside it (L2).
	 *
	 * <p><b>Truncated toward zero, never rounded.</b> The GE site computes
	 * {@code trunc_toward_zero((daily[D] - daily[D-N]) / daily[D-N] * 100)}: measured against 26 live figures,
	 * truncation matched 26/26 and rounding only 15/26 (L-B). Ours truncates at {@value #PCT_DECIMALS} decimal
	 * instead of at a whole percent, so "-12.44" reads "-12.4%" - one digit shorter than the value, never one
	 * digit larger than it. {@link BigDecimal#valueOf(double)} goes through the double's SHORTEST decimal
	 * representation, so 0.7 truncates to "0.7" rather than to the "0.6" that {@code (long) (0.7 * 10)} yields
	 * from 6.999999999999999.
	 *
	 * <p><b>Why the sign is the gp change's and not the percentage's.</b> A fall of a hundredth of a percent
	 * truncates to a bare zero, and the site still prints it with a minus and a red arrow ("Amulet of fury",
	 * 30 d, -0.10 % shown as "-0.0%", L-B). So a row whose gp change is negative reads "-0.0%" and stays red,
	 * a row whose gp change is positive reads "+0.0%", and only a genuinely unmoved row reads "0.0%" in grey -
	 * the three states {@code MovementRowPanel.changeColor} already paints from the same gp figure.
	 *
	 * @param pct     the move in percent, or null / non-finite for {@link #DASH}
	 * @param deltaGp the gp change the percentage was computed from; null takes the sign from {@code pct}
	 */
	public static String formatPct(@Nullable final Double pct, @Nullable final Long deltaGp)
	{
		if (pct == null || !Double.isFinite(pct))
		{
			return DASH;
		}

		final BigDecimal truncated = BigDecimal.valueOf(pct).setScale(PCT_DECIMALS, RoundingMode.DOWN);
		// toPlainString, not toString: a percentage this large is nonsense data rather than "1.0E+2" on a row.
		return signedPct(truncated.abs().toPlainString(), pct, deltaGp);
	}

	/**
	 * The percentage as a ROW'S FACE prints it (addendum AT): {@link #formatPct(Double, Long)} below a hundred,
	 * and shorter above it, because the face's column is 54 px at a 15 px bold face and "+100.0%" measures 58 -
	 * a minus is narrower than a plus, so "-100.0%" (54) held whole while every RISE of a hundred percent or
	 * more was cut to "+157..." (the user's Elemental shield, 2026-09-24). Whole percents from 100 ("+157%",
	 * "+9999%" is 54), thousands from 10,000 ("+12k%", "+999k%"), millions from a million ("+1m%") and
	 * billions after that - every one truncated toward zero, as the one-decimal form is, and every one inside the
	 * column. The sign is the gp change's, as in {@link #formatPct}. The exact one-decimal figure is still in
	 * the block a row opens into, which uses {@link #formatPct} directly.
	 *
	 * @param pct     the move in percent, or null / non-finite for {@link #DASH}
	 * @param deltaGp the gp change the percentage was computed from; null takes the sign from {@code pct}
	 */
	public static String formatPctCompact(@Nullable final Double pct, @Nullable final Long deltaGp)
	{
		if (pct == null || !Double.isFinite(pct))
		{
			return DASH;
		}

		final double size = Math.abs(pct);
		if (size < 100d)
		{
			return formatPct(pct, deltaGp);
		}

		// Whole units of 1, 1,000, 1,000,000 or 1,000,000,000 percent, truncated toward zero like the decimal
		// form: the face never prints a move larger than it is.
		final String digits;
		if (size < 10_000d)
		{
			digits = Long.toString((long) size);
		}
		else if (size < 1_000_000d)
		{
			digits = (long) (size / 1_000d) + "k";
		}
		else if (size < 1_000_000_000d)
		{
			digits = (long) (size / 1_000_000d) + "m";
		}
		else
		{
			digits = (long) (size / 1_000_000_000d) + "b";
		}
		return signedPct(digits, pct, deltaGp);
	}

	/** {@code digits} with a percent sign and the sign of {@code deltaGp} (or of {@code pct} without one), L2. */
	private static String signedPct(final String digits, final double pct, @Nullable final Long deltaGp)
	{
		final int sign = deltaGp != null ? Long.signum(deltaGp) : signum(pct);
		if (sign > 0)
		{
			return "+" + digits + "%";
		}

		if (sign < 0)
		{
			return "-" + digits + "%";
		}

		return digits + "%";
	}

	/**
	 * The sign of a double as -1, 0 or 1, with negative zero counted as zero - {@code Math.signum} answers
	 * {@code -0.0} for it, which would print a minus in front of an unmoved row.
	 */
	private static int signum(final double value)
	{
		if (value > 0.0d)
		{
			return 1;
		}

		return value < 0.0d ? -1 : 0;
	}

	/**
	 * A timestamp as the header's "Prices HH:mm" clock, in the viewer's own zone (contract C10).
	 *
	 * @param millis epoch millis; 0 or less - the "never fetched" reading of every timestamp in this plugin -
	 *               gives {@link #DASH} rather than 1970
	 */
	public static String formatTime(final long millis)
	{
		if (millis <= 0L)
		{
			return DASH;
		}

		return CLOCK.format(Instant.ofEpochMilli(millis).atZone(ZoneId.systemDefault()));
	}

	/**
	 * A guide-price DAY as the status line and every row tooltip stamp it - "07 Sep" (addendum L, L7).
	 *
	 * <p>This is what a baseline is labelled with since addendum L; addendum K's {@code formatDayTime} - a local
	 * "07 Sep 19:55" built from the wiki revision's publication clock - went with the label it printed, so no
	 * caller can reach for a zone-shifted day by mistake (removed by the checker, 2026-09-09). The
	 * series steps ONCE A DAY at a variable UTC hour (L-A: the Jagex rollover was observed between 00:47 and
	 * 02:06 UTC, not at midnight) and the wiki's bot republishes it at a random hour of that day (02:11-22:20 UTC,
	 * L-C), so the publication CLOCK says nothing about which day's prices are in the table - the table's own
	 * {@code %LAST_UPDATE%} does (L-E), and that is a date. Printing a clock beside it invited exactly the
	 * misreading addendum L exists to end.
	 *
	 * <p>The date is printed as it stands, in no zone at all: it was derived in UTC (L9), and re-interpreting it
	 * in the viewer's zone would name the wrong day for anyone west of Greenwich.
	 *
	 * @param day the UTC calendar date; null - no baseline day known yet - gives {@link #DASH}
	 */
	public static String formatDay(@Nullable final LocalDate day)
	{
		if (day == null)
		{
			return DASH;
		}

		return DAY.format(day);
	}

	/**
	 * The hero card's baseline phrase - "since 08 Sep" (addendum N sections 3.1 and 4.4, the sub-line under
	 * the bank total and the Ticker card's provenance footnote).
	 *
	 * <p>Its whole job is the null. {@code " since " + formatDay(null)} would read "since -", a sentence
	 * that claims a baseline and then fails to name it; a card with no baseline day shows the one
	 * {@link #DASH} the rest of the panel shows instead, and the problem row says why (N 3.6).
	 *
	 * @param day the baseline's UTC calendar date; null - no baseline settled - gives {@link #DASH}
	 */
	public static String formatSince(@Nullable final LocalDate day)
	{
		return day == null ? DASH : "since " + formatDay(day);
	}

	/**
	 * Lower-cases a trailing K/M/B so a stack size reads as a price.
	 */
	private static String lowerSuffix(final String text)
	{
		final int last = text.length() - 1;
		if (last >= 0 && Character.isLetter(text.charAt(last)))
		{
			return text.substring(0, last) + Character.toLowerCase(text.charAt(last));
		}

		return text;
	}
}

package com.bankpricemovement;

import java.util.Map;

/**
 * The on-disk form of a {@link PriceMap}: public fields, a no-arg constructor and nothing but JSON-friendly
 * types, so the INJECTED Gson can read and write it without an adapter (contract C4, extended by K11; the
 * workspace rule for a persisted class - playbook step 13 - is "public fields, no-arg ctor, stock Gson").
 *
 * <p>Two shape decisions, both because a saved map holds 3-4.5k entries:
 *
 * <ul>
 * <li>the keys are STRINGS. A JSON object key is always a string, and Gson round-trips a {@code Map<Integer,..>}
 * only by re-parsing those keys; spelling that out here keeps the file honest and lets a key that is not a
 * number be skipped rather than throw ({@link PriceMap#fromDto}).</li>
 * <li>each value is a two-slot {@code long[]} - {@code [high, low]} - with {@link #ABSENT} (-1) standing for
 * "the wiki gave no price on that side". A {@code Long[]} would carry null directly, but whether a null
 * survives depends on the Gson instance's null handling (the injected client Gson drops nulls in objects -
 * playbook 7.8), and a price can never be negative, so a sentinel is the shape that cannot be configured
 * away. {@code 0} stays a legal price.</li>
 * </ul>
 */
public class PriceMapDto
{
	/**
	 * The stored value that means "no price on this side" - see {@link PricePoint} on why a side goes missing.
	 * -1 is safe as a sentinel because the wiki never returns a negative price.
	 */
	public static final long ABSENT = -1L;

	/**
	 * The version of THIS document shape that the current build writes ({@link #schema}). Bump it whenever a
	 * stored field's MEANING changes, not when a field is merely added: a new field an old file lacks reads as
	 * its zero and costs nothing, while a field that means something else than it used to is a file this build
	 * must not believe.
	 *
	 * <p>Addendum K to L is the change that proves the need. Both eras write {@code revId > 0}, so the sweep's
	 * revision test cannot separate them, and yet {@link #bucketSeconds} means the REVISION'S SAVE TIME in a
	 * K-era file and the table's own {@code %LAST_UPDATE%} in an L-era one - a day apart often enough to flip
	 * the sign on a row. Nothing on any machine is K-era (v1 has never been published), so 1 is the first
	 * number this field has ever carried and every file written before it existed reads as 0, which is exactly
	 * the marker those two eras lack.
	 */
	public static final int SCHEMA = 1;

	/**
	 * Which build's shape this document is: {@link #SCHEMA} in anything this build wrote, and 0 in every file
	 * written before the field existed (Gson leaves an absent key at its zero - the whole point of the marker).
	 *
	 * <p>Read by {@code PriceService.guideOrEmpty}, alongside the {@code revId > 0} test it already made: a
	 * baseline below the current schema is REFUSED rather than adopted, so it can never teach the service a
	 * calendar day that its fields no longer mean. The cost of a refusal is one refetch of that window - the
	 * same refetch the six-hour cadence makes anyway - and the panel says "No 1d history yet" until it lands.
	 */
	public int schema;

	/**
	 * When the map was fetched, in epoch millis (0 when unknown).
	 */
	public long fetchedAtMillis;

	/**
	 * The moment this map's prices belong to, in unix seconds; 0 when it is a "now" reading with no history
	 * behind it.
	 *
	 * <p>The name is pre-addendum-K, when the value really was a wiki hourly TRADE bucket. Since the switch to
	 * the guide series (K11) it carries a moment out of {@code Module:GEPrices/data.json}, and since addendum L
	 * (L7) that moment is the table's own {@code %LAST_UPDATE%} - the DAY MARKER Jagex stamped the prices with -
	 * rather than the revision's save time, which a human maintenance edit can put a whole day later than the
	 * prices in the body (L-E). The field keeps its name so a saved baseline written by the first build still
	 * parses ({@code PriceMap.fromDto} reads it either way); {@link #revId} is what distinguishes the two eras,
	 * and {@code PriceStore.deleteStaleFiles()} uses exactly that to sweep a trade-era file away.
	 */
	public long bucketSeconds;

	/**
	 * The wiki revision {@link #bucketSeconds} and the prices came from (K11), or 0 when this map predates the
	 * guide switch or is a "now" reading.
	 *
	 * <p>A real revision id is in the fifteen millions (measured 2026-09-08), and
	 * {@code GuidePriceClient.parseRevisionIndex} drops anything that is not positive, so 0 is an unambiguous
	 * "not from the guide table". Absent from a file written by the first build, where Gson leaves it at 0 - the
	 * back-compat case {@code PriceMapTest} pins.
	 */
	public long revId;

	/**
	 * Item id (as text) to {@code [high, low]}, each side {@link #ABSENT} when there was no price on it. A guide
	 * map carries the same number on both sides (the guide price is a single figure, K1), which keeps one shape
	 * on disk for both eras.
	 */
	public Map<String, long[]> points;

	public PriceMapDto()
	{
	}

	/**
	 * Turns a nullable price side into its stored form.
	 */
	public static long encode(final Long side)
	{
		return side == null ? ABSENT : side;
	}

	/**
	 * Turns a stored side back into a nullable price. Anything negative reads as "absent", so a hand-edited
	 * or truncated file cannot inject a negative price into the maths.
	 */
	public static Long decode(final long stored)
	{
		return stored < 0 ? null : stored;
	}
}

package com.bankpricemovement;

import java.util.Locale;

/**
 * The four columns the sidebar's sort button offers, in the order the user gave them (addendum W, line W1;
 * {@code docs/bank-price-movement-addendum-W-2026-09-13.md}): <b>"1) Percent change 2) GP change 3) Item price
 * 4) Stack price"</b>, with the gp one written lowercase as he asked.
 *
 * <p><b>Four, not three.</b> {@link #STACK_VALUE} is the column addendum W adds ("i dont see the sort by stack
 * value option", 2026-09-12): a hundred Robin hood hats ARE a large holding though one hat is not a dear item,
 * and before W the only way to see them near the top was to throw a display switch and change what
 * {@link #UNIT_PRICE} meant. Now the two questions have a column each and neither moves under a switch.
 *
 * <p><b>Direction is NOT part of this enum</b>: it rides beside it on {@link RowFilter#descending()}, because
 * the sidebar flips direction by pressing the column that is already lit (addendum W, line W2 - the arrow on
 * the button is the direction), so the column and the arrow are two independent pieces of state.
 *
 * <p><b>The constant names are frozen surface</b>: {@code sortMode} stores {@link #name()}, so a profile
 * written by an older build still reads. Adding a constant is allowed - that is what W did - renaming one is
 * not.
 *
 * <p>{@link #parse(String)} takes the short verbs the dev bridge uses ({@code bpm sort=stack}) as well as the
 * labels and the constant names, so one code path serves the panel, the config and the terminal. Every verb
 * that ever worked still works, the pre-W labels ("% move", "gp move") included.
 *
 * <p>{@link #toString()} is the LABEL so RuneLite's config combo box reads "Percent change" rather than
 * "PERCENT_MOVE"; the stored value is unaffected because {@code ConfigManager} serialises an enum with
 * {@code name()} ({@code ConfigManager.java:1279-1281}) and reads it with {@code Enum.valueOf}
 * ({@code :1205-1207}).
 */
public enum SortMode
{
	/** The percentage the unit price moved over the window. The default column ({@link RowFilter#DEFAULT}). */
	PERCENT_MOVE("Percent change", "pct", "percent", "% move"),

	/**
	 * The gp the WHOLE STACK moved over the window ({@link MovementRow#holdingDeltaGp()}), under every switch
	 * (addendum AO, line AO1).
	 *
	 * <p>It used to be ONE item's move, with {@code holdingOnRows} turning it into the stack's (Q6, and for one
	 * addendum V1 did the same to {@link #UNIT_PRICE}); that key is deleted, and the stack is the reading that
	 * survived it. This is a portfolio tracker, so "biggest gainers" means the holding that gained the most gp -
	 * ten thousand feathers up a gp each are a bigger gain than one whip up two hundred - and since addendum AN
	 * the row's headline line IS the stack, so the column now orders by the figure the eye lands on.
	 *
	 * <p><b>That changes the default ordering of this column for every existing user</b>: the deleted switch
	 * defaulted to OFF, and OFF was the per-item reading. No stored {@code sortMode} moves - the constant, the
	 * label and every alias are the ones they always were - but the list this column draws is ordered by a
	 * different number than it was before AO.
	 */
	GP_MOVE("gp change", "gp", "amount", "gp move"),

	/** What ONE item costs, under every switch (addendum W reverted addendum V's line V1). */
	UNIT_PRICE("Item price", "price", "unit"),

	/** What the whole stack is worth: unit price times quantity ({@link MovementRow#holdingValue()}). */
	STACK_VALUE("Stack price", "stack", "stacks", "holding");

	private final String label;
	private final String[] aliases;

	SortMode(final String label, final String... aliases)
	{
		this.label = label;
		this.aliases = aliases;
	}

	/**
	 * The button text the sidebar draws, and the menu entry's words ("Stack price").
	 */
	public String label()
	{
		return label;
	}

	/**
	 * Reads a column out of user or dev-bridge text: the constant name ("STACK_VALUE"), the label ("Stack
	 * price"), or one of the short verbs - "pct" / "percent" / "% move", "gp" / "amount" / "gp move", "price"
	 * / "unit", "stack" / "stacks" / "holding". Trimmed and case-insensitive.
	 *
	 * <p>The pre-addendum-W labels are among those verbs on purpose: "% move" and "gp move" were what the
	 * button printed for two years of scripts, and a rename of the words on screen is no reason for
	 * {@code bpm sort="% move"} to stop answering.
	 *
	 * @param text anything, including null
	 * @return the column, or null when the text names none (the caller keeps its current column)
	 */
	public static SortMode parse(final String text)
	{
		if (text == null)
		{
			return null;
		}

		final String key = text.trim().toLowerCase(Locale.ENGLISH);
		if (key.isEmpty())
		{
			return null;
		}

		for (final SortMode mode : values())
		{
			if (key.equals(mode.label.toLowerCase(Locale.ENGLISH))
				|| key.equals(mode.name().toLowerCase(Locale.ENGLISH)))
			{
				return mode;
			}

			for (final String alias : mode.aliases)
			{
				if (key.equals(alias))
				{
					return mode;
				}
			}
		}

		return null;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * The whole bank's guide-price move over ONE window, on a consistent basis (addendum M, line M1/M2;
 * {@code docs/bank-price-movement-addendum-M-2026-09-09.md}): only the stacks priced on BOTH days count, so
 * {@link #valueThen()} and {@link #valueNowCovered()} are sums over the same stacks and their difference is a real
 * move rather than the arrival or departure of a price. {@link #itemsCovered()} says how many stacks that was, and
 * the panel shows it beside {@code itemsPriced} so a reader can see when a window's coverage is thin.
 *
 * <p>Since addendum P line P1 the bank's cash ({@link BankSnapshot#currencyGp}) sits inside {@link #valueThen()} and
 * {@link #valueNowCovered()} alike, so {@link #deltaGp()} is exactly what it always was and {@link #deltaPct()} is
 * measured against the whole bank. A window that covers no stack carries no cash and keeps its zeros - see
 * {@link PortfolioMath}, which computes all of this; this class stays a value holder.
 *
 * <p>Immutable, like {@link MovementRow}: built on the service's executor and read on the EDT and by the dev bridge.
 * Sums are {@code long} clamped at {@link Long#MAX_VALUE} by {@link PortfolioMath}, never wrapped.
 */
public final class WindowMove
{
	private final MovementWindow window;
	@Nullable
	private final LocalDate thenDay;
	private final long valueThen;
	private final long valueNowCovered;
	private final long deltaGp;
	@Nullable
	private final Double deltaPct;
	private final int itemsCovered;

	/**
	 * @param window          the window this move is measured over; null reads as {@link MovementWindow#DEFAULT}
	 * @param thenDay         the UTC day the window's baseline table claims (its own {@code %LAST_UPDATE%}, L7), or
	 *                        null when the baseline carries no day marker
	 * @param valueThen       the sum of {@code then x quantity} over the covered stacks plus the bank's cash (P1),
	 *                        clamped; the cash is left off when nothing is covered
	 * @param valueNowCovered the sum of {@code now x quantity} over the SAME stacks plus the same cash, clamped
	 * @param deltaGp         {@code valueNowCovered - valueThen}
	 * @param deltaPct        {@code deltaGp x 100 / valueThen}, or null when {@code valueThen} is 0 (M1)
	 * @param itemsCovered    how many stacks were priced on both days
	 */
	public WindowMove(@Nullable final MovementWindow window, @Nullable final LocalDate thenDay, final long valueThen,
		final long valueNowCovered, final long deltaGp, @Nullable final Double deltaPct, final int itemsCovered)
	{
		this.window = window == null ? MovementWindow.DEFAULT : window;
		this.thenDay = thenDay;
		this.valueThen = valueThen;
		this.valueNowCovered = valueNowCovered;
		this.deltaGp = deltaGp;
		this.deltaPct = deltaPct;
		this.itemsCovered = itemsCovered;
	}

	/** Never null. */
	public MovementWindow window()
	{
		return window;
	}

	/** The baseline table's own UTC day (L7), the day the tooltip prints ("1d vs 07 Sep"); null when unknown. */
	@Nullable
	public LocalDate thenDay()
	{
		return thenDay;
	}

	/** The covered stacks' worth at the baseline day's guide prices, plus the bank's cash (P1). */
	public long valueThen()
	{
		return valueThen;
	}

	/**
	 * The SAME stacks' worth at today's guide prices, plus the same cash - still not the whole bank's
	 * {@link PortfolioSummary#valueNow()}, which counts every priced stack rather than only the covered ones.
	 */
	public long valueNowCovered()
	{
		return valueNowCovered;
	}

	/**
	 * {@link #valueNowCovered()} minus {@link #valueThen()}; the sign that colours the line (L2). The cash cancels,
	 * so this is the covered stacks' move and nothing else (P1).
	 */
	public long deltaGp()
	{
		return deltaGp;
	}

	/**
	 * The move as a percentage of {@link #valueThen()} - cash included in that base since P1 - untruncated; null
	 * when nothing was worth anything then, which is also the case of a window that covers no stack at all.
	 */
	@Nullable
	public Double deltaPct()
	{
		return deltaPct;
	}

	/** How many stacks were priced on both days - the basis of the three sums. */
	public int itemsCovered()
	{
		return itemsCovered;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof WindowMove))
		{
			return false;
		}
		final WindowMove other = (WindowMove) o;
		return window == other.window
			&& Objects.equals(thenDay, other.thenDay)
			&& valueThen == other.valueThen
			&& valueNowCovered == other.valueNowCovered
			&& deltaGp == other.deltaGp
			&& Objects.equals(deltaPct, other.deltaPct)
			&& itemsCovered == other.itemsCovered;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(window, thenDay, valueThen, valueNowCovered, deltaGp, deltaPct, itemsCovered);
	}

	@Override
	public String toString()
	{
		return "WindowMove{window=" + window.name()
			+ ", thenDay=" + thenDay
			+ ", valueThen=" + valueThen
			+ ", valueNowCovered=" + valueNowCovered
			+ ", deltaGp=" + deltaGp
			+ ", deltaPct=" + deltaPct
			+ ", itemsCovered=" + itemsCovered + '}';
	}
}

package com.bankpricemovement;

import java.util.Objects;

/**
 * Everything the user has chosen about what the sidebar shows: the gp band, the sort and its direction, and
 * the window (contract C7). One immutable value, so the panel, the config and the dev bridge cannot drift
 * apart - a change is a NEW filter handed to the service, never a field edited in place.
 *
 * <p>The band filters the UNIT price, not the holding value (design D4 - the user's "gp min and max" against
 * the price of one item), and {@code gpMax == 0} means "no upper bound" rather than "nothing over 0 gp", which
 * is what an empty Max field writes.
 *
 * <p>The five fields are the five FILTER keys of C39, so {@code Prefs.load()} / {@code Prefs.save()} is a
 * straight copy in each direction. The config also carries addendum O2's three hero show/hide switches, which
 * are deliberately NOT here: a filter says what the list CONTAINS, and a switch that only decides what is
 * painted must not make the service recompute anything - those ride on {@code HeroVisibility} through
 * {@code Prefs.loadHero()} / {@code Prefs.saveHero()}.
 */
public final class RowFilter
{
	/**
	 * A fresh install: no band, sorted by the biggest percentage move first, over the last day
	 * ({@link MovementWindow#DEFAULT}; design D5 as rewritten by addendum K4 - the guide table is republished
	 * about once a day, so a day is the shortest window the series can express).
	 */
	public static final RowFilter DEFAULT = new RowFilter(0L, 0L, SortMode.PERCENT_MOVE, true, MovementWindow.DEFAULT);

	private final long gpMin;
	private final long gpMax;
	private final SortMode sort;
	private final boolean descending;
	private final MovementWindow window;

	/**
	 * @param gpMin      lowest unit price to show; negatives clamp to 0
	 * @param gpMax      highest unit price to show, or 0 for no upper bound; negatives clamp to 0
	 * @param sort       which column orders the list; null becomes {@link SortMode#PERCENT_MOVE}
	 * @param descending true for biggest first
	 * @param window     the baseline the move is measured against; null becomes {@link MovementWindow#DEFAULT}
	 */
	public RowFilter(final long gpMin, final long gpMax, final SortMode sort, final boolean descending,
		final MovementWindow window)
	{
		this.gpMin = Math.max(0L, gpMin);
		this.gpMax = Math.max(0L, gpMax);
		this.sort = sort == null ? SortMode.PERCENT_MOVE : sort;
		this.descending = descending;
		this.window = window == null ? MovementWindow.DEFAULT : window;
	}

	public long gpMin()
	{
		return gpMin;
	}

	/**
	 * The upper bound of the band, or 0 for none.
	 */
	public long gpMax()
	{
		return gpMax;
	}

	/**
	 * Never null.
	 */
	public SortMode sort()
	{
		return sort;
	}

	public boolean descending()
	{
		return descending;
	}

	/**
	 * Never null.
	 */
	public MovementWindow window()
	{
		return window;
	}

	public RowFilter withGpMin(final long newGpMin)
	{
		return new RowFilter(newGpMin, gpMax, sort, descending, window);
	}

	public RowFilter withGpMax(final long newGpMax)
	{
		return new RowFilter(gpMin, newGpMax, sort, descending, window);
	}

	public RowFilter withSort(final SortMode newSort)
	{
		return new RowFilter(gpMin, gpMax, newSort, descending, window);
	}

	public RowFilter withDescending(final boolean newDescending)
	{
		return new RowFilter(gpMin, gpMax, sort, newDescending, window);
	}

	public RowFilter withWindow(final MovementWindow newWindow)
	{
		return new RowFilter(gpMin, gpMax, sort, descending, newWindow);
	}

	/**
	 * Value equality: the service compares the incoming filter with the current one to decide whether a
	 * recompute or a fetch is needed at all, so this has to be a value, not an identity.
	 */
	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof RowFilter))
		{
			return false;
		}

		final RowFilter other = (RowFilter) o;
		return gpMin == other.gpMin
			&& gpMax == other.gpMax
			&& descending == other.descending
			&& sort == other.sort
			&& window == other.window;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(gpMin, gpMax, sort, descending, window);
	}

	@Override
	public String toString()
	{
		return "RowFilter{gpMin=" + gpMin
			+ ", gpMax=" + gpMax
			+ ", sort=" + sort.name()
			+ ", descending=" + descending
			+ ", window=" + window.name() + '}';
	}
}

package com.bankpricemovement;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * The bank as a portfolio (addendum M, lines M1/M2; {@code docs/bank-price-movement-addendum-M-2026-09-09.md}):
 * what every priced stack is worth at today's guide prices, how many stacks that covers, and one {@link WindowMove}
 * per window that has a baseline in memory. The WHOLE bank - the gp band the rows are filtered on is not applied,
 * because a portfolio is everything you own, not the slice you are looking at.
 *
 * <p>Immutable and shared: computed by {@link PortfolioMath#summariseResolved} (the service's shape) or
 * {@link PortfolioMath#summarise} (the contract's) on the service's executor, published inside
 * {@link PriceService.Status} to the EDT, echoed by the dev bridge. {@link #EMPTY} is what a status carries until
 * the first computation (M3).
 *
 * <p><b>Live prices</b> (addendum T, line T5). With the {@code livePrices} switch on, a stack that passed the
 * liquidity checks - T3's three, and addendum V's two on yesterday's own daily bucket - is counted at its live
 * traded mid rather than at the guide price, and every window
 * compares it against that day's traded average - each stack on its own series, which is why
 * {@link PortfolioMath} takes a "now" resolver per window as well as the one behind {@link #valueNow()}.
 * {@link #liveRows()} is how many stacks that was. With the switch off it is 0 and every figure here is the
 * guide-only one of addenda K to S, to the gp.
 *
 * <p><b>Cash</b> (addendum P, line P1; {@code docs/bank-price-movement-addendum-P-2026-09-10.md}). The bank's coins
 * and platinum tokens are not stacks - they have no market and never appear as a row - but they are half of what a
 * player means by "bank value", so {@link #currencyGp()} rides here beside the stacks and {@link #valueNow()} is the
 * two added. {@link #itemsPriced()} and {@link #itemsTotal()} still count stacks only.
 */
public final class PortfolioSummary
{
	/** No bank computed yet: nothing is worth anything, no stacks, no cash, no windows (M3: "EMPTY until the first compute"). */
	public static final PortfolioSummary EMPTY = new PortfolioSummary(0L, 0, 0, Collections.emptyMap(), 0L);

	private final long valueStacks;
	private final int itemsPriced;
	private final int itemsTotal;
	private final long currencyGp;
	private final int liveRows;
	private final Map<MovementWindow, WindowMove> moves;

	/**
	 * The pre-P1 arity, kept so every caller that knows nothing of cash keeps compiling AND keeps its figures: it
	 * delegates with {@code currencyGp} 0, and 0 cash makes {@link #valueNow()} the stacks' value exactly as before.
	 *
	 * @param valueStacks the sum of {@code now x quantity} over every stack with a guide price, clamped at
	 *                    {@link Long#MAX_VALUE} (M1)
	 * @param itemsPriced how many stacks have a guide price
	 * @param itemsTotal  how many stacks the bank holds
	 * @param moves       one move per window WITH a baseline; copied into an unmodifiable {@link EnumMap}, null keys or
	 *                    values dropped, null reads as empty
	 */
	public PortfolioSummary(final long valueStacks, final int itemsPriced, final int itemsTotal,
		@Nullable final Map<MovementWindow, WindowMove> moves)
	{
		this(valueStacks, itemsPriced, itemsTotal, moves, 0L);
	}

	/**
	 * @param valueStacks the sum of {@code now x quantity} over every stack with a guide price, WITHOUT the cash,
	 *                    clamped at {@link Long#MAX_VALUE} (M1); {@link #valueNow()} is this plus {@code currencyGp}
	 * @param itemsPriced how many stacks have a guide price - cash is not a stack and is not counted here
	 * @param itemsTotal  how many stacks the bank holds - cash is not one of them either
	 * @param moves       one move per window WITH a baseline; copied into an unmodifiable {@link EnumMap}, null keys or
	 *                    values dropped, null reads as empty
	 * @param currencyGp  the bank's coins and platinum tokens in gp ({@link BankSnapshot#currencyGp}, P1); a negative
	 *                    reads as 0, because there is no such thing as a negative fortune
	 */
	public PortfolioSummary(final long valueStacks, final int itemsPriced, final int itemsTotal,
		@Nullable final Map<MovementWindow, WindowMove> moves, final long currencyGp)
	{
		this(valueStacks, itemsPriced, itemsTotal, moves, currencyGp, 0);
	}

	/**
	 * The same, carrying how many of those stacks were priced from the LIVE traded series (addendum T, line T5).
	 * The arity above is the pre-T one, kept so every caller that knows nothing of live prices keeps compiling AND
	 * keeps its meaning: it delegates with 0, which is what a summary computed with the switch off holds.
	 *
	 * @param liveRows how many stacks {@link #valueStacks()} counted at a live traded mid rather than at a guide
	 *                 price; a negative reads as 0, and 0 is every summary of addenda K to S
	 */
	public PortfolioSummary(final long valueStacks, final int itemsPriced, final int itemsTotal,
		@Nullable final Map<MovementWindow, WindowMove> moves, final long currencyGp, final int liveRows)
	{
		this.valueStacks = valueStacks;
		this.itemsPriced = itemsPriced;
		this.itemsTotal = itemsTotal;
		this.currencyGp = Math.max(0L, currencyGp);
		this.liveRows = Math.max(0, liveRows);
		final EnumMap<MovementWindow, WindowMove> copy = new EnumMap<>(MovementWindow.class);
		if (moves != null)
		{
			for (final Map.Entry<MovementWindow, WindowMove> entry : moves.entrySet())
			{
				if (entry.getKey() != null && entry.getValue() != null)
				{
					copy.put(entry.getKey(), entry.getValue());
				}
			}
		}
		this.moves = Collections.unmodifiableMap(copy);
	}

	/**
	 * The whole bank's worth at today's guide prices: the {@link #itemsPriced()} stacks that have one, PLUS the
	 * {@link #currencyGp()} in the bank (P1). The headline figure on the card, and clamped at
	 * {@link Long#MAX_VALUE} like every other sum here.
	 */
	public long valueNow()
	{
		return PortfolioMath.clampedAdd(valueStacks, currencyGp);
	}

	/**
	 * {@link #valueNow()} without the cash: what the STACKS alone are worth - the {@link #itemsPriced()} with a
	 * guide price, which since addendum R includes an untradeable stack valued at the sum of its tradeable parts
	 * (R3), plus any remaining untradeable ones at their High Alchemy value (Q5) - which is the
	 * figure the rows add up to. The card and its tooltip both print {@link #valueNow()} - the whole bank in one
	 * number - so this is for a reader who wants the two halves apart (a test, or a live session subtracting the
	 * cash) rather than for anything drawn.
	 */
	public long valueStacks()
	{
		return valueStacks;
	}

	/**
	 * The bank's coins and platinum tokens in gp ({@code coins + 1,000 x platinum}, P1); 0 when the bank holds no
	 * currency, and 0 for a remembered bank captured before the plugin measured it ({@link BankSnapshot#currencyGp}).
	 */
	public long currencyGp()
	{
		return currencyGp;
	}

	/**
	 * Stacks with a GUIDE price - the market prices behind {@link #valueStacks()}. Cash is not a stack, and
	 * neither is an untradeable stack valued at its High Alchemy value counted here (Q5): an alch value is not a
	 * market price, so such a stack lands in {@link #valueStacks()} and {@link #itemsTotal()} but never here. An
	 * untradeable stack valued at the sum of its TRADEABLE PARTS does count (R3): every gp of that sum is a guide
	 * price, and it moves with them.
	 */
	public int itemsPriced()
	{
		return itemsPriced;
	}

	/**
	 * Every stack the summary was given, priced or not - including the untradeable ones while they are being
	 * counted (Q5). Cash is not one of them.
	 */
	public int itemsTotal()
	{
		return itemsTotal;
	}

	/**
	 * How many of the {@link #itemsPriced()} stacks were valued at a LIVE traded mid rather than at the Jagex
	 * guide price (addendum T, line T5). It was the N of the card tooltip's "N of M stacks live" until addendum
	 * AF took that hover down to the bank value alone; it now reaches a reader through the dev bridge. 0 whenever the
	 * {@code livePrices} switch is off, which is every summary of addenda K to S.
	 */
	public int liveRows()
	{
		return liveRows;
	}

	/** One move per window with a baseline in memory, in window order; unmodifiable, never null. */
	public Map<MovementWindow, WindowMove> moves()
	{
		return moves;
	}

	/** The move for one window, or null when that window has no baseline (the panel prints "1d   -   -"). */
	@Nullable
	public WindowMove move(@Nullable final MovementWindow window)
	{
		return window == null ? null : moves.get(window);
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof PortfolioSummary))
		{
			return false;
		}
		final PortfolioSummary other = (PortfolioSummary) o;
		// The stacks and the cash separately, not their sum: two banks that add up to the same clamped total are
		// still two different banks.
		return valueStacks == other.valueStacks
			&& itemsPriced == other.itemsPriced
			&& itemsTotal == other.itemsTotal
			&& currencyGp == other.currencyGp
			&& liveRows == other.liveRows
			&& moves.equals(other.moves);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(valueStacks, itemsPriced, itemsTotal, currencyGp, liveRows, moves);
	}

	@Override
	public String toString()
	{
		return "PortfolioSummary{valueNow=" + valueNow()
			+ ", currencyGp=" + currencyGp
			+ ", itemsPriced=" + itemsPriced
			+ ", itemsTotal=" + itemsTotal
			+ (liveRows > 0 ? ", liveRows=" + liveRows : "")
			+ ", moves=" + moves.values() + '}';
	}
}

package com.bankpricemovement;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The plugin's only network code (addendum L, contract lines L4, L6, L7, L8, L11): the HISTORY of the Grand
 * Exchange guide price, read off the OSRS wiki page {@value #PAGE}, plus the id-to-wiki-name table that lets a
 * bank item find its row in it. "Now" needs no request at all - it is RuneLite's own guide price from
 * {@code ItemManager} (L1).
 *
 * <p><b>Why the guide table and not the real-time trade API.</b> The first live look (2026-09-08 19:20) showed
 * "Green hat +1,413 gp (+12845.5 %)" while the GE web site said -38 gp (-3 %). Nothing was broken: the wiki's
 * hourly TRADE bucket 24 h earlier held nine units at an average high of 11 gp with no low side. The number every
 * player recognises - in-game GE, the GE web site, RuneLite's own tooltips - is the Jagex daily GUIDE price, and
 * the wiki republishes the whole guide table as {@value #PAGE} (bot "Gaz GEBot", one revision a day, 4,566 names,
 * 126 KB). Its revisions reproduce Jagex's own daily history exactly: 70 of 70 archived values across 14 items
 * and five spans match {@code secure.runescape.com/m=itemdb_oldschool/api/graph/<id>.json} (L-A). Evidence:
 * {@code docs/research/bank-price-movement-calibration-2026-09-08.md} and addendum L.
 *
 * <p><b>Two calls a day, not two per window</b> (L4, L6, L10). Addendum K asked MediaWiki for "the newest
 * revision at or before instant X" and then fetched that revision's bytes - two requests per window, and, worse,
 * the wrong revision about half the time, because the bot publishes at a random hour (L-C). This client instead
 * fetches:
 * <ul>
 * <li>the revision INDEX once ({@link #fetchRevisionIndex}): one call, {@code rvlimit=250}, about 232 days of
 * history in roughly 3.6 KB gzipped. The baseline for any window is then chosen from that list LOCALLY, by
 * calendar day ({@link RevisionRef#pickThen}), with no request at all;</li>
 * <li>the bodies it still needs ({@link #fetchTables}): several whole tables in ONE call through
 * {@code revids=a|b|c}. Measured by the lead: two revisions, 76.6 KB on the wire, 0.37 s. The
 * {@code index.php?action=raw} route of K2 is gone - it is served uncompressed, 126 KB per revision (L-G).</li>
 * </ul>
 * Per-item requests are never made, whatever the bank holds.
 *
 * <p><b>What leaves the client, exactly</b> (B035; the evidence the Hub manifest's {@code warning=} decision
 * rests on - the decision itself is the lead's, beside D15). Three URLs exist in this plugin and NONE of them
 * carries anything derived from the player: {@link #revisionIndexUrl()} is a fixed query for one fixed page
 * title, {@link #tablesUrl(Collection)} carries only wiki revision ids the plugin picked out of that public
 * index, and {@link #MAPPING_URL} is a bare GET of a public table. No item id, no item name, no quantity, no
 * account and no search text is ever a parameter, so every user of this plugin issues BYTE-IDENTICAL requests
 * and the hosts learn only an IP - which the descriptive {@link #USER_AGENT} already discloses - and that this
 * plugin is installed. The bank itself never leaves the client: it is read on the client thread and persisted
 * under {@code ~/.runelite/plugin-data/bank-portfolio-tracker/} only. {@code theRequestUrlsCarryNothingDerivedFromThePlayer}
 * in the tests is what keeps that true as the routes change.
 *
 * <p><b>Why the client and the Gson are injected.</b> RuneLite's {@code @Provides OkHttpClient}
 * ({@code runelite-client/src/main/java/net/runelite/client/RuneLiteModule.java:180-205}, clone tag
 * runelite-parent-1.12.37) is the only client whose requests carry a usable User-Agent: the boot interceptor at
 * {@code RuneLite.java:415-437} stamps {@code RuneLite/<version>-<commit>} when a request has no UA and PREPENDS
 * it to any UA that does not already start with "RuneLite" ({@code RuneLite.java:425-429}), so the wiki sees
 * both the client and this plugin. It also gives us transparent gzip (OkHttp sets {@code Accept-Encoding} itself
 * and decompresses, which is what makes the batched call cheap - so this class never sets that header), the
 * shared disk cache, and the three refusals that arrive as plain {@code IOException}s in {@code onFailure}
 * (client thread, EDT, and the non-LIVE environment block). Constructing an OkHttpClient or a Gson here is a
 * Plugin Hub packaging blocker (C46) as well.
 *
 * <p><b>Why enqueue, never execute.</b> {@code RuneLiteModule.java:185-192} throws for a blocking call made on
 * the client thread or the EDT in EVERY environment, and this client is driven from the panel and from the
 * plugin's scheduled executor. {@code enqueue} hands the work to OkHttp's dispatcher and completes the returned
 * future on that thread, so no caller thread is ever parked. Shape copied from
 * {@code LootTrackerClient.java:84-106} and {@code ConfigClient.java:151-193}; the {@code try (response)} close
 * idiom from {@code WikiDpsManager.java:425-448}.
 *
 * <p><b>Why every failure is one exception type</b> (L11, failure shapes L-G). A MediaWiki error arrives as
 * {@code {"error": {...}}} with HTTP 200, so neither the status nor the body alone is the failure test. Non-2xx,
 * an {@code error} member, a body that is not the expected shape, a page that is {@code missing}, a batch in
 * which no revision survived validation, an empty table and a transport {@code IOException} all complete the
 * future exceptionally with a {@link WikiPriceException}; the future never completes with null. Callers keep
 * their last good baseline and carry on (design D9, fail soft). A window whose target simply predates the page
 * is NOT a failure and never reaches here: {@code pickThen} answers null and the panel says "No 180d history".
 *
 * <p>This class holds no cache and no history: staleness, scheduling and one-in-flight-per-window are
 * {@code PriceService}'s rules (L10). Its only state is {@link #setEnabled(boolean)}, the list of calls still on
 * the wire for {@link #cancelInFlight()}, and the "a failure has already been logged loudly" flag.
 */
public class GuidePriceClient
{
	private static final Logger log = LoggerFactory.getLogger(GuidePriceClient.class);

	/** The wiki's MediaWiki API endpoint - the revision index (L4) and the batched bodies (L6) both go here. */
	public static final String API_URL = "https://oldschool.runescape.wiki/api.php";

	/**
	 * The guide-price table page. Its content is a flat JSON object of item name to guide gp plus two
	 * {@code %...%} bookkeeping keys (measured 2026-09-08: 4,566 names, 125,696 bytes).
	 */
	public static final String PAGE = "Module:GEPrices/data.json";

	/**
	 * The id-to-name table (K3, restated by L8). It is the PRIMARY name source, not a fallback: {@code /mapping}
	 * has zero id-to-name collisions and the guide table's keys are a strict subset of its names, and
	 * {@code table[mapping name(id)]} equalled the GE price for 28 of 28 probed ids (L-F).
	 */
	public static final String MAPPING_URL = "https://prices.runescape.wiki/api/v1/osrs/mapping";

	/**
	 * The descriptive User-Agent both wiki hosts' policies ask for; unchanged since the first build so an
	 * operator reading the wiki's logs sees one plugin across every change of route. RuneLite prepends its own
	 * {@code RuneLite/<version>-<commit>} because this string does not start with "RuneLite"
	 * ({@code RuneLite.java:425-429}).
	 */
	public static final String USER_AGENT = "bank-portfolio-tracker (RuneLite plugin; github.com/2hBuilds)";

	/** Header name, spelled once so the request builder and the tests cannot drift apart. */
	public static final String USER_AGENT_HEADER = "User-Agent";

	/**
	 * How many revisions the index asks for (L4). 250 is the anonymous {@code rvlimit} ceiling, and no
	 * continuation is followed, so ONE call sees at most this many revisions however far back the page goes.
	 *
	 * <p>The margin is thinner than it looks: 250 revisions is about 232 days at the one bot run a day L-C
	 * measured, against a longest window of 180 - but only about 178 days at 1.4 revisions a day, which a stretch
	 * of maintenance edits produces (the live index on this machine already averages 1.11). Because a shortfall
	 * would show as "No 180d history", the same sentence an honestly short page gets,
	 * {@code PriceService.finishIndex} MERGES each fetch with the index it already holds rather than replacing it,
	 * so a long-running install keeps reach it has already seen, and {@code PriceService.reconcile} logs the
	 * ambiguity once per session.
	 */
	public static final int INDEX_LIMIT = 250;

	/**
	 * How many revision ids one batched body call may carry (L6). 50 is MediaWiki's own {@code revids} ceiling
	 * for an anonymous client; the service never needs more than six (the newest table plus one per window).
	 */
	public static final int MAX_REVIDS = 50;

	/** The table's own day marker, and the authoritative one (L7, evidence L-E). */
	public static final String LAST_UPDATE_KEY = "%LAST_UPDATE%";

	/** Keys in the guide table that are bookkeeping, not items: {@code %LAST_UPDATE%}, {@code %LAST_UPDATE_F%}. */
	private static final char BOOKKEEPING_PREFIX = '%';

	/**
	 * How far BEHIND its own save time a body's {@code %LAST_UPDATE%} may be before the body is refused (L7).
	 * Two days: a human maintenance edit republishes the previous day's table (L-E), which is one day behind and
	 * must be accepted so L5's retry can recognise it; anything older than that is not this page's data.
	 */
	private static final long MAX_DATA_LAG_SECONDS = 48L * 60L * 60L;

	/**
	 * How far AHEAD of its own save time a body's {@code %LAST_UPDATE%} may be (L7). Five minutes of clock skew:
	 * a table cannot be stamped after the edit that published it, so anything further ahead is a body that does
	 * not belong to this revision.
	 */
	private static final long MAX_DATA_LEAD_SECONDS = 300L;

	/** Error and diagnostic text is cut to this many characters before it reaches a message or the log. */
	private static final int MAX_DETAIL_CHARS = 200;

	private final OkHttpClient client;
	private final Gson gson;

	/**
	 * Developer-mode switch behind the dev bridge's {@code wiki=on|off} verb (L13): when false every fetch fails
	 * immediately without touching the network, so the "no history" statuses can be exercised in a live client.
	 * Volatile because it is written from the bridge/EDT and read on whichever thread starts a fetch. Never
	 * flipped by user-facing code.
	 */
	private volatile boolean enabled = true;

	/**
	 * Every call enqueued and not yet answered, so {@link #cancelInFlight()} can drop them when the plugin stops
	 * (B012). Copy-on-write: at most a handful of entries, written from whichever thread starts a fetch and from
	 * OkHttp's dispatcher as each answers.
	 */
	private final List<Call> inFlight = new CopyOnWriteArrayList<>();

	/** Whether {@link #report} has already logged a failure loudly this session (B010). */
	private volatile boolean reported;

	public GuidePriceClient(final OkHttpClient client, final Gson gson)
	{
		if (client == null)
		{
			throw new IllegalArgumentException("client is required (inject RuneLite's OkHttpClient)");
		}
		if (gson == null)
		{
			throw new IllegalArgumentException("gson is required (inject RuneLite's Gson)");
		}
		this.client = client;
		this.gson = gson;
	}

	// ---------------------------------------------------------------- L4: the revision index

	/**
	 * The page's recent revision history, newest first - one call, no content (L4).
	 *
	 * <p>This is what makes calendar-day selection possible at all: with the whole history in hand, the baseline
	 * for any window is {@link RevisionRef#pickThen} on a date, decided locally and instantly, and a window
	 * change costs a request only when the chosen revision is one the store has not already got (L10).
	 *
	 * @param nowMillis the caller's clock; not used by the request itself, but taken so the SERVICE's settable
	 *                  clock - never {@code System.currentTimeMillis()} in here - decides when the index is
	 *                  stale (six hours, L4) and what stamp {@code revindex.json} is written with
	 * @return a future completing with the history, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<List<RevisionRef>> fetchRevisionIndex(final long nowMillis)
	{
		log.debug("bank-portfolio-tracker: fetching the guide-table revision index at {}", nowMillis);
		return request(revisionIndexUrl(), this::parseRevisionIndex);
	}

	// ---------------------------------------------------------------- L6: the batched bodies

	/**
	 * The full guide table of every named revision, in ONE request (L6).
	 *
	 * <p>MediaWiki serves several revisions of a page from a single {@code revids=} query and the response is
	 * gzipped in flight, which is the whole reason this replaced K2's per-revision {@code action=raw} reads: the
	 * lead measured two whole tables at 76.6 KB on the wire in 0.37 s, against 126 KB uncompressed EACH the old
	 * way (L-G). A steady day therefore costs one index call and one body call (L10).
	 *
	 * <p>A revision that comes back unusable - no content, a table with no prices, or a {@code %LAST_UPDATE%}
	 * outside the window its own save time allows (L7) - is left OUT of the map rather than failing the batch:
	 * the caller keeps the stored baseline for that window and every other window still gets its table. Only a
	 * batch in which NOTHING survived fails, because that is a route change, not one odd revision. A revision
	 * the wiki declined to include at all (a {@code badrevids} entry, or a {@code continue} the caller is not
	 * asked to follow) is simply absent for the same reason: the map is what arrived, and the caller reads it by
	 * revision id rather than by position.
	 *
	 * @param revIds    the revisions to read; nulls and non-positive ids are dropped and duplicates collapse
	 * @param nowMillis stamped onto every snapshot as {@code fetchedAtMillis}; passed in rather than read here so
	 *                  the service's settable clock governs every staleness decision (C27)
	 * @return a future completing with revision id to table, or exceptionally with {@link WikiPriceException} -
	 *         including when no id is usable, or when more than {@value #MAX_REVIDS} are asked for at once
	 */
	public CompletableFuture<Map<Long, GuideSnapshot>> fetchTables(final Collection<Long> revIds, final long nowMillis)
	{
		final List<Long> ids = usableIds(revIds);
		if (ids.isEmpty())
		{
			// Deliberately a failure and not an empty success: a caller that asked for nothing has a bug, and an
			// empty map would look like "every requested revision was fetched" to the code that stores baselines.
			return failed(new WikiPriceException("no usable revision ids to fetch"));
		}

		if (ids.size() > MAX_REVIDS)
		{
			return failed(new WikiPriceException(
				"a batched revision fetch may carry at most " + MAX_REVIDS + " ids, was asked for " + ids.size()));
		}

		log.debug("bank-portfolio-tracker: fetching {} guide table(s) in one call: {}", ids.size(), ids);
		return request(tablesUrl(ids), body -> parseTables(body, nowMillis));
	}

	/**
	 * The wiki's id-to-name table (L8), fetched at most weekly by the caller and persisted as {@code mapping.json}.
	 *
	 * @param nowMillis unused by the request itself; present so the caller's clock, not this class, decides what
	 *                  "weekly" means and so the signature matches the other two fetches
	 * @return a future completing with item id to wiki name, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<Map<Integer, String>> fetchMapping(final long nowMillis)
	{
		log.debug("bank-portfolio-tracker: fetching the id/name mapping at {}", nowMillis);
		return request(MAPPING_URL, this::parseMapping);
	}

	/**
	 * Developer-mode kill switch for the {@code wiki=on|off} bridge verb (L13); true is the shipped state.
	 * User-facing behaviour must never depend on this (workspace rule: no user feature may need a dev hook).
	 */
	public void setEnabled(final boolean enabled)
	{
		this.enabled = enabled;
	}

	/** @see #setEnabled(boolean) */
	public boolean isEnabled()
	{
		return enabled;
	}

	// ---------------------------------------------------------------- the exact URLs (L4, L6)

	/**
	 * The revision index query of L4, verbatim:
	 * {@code api.php?action=query&prop=revisions&titles=Module:GEPrices/data.json&rvlimit=250&rvdir=older&rvprop=ids|timestamp|user|comment&format=json&formatversion=2}.
	 *
	 * <p>{@code user} and {@code comment} are asked for because they are what separates the bot's daily run from
	 * a human's maintenance edit ({@link RevisionRef#isBot()}, L-E), and {@code rvdir=older} is what makes the
	 * answer start at the newest revision.
	 *
	 * <p>Assembled as a literal string rather than through {@code HttpUrl.Builder} because OkHttp's query
	 * canonicaliser leaves {@code :}, {@code /} and {@code |} alone (they are legal query characters, RFC 3986
	 * {@code pchar / "/" / "?"}) while {@code addQueryParameter} would still be a second spelling of the same
	 * thing; one literal is the shape a maintainer can paste into curl to reproduce a bug.
	 */
	static String revisionIndexUrl()
	{
		return API_URL
			+ "?action=query"
			+ "&prop=revisions"
			+ "&titles=" + PAGE
			+ "&rvlimit=" + INDEX_LIMIT
			+ "&rvdir=older"
			+ "&rvprop=ids|timestamp|user|comment"
			+ "&format=json"
			+ "&formatversion=2";
	}

	/**
	 * The batched content query of L6:
	 * {@code api.php?action=query&prop=revisions&revids=<a>|<b>&rvprop=ids|timestamp|content&rvslots=main&format=json&formatversion=2}.
	 *
	 * <p>{@code rvslots=main} is not optional: since MediaWiki 1.32 a revision's text lives in a slot, and asking
	 * for {@code content} without naming a slot answers a deprecation warning instead of the bytes.
	 * {@code timestamp} rides along because {@link #parseTables} needs each revision's own save time to bound the
	 * {@code %LAST_UPDATE%} check (L7).
	 */
	static String tablesUrl(final Collection<Long> revIds)
	{
		final StringBuilder ids = new StringBuilder();
		for (final Long revId : revIds)
		{
			if (ids.length() > 0)
			{
				ids.append('|');
			}
			ids.append(revId);
		}

		return API_URL
			+ "?action=query"
			+ "&prop=revisions"
			+ "&revids=" + ids
			+ "&rvprop=ids|timestamp|content"
			+ "&rvslots=main"
			+ "&format=json"
			+ "&formatversion=2";
	}

	// ---------------------------------------------------------------- parsers (package-private, pure, L4/L6)

	/**
	 * The revision index as a newest-first list (L4). Shape under {@code formatversion=2}:
	 * {@code {"batchcomplete":true,"query":{"pages":[{"pageid":180412,"title":"Module:GEPrices/data.json",
	 * "revisions":[{"revid":15334656,"parentid":15333448,"timestamp":"2026-09-08T09:25:12Z","user":"Gaz GEBot",
	 * "comment":"GE update"}, ...]}]}}}.
	 *
	 * <p>{@code pages} is an ARRAY under {@code formatversion=2} and an object keyed by page id in the default
	 * output format; both are read, because the wiki could switch its default and a silently empty index is
	 * worse than a loud failure. One revision that cannot be used - no id, or a timestamp that will not parse,
	 * without which no calendar day can be derived - is skipped; an index with nothing usable in it is fatal.
	 *
	 * <p>The result is SORTED newest-first rather than trusted to arrive that way, so a change of default
	 * ordering at the wiki could only make the dev bridge's echo untidy. {@link RevisionRef#pickThen} does not
	 * depend on the order either way.
	 *
	 * @throws WikiPriceException on a non-object body, an {@code error} member, a missing page or no usable
	 *                            revision at all
	 */
	List<RevisionRef> parseRevisionIndex(final String json) throws WikiPriceException
	{
		final JsonObject root = readObject(json);
		failOnErrorMember(root);

		final List<RevisionRef> index = new ArrayList<>();
		for (final JsonObject revision : revisionsOf(root))
		{
			final Long revId = optLong(revision, "revid");
			if (revId == null || revId <= 0L)
			{
				continue;
			}

			final Long editSeconds = optInstantSeconds(revision);
			if (editSeconds == null)
			{
				continue;
			}

			index.add(new RevisionRef(revId, editSeconds, memberText(revision, "user"),
				memberText(revision, "comment")));
		}

		if (index.isEmpty())
		{
			throw new WikiPriceException("the wiki listed no usable revisions of " + PAGE);
		}

		index.sort(RevisionRef.NEWEST_FIRST);
		return index;
	}

	/**
	 * Every revision body in a batched answer, keyed by revision id (L6). Shape is
	 * {@link #parseRevisionIndex}'s, with the text under
	 * {@code query.pages[0].revisions[i].slots.main.content} and several revisions of the one page in the array.
	 *
	 * <p>Each body is validated before it is kept (L7): its {@code %LAST_UPDATE%} must sit between 48 hours
	 * before and 5 minutes after the revision's own save time. That window is what a human maintenance edit
	 * looks like - it republishes the previous day's table under a later timestamp (L-E) - while a body with no
	 * marker at all, or one from another page entirely, falls outside it. A revision that fails is skipped with
	 * a log line, never guessed at: L5's "is this really day T's table?" step compares
	 * {@code GuideSnapshot.dataDay()} against the date it asked for, and a marker invented here would defeat it.
	 *
	 * @param nowMillis stamped onto every snapshot as {@code fetchedAtMillis}
	 * @throws WikiPriceException on a non-object body, an {@code error} member, or a batch in which no revision
	 *                            survived (a route change, as opposed to one odd revision)
	 */
	Map<Long, GuideSnapshot> parseTables(final String json, final long nowMillis) throws WikiPriceException
	{
		final JsonObject root = readObject(json);
		failOnErrorMember(root);

		final Map<Long, GuideSnapshot> tables = new LinkedHashMap<>();
		for (final JsonObject revision : revisionsOf(root))
		{
			final Long revId = optLong(revision, "revid");
			final Long editSeconds = optInstantSeconds(revision);
			if (revId == null || revId <= 0L || editSeconds == null)
			{
				continue;
			}

			final String content = contentOf(revision);
			if (content == null || content.trim().isEmpty())
			{
				log.debug("bank-portfolio-tracker: revision {} came back without content", revId);
				continue;
			}

			final JsonObject body;
			final Map<String, Long> prices;
			try
			{
				body = readObject(content);
				prices = tableOf(body);
			}
			catch (final WikiPriceException e)
			{
				log.debug("bank-portfolio-tracker: revision {} carried no usable table: {}", revId, e.getMessage());
				continue;
			}

			final long dataSeconds = dataSecondsOf(body);
			if (dataSeconds < editSeconds - MAX_DATA_LAG_SECONDS || dataSeconds > editSeconds + MAX_DATA_LEAD_SECONDS)
			{
				// No day marker, or one that cannot belong to this revision. Guessing a day here would produce a
				// row labelled with a date its numbers are not from - the exact defect addendum L exists to fix.
				log.debug("bank-portfolio-tracker: revision {} has a {} of {} against an edit time of {} - skipped",
					revId, LAST_UPDATE_KEY, dataSeconds, editSeconds);
				continue;
			}

			tables.put(revId, new GuideSnapshot(revId, editSeconds, dataSeconds, nowMillis, prices));
		}

		if (tables.isEmpty())
		{
			throw new WikiPriceException("the wiki returned no usable guide tables");
		}
		return tables;
	}

	/**
	 * One revision of {@value #PAGE} as folded item name to guide gp. Content shape (calibration doc):
	 * {@code {"Green hat":1086, "Abyssal whip":799012, ..., "%LAST_UPDATE%":1788859349,
	 * "%LAST_UPDATE_F%":"08 September 2026 09:22:29 (UTC)"}}.
	 *
	 * <p>Keys beginning with {@code %} are the page's own bookkeeping and are skipped; a value that is not a
	 * number is skipped rather than fatal, so one odd entry cannot cost the other four and a half thousand. Every
	 * surviving key is folded through {@code GuideSnapshot.key} (L8) - the wiki case-renamed 81 keys in August
	 * 2026, so a byte-exact table loses three of the user's bank items on any window of 30 days or more.
	 *
	 * <p>The table's "unpriced" sentinel (2,147,483,646) is left in the map here and dropped by
	 * {@link GuideSnapshot}: the model applies that rule once, for every construction path, including a baseline
	 * read back off disk.
	 *
	 * <p>An empty result IS fatal: a JSON-shaped body with no prices in it means the page moved or the revision
	 * was deleted, and publishing an empty baseline would quietly show "-" on every row as though the plugin
	 * were working.
	 *
	 * @throws WikiPriceException on a non-object body or a table with no prices in it
	 */
	Map<String, Long> parseGuideTable(final String json) throws WikiPriceException
	{
		return tableOf(readObject(json));
	}

	/**
	 * The {@code /mapping} array as item id to wiki name. Shape:
	 * {@code [{"id":4151,"name":"Abyssal whip","examine":"...","members":true,...}, ...]}, about 4,660 entries.
	 *
	 * <p>Only {@code id} and {@code name} are read; every other member is ignored so a new field cannot break a
	 * release. An entry that is not an object, or that lacks either member, is skipped. Names are kept in the
	 * wiki's own spelling - the fold to a table key happens at lookup time ({@code GuideSnapshot.get}) so the
	 * mapping stays readable on disk and in the dev bridge's echo.
	 *
	 * <p>An empty result is fatal for the same reason as {@link #parseGuideTable(String)}: without names, nothing
	 * can be priced.
	 *
	 * @throws WikiPriceException on a body that is not a JSON array, or an array with no usable entries
	 */
	Map<Integer, String> parseMapping(final String json) throws WikiPriceException
	{
		final JsonElement root = readElement(json);
		if (!root.isJsonArray())
		{
			throw new WikiPriceException("the wiki mapping response was not a JSON array");
		}

		final JsonArray array = root.getAsJsonArray();
		final Map<Integer, String> names = new LinkedHashMap<>();
		for (final JsonElement element : array)
		{
			if (element == null || !element.isJsonObject())
			{
				continue;
			}

			final JsonObject entry = element.getAsJsonObject();
			final Long id = optLong(entry, "id");
			final String name = memberText(entry, "name");
			if (id == null || name == null || name.isEmpty() || id <= 0L || id > Integer.MAX_VALUE)
			{
				continue;
			}
			names.put(id.intValue(), name);
		}

		if (names.isEmpty())
		{
			throw new WikiPriceException("the wiki mapping table carried no entries");
		}
		return names;
	}

	// ---------------------------------------------------------------- internals

	/**
	 * Builds the request, enqueues it and adapts OkHttp's callback pair onto one future. Nothing in here blocks:
	 * the method returns as soon as the call is queued. The response is CLOSED before the future completes, so a
	 * dependent that starts another request never runs while a body is still open.
	 *
	 * <p><b>The future is completed on every path, including an {@link Error}</b> (B006). OkHttp 3.14.9 sets
	 * {@code signalledCallback} before it invokes {@code onResponse}, so a Throwable thrown from inside the
	 * callback is rethrown on the dispatcher thread and never routed to {@code onFailure}: the future would then
	 * never complete, and {@code PriceService}'s in-flight flag would stay claimed for the rest of the session -
	 * the whole history subsystem stopping with nothing on screen and nothing in the log. A parse of six 4,566-entry
	 * tables is exactly the shape that can raise {@code OutOfMemoryError} on a small heap, or
	 * {@code StackOverflowError} on a hostile body, so the catch is on {@code Throwable}, the future is completed
	 * FIRST, and an {@code Error} is rethrown afterwards for the JVM's own handling. {@link #fail} and
	 * {@link #failAndRethrow} are that order, spelled once: every failure path here goes through them.
	 *
	 * <p>The call is remembered for {@link #cancelInFlight()} until it answers.
	 */
	private <T> CompletableFuture<T> request(final String url, final BodyParser<T> parser)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();

		if (!enabled)
		{
			future.completeExceptionally(new WikiPriceException("wiki fetches are switched off (developer mode)"));
			return future;
		}

		final Request request;
		try
		{
			request = new Request.Builder()
				.url(url)
				.header(USER_AGENT_HEADER, USER_AGENT)
				.get()
				.build();
		}
		catch (final RuntimeException e)
		{
			// IllegalArgumentException from HttpUrl for a url this class built itself: a programming error, but
			// it must not escape onto the caller's thread (the service's executor) as an unchecked throw.
			future.completeExceptionally(new WikiPriceException("could not build the wiki request for " + url, e));
			return future;
		}

		try
		{
			final Call call = client.newCall(request);
			inFlight.add(call);
			future.whenComplete((value, error) -> inFlight.remove(call));
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(final Call call, final IOException e)
				{
					// Everything the injected client refuses lands here: no network, DNS, TLS, and the three
					// RuneLiteModule interceptor throws (client thread, EDT, non-LIVE environment domain block).
					fail(future, url, new WikiPriceException("wiki request failed: " + messageOf(e), e));
				}

				@Override
				public void onResponse(final Call call, final Response response)
				{
					final T value;
					try (Response closing = response)
					{
						final String body = bodyText(closing);
						if (!closing.isSuccessful())
						{
							fail(future, url, httpFailure(closing.code(), body));
							return;
						}
						value = parser.parse(body);
					}
					catch (final IOException e)
					{
						fail(future, url, e instanceof WikiPriceException
							? (WikiPriceException) e
							: new WikiPriceException("could not read the wiki response: " + messageOf(e), e));
						return;
					}
					catch (final Throwable t)
					{
						failAndRethrow(future, url, new WikiPriceException(
							"could not parse the wiki response: " + messageOf(t), t), t);
						return;
					}
					future.complete(value);
				}
			});
		}
		catch (final Throwable t)
		{
			// Throwable for the same reason: this runs on the service's executor, whose own guard used to stop at
			// RuntimeException, and an unanswered future is a flag claimed for the session.
			failAndRethrow(future, url, new WikiPriceException("could not queue the wiki request: " + messageOf(t), t), t);
		}

		return future;
	}

	/**
	 * The one way a request fails: {@link #report} the failure, THEN complete the future with it. Every failure
	 * site in {@link #request} goes through here, so the once-per-session warning has a single gate and no path
	 * can leave the future unanswered - which is the whole of B006, since an unanswered future leaves
	 * {@code PriceService}'s in-flight flag claimed for the rest of the session.
	 */
	private <T> void fail(final CompletableFuture<T> future, final String url, final WikiPriceException failure)
	{
		report(url, failure);
		future.completeExceptionally(failure);
	}

	/**
	 * {@link #fail} for a {@code catch} on {@link Throwable}: the future is completed FIRST and an {@link Error}
	 * is rethrown afterwards, for the JVM's own handling. The order is the point (class note above) - OkHttp
	 * 3.14.9 rethrows on its dispatcher thread rather than routing to {@code onFailure}, so a rethrow before the
	 * completion would strand the caller.
	 *
	 * @param cause what was caught; rethrown only when it is an {@link Error}
	 */
	private <T> void failAndRethrow(final CompletableFuture<T> future, final String url,
		final WikiPriceException failure, final Throwable cause)
	{
		fail(future, url, failure);
		if (cause instanceof Error)
		{
			throw (Error) cause;
		}
	}

	/**
	 * Cancels every call still on the wire. Called from {@code PriceService.stop()} when the plugin is switched
	 * off or its config profile changes: a batched body download is most of a megabyte, and neither finishing it
	 * nor parsing six tables afterwards can produce anything but a discarded result. {@code Call.cancel()} is safe
	 * from any thread; a cancelled call's {@code onFailure} completes its future as an ordinary failure, which the
	 * stopped service drops.
	 */
	public void cancelInFlight()
	{
		for (final Call call : new ArrayList<>(inFlight))
		{
			inFlight.remove(call);
			try
			{
				call.cancel();
			}
			catch (final RuntimeException e)
			{
				log.debug("bank-portfolio-tracker: a wiki call refused to cancel", e);
			}
		}
	}

	/**
	 * Logs one failure. The FIRST of the session is a warning carrying the url and, where the wiki answered with
	 * a status, that status; every one after it is debug (B010).
	 *
	 * <p>Why the first one is loud: RuneLite logs at INFO, so before this every network failure in the plugin -
	 * an outage, a proxy serving HTML, the 403 the prices API returns to a default User-Agent - left NOTHING in
	 * the user's client.log, while every DISK failure in the same plugin was a warning. A bug report then could
	 * not tell a 403 from a DNS failure without asking the user to reproduce with debug logging on. Why only the
	 * first: an outage lasts hours and the tick is thirty minutes, and a repeated line is noise in someone else's
	 * log.
	 */
	private void report(final String url, final WikiPriceException failure)
	{
		final String status = failure.hasHttpCode() ? " (HTTP " + failure.getHttpCode() + ")" : "";
		if (reported)
		{
			log.debug("bank-portfolio-tracker: wiki request to {} failed{}", url, status, failure);
			return;
		}
		reported = true;
		log.warn("bank-portfolio-tracker: wiki request to {} failed{} - movement will show stored data until it recovers",
			url, status, failure);
	}

	/** A future that has already failed - the shape {@link #fetchTables} refuses a bad argument with. */
	private static <T> CompletableFuture<T> failed(final WikiPriceException failure)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();
		future.completeExceptionally(failure);
		return future;
	}

	/**
	 * The revision ids worth asking for: non-null, positive, in the caller's order and each named once. A
	 * duplicate would be answered once by MediaWiki anyway; collapsing it here keeps the {@code revids=} count
	 * honest against {@value #MAX_REVIDS}.
	 */
	private static List<Long> usableIds(final Collection<Long> revIds)
	{
		final Set<Long> unique = new LinkedHashSet<>();
		if (revIds != null)
		{
			for (final Long revId : revIds)
			{
				if (revId != null && revId > 0L)
				{
					unique.add(revId);
				}
			}
		}
		return new ArrayList<>(unique);
	}

	/**
	 * Every revision object in a {@code query} answer, across every page it lists. Reads both the
	 * {@code formatversion=2} array of pages and the default object keyed by page id; a page that is
	 * {@code missing} simply has no revisions and contributes nothing.
	 *
	 * @throws WikiPriceException when there is no {@code query} object at all (a shape this parser cannot read)
	 */
	private static List<JsonObject> revisionsOf(final JsonObject root) throws WikiPriceException
	{
		final JsonElement query = root.get("query");
		if (query == null || !query.isJsonObject())
		{
			throw new WikiPriceException("the wiki revision response has no query object");
		}

		final List<JsonObject> revisions = new ArrayList<>();
		final JsonElement pages = query.getAsJsonObject().get("pages");
		if (pages == null)
		{
			return revisions;
		}

		if (pages.isJsonObject())
		{
			for (final Map.Entry<String, JsonElement> page : pages.getAsJsonObject().entrySet())
			{
				collectRevisions(page.getValue(), revisions);
			}
		}
		else if (pages.isJsonArray())
		{
			for (final JsonElement page : pages.getAsJsonArray())
			{
				collectRevisions(page, revisions);
			}
		}
		return revisions;
	}

	/** Appends one page's {@code revisions} array; a missing page or a malformed entry adds nothing. */
	private static void collectRevisions(final JsonElement page, final List<JsonObject> into)
	{
		if (page == null || !page.isJsonObject())
		{
			return;
		}

		final JsonElement revisions = page.getAsJsonObject().get("revisions");
		if (revisions == null || !revisions.isJsonArray())
		{
			return;
		}

		for (final JsonElement revision : revisions.getAsJsonArray())
		{
			if (revision != null && revision.isJsonObject())
			{
				into.add(revision.getAsJsonObject());
			}
		}
	}

	/**
	 * One revision's wikitext. {@code slots.main.content} is the {@code rvslots=main} shape this client asks for;
	 * the bare {@code content} and the pre-1.32 {@code *} members are read as well so a change of API default
	 * cannot silently empty every table.
	 */
	private static String contentOf(final JsonObject revision)
	{
		final JsonElement slots = revision.get("slots");
		if (slots != null && slots.isJsonObject())
		{
			final JsonElement main = slots.getAsJsonObject().get("main");
			if (main != null && main.isJsonObject())
			{
				final String text = rawText(main.getAsJsonObject().get("content"));
				if (text != null)
				{
					return text;
				}
			}
		}

		final String direct = rawText(revision.get("content"));
		return direct != null ? direct : rawText(revision.get("*"));
	}

	/** A JSON string member as its whole text - unlike {@link #memberText} this is never truncated. */
	private static String rawText(final JsonElement value)
	{
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return value.getAsString();
		}
		catch (final RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * The prices out of one parsed table body, folded through {@code GuideSnapshot.key} and without the
	 * {@code %...%} bookkeeping.
	 *
	 * @throws WikiPriceException when nothing in the object is a price
	 */
	private static Map<String, Long> tableOf(final JsonObject root) throws WikiPriceException
	{
		final Map<String, Long> prices = new HashMap<>();
		for (final Map.Entry<String, JsonElement> entry : root.entrySet())
		{
			final String name = entry.getKey();
			if (name == null || name.isEmpty() || name.charAt(0) == BOOKKEEPING_PREFIX)
			{
				continue;
			}

			final Long price = asLong(entry.getValue());
			if (price == null)
			{
				continue;
			}

			final String folded = GuideSnapshot.key(name);
			if (folded != null && !folded.isEmpty())
			{
				prices.put(folded, price);
			}
		}

		if (prices.isEmpty())
		{
			throw new WikiPriceException("the wiki guide table carried no prices");
		}
		return prices;
	}

	/**
	 * The body's {@code %LAST_UPDATE%} in unix seconds, or 0 when it is absent or not a number - which
	 * {@link #parseTables} treats as "outside the allowed window" and refuses (L7). Never guessed from the
	 * revision timestamp: the whole point of the marker is that the two disagree on 4 of 38 sampled bodies.
	 */
	private static long dataSecondsOf(final JsonObject root)
	{
		final Long seconds = optLong(root, LAST_UPDATE_KEY);
		return seconds == null ? 0L : seconds;
	}

	/**
	 * A revision's {@code timestamp} as unix seconds, or null when it is absent or not ISO-8601. Null costs the
	 * revision its place in the index or the batch: without a save time there is no calendar day to select on
	 * and no window to validate a body's day marker against.
	 */
	private static Long optInstantSeconds(final JsonObject revision)
	{
		final String timestamp = memberText(revision, "timestamp");
		if (timestamp == null)
		{
			return null;
		}

		try
		{
			return Instant.parse(timestamp).getEpochSecond();
		}
		catch (final DateTimeParseException e)
		{
			log.debug("bank-portfolio-tracker: revision timestamp is not ISO-8601: {}", timestamp);
			return null;
		}
	}

	/**
	 * MediaWiki reports an error as {@code {"error":{"code":"...","info":"..."}}} with HTTP 200, so the body -
	 * not the status - is the failure test. Checked before anything else is read out of the envelope.
	 */
	private void failOnErrorMember(final JsonObject root) throws WikiPriceException
	{
		final String error = memberText(root, "error");
		if (error != null)
		{
			throw new WikiPriceException("wiki error: " + error);
		}
	}

	/** Reads the whole body as text, tolerating a null body (a HEAD-shaped or synthetic response). */
	private static String bodyText(final Response response) throws IOException
	{
		final ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	/**
	 * A body as a {@link JsonObject}, or a failure. Parsed as {@link JsonElement} first so a non-object body (an
	 * array, or a bare string from Gson's lenient reader) becomes a clean failure rather than a
	 * ClassCastException out of {@code fromJson(json, JsonObject.class)}.
	 */
	private JsonObject readObject(final String json) throws WikiPriceException
	{
		final JsonElement root = readElement(json);
		if (!root.isJsonObject())
		{
			throw new WikiPriceException("wiki response was not a JSON object");
		}
		return root.getAsJsonObject();
	}

	/**
	 * A body as any JSON value, with the INJECTED Gson - constructing a Gson or a GsonBuilder in plugin code is
	 * a Plugin Hub blocker (C46), and Gson 2.8.5 (the version the pinned client ships) has no static
	 * {@code JsonParser.parseString} to reach for instead.
	 */
	private JsonElement readElement(final String json) throws WikiPriceException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new WikiPriceException("empty response from the wiki");
		}

		final JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (final RuntimeException e)
		{
			throw new WikiPriceException("malformed JSON from the wiki: " + messageOf(e), e);
		}

		if (root == null || root.isJsonNull())
		{
			// A literal "null" body: JSON-shaped, but there is nothing in it for any caller to read.
			throw new WikiPriceException("wiki response was a JSON null");
		}
		return root;
	}

	/**
	 * A nullable numeric member as a {@code Long}. Guide prices, revision ids and unix seconds all exceed what an
	 * {@code int} comfortably holds (a revid is already past 15 million and a price past two billion), so every
	 * number is read as a long. A member that is absent, JSON null, or not a number reads as null.
	 */
	private static Long optLong(final JsonObject object, final String key)
	{
		return object == null ? null : asLong(object.get(key));
	}

	/** One JSON value as a {@code Long}, or null when it is absent, null, or not a number. Never throws. */
	private static Long asLong(final JsonElement value)
	{
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return Long.valueOf(value.getAsLong());
		}
		catch (final RuntimeException e)
		{
			// A boolean primitive, or a string that is not a number: skip the entry, never fail the refresh.
			return null;
		}
	}

	/** A member rendered as short text, or null when it is absent or JSON null. Never throws. */
	private static String memberText(final JsonObject root, final String key)
	{
		final JsonElement value = root.get(key);
		if (value == null || value.isJsonNull())
		{
			return null;
		}
		if (value.isJsonPrimitive())
		{
			try
			{
				return truncate(value.getAsString());
			}
			catch (final RuntimeException e)
			{
				// fall through to the structural rendering
			}
		}
		return truncate(value.toString());
	}

	/**
	 * A non-2xx answer. The status is carried on the exception because 403 is diagnosable on its own (both wiki
	 * hosts pre-emptively block default user agents, research C3) while the body for it is unhelpful.
	 */
	private WikiPriceException httpFailure(final int code, final String body)
	{
		String detail = null;
		try
		{
			detail = memberText(readObject(body), "error");
		}
		catch (final WikiPriceException e)
		{
			// A non-JSON error body (an HTML error page, cloudflare's one-byte 403) is normal here - the status
			// is the information.
		}

		final String message = detail == null
			? "wiki request failed with HTTP " + code
			: "wiki request failed with HTTP " + code + ": " + detail;
		return new WikiPriceException(message, code);
	}

	/** {@code Throwable.getMessage()} is null for plenty of IO failures; fall back to the type name. */
	private static String messageOf(final Throwable t)
	{
		final String message = t.getMessage();
		return truncate(message == null || message.isEmpty() ? t.getClass().getSimpleName() : message);
	}

	private static String truncate(final String text)
	{
		if (text == null)
		{
			return null;
		}
		return text.length() <= MAX_DETAIL_CHARS ? text : text.substring(0, MAX_DETAIL_CHARS) + "...";
	}

	/**
	 * The one thing that differs between the three requests once the bytes are in hand. A tiny interface rather
	 * than a {@code Function} because the parsers throw a checked {@link WikiPriceException}.
	 */
	@FunctionalInterface
	private interface BodyParser<T>
	{
		T parse(String body) throws WikiPriceException;
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Insets;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.util.Locale;
import java.util.Objects;
import javax.annotation.Nullable;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * One row of the History view's list of days (addendum AU, plan 7.2 items 3, 4 and 11; contract section 6).
 *
 * <p>A day WITH a reading is a {@value #HEIGHT} px card with a coloured left edge - green for a rise, the rows' red
 * for a fall, grey for no change or the first reading - and three columns of two lines:
 * <pre>
 *   Sat 26 Sep            736m            +0.4%
 *   vs 25 Sep             736,412,683     +3.41m
 * </pre>
 * A day with NO reading is a thin {@value #CARRIED_HEIGHT} px grey line reading its date alone, "Tue 22 Sep" (the
 * user on the first live look, 2026-09-29: "remove the text '-carried, 754m' on days we dont login"; the chart still
 * draws the day carried forward). There is no clock on a row (plan 7.2 item 3).
 *
 * <p><b>The columns are measured at 213 px, not taken from the mock</b> (plan 7.2 item 2, amendment 9.8). Mock 5 was
 * drawn 223 px wide; at 213 its second line - "vs 01 May, 100 days" (95 px at 10 px: a May date is the widest, and
 * every 3-digit span measures the same), "12,345,678,901" (75) and "+1.66m" (36, the widest the row face's gp figure
 * ever prints) - wants 206 px of text plus two gaps in 200 px of room, and collides. So the left column is
 * {@value #LEFT_COLUMN} px (the widest honest sub-line), the exact total is printed at {@value #EXACT_SIZE} px
 * (64 px for twelve billion), the gap between columns is {@value #GAP} px, the right column is right-aligned to the
 * row's inner edge, and the middle column takes what is left - line 2 of the worst row is then
 * 95 + 2 + 64 + 2 + 36 = 199 of 200 px at 213, and at 230 all the slack goes to the middle. Every label is laid out at
 * its own preferred width and cut to its room only as a last resort; {@code BankHistoryViewFitTest} proves the widest
 * honest row cuts nothing and overlaps nothing.
 *
 * <p>KNOWN LIMIT: a gap of 1,000 days or more between two readings ("vs 01 May, 1000 days", 101 px) does not fit
 * the column and is cut with an ellipsis; the words are final, and nearly three years without a reading is the
 * only way to reach it.
 *
 * <p>Built from an immutable {@link Model} of the strings it prints, so the view can keep a row whose model has not
 * changed (plan 7.2 item 9) and a test can build the widest honest row directly. Plain labels only: no
 * {@code <html>}, no tooltip (amendment 9.13).
 */
final class BankHistoryDayRow extends JPanel
{
	/** A day with a reading. */
	static final int HEIGHT = 36;
	/** A carried day: no reading of its own. */
	static final int CARRIED_HEIGHT = 20;
	/** The "Day / Bank Total / Change" header over the list. */
	static final int HEADER_HEIGHT = 16;

	/** Inside the {@link Widgets#EDGE_WIDTH} px edge, and before the right edge. */
	static final int PAD_LEFT = 5;
	static final int PAD_RIGHT = 5;
	/**
	 * The date column: "vs 01 May, 100 days" at {@value #SUB_SIZE} px, the widest honest sub-line (any May date with
	 * a 3-digit span), is 95 px; the widest date on line 1 ("01 May 2025", bold 12) is 71.
	 */
	static final int LEFT_COLUMN = 95;
	/** Between two columns: 2, not 3, so the 95 px sub-line and the 64 px exact total both fit line 2 at 213 px. */
	static final int GAP = 2;
	/** Where a carried row's words start, from the row's left edge (mock 5 indents them past the rows' text). */
	static final int CARRIED_INDENT = Widgets.EDGE_WIDTH + PAD_LEFT + 4;

	/** A date more than this many days before today prints its year (plan 7.2 item 11, amendment 9.14). */
	static final int YEAR_AFTER_DAYS = 300;

	static final String FIRST_READING = "first reading";
	static final String DAY_HEADER = "Day";
	static final String TOTAL_HEADER = "Bank Total";
	static final String CHANGE_HEADER = "Change";

	private static final int DATE_SIZE = 12;
	private static final int SUB_SIZE = 10;
	private static final int TOTAL_SIZE = 13;
	/** A size below the other sub-lines: the one thing that makes the widest honest row fit at 213 px. */
	private static final int EXACT_SIZE = 9;
	private static final int PCT_SIZE = 14;
	private static final int GP_SIZE = 10;
	private static final int CARRIED_SIZE = 11;
	private static final int HEADER_SIZE = 11;

	static final Font DATE_FONT = Widgets.sansBold(DATE_SIZE);
	static final Font SUB_FONT = Widgets.sans(SUB_SIZE);
	static final Font TOTAL_FONT = Widgets.sans(TOTAL_SIZE);
	static final Font EXACT_FONT = Widgets.sans(EXACT_SIZE);
	static final Font PCT_FONT = Widgets.sansBold(PCT_SIZE);
	static final Font GP_FONT = Widgets.sans(GP_SIZE);
	static final Font CARRIED_FONT = Widgets.sans(CARRIED_SIZE);
	static final Font HEADER_FONT = Widgets.sans(HEADER_SIZE);

	/**
	 * Line 1's baseline and line 2's, from the row's top: far enough apart that no line-1 label's box (the 14 px
	 * percentage's descent included) reaches into a line-2 label's.
	 */
	private static final int LINE1_BASELINE = 16;
	private static final int LINE2_BASELINE = 31;

	/** The grey of a carried row's ground: between the card grey and the sidebar's, as mock 5 draws it. */
	static final Color CARRIED_GROUND = ColorScheme.DARK_GRAY_HOVER_COLOR;
	/** The edge of a reading that did not move, or of the first reading: a grey that shows on the card grey. */
	static final Color FLAT_EDGE = ColorScheme.MEDIUM_GRAY_COLOR;

	private static final DateTimeFormatter WEEKDAY = DateTimeFormatter.ofPattern("EEE", Locale.ENGLISH);

	/** The strings one row prints, and the sign its colours follow. Value equality: the view reuses equal rows. */
	static final class Model
	{
		private final LocalDate day;
		private final boolean carried;
		private final String date;
		private final String sub;
		private final String total;
		private final String exact;
		private final String pct;
		private final String gp;
		/** +1 rise, -1 fall, 0 no change; {@link #first} rows are 0 too. */
		private final int signum;
		private final boolean first;

		Model(final LocalDate day, final boolean carried, final String date, final String sub, final String total,
			final String exact, final String pct, final String gp, final int signum, final boolean first)
		{
			this.day = Objects.requireNonNull(day, "day");
			this.carried = carried;
			this.date = text(date);
			this.sub = text(sub);
			this.total = text(total);
			this.exact = text(exact);
			this.pct = text(pct);
			this.gp = text(gp);
			this.signum = Integer.signum(signum);
			this.first = first;
		}

		private static String text(@Nullable final String s)
		{
			return s == null ? "" : s;
		}

		LocalDate day()
		{
			return day;
		}

		boolean carried()
		{
			return carried;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Model))
			{
				return false;
			}
			final Model m = (Model) o;
			return carried == m.carried && signum == m.signum && first == m.first && day.equals(m.day)
				&& date.equals(m.date) && sub.equals(m.sub) && total.equals(m.total) && exact.equals(m.exact)
				&& pct.equals(m.pct) && gp.equals(m.gp);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(day, carried, date, sub, total, exact, pct, gp, signum, first);
		}

		@Override
		public String toString()
		{
			return carried ? "Model{" + date + '}'
				: "Model{" + date + " | " + sub + " | " + total + " | " + exact + " | " + pct + " | " + gp + '}';
		}
	}

	/**
	 * What the row of one calendar day prints, every figure through {@link BankHistoryPoint#valueFor} by way of
	 * {@link BankHistoryMath}: the compact total as the card prints it ({@link MovementMath#formatGp}, so "736m"),
	 * the exact one, the change against the PREVIOUS reading (% bold, gp quiet), the sub-line naming the day
	 * compared - "vs 25 Sep", "vs 21 Sep, 2 days", or "first reading" for the first reading ever. A day with no
	 * reading prints its date and nothing else.
	 *
	 * @param series the series already cut to {@code today}
	 */
	static Model model(final BankHistorySeries series, final BankHistoryMath.Day day, final LocalDate today,
		@Nullable final ViewOptions options)
	{
		final String date = dayText(day.day(), today);
		if (day.carried())
		{
			return new Model(day.day(), true, date, "", "", "", "", "", 0, false);
		}
		final String total = MovementMath.formatGp(day.valueGp());
		final String exact = MovementMath.formatExact(day.valueGp());
		final BankHistoryMath.Change change = BankHistoryMath.vsPrevious(series, day.day(), options);
		if (change == null)
		{
			return new Model(day.day(), false, date, FIRST_READING, total, exact, MovementMath.DASH, "", 0, true);
		}
		final long delta = change.deltaGp();
		final int span = change.spanDays();
		final String sub = "vs " + MovementMath.formatDay(change.fromDay()) + (span > 1 ? ", " + span + " days" : "");
		return new Model(day.day(), false, date, sub, total, exact,
			MovementMath.formatPctCompact(change.pct(), delta), delta == 0L ? "" : MovementRowPanel.signedGp(delta),
			Long.signum(delta), false);
	}

	/** "Tue 22 Sep" (amendment 9.14's weekday form). */
	static String weekday(final LocalDate day)
	{
		return WEEKDAY.format(day) + " " + MovementMath.formatDay(day);
	}

	/**
	 * A list row's date: the weekday form, or - for a day more than {@value #YEAR_AFTER_DAYS} days before today -
	 * amendment 9.14's {@code formatDay + " " + year} ("30 Sep 2025"), which leaves the weekday out so the year fits
	 * the date column.
	 */
	static String dayText(final LocalDate day, final LocalDate today)
	{
		if (ChronoUnit.DAYS.between(day, today) > YEAR_AFTER_DAYS)
		{
			return MovementMath.formatDay(day) + " " + day.getYear();
		}
		return weekday(day);
	}

	private final Model model;
	private final JLabel dateLabel;
	@Nullable
	private final JLabel subLabel;
	@Nullable
	private final JLabel totalLabel;
	@Nullable
	private final JLabel exactLabel;
	@Nullable
	private final JLabel pctLabel;
	@Nullable
	private final JLabel gpLabel;

	BankHistoryDayRow(final Model model)
	{
		super(null);
		this.model = Objects.requireNonNull(model, "model");
		setOpaque(true);
		if (model.carried)
		{
			setBackground(CARRIED_GROUND);
			setBorder(new EmptyBorder(0, CARRIED_INDENT, 0, PAD_RIGHT));
			dateLabel = add(Widgets.label(model.date, CARRIED_FONT, Widgets.PLACEHOLDER_COLOR));
			subLabel = null;
			totalLabel = null;
			exactLabel = null;
			pctLabel = null;
			gpLabel = null;
			setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, CARRIED_HEIGHT));
			return;
		}
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		final Color edge = model.signum == 0 ? FLAT_EDGE : Widgets.move(model.signum, Widgets.Kind.EDGE);
		setBorder(Widgets.card(edge, new Insets(0, PAD_LEFT, 0, PAD_RIGHT)));
		dateLabel = add(Widgets.label(model.date, DATE_FONT, Color.WHITE));
		subLabel = add(Widgets.label(model.sub, SUB_FONT, ColorScheme.LIGHT_GRAY_COLOR));
		totalLabel = add(Widgets.label(model.total, TOTAL_FONT, Color.WHITE));
		exactLabel = add(Widgets.label(model.exact, EXACT_FONT, ColorScheme.LIGHT_GRAY_COLOR));
		pctLabel = add(Widgets.label(model.pct, PCT_FONT, Widgets.move(model.signum, Widgets.Kind.FIGURE)));
		gpLabel = add(Widgets.label(model.gp, GP_FONT, Widgets.move(model.signum, Widgets.Kind.QUIET)));
		setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, HEIGHT));
	}

	private JLabel add(final JLabel label)
	{
		super.add(label);
		return label;
	}

	Model model()
	{
		return model;
	}

	/** Columns from the row's own width, so the same row is right at 213 px and at 230. */
	@Override
	public void doLayout()
	{
		final Insets in = getInsets();
		final int left = in.left;
		final int right = getWidth() - in.right;
		if (model.carried)
		{
			place(dateLabel, left, right - left, (getHeight() - height(dateLabel)) / 2);
			return;
		}
		final int middle = left + LEFT_COLUMN + GAP;
		final int pctX = right - width(pctLabel);
		final int gpX = right - width(gpLabel);
		place(pctLabel, pctX, width(pctLabel), top(pctLabel, LINE1_BASELINE));
		place(gpLabel, gpX, width(gpLabel), top(gpLabel, LINE2_BASELINE));
		place(totalLabel, middle, Math.min(width(totalLabel), pctX - GAP - middle), top(totalLabel, LINE1_BASELINE));
		place(exactLabel, middle, Math.min(width(exactLabel), gpX - GAP - middle), top(exactLabel, LINE2_BASELINE));
		place(dateLabel, left, Math.min(width(dateLabel), middle - GAP - left), top(dateLabel, LINE1_BASELINE));
		place(subLabel, left, Math.min(width(subLabel), middle - GAP - left), top(subLabel, LINE2_BASELINE));
	}

	private static int width(final JLabel label)
	{
		return label.getPreferredSize().width;
	}

	private static int height(final JLabel label)
	{
		return label.getPreferredSize().height;
	}

	/** Where a label's top goes for its text to stand on {@code baseline}. */
	private static int top(final JLabel label, final int baseline)
	{
		final FontMetrics fm = label.getFontMetrics(label.getFont());
		return baseline - fm.getAscent();
	}

	private static void place(final JLabel label, final int x, final int width, final int y)
	{
		label.setBounds(x, y, Math.max(0, width), height(label));
	}

	/**
	 * The "Day / Bank Total / Change" header over the list, on the sidebar's own ground, its words standing over the
	 * columns of {@link BankHistoryDayRow}.
	 */
	static JPanel header()
	{
		final JLabel day = Widgets.label(DAY_HEADER, HEADER_FONT, ColorScheme.LIGHT_GRAY_COLOR);
		final JLabel total = Widgets.label(TOTAL_HEADER, HEADER_FONT, ColorScheme.LIGHT_GRAY_COLOR);
		final JLabel change = Widgets.label(CHANGE_HEADER, HEADER_FONT, ColorScheme.LIGHT_GRAY_COLOR);
		final JPanel header = new JPanel(null)
		{
			@Override
			public void doLayout()
			{
				final int left = Widgets.EDGE_WIDTH + PAD_LEFT;
				final int right = getWidth() - PAD_RIGHT;
				final int y = (getHeight() - height(day)) / 2;
				place(day, left, width(day), y);
				place(total, left + LEFT_COLUMN + GAP, width(total), y);
				place(change, right - width(change), width(change), y);
			}
		};
		header.setOpaque(false);
		header.add(day);
		header.add(total);
		header.add(change);
		header.setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, HEADER_HEIGHT));
		return header;
	}
}

package com.bankpricemovement;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * The arithmetic over a {@link BankHistorySeries} (addendum AU; phase 0 contract sections 3, 9.5 and 9.6): the
 * change over a window, the change a day's reading made against the reading before it, the calendar days a
 * chart draws - carried days included - and the thinning that keeps a long range to about 120 points.
 *
 * <p>Pure and static. Nothing here reads a clock or a time zone: every caller hands in "today" (from its own
 * clock), and {@link #dayOf} takes the zone. Every figure is a reading's {@link BankHistoryPoint#valueFor}, so
 * everything drawn follows the switches that are on now; a null {@link ViewOptions} reads as
 * {@link ViewOptions#DEFAULT} everywhere (amendment 9.2).
 */
public final class BankHistoryMath
{
	private BankHistoryMath()
	{
	}

	/**
	 * The LOCAL calendar date of an epoch-millisecond stamp (contract section 3): what a reading is filed under.
	 * Production passes {@link ZoneId#systemDefault()}; a test passes the zone it needs.
	 */
	public static LocalDate dayOf(final long epochMillis, final ZoneId zone)
	{
		return Instant.ofEpochMilli(epochMillis).atZone(Objects.requireNonNull(zone, "zone")).toLocalDate();
	}

	/**
	 * The total moved from one reading to another (or to "now"). {@link #fromDay()} is the day of the reading
	 * actually USED, which is older than the window's day whenever that day had no reading - {@link #spanDays()}
	 * is what says so.
	 */
	public static final class Change
	{
		private final LocalDate fromDay;
		private final LocalDate toDay;
		private final long fromGp;
		private final long toGp;
		private final long deltaGp;
		@Nullable
		private final Double pct;
		private final int spanDays;

		/**
		 * deltaGp = toGp - fromGp; pct = deltaGp x 100 / fromGp, or null when fromGp is 0 (the formula
		 * {@link PortfolioMath} uses for a window); spanDays = the calendar days from fromDay to toDay.
		 */
		Change(final LocalDate fromDay, final LocalDate toDay, final long fromGp, final long toGp)
		{
			this.fromDay = Objects.requireNonNull(fromDay, "fromDay");
			this.toDay = Objects.requireNonNull(toDay, "toDay");
			this.fromGp = fromGp;
			this.toGp = toGp;
			this.deltaGp = toGp - fromGp;
			this.pct = fromGp == 0L ? null : deltaGp * 100.0d / fromGp;
			this.spanDays = (int) ChronoUnit.DAYS.between(fromDay, toDay);
		}

		/** The day of the reading compared FROM - the one actually used. */
		public LocalDate fromDay()
		{
			return fromDay;
		}

		/** The day compared TO. */
		public LocalDate toDay()
		{
			return toDay;
		}

		/** The total at the day compared TO less the total at the day compared FROM. */
		public long deltaGp()
		{
			return deltaGp;
		}

		/**
		 * The move as a percentage of the total compared FROM, unrounded (a reader truncates it toward zero when printing,
		 * as every percentage in the plugin is); null when {@code fromGp} is 0.
		 */
		@Nullable
		public Double pct()
		{
			return pct;
		}

		/** Calendar days from {@link #fromDay()} to {@link #toDay()}. */
		public int spanDays()
		{
			return spanDays;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Change))
			{
				return false;
			}
			final Change other = (Change) o;
			return fromDay.equals(other.fromDay) && toDay.equals(other.toDay) && fromGp == other.fromGp
				&& toGp == other.toGp;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(fromDay, toDay, fromGp, toGp);
		}

		@Override
		public String toString()
		{
			return "Change{" + fromDay + " " + fromGp + " -> " + toDay + " " + toGp + ", deltaGp=" + deltaGp
				+ ", pct=" + pct + ", spanDays=" + spanDays + '}';
		}
	}

	/**
	 * One calendar day as drawn. A day with no reading is CARRIED: its value is the last reading before it, carried
	 * forward. Two days are equal when they are the same day, value and reading.
	 */
	public static final class Day
	{
		private final LocalDate day;
		private final long valueGp;
		private final boolean carried;
		@Nullable
		private final BankHistoryPoint reading;

		Day(final LocalDate day, final long valueGp, @Nullable final BankHistoryPoint reading)
		{
			this.day = Objects.requireNonNull(day, "day");
			this.valueGp = valueGp;
			this.carried = reading == null;
			this.reading = reading;
		}

		public LocalDate day()
		{
			return day;
		}

		/** The day's total under the switches it was computed with - carried forward on a carried day. */
		public long valueGp()
		{
			return valueGp;
		}

		/** True when the day has no reading of its own. */
		public boolean carried()
		{
			return carried;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Day))
			{
				return false;
			}
			final Day other = (Day) o;
			return day.equals(other.day) && valueGp == other.valueGp && Objects.equals(reading, other.reading);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(day, valueGp, reading);
		}

		@Override
		public String toString()
		{
			return "Day{" + day + " " + valueGp + (carried ? " carried" : "") + '}';
		}
	}

	/**
	 * The change over a range of {@code days} ending today (amendment 9.5): the series is first cut to
	 * {@code upTo(today)}; to = the last reading on or before today; from = the first reading when
	 * {@code days <= 0} (the "all" range), else the last reading on or before {@code today - days}. Null when either
	 * is missing, or when from is the same reading as to - never a change of 0 that was not measured.
	 */
	@Nullable
	public static Change overDays(@Nullable final BankHistorySeries series, final LocalDate today, final int days,
		@Nullable final ViewOptions options)
	{
		Objects.requireNonNull(today, "today");
		final BankHistorySeries s = cut(series, today);
		final BankHistoryPoint to = s.atOrBefore(today);
		final BankHistoryPoint from = days <= 0 ? s.first() : s.atOrBefore(today.minusDays(days));
		if (to == null || from == null || from.day().equals(to.day()))
		{
			return null;
		}
		return new Change(from.day(), to.day(), from.valueFor(options), to.valueFor(options));
	}

	/**
	 * The card's move in History (amendment 9.6): the total NOW against the last reading on or before
	 * {@code today - days}. toDay is today and toGp is {@code nowGp}, the card's own headline, so the move is the
	 * figure the card prints against the day the footnote names. Null when no reading is old enough - the chip is
	 * then greyed. {@code days <= 0} compares against the first reading, as {@link #overDays} does.
	 */
	@Nullable
	public static Change sinceDay(@Nullable final BankHistorySeries series, final LocalDate today, final int days,
		@Nullable final ViewOptions options, final long nowGp)
	{
		Objects.requireNonNull(today, "today");
		final BankHistorySeries s = cut(series, today);
		final BankHistoryPoint from = days <= 0 ? s.first() : s.atOrBefore(today.minusDays(days));
		if (from == null)
		{
			return null;
		}
		return new Change(from.day(), today, from.valueFor(options), nowGp);
	}

	/**
	 * The reading of {@code day} against the reading before it (the day list's change column). Null when that day
	 * has no reading, or when it is the first reading ("first reading" on the row).
	 */
	@Nullable
	public static Change vsPrevious(@Nullable final BankHistorySeries series, @Nullable final LocalDate day,
		@Nullable final ViewOptions options)
	{
		if (series == null || day == null)
		{
			return null;
		}
		final BankHistoryPoint to = series.on(day);
		final BankHistoryPoint from = to == null ? null : series.atOrBefore(day.minusDays(1));
		if (from == null)
		{
			return null;
		}
		return new Change(from.day(), to.day(), from.valueFor(options), to.valueFor(options));
	}

	/**
	 * Every calendar day from {@code max(from, first reading)} to {@code to}, ascending - the ONE place carried days
	 * are derived (contract section 3). A day with a reading is that reading's total; a day without one carries the
	 * last reading before it forward. Readings after {@code to} play no part. Empty when the series is empty or
	 * {@code to} is before the first reading.
	 *
	 * @param from the first day wanted, or null for the first reading's day (the "all" range)
	 * @param to   the last day wanted - today, for the chart and the list
	 */
	public static List<Day> days(@Nullable final BankHistorySeries series, @Nullable final LocalDate from,
		final LocalDate to, @Nullable final ViewOptions options)
	{
		Objects.requireNonNull(to, "to");
		final BankHistoryPoint first = series == null ? null : series.first();
		if (first == null)
		{
			return Collections.emptyList();
		}
		final LocalDate start = from == null || from.isBefore(first.day()) ? first.day() : from;
		if (start.isAfter(to))
		{
			return Collections.emptyList();
		}

		final List<BankHistoryPoint> points = series.points();
		final List<Day> out = new ArrayList<>((int) Math.min(Integer.MAX_VALUE - 8,
			ChronoUnit.DAYS.between(start, to) + 1));
		// The last reading on or before `start` seeds the carry; `next` walks the readings after it in step with the
		// days, so the whole range is one pass however long it is.
		BankHistoryPoint carry = series.atOrBefore(start);
		int next = carry == null ? 0 : points.indexOf(carry) + 1;
		long carriedValue = carry == null ? 0L : carry.valueFor(options);
		for (LocalDate d = start; !d.isAfter(to); d = d.plusDays(1))
		{
			while (next < points.size() && !points.get(next).day().isAfter(d))
			{
				carry = points.get(next++);
				carriedValue = carry.valueFor(options);
			}
			final BankHistoryPoint reading = carry != null && carry.day().equals(d) ? carry : null;
			out.add(new Day(d, carriedValue, reading));
		}
		return Collections.unmodifiableList(out);
	}

	/**
	 * At most about {@code maxPoints} of these days (plan 7.2 item 10): unchanged when there are no more than that;
	 * otherwise buckets of {@code ceil(n / maxPoints)} days, aligned to the LAST day (so the newest bucket is always
	 * whole and ends today, and only the oldest may be short), each drawn as its last READING - or, when every day in
	 * it is carried, as its last day.
	 *
	 * @throws IllegalArgumentException if {@code maxPoints} is below 1
	 */
	public static List<Day> thin(@Nullable final List<Day> days, final int maxPoints)
	{
		if (maxPoints < 1)
		{
			throw new IllegalArgumentException("maxPoints must be at least 1, not " + maxPoints);
		}
		if (days == null || days.isEmpty())
		{
			return Collections.emptyList();
		}
		final int n = days.size();
		if (n <= maxPoints)
		{
			return days;
		}
		final int bucket = (n + maxPoints - 1) / maxPoints;
		final List<Day> out = new ArrayList<>(maxPoints);
		// Walk back from the last day, one bucket at a time, then reverse: the alignment is to the end.
		for (int end = n - 1; end >= 0; end -= bucket)
		{
			final int start = Math.max(0, end - bucket + 1);
			Day pick = days.get(end);
			for (int i = end; i >= start; i--)
			{
				if (!days.get(i).carried())
				{
					pick = days.get(i);
					break;
				}
			}
			out.add(pick);
		}
		Collections.reverse(out);
		return Collections.unmodifiableList(out);
	}

	/**
	 * The day a window of {@code days} first has a reading old enough - {@code first().day() + days} - which is
	 * when a greyed chip stops being grey (amendment 9.6). Null for an empty series.
	 */
	@Nullable
	public static LocalDate fillsOn(@Nullable final BankHistorySeries series, final int days)
	{
		final BankHistoryPoint first = series == null ? null : series.first();
		return first == null ? null : first.day().plusDays(Math.max(0, days));
	}

	/** The series cut to today; a null series reads as {@link BankHistorySeries#EMPTY}. */
	private static BankHistorySeries cut(@Nullable final BankHistorySeries series, final LocalDate today)
	{
		return series == null ? BankHistorySeries.EMPTY : series.upTo(today);
	}
}

package com.bankpricemovement;

import java.text.ParseException;
import java.util.Arrays;
import java.util.regex.Pattern;
import javax.annotation.Nullable;

/**
 * The three quick bands under the band button, carried as one immutable value the way {@link ViewOptions} carries
 * the view switches (addendum Z, line Z1): three DISTINCT POSITIVE gp amounts, always held ASCENDING.
 *
 * <p>Before addendum Z these were two constants in the panel - {@code PRESET_MINS} and {@code PRESET_LABELS} - so
 * a bank whose cheapest interesting stack is worth ten million had three chips it never pressed. They are now a
 * config line the user edits in the boxes at the foot of the gear menu, and this value is what travels between
 * that line, those boxes, the fold's chips and the dev bridge.
 *
 * <p>Pure on purpose, like {@link MovementMath}: nothing here touches Swing, the client or the config, so every
 * rule below - what a typed line means, what is refused, how a band is written back out - is testable without a
 * client.
 *
 * <p><b>The invariant is the type.</b> Only {@link #of(long, long, long)} and {@link #parse(String)} build one,
 * and neither can produce a trio that is out of order, holds a duplicate or holds a zero. A duplicate would draw
 * two identical chips of which only one could ever light; a zero or a negative is not a price (the same rule
 * {@code MovementMath.parseGp} applies to the Min / Max fields).
 */
public final class BandPresets
{
	/**
	 * What the plugin has always offered and what "Reset to default" restores: 100k, 1m, 10m - the trio the fold
	 * drew from {@code PRESET_MINS} up to addendum W, so a profile that never touches the new config line sees
	 * exactly today's chips.
	 */
	public static final BandPresets DEFAULT = new BandPresets(100_000L, 1_000_000L, 10_000_000L);

	/** How many bands a trio holds. Three chips beside "All" is what the 213 px fold has room for. */
	private static final int BANDS = 3;

	/**
	 * What separates one band from the next in a typed line: a run of whitespace and slashes, and a comma that is
	 * NOT a thousands grouping comma.
	 *
	 * <p>The three alternatives, in order: {@code [\s/]} is always a separator; {@code (?<![0-9]),} is a comma that
	 * does not follow a digit ("100k, 1m"); {@code ,(?![0-9]{3}(?![0-9]))} is a comma that does not introduce a
	 * group of exactly three digits ("1000,2000"). What is left - a comma between a digit and exactly three digits -
	 * is the grouping comma of "1,000", which {@code MovementMath.parseGp} reads as part of the number and which
	 * {@link #format()} itself writes for any band under 10,000 ({@code QuantityFormatter} spells 1,000 as
	 * "1,000", not as "1k"). Were the split blind to it, {@code parse(of(1000, 2000, 3000).format())} - six parts -
	 * would refuse the very line this class had just written.
	 *
	 * <p>The trailing {@code +} makes a whole run of separators one match, so ", " does not yield an empty band
	 * between the comma and the space.
	 */
	private static final Pattern SEPARATORS = Pattern.compile("(?:[\\s/]|(?<![0-9]),|,(?![0-9]{3}(?![0-9])))+");

	private final long small;
	private final long middle;
	private final long large;

	/**
	 * The only constructor, and private: {@link #of(long, long, long)} is the one door, so no caller can build a
	 * trio that breaks the invariant. The arguments must already be ascending, distinct and positive.
	 */
	private BandPresets(final long small, final long middle, final long large)
	{
		this.small = small;
		this.middle = middle;
		this.large = large;
	}

	/**
	 * Reads the config line, a dev verb's argument or the three boxes joined together (Z1): the text is split on
	 * commas, slashes and whitespace, each part is read by {@link MovementMath#parseGp(String)} - so "100k",
	 * "1.5m", "2b" and "1,000" all work - and the trio is sorted.
	 *
	 * <p>Answers NULL rather than throwing, because every caller of this treats a line it cannot read the same
	 * way: keep the last good presets (a stored string that does not parse reads as {@link #DEFAULT}, never a
	 * crash - Z1). The three refusals are: not exactly three values, a value that is not positive, and two values
	 * that are equal.
	 *
	 * @param text what the user typed, or what the config holds; null and blank are refusals like any other
	 * @return the trio held ascending, or null when the text names no valid one
	 */
	@Nullable
	public static BandPresets parse(final String text)
	{
		if (text == null)
		{
			return null;
		}

		final String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}

		final long[] values = new long[BANDS];
		int found = 0;
		for (final String part : SEPARATORS.split(trimmed))
		{
			if (part.isEmpty())
			{
				// A separator run at the very start of the text yields one empty piece; it is not a band.
				continue;
			}

			if (found == BANDS)
			{
				// A fourth value: the user meant something this line cannot hold, so read none of it.
				return null;
			}

			try
			{
				values[found] = MovementMath.parseGp(part);
			}
			catch (ParseException notANumber)
			{
				return null;
			}

			found++;
		}

		if (found != BANDS || !valid(values[0], values[1], values[2]))
		{
			return null;
		}

		return of(values[0], values[1], values[2]);
	}

	/**
	 * The trio of three amounts in any order, sorted ascending (Z1) - what the gear menu's three boxes and the
	 * {@code presets=} verb build once their text has been read.
	 *
	 * <p>Throws rather than answering null, because a caller that has three longs in hand has already done the
	 * reading: this is the invariant's last gate, not the place a typed line is judged. A panel that reads three
	 * boxes catches it beside the {@link ParseException} the boxes themselves can throw
	 * ({@code catch (ParseException | IllegalArgumentException bad)}) and paints them red.
	 *
	 * @throws IllegalArgumentException when a value is not positive, or two of the three are equal
	 */
	public static BandPresets of(final long a, final long b, final long c)
	{
		if (!valid(a, b, c))
		{
			throw new IllegalArgumentException(
				"Three distinct positive gp bands are needed, not " + a + ", " + b + ", " + c);
		}

		final long[] sorted = {a, b, c};
		Arrays.sort(sorted);
		return new BandPresets(sorted[0], sorted[1], sorted[2]);
	}

	/**
	 * The three lower bounds, smallest first - what the fold's chips apply as {@code applyBand(min, 0)} (Z3).
	 *
	 * @return a fresh array each call, so a caller sorting or scaling it cannot reach back into the value
	 */
	public long[] mins()
	{
		return new long[]{small, middle, large};
	}

	/**
	 * The three chip labels, smallest first: each band in gp shorthand with a "+" after it, since a preset has a
	 * lower bound and no upper one (Z1). For {@link #DEFAULT} exactly "100k+", "1m+", "10m+" - the labels the fold
	 * has drawn since addendum N, which is why the default presets leave every picture byte-identical.
	 *
	 * @return a fresh array each call
	 */
	public String[] labels()
	{
		return new String[]{label(small), label(middle), label(large)};
	}

	/**
	 * The three bands as one line in gp shorthand, smallest first - "100k, 1m, 10m" (Z1): what the config item
	 * holds, what the gear menu's boxes print (one band each), and what {@link #parse(String)} reads back.
	 *
	 * <p>Shorthand is LOSSY where it must be, because it is the same shorthand the boxes and the Min / Max fields
	 * use: a band of 1,234,567 gp is written "1.23m" and read back as 1,230,000. Anything the game itself writes
	 * exactly - every round thousand, million and billion, and every amount under 10,000 - survives the trip.
	 */
	public String format()
	{
		return MovementMath.formatGp(small) + ", " + MovementMath.formatGp(middle) + ", "
			+ MovementMath.formatGp(large);
	}

	/** One chip's label: the band, then the "+" that says "and everything dearer". */
	private static String label(final long min)
	{
		return MovementMath.formatGp(min) + "+";
	}

	/**
	 * The invariant in one place: three positive amounts, no two the same. Order is not its business -
	 * {@link #of(long, long, long)} sorts.
	 */
	private static boolean valid(final long a, final long b, final long c)
	{
		return a > 0L && b > 0L && c > 0L && a != b && b != c && a != c;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BandPresets))
		{
			return false;
		}
		final BandPresets other = (BandPresets) o;
		return small == other.small && middle == other.middle && large == other.large;
	}

	@Override
	public int hashCode()
	{
		int hash = Long.hashCode(small);
		hash = 31 * hash + Long.hashCode(middle);
		hash = 31 * hash + Long.hashCode(large);
		return hash;
	}

	/**
	 * A debugging line, in gp rather than in shorthand: {@link #format()} is the text the user sees, and a log
	 * that rounded 1,234,567 to "1.23m" would hide the very difference one would be reading a log to find.
	 */
	@Override
	public String toString()
	{
		return "BandPresets{" + small + ", " + middle + ", " + large + '}';
	}
}

package com.bankpricemovement;

import java.util.function.Function;

/**
 * A test hook, and nothing else: the one static handle a developer-mode client hands the Effect Lab's HTTP
 * server so a script (or Claude) can drive the 2h Bank Portfolio Tracker sidebar without a person at the keyboard.
 * The same shape as {@code com.lootandbeam.DevBridge}, which the lab's {@code /lb} route reaches; this one is
 * reached by {@code /bpm}.
 *
 * <p><b>It is null in every production client.</b> {@link BankPriceMovementPlugin#startUp()} sets it only
 * when RuneLite's injected {@code @Named("developerMode")} constant is true - which the client only ever
 * binds true for a from-source launch with {@code --developer-mode} and no launcher version
 * (RuneLiteModule.java:120, from RuneLite.java:224) - and {@link BankPriceMovementPlugin#shutDown()} clears
 * it as its first statement. A Plugin Hub build therefore carries a field that is written once with
 * null-equivalent state, read by nothing, and reachable only from a class in the test source set
 * ({@code com.osrslos.lab.LabServer}) that is not in the jar at all.
 *
 * <p>The handler takes ONE command string ({@code key} or {@code key=value}) and answers a JSON string; see
 * {@link BpmCommands} for the command list and {@code docs/effect-lab.md} §3.3 for the {@code /bpm} route
 * that reaches it. It bounces the work onto the Swing thread itself, so it is safe to call from the HTTP
 * thread; it never throws.
 *
 * <p>Volatile because it is written on the EDT (plugin start/stop) and read on the lab's HTTP thread.
 */
public final class BpmDevBridge
{
	/** The running panel's command handler while a developer-mode client has the plugin on; null otherwise. */
	public static volatile Function<String, String> handler;

	private BpmDevBridge()
	{
	}
}

package com.bankpricemovement;

import java.text.Normalizer;
import java.time.LocalDate;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * One revision of the wiki's Grand Exchange guide-price table: the revision it came from, the moment that
 * revision was SAVED, the DAY its prices belong to, the moment we read it, and the whole name-to-gp map
 * (contract K12, rewritten by addendum L - L7, L8).
 *
 * <p><b>The day marker, and why it is not the timestamp</b> (L7, evidence L-E). The revision timestamp says
 * when someone pressed save; it does not say which Jagex day the prices in the body are. Human maintenance
 * edits - 24 of 194 in-window revisions, and once the bot itself - republish the PREVIOUS day's table under the
 * next day's timestamp (revision 15329323, Riblet15, saved 2026-09-03T06:46Z, carries
 * {@code %LAST_UPDATE_F%} "02 September 2026 07:21:23"). The table's own {@code %LAST_UPDATE%} field is the
 * authoritative marker and was right on 38 of 38 sampled bodies against 34 of 38 for the timestamp, so
 * {@link #dataSeconds()} - not {@link #revisionSeconds()} - is what the status line, the tooltip and the L5 day
 * check read. {@link #revisionSeconds()} stays for cache identity beside {@link #revId()}.
 *
 * <p><b>Why the map is keyed by NAME.</b> {@code Module:GEPrices/data.json} is a wiki page written for wiki
 * templates, so its keys are item names ({@code {"Green hat": 1086, "Abyssal whip": 799012, ...}}, 4,566 of them,
 * 126 KB - {@code docs/research/bank-price-movement-calibration-2026-09-08.md}). Turning that into the id-keyed
 * {@link PriceMap} the rows are computed from needs the id-to-wiki-name table
 * ({@code prices.runescape.wiki/api/v1/osrs/mapping}, contract K3), which is the caller's business and is
 * refreshed on a completely different cadence (weekly, against six-hourly for the history - L10). Keeping this
 * type name-keyed means one fetched revision can be re-projected onto ids whenever the mapping changes, without
 * going back to the network.
 *
 * <p><b>Why every key goes through {@link #key(String)}</b> (L8, evidence L-F). The wiki case-renamed 81 keys on
 * 2026-08-12..20 ("3rd age amulet" became "3rd Age amulet"), so a byte-exact lookup silently loses three of the
 * user's bank items on every window of 30 days or more - the older revision spells them the other way.
 * Lower-casing with {@link Locale#ROOT} after an NFC normalise and a whitespace collapse recovers all of them and
 * was collision-free on all six sampled revisions. Both the parsed table and every lookup are keyed through the
 * one method, so a caller cannot accidentally compare a raw name against a folded key.
 *
 * <p>Immutable and safe to share across threads: the map is built on an OkHttp dispatcher thread, handed to the
 * service's executor and read while rows are computed, so it is copied once here and handed out
 * {@link Collections#unmodifiableMap unmodifiable}.
 */
public final class GuideSnapshot
{
	private static final Logger log = LoggerFactory.getLogger(GuideSnapshot.class);

	/** The "no guide table yet" snapshot: no revision, no day, no stamp, no prices. Immutable, safe to share. */
	public static final GuideSnapshot EMPTY = new GuideSnapshot(0L, 0L, 0L, 0L, Collections.emptyMap());

	/**
	 * The table's "this item has no price" value (L8 c). Three keys carried exactly 2,147,483,646 on the sampled
	 * revisions - "3rd Age axe", "3rd Age druidic robe top", "3rd Age pickaxe" - one short of
	 * {@link Integer#MAX_VALUE}, which is the wiki's way of writing "unpriced" in a field that must hold a
	 * number. Treated as a threshold rather than an equality so a future 2,147,483,647 cannot slip a two-billion
	 * gp price onto a row.
	 */
	public static final long NO_PRICE = 2_147_483_646L;

	/**
	 * Anything Java calls whitespace, plus U+00A0. {@code \s} does NOT match a non-breaking space, and a wiki
	 * name saved with one would otherwise never match the same name typed with an ordinary space.
	 */
	private static final Pattern WHITESPACE = Pattern.compile("[\\s\\u00A0]+");

	private final long revId;
	private final long revisionSeconds;
	private final long dataSeconds;
	private final long fetchedAtMillis;
	private final Map<String, Long> pricesByName;

	/**
	 * @param revId           the wiki revision id this table came from; 0 only for {@link #EMPTY}
	 * @param revisionSeconds when that revision was SAVED, unix seconds (the API's {@code timestamp}); cache
	 *                        identity only (L7)
	 * @param dataSeconds     the table's own {@code %LAST_UPDATE%}, unix seconds - the day marker every label
	 *                        and every day comparison uses (L7)
	 * @param fetchedAtMillis when we read it, epoch millis - the value the six-hourly refetch rule compares (L10)
	 * @param pricesByName    wiki item name to guide price in gp. Copied; keys are folded through
	 *                        {@link #key(String)}, null keys and values are dropped, and a value at or above
	 *                        {@link #NO_PRICE} is dropped because it is the table's "unpriced" marker, not a price
	 */
	public GuideSnapshot(final long revId, final long revisionSeconds, final long dataSeconds,
		final long fetchedAtMillis, final Map<String, Long> pricesByName)
	{
		final Map<String, Long> copy = new HashMap<>();
		if (pricesByName != null)
		{
			for (final Map.Entry<String, Long> entry : pricesByName.entrySet())
			{
				final String folded = key(entry.getKey());
				final Long price = entry.getValue();
				if (folded == null || folded.isEmpty() || price == null || price >= NO_PRICE)
				{
					continue;
				}

				final Long clash = copy.putIfAbsent(folded, price);
				if (clash != null && !clash.equals(price))
				{
					// Never seen: the fold was collision-free on all six sampled revisions (L-F). If the wiki
					// ever ships two spellings of one name with two prices, one of them wins arbitrarily and
					// this line is the only record of it - a wrong-by-a-rename row is still better than a throw
					// inside a fetch callback.
					log.debug("bank-portfolio-tracker: revision {} folds two spellings of \"{}\" onto {} gp (kept {})",
						revId, folded, price, clash);
				}
			}
		}

		this.revId = revId;
		this.revisionSeconds = revisionSeconds;
		this.dataSeconds = dataSeconds;
		this.fetchedAtMillis = fetchedAtMillis;
		this.pricesByName = Collections.unmodifiableMap(copy);
	}

	/**
	 * The wiki revision id this table is the content of. Never 0 for a fetched snapshot -
	 * {@code GuidePriceClient} drops a revision it could not identify rather than report one.
	 */
	public long revId()
	{
		return revId;
	}

	/**
	 * When the revision was SAVED, in unix seconds. Cache identity, not a day marker: a body whose
	 * {@link #dataSeconds()} disagrees with it by up to two days is an ordinary human edit (L-E), which is why
	 * nothing user-facing prints this value any more (L7).
	 */
	public long revisionSeconds()
	{
		return revisionSeconds;
	}

	/**
	 * The table's own {@code %LAST_UPDATE%} in unix seconds - the moment Jagex stamped the guide prices in this
	 * body. This is the authoritative day marker (L7): the status line and the tooltip print its DAY, and L5's
	 * "is this really day T's table?" check compares {@link #dataDay()} against the target date.
	 */
	public long dataSeconds()
	{
		return dataSeconds;
	}

	/**
	 * The UTC calendar day these prices belong to, or null when the body carried no marker ({@link #EMPTY}).
	 * UTC always (L9) - the guide price steps once a day and every date in this plugin's selection maths is a UTC
	 * date, so a local-zone date would put a user east of Greenwich a whole day out.
	 *
	 * <p><b>What this rests on, exactly.</b> Not a midnight stamp: the Jagex rollover was observed between 00:47
	 * and 02:06 UTC (L-A), and {@code %LAST_UPDATE%} is not the rollover at all - it is the wiki bot's own capture
	 * moment for that step, which lands anywhere in the day (02:11-22:20 UTC, L-C; the five stored baselines here
	 * read 03:35, 07:21, 09:22, 13:00 and 13:51 UTC, each a few minutes before its revision's save time). So the
	 * UTC date of the marker names the right Jagex day only while the bot runs AFTER the rollover - a margin of
	 * about five minutes between the latest observed rollover and the earliest observed bot run. A body whose
	 * marker falls outside the window its own save time allows is already refused upstream
	 * ({@code GuidePriceClient}, L7); a bot run that slipped in front of a late rollover would not be, and would
	 * date its table one day late. Nothing detects that case today - see {@code PriceService.deriveAnchorDay}.
	 */
	public LocalDate dataDay()
	{
		return dataSeconds <= 0L ? null : RevisionRef.dayOf(dataSeconds);
	}

	/**
	 * When this snapshot was read from the network, in epoch millis. The index and the newest table are refetched
	 * when this is more than six hours old (L10), because the table only changes about once a day.
	 */
	public long fetchedAtMillis()
	{
		return fetchedAtMillis;
	}

	/**
	 * The guide price for one wiki item name, or null when the table does not list it or lists it as unpriced.
	 * The name is folded through {@link #key(String)} first, so the caller may pass the {@code /mapping} name,
	 * the item composition name, or the table's own spelling in any case (L8).
	 */
	public Long get(final String name)
	{
		final String folded = key(name);
		return folded == null ? null : pricesByName.get(folded);
	}

	/** Every folded-name-to-gp entry, unmodifiable. Keys are {@link #key(String)} output, not wiki spelling. */
	public Map<String, Long> pricesByName()
	{
		return pricesByName;
	}

	public int size()
	{
		return pricesByName.size();
	}

	public boolean isEmpty()
	{
		return pricesByName.isEmpty();
	}

	/**
	 * The one name-folding rule (L8): NFC normalise, collapse every run of whitespace to a single space, trim,
	 * then lower-case with {@link Locale#ROOT}.
	 *
	 * <p>Each step earns its place. NFC because the wiki serves UTF-8 that may spell an accent either
	 * pre-composed or as a combining pair and the two are different Strings. The whitespace collapse because a
	 * double space between words is invisible in a wiki edit box. {@link Locale#ROOT} rather than the default
	 * locale because a Turkish user's JVM lower-cases "I" to a dotless "&#x131;", which would fold "Ice gloves"
	 * onto a key no table has - the classic locale bug, and this method runs on whatever machine the plugin is
	 * installed on.
	 *
	 * <p>Package-private: it is an internal key, and letting the panel or the service invent its own folding is
	 * exactly the drift L8 exists to prevent.
	 *
	 * @param name any name, including null
	 * @return the folded key, or null when {@code name} is null
	 */
	static String key(final String name)
	{
		if (name == null)
		{
			return null;
		}

		final String composed = Normalizer.normalize(name, Normalizer.Form.NFC);
		final String collapsed = WHITESPACE.matcher(composed).replaceAll(" ").trim();
		return collapsed.toLowerCase(Locale.ROOT);
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof GuideSnapshot))
		{
			return false;
		}

		final GuideSnapshot other = (GuideSnapshot) o;
		return revId == other.revId
			&& revisionSeconds == other.revisionSeconds
			&& dataSeconds == other.dataSeconds
			&& fetchedAtMillis == other.fetchedAtMillis
			&& pricesByName.equals(other.pricesByName);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(revId, revisionSeconds, dataSeconds, fetchedAtMillis, pricesByName);
	}

	@Override
	public String toString()
	{
		return "GuideSnapshot{revId=" + revId
			+ ", dataDay=" + dataDay()
			+ ", revisionSeconds=" + revisionSeconds
			+ ", fetchedAtMillis=" + fetchedAtMillis
			+ ", names=" + pricesByName.size() + '}';
	}
}

package com.bankpricemovement;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.stream.JsonReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.FileAlreadyExistsException;
import java.nio.file.NoSuchFileException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
